classdef PipelineManager < handle
    % PIPELINEMANAGER manages data processing pipelines.
    % This class allows the creation of analysis pipeline and manages the execution of
    % functions. In addition, it controls for failed / completed  steps in the pipeline.

    properties
        b_skipSteps logical = true % If TRUE, PIPELINEMANAGER will load existing data from the SaveFolder to skip a section of a pipeline.
        b_saveDataBeforeFail logical = true % If TRUE, the more recent data ("current_data") in the pipeline will be saved to a file when an error occurs.
        b_alwaysSaveLeaf logical = false %
        b_avoidOverwrite logical = true %

        %----RAM Management Settings ----
        % Execution mode for RAM handling:
        %   'auto'    : PipelineManager decides whether to pass DATA as arrays or filenames.
        %   'ramsafe'  : Always pass DATA as filenames (strict/bestEffort governed by ramSafePolicy).
        ramMode char {mustBeMember(ramMode,{'auto','ramsafe'})} = 'auto'
        % RAM-safe sub-mode:
        %   'strict'     : preflight error if any required node has a DATA input with supportsFile==false.
        %   'bestEffort' : preflight warning; runtime may rehydrate (load to RAM) when safe.
        ramSafePolicy char {mustBeMember(ramSafePolicy,{'strict','bestEffort'})} = 'strict'

        % Leaf-output persistence policy:
        %   'explicit'   : save only outputs with explicit save targets or outputMode='file'.
        %   'saveLeaves' : save all supported DATA leaf outputs using explicit/default/generated names.
        %   'viewerTemp' : save DataViewer-compatible DATA leaf outputs as same-folder PMTMP_* files.
        %   'transient'  : allow unsaved DATA leaf outputs and report them as transient.
        leafOutputPolicy char {mustBeMember(leafOutputPolicy,{'explicit','saveLeaves','viewerTemp','transient'})} = 'saveLeaves'

        % Auto mode decision knobs
        % Lookahead length (L) used by the Auto policy when considering FILE->RAM rehydration.
        ramLookaheadLength (1,1) double {mustBeInteger, mustBePositive} = 2

        % Cooldown length (N) in steps. While cooldownRemaining>0, Auto avoids rehydration.
        ramCooldownSteps (1,1) double {mustBeInteger, mustBePositive} = 2

        % RAM safety rule parameters for rehydration decisions:
        % Rehydrate allowed if:
        %   availableRAM*(1-ramSafetyOverheadPct) >= ramSafetyDataMultiplier*dataBytes
        ramSafetyOverheadPct (1,1) double {mustBeGreaterThanOrEqual(ramSafetyOverheadPct,0), mustBeLessThan(ramSafetyOverheadPct,1)} = 0.15
        ramSafetyDataMultiplier (1,1) double {mustBeGreaterThan(ramSafetyDataMultiplier,0)} = 2.0
    end

    properties (SetAccess = {?DataViewer})
        % Structure array containing steps of the pipeline:
        funcList struct % structure containing the info about each function in the "fcnDir".
    end

    properties (Access = {?DataViewer})
        b_inputFromDataViewer logical = false % TRUE if the first input from the pipeline comes from the DataViewer app.
    end

    properties (Access = {?DataViewer})
        %%%%%%-- DEPRECATED PROPERTIES FOR REVIEW -------------------------
        b_enforceSaving logical = true % Ensures that all data generated by the pipeline is saved. This is set to FALSE for pipeline executed in DataViewer.
    end

    properties (SetAccess = private)
        % the same changes to the property's set method.
        pipelineVersion char = '2.0' % Version identifier for the pipeline class format/implementation
        PipelineSummary table% Shows the jobs run in the current Pipeline
        SaveFolderList cell % List of Save folders
        RawFolderList cell = {'Missing'} % List of Raw folders corresponding to the items in SaveFolderList.
        nodes struct       % struct array
        connections struct % struct array
        nextNodeID    % incremental unique ID
        activeLeafNodeID
        globalPipeLog table
        lastExecutionPlan struct = struct()
        lastExecutionResult struct = struct()
    end

    properties (GetAccess = {?DataViewer})
        dataHistory struct % Local copy of the content from the dataHistory file in the data's SaveFolder.
    end

    properties (GetAccess = {?DataViewer})
        %%%%%%-- DEPRECATED PROPERTIES FOR REVIEW -------------------------
        current_saveFolder char % Current path to save folder during pipeline execution.
        current_data % Data available in the workspace during pipeline.
        current_info struct% Structure with info about the functions ran on "current_data". This will be saved to the dataHistory file.
        current_rawFolder char % Current path to raw folder during pipeline execution.
        b_state logical = false % True if a task of a pipeline was successfully executed.
    end

    properties (Access = private)
        fcnDir char % Directory of the analysis functions.
        projectFolder char % Path to Project's Directory. Used to locate PipelineConfig and Error Log folders.
        folderPipeLog table % Pipeline LogTable stored in the "pipeLog.mat" file in the SaveFolder.
        maxLogRows = 100 % Maximum number of rows in the folderLog table. If exeeded, older entries will be erased.
        current_outFile cell % List of file names created as output from some of the analysis functions.
        % It can be the name of an existing file, or "outFile" for a function
        %  that creates a file such as "run_ImagesClassification".
        timeTag % timestamp used as "tag" for temporary files created during the pipeline execution.
        b_pipeIsValid logical = false % TRUE, if the pipeline passed all validations and is ready to execution.
        SaveFolderList_truncated cell % Truncated version of the save folder list for better display in Global Pipeline Summary.
        RawFolderList_truncated  cell % Truncated version of the raw folder list for better display in Global Pipeline Summary.
        topoOrder
        dataStore        % registry of produced outputs (ram/file/temp/remainingConsumers)
        consumerCount    % precomputed counts per (nodeID,outputPort)
        tempFiles string % list of temp files created during run
        currentLeafOutputPolicy char = '' % per-run leaf output policy override
        currentTempSessionTag char = '' % per-run tag used for PMTMP_* outputs
        executionTrace
        executionProgressLog struct = struct([]) % Progress events emitted during the latest execution.
        currentExecutionWasCancelled logical = false % TRUE when the latest executePipeline run was cancelled by request.
        metaData
    end

    properties (Access = private)
        %%%%%%-- DEPRECATED PROPERTIES FOR REVIEW -------------------------
        pipe_session % Copy of the pipeline stored in "pipe" used during the pipeline execution that can be dynamically modified.
        current_pipe struct % Pipeline currently running.
        h_wbItem % Handle of waitbar dialog showing the progress of the pipeline across protocol's objects.
        h_wbTask % Handle of waitbar dialog showing the progress of the pipeline in the current object.
        current_seq (1,1) {mustBeNonnegative} = 0 % index of current sequence in pipeline.
        current_seqIndx (1,1) {mustBeNonnegative} = 0 % index of step in current sequence in pipeline.
    end

    properties (Constant)
        dataSemanticTypes = { ...
            'Image', ...                   % 2-D imaging data (Y×X or YxXxE)
            'ImageTimeSeries', ...         % 3-D imaging data (Y×X×T or YxXxTxE)
            'ProcessedData', ...           % Processed data stored in UMT structs
            'UnknownDataType' ...          % Fallback semantic type for unspecified or legacy data
            };

        tempOutputPrefix = 'PMTMP_' % Reserved same-folder prefix for temporary PipelineManager outputs.
    end

    methods

        function obj = PipelineManager(SaveFolderList,varargin)
            % PIPELINEMANAGER Constructs an instance of this class
            %
            % Input:
            %   SaveFolderList (cell array / char / string):
            %       List of Save folder paths containing .dat and .mat files.
            %
            % Optional positional inputs:
            %   RawFolderList (cell array / char / string):
            %       List of Raw folder paths associated with SaveFolderList.
            %       The list must have the same length as SaveFolderList.
            %       Each item is validated independently with ISFOLDER:
            %           - valid folder    -> stored as full path
            %           - invalid / empty -> replaced by 'Missing'
            %
            %   ProjectFolder (char):
            %       Path to the project folder. Used to save/load pipelines and
            %       save pipeline error logs.
            %
            % Notes:
            %   - If no RawFolderList is provided, all entries are set to 'Missing'.
            %   - Missing raw folders are allowed at construction time.
            %   - During execution, items with RawFolder='Missing' are skipped if
            %     the current pipeline requires RawFolder input.

            p = inputParser;

            listValidationFun = @(x) ...
                ischar(x) || ...
                isstring(x) || ...
                (iscell(x) && all(cellfun(@(c) ischar(c) || (isstring(c) && isscalar(c)), x)));

            addRequired(p,'SaveFolderList', listValidationFun);
            addOptional(p,'RawFolderList',{''}, listValidationFun);
            addOptional(p,'ProjectFolder',pwd,@ischar);

            parse(p,SaveFolderList, varargin{:});

            saveFolderListInRaw = p.Results.SaveFolderList;
            rawFolderListInRaw  = p.Results.RawFolderList;
            obj.projectFolder = p.Results.ProjectFolder;
            clear p

            % -------------------------------------------------------------
            % Normalize list containers
            % -------------------------------------------------------------
            saveFolderListIn = normalizePathList(saveFolderListInRaw);

            if isempty(rawFolderListInRaw)
                rawFolderListIn = cell(0,1);
            else
                rawFolderListIn = normalizePathList(rawFolderListInRaw);
            end

            % -------------------------------------------------------------
            % Validate SaveFolder list
            % -------------------------------------------------------------
            errID = 'Umitoolbox:PipelineManager:wrongInput';

            b_saveFolderExists = false(numel(saveFolderListIn),1);
            for iSF = 1:numel(saveFolderListIn)
                b_saveFolderExists(iSF) = isfolder(saveFolderListIn{iSF});
            end

            msg_char = repmat('\n%s',1,sum(~b_saveFolderExists));
            assert(all(b_saveFolderExists), ...
                ['Operation aborted! The following Save Folder(s) do not exist:' msg_char], ...
                saveFolderListIn{~b_saveFolderExists});

            assert(isequaln(numel(unique(saveFolderListIn)),numel(saveFolderListIn)), ...
                errID, ...
                'Save Folder list cannot have duplicates!')

            % Enforce full path for SaveFolderList
            [~,saveFolderInfo] = cellfun(@(x) fileattrib(x),saveFolderListIn);
            saveFolderListNormalized = {saveFolderInfo.Name}';

            % -------------------------------------------------------------
            % Validate / normalize RawFolder list
            % -------------------------------------------------------------
            nSave = numel(saveFolderListNormalized);

            if isempty(rawFolderListIn) || all(strlength(strtrim(string(rawFolderListIn))) == 0)
                rawFolderListNormalized = repmat({'Missing'}, nSave, 1);
                warning(['No Raw Folder provided. All RawFolder entries were set to "Missing". ' ...
                    'Any SaveFolder item whose pipeline requires RawFolder input will be skipped during execution.']);
            else
                assert(isequaln(numel(rawFolderListIn), nSave), ...
                    errID, ...
                    'Save Folder and Raw Folder lists should have the same length!');

                rawFolderListNormalized = rawFolderListIn(:);
                invalidRawDisplay = strings(0,1);

                for iRF = 1:numel(rawFolderListNormalized)

                    thisRawFolder = char(string(rawFolderListNormalized{iRF}));

                    if isempty(strtrim(thisRawFolder)) || ~isfolder(thisRawFolder)

                        if isempty(strtrim(thisRawFolder))
                            invalidRawDisplay(end+1,1) = "<empty>"; %#ok<AGROW>
                        else
                            invalidRawDisplay(end+1,1) = string(thisRawFolder); %#ok<AGROW>
                        end

                        rawFolderListNormalized{iRF} = 'Missing';
                        continue
                    end

                    [~,rawFolderInfoThis] = fileattrib(thisRawFolder);
                    rawFolderListNormalized{iRF} = rawFolderInfoThis.Name;
                end

                if ~isempty(invalidRawDisplay)
                    msg_char = repmat('\n%s',1,numel(invalidRawDisplay));
                    warning(['The following Raw Folder(s) are invalid and were replaced by "Missing":' msg_char ...
                        '\nAny SaveFolder item whose pipeline requires RawFolder input will be skipped during execution.'], ...
                        invalidRawDisplay{:});
                end
            end

            % -------------------------------------------------------------
            % Store folder lists
            % -------------------------------------------------------------
            obj.SaveFolderList = saveFolderListNormalized;
            obj.RawFolderList  = rawFolderListNormalized;

            % Truncated display lists
            obj.SaveFolderList_truncated = obj.truncateFolderList(obj.SaveFolderList);
            obj.RawFolderList_truncated  = obj.truncateFolderList(obj.RawFolderList);

            % Create timestamp tag
            obj.timeTag = char(datetime('now','Format','_ddMMyyyyHHmmSS'));

            % -------------------------------------------------------------
            % Get list of available analysis functions
            % -------------------------------------------------------------
            if isdeployed
                [obj.fcnDir,~,~] = fileparts(which('funcTemplate.m'));
                a = load(fullfile(obj.fcnDir,'deployFcnList.mat'));
                obj.funcList = a.out; % Structure "out" created by umitFcnReader
            else
                rootDir = erase(mfilename('fullpath'),['classes' filesep 'PipelineManager']);
                if isempty(rootDir)
                    error('Umitoolbox environment variable not found!')
                end
                obj.fcnDir = fullfile(rootDir, 'Analysis');
                obj.createFcnList;
            end

            % =============================================================
            % Local helper
            % =============================================================
            function pathList = normalizePathList(pathInput)
                %NORMALIZEPATHLIST Convert char/string/cell input to N-by-1 cell array of char.

                if ischar(pathInput)
                    if isrow(pathInput)
                        pathList = {pathInput};
                    else
                        pathList = cellstr(pathInput);
                    end

                elseif isstring(pathInput)
                    pathList = cellstr(pathInput(:));

                elseif iscell(pathInput)
                    pathList = cellfun(@(x) char(string(x)), pathInput(:), 'UniformOutput', false);

                else
                    pathList = cell(0,1);
                end
            end
        end

        function state = setParameters(obj, stepName)
            %SETPARAMETERS Edit parameter values of a step in the pipeline.
            %
            %   state = obj.setParameters()
            %   state = obj.setParameters(stepName)
            %
            %   Inputs:
            %       stepName - Optional step tag. If omitted, the user is prompted
            %                  to choose one from the current pipeline.
            %
            %   Output:
            %       state - True if the parameter dialog was completed and the
            %               values were applied. False if the operation was
            %               cancelled or no editable parameters exist.

            state = false;

            if isempty(obj.nodes)
                error('Pipeline is empty.');
            end

            % ---------------------------------------
            % Step selection
            % ---------------------------------------
            if nargin < 2 || isempty(stepName)

                fprintf('\nAvailable steps:\n');
                for i = 1:numel(obj.nodes)
                    if strcmpi(obj.nodes(i).kind,'stream')
                        fprintf('  - %s\n', obj.nodes(i).name);
                    end
                end

                stepName = input('Type step name: ','s');
            end

            stepName = char(string(stepName));
            idx = find(strcmpi(stepName,{obj.nodes.name}),1);

            if isempty(idx)
                error('Step "%s" not found.', stepName);
            end

            node = obj.nodes(idx);

            if ~strcmpi(node.kind,'stream')
                fprintf('Folder steps have no parameters.\n');
                return
            end

            if ~isfield(node.info,'parameters') || isempty(node.info.parameters)
                fprintf('Step "%s" has no parameters.\n', node.name);
                return
            end

            % ---------------------------------------
            % Build dialog
            % ---------------------------------------
            [out,state] = obj.buildParameterDialog(node);

            if ~state || isempty(out)
                return
            end

            % ---------------------------------------
            % Validate and save values
            % ---------------------------------------
            candidateParams = node.info.parameters;
            for i = 1:numel(candidateParams)
                candidateParams(i).value = out{i};
            end

            paramErrors = obj.validateParameterStructArray(candidateParams, node.name);
            if ~isempty(paramErrors)
                error('PipelineManager:setParameters:InvalidParameters', ...
                    '%s', strjoin(paramErrors, newline));
            end

            obj.nodes(idx).info.parameters = candidateParams;
            obj.nodes(idx).runtime.b_paramsSet = true;

            fprintf('Parameters updated for step: %s\n', node.name);
        end

        function stepTag = addStep(obj, funcName, varargin)
            %ADDSTEP Add a processing step to the workflow.
            %
            %   stepTag = addStep(obj,'GSR')
            %   stepTag = addStep(obj,'GSR','input','SpatialFilter_1')
            %   stepTag = addStep(obj,'Compare','input',{'GSR_1','GSR_2'})
            %
            % Saving outputs (positional mapping to SAVEABLE outputs only):
            %   - Single saveable output:
            %       addStep(obj,'GSR','saveas','GSR.dat')
            %   - Multiple saveable outputs:
            %       addStep(obj,'MyFcn','saveas',{'A.dat','B.dat'})       % cellstr
            %       addStep(obj,'MyFcn','saveas',["A.dat","B.dat"])       % string array
            %
            % IMPORTANT:
            %   Outputs with outputMode='file' are NOT manager-saveable because the
            %   function already produces file(s). They may still have isData=true
            %   for DAG connectivity, but saveas does not apply to them.

            p = inputParser;
            addRequired(p,'funcName',@(x)ischar(x)||isstring(x));
            addParameter(p,'input',[],@(x)ischar(x)||isstring(x)||iscell(x)||isempty(x));
            addParameter(p,'saveas','',@(x) isempty(x) || ischar(x) || isstring(x) || iscell(x));
            parse(p,funcName,varargin{:});

            funcName = char(string(funcName));
            inputRef = p.Results.input;
            saveasList = obj.normalizeSaveAsInput(p.Results.saveas);

            % -------------------------------------------------------------
            % Create node (but ensure rollback on any downstream error)
            % -------------------------------------------------------------
            stepTag = obj.generateStepTag(funcName);
            info = obj.getPipelineInfo(funcName);

            node = obj.createNodeFromFuncInfo(funcName, info, ...
                'name', stepTag);

            nodeID = node.id;

            % -------------------------------------------------------------
            % Apply saveas mapping and resolve filename collisions
            % -------------------------------------------------------------
            node = obj.applySaveAsToNodeOutputs(node, saveasList, funcName);
            node = obj.resolveNodeSaveNameCollisions(node);

            % Snapshot state for rollback
            prevNodes       = obj.nodes;
            prevConnections = obj.connections;
            prevTopoOrder   = obj.topoOrder;
            prevActiveLeaf  = [];
            if isprop(obj,'activeLeafNodeID')
                prevActiveLeaf = obj.activeLeafNodeID;
            end

            % Commit node first, guarantee rollback in catch
            if isempty(obj.nodes)
                obj.nodes = node;
            else
                obj.nodes(end+1) = node;
            end

            try
                % -------------------------------------------------------------
                % Determine declared DATA inputs
                % -------------------------------------------------------------
                declaredInputs = node.info.inputs;
                mask = arrayfun(@(x) x.isData, declaredInputs);
                declaredInputs = declaredInputs(mask);
                nRequired = numel(declaredInputs);

                % -------------------------------------------------------------
                % Resolve input references
                % -------------------------------------------------------------
                if isempty(inputRef)

                    leafIDs = obj.getLeafNodeIDs();
                    leafIDs = leafIDs(leafIDs ~= nodeID);

                    if nRequired == 0
                        srcRefs = [];

                    elseif nRequired == 1

                        if isempty(leafIDs)
                            reqType = declaredInputs(1).type;

                            selection = obj.promptUserToSelectSource(reqType,'file');

                            if isempty(selection)
                                rollbackAndWarn( ...
                                    'PipelineManager:addStep:UserCancelled', ...
                                    'Input selection was cancelled. Step "%s" was not added.', ...
                                    stepTag);
                                return
                            end

                            srcID = obj.ensureFileSourceNode(selection.path, reqType);
                            srcRefs = srcID;

                        elseif numel(leafIDs) == 1
                            srcRefs = leafIDs;

                        else
                            useActive = false;
                            if isprop(obj,'activeLeafNodeID') && ~isempty(obj.activeLeafNodeID)
                                if ismember(obj.activeLeafNodeID, leafIDs)
                                    srcRefs = obj.activeLeafNodeID;
                                    useActive = true;
                                end
                            end

                            if ~useActive
                                fprintf('\nMultiple branches detected.\n');
                                obj.showBranches();
                                selTag = input('Select step tag to extend: ','s');
                                srcRefs = obj.resolveInputReference(selTag);

                                if isprop(obj,'activeLeafNodeID') && ~isempty(srcRefs) && isnumeric(srcRefs)
                                    obj.activeLeafNodeID = srcRefs(1);
                                end
                            end
                        end

                    else
                        error(['Step "%s" requires %d inputs. ' ...
                            'Merge must be explicit via ''input''.'], ...
                            funcName, nRequired);
                    end

                else
                    srcRefs = obj.resolveInputReference(inputRef);
                end

                % Normalize srcRefs
                if isstruct(srcRefs)
                    srcRefs = srcRefs(:)';
                    nProvided = numel(srcRefs);
                else
                    if ~iscell(srcRefs)
                        srcRefs = srcRefs(:)';
                    end
                    nProvided = numel(srcRefs);
                end

                if nProvided ~= nRequired
                    error('Step "%s" requires %d input(s), but %d provided.', ...
                        funcName, nRequired, nProvided);
                end

                % Duplicate function prevention per branch
                for iReq = 1:nRequired
                    if isstruct(srcRefs)
                        sid = srcRefs(iReq).nodeID;
                    else
                        sid = srcRefs(iReq);
                    end
                    upstreamFuncs = obj.getUpstreamFunctionNames(sid);
                    if any(strcmpi(upstreamFuncs,funcName))
                        rollbackAndWarn( ...
                            'PipelineManager:addStep:DuplicateFunctionInBranch', ...
                            'Function "%s" already exists upstream in this branch. Step "%s" was not added.', ...
                            {funcName, stepTag});
                        return
                    end
                end

                % Semantic compatibility check + connect
                for iReq = 1:nRequired

                    if isstruct(srcRefs)
                        srcNodeID    = srcRefs(iReq).nodeID;
                        forcedOut    = '';
                        forcedFile   = '';
                        if isfield(srcRefs(iReq),'outputName');   forcedOut  = srcRefs(iReq).outputName;   end
                        if isfield(srcRefs(iReq),'selectedFile'); forcedFile = srcRefs(iReq).selectedFile; end
                    else
                        srcNodeID  = srcRefs(iReq);
                        forcedOut  = '';
                        forcedFile = '';
                    end

                    srcNode = obj.nodes([obj.nodes.id] == srcNodeID);

                    if ~isfield(srcNode.info,'outputs') || isempty(srcNode.info.outputs)
                        error('Source node %d has no outputs.', srcNodeID);
                    end

                    dstTypes = declaredInputs(iReq).type;

                    if ~isempty(forcedOut)

                        outIdx = find(strcmpi({srcNode.info.outputs.name}, forcedOut), 1);
                        if isempty(outIdx)
                            error('Output "%s" not found in node %d.', forcedOut, srcNodeID);
                        end

                        out = srcNode.info.outputs(outIdx);

                        if ~out.isData
                            error('Output "%s" in node %d is not a DATA output.', forcedOut, srcNodeID);
                        end

                        srcTypes = out.type;
                        srcHasWildcard = any(strcmp(srcTypes,'UnknownDataType'));
                        dstHasWildcard = any(strcmp(dstTypes,'UnknownDataType'));

                        isCompatible = srcHasWildcard || dstHasWildcard || ...
                            ~isempty(intersect(srcTypes,dstTypes));

                        if ~isCompatible
                            error('Incompatible types for forced output "%s" from node %d.', forcedOut, srcNodeID);
                        end

                        obj.connectNodes(srcNodeID, nodeID, out.name, declaredInputs(iReq).name, forcedFile);
                        continue
                    end

                    compatibleOutputs = [];

                    for jOut = 1:numel(srcNode.info.outputs)

                        out = srcNode.info.outputs(jOut);

                        if ~out.isData
                            continue
                        end

                        srcTypes = out.type;

                        srcHasWildcard = any(strcmp(srcTypes,'UnknownDataType'));
                        dstHasWildcard = any(strcmp(dstTypes,'UnknownDataType'));

                        isCompatible = srcHasWildcard || dstHasWildcard || ...
                            ~isempty(intersect(srcTypes,dstTypes));

                        if isCompatible
                            compatibleOutputs = [compatibleOutputs jOut]; %#ok<AGROW>
                        end
                    end

                    if isempty(compatibleOutputs)
                        error('No compatible DATA output found in node %d for step "%s".', ...
                            srcNodeID, funcName);
                    end

                    selectedIdx = [];

                    if numel(compatibleOutputs) == 1
                        selectedIdx = compatibleOutputs(1);

                    else
                        dataOutputs = compatibleOutputs( ...
                            strcmpi({srcNode.info.outputs(compatibleOutputs).outputMode}, 'data'));

                        if numel(dataOutputs) == 1
                            selectedIdx = dataOutputs(1);

                        elseif isempty(dataOutputs)
                            fileOutputs = compatibleOutputs( ...
                                strcmpi({srcNode.info.outputs(compatibleOutputs).outputMode}, 'file'));

                            if numel(fileOutputs) == 1
                                selectedIdx = fileOutputs(1);
                            else
                                fprintf('\nMultiple file outputs available from step "%s":\n', srcNode.name);

                                for ii = 1:numel(fileOutputs)
                                    out = srcNode.info.outputs(fileOutputs(ii));
                                    defStr = '';
                                    if isfield(out,'defOutfilename') && ~isempty(out.defOutfilename)
                                        if iscell(out.defOutfilename)
                                            defStr = sprintf('%d file(s)', numel(out.defOutfilename));
                                        else
                                            defStr = char(string(out.defOutfilename));
                                        end
                                    end
                                    fprintf('  %d) %s  (default: %s)\n', ii, out.name, defStr);
                                end

                                choice = input('Select output to use: ');

                                if isempty(choice) || choice < 1 || choice > numel(fileOutputs)
                                    error('Invalid output selection.');
                                end

                                selectedIdx = fileOutputs(choice);
                            end
                        else
                            error(['Multiple in-memory compatible outputs found in node %d. ' ...
                                'Please specify explicitly.'], srcNodeID);
                        end
                    end

                    out = srcNode.info.outputs(selectedIdx);
                    selectedFile = '';

                    if isfield(out,'outputMode') && strcmpi(out.outputMode,'file')
                        fileChoices = {};
                        if isfield(out,'defOutfilename') && ~isempty(out.defOutfilename)
                            if iscell(out.defOutfilename)
                                fileChoices = cellfun(@(x) char(string(x)), out.defOutfilename, 'UniformOutput', false);
                            else
                                fileChoices = {char(string(out.defOutfilename))};
                            end
                            fileChoices = fileChoices(~cellfun(@isempty, fileChoices));
                            fileChoices = unique(fileChoices,'stable');
                        end

                        if numel(fileChoices) > 1
                            fprintf('\nMultiple declared files available from output "%s" in step "%s":\n', ...
                                out.name, srcNode.name);
                            for ii = 1:numel(fileChoices)
                                fprintf('  %d) %s\n', ii, fileChoices{ii});
                            end

                            choice = input('Select file index to use from list: ');

                            if isempty(choice) || choice < 1 || choice > numel(fileChoices)
                                error('Invalid file selection.');
                            end

                            selectedFile = fileChoices{choice};
                        elseif numel(fileChoices) == 1
                            selectedFile = fileChoices{1};
                        end
                    end

                    obj.connectNodes(srcNodeID, nodeID, out.name, declaredInputs(iReq).name, selectedFile);
                end

                obj.updateTopoOrder();
                obj.autoValidate();

                if isprop(obj,'activeLeafNodeID')
                    obj.activeLeafNodeID = nodeID;
                end
                if strcmpi(obj.nodes(end).kind,'stream')
                    fprintf('Function "%s" added to the pipeline\n', obj.nodes(end).info.name)
                end

            catch ME
                rollbackState();
                rethrow(ME);
            end

            function rollbackState()
                obj.nodes       = prevNodes;
                obj.connections = prevConnections;
                obj.topoOrder   = prevTopoOrder;

                if isprop(obj,'activeLeafNodeID')
                    obj.activeLeafNodeID = prevActiveLeaf;
                end
            end

            function rollbackAndWarn(warnID, warnMsg, vararginLocal)
                beep()
                warning(warnID, warnMsg, vararginLocal{:});

                rollbackState();
                stepTag = '';
            end
        end

        function state = setSaveTargets(obj, stepName, saveas)
            %SETSAVETARGETS Configure PipelineManager-managed save targets for one step.
            %
            %   state = obj.setSaveTargets(stepName, saveas)
            %
            %   Inputs:
            %       stepName - Step tag of an existing stream node.
            %       saveas   - Same contract as addStep(...,'saveas',...), but applies
            %                  only to SAVEABLE outputs:
            %                      isData == true AND outputMode ~= 'file'
            %                  * '' or [] clears all save targets
            %                  * scalar filename applies to a single saveable output only
            %                  * list of filenames must match the number of saveable outputs
            %
            %   Output:
            %       state    - True if the save targets were applied successfully.

            state = false;

            if isempty(obj.nodes)
                error('Pipeline is empty.');
            end

            stepName = char(string(stepName));
            if isempty(strtrim(stepName))
                error('setSaveTargets:InvalidStepName', 'stepName cannot be empty.');
            end

            idx = find(strcmpi(stepName, {obj.nodes.name}), 1, 'first');
            if isempty(idx)
                error('setSaveTargets:UnknownStep', 'Step "%s" not found.', stepName);
            end

            node = obj.nodes(idx);

            if ~strcmpi(node.kind,'stream')
                error('setSaveTargets:FolderStep', ...
                    'Folder steps do not support PipelineManager-managed save targets.');
            end

            saveasList = obj.normalizeSaveAsInput(saveas);

            funcNameForMsg = char(string(node.name));
            if isfield(node,'info') && isfield(node.info,'name') && ~isempty(node.info.name)
                funcNameForMsg = char(string(node.info.name));
            end

            node = obj.applySaveAsToNodeOutputs(node, saveasList, funcNameForMsg);
            node = obj.resolveNodeSaveNameCollisions(node, 'excludeNodeID', node.id);

            obj.nodes(idx) = node;
            obj.autoValidate();

            fprintf('Save targets updated for step: %s\n', node.name);
            state = true;
        end

        function rmStep(obj, stepTag)
            %RMSTEP Remove a step by tag.

            stepTag = char(string(stepTag));

            idx = find(strcmp({obj.nodes.name},stepTag),1);
            if isempty(idx)
                error('Step "%s" not found.',stepTag);
            end

            nodeID = obj.nodes(idx).id;

            % Remove connections
            mask = [obj.connections.sourceNodeID] ~= nodeID & ...
                [obj.connections.targetNodeID] ~= nodeID;

            obj.connections = obj.connections(mask);

            if strcmpi(obj.nodes(idx).kind,'folder')
                msg = sprintf('Source file "%s" removed from the pipeline.\n',obj.nodes(idx).name);
            else
                msg = sprintf('Function "%s" removed from the pipeline\n',obj.nodes(idx).name);
            end
            % Remove node
            obj.nodes(idx) = [];

            obj.updateTopoOrder();
            obj.autoValidate();

            disp(msg);
        end

        function removed = removeInvalidNodes(obj, varargin)
            %REMOVEINVALIDNODES Remove nodes that participate in validation errors.
            %
            %   removed = REMOVEINVALIDNODES(obj)
            %   removed = REMOVEINVALIDNODES(obj,'maxPasses',N)
            %
            % Behavior:
            %   - Iteratively validates the DAG and removes nodes implicated in errors.
            %   - Removes all incident connections of removed nodes.
            %   - After validation passes, removes any completely disconnected FOLDER nodes.
            %     Assumption: folder nodes are always roots (no incoming edges).
            %     Therefore, a folder is disconnected iff it is a leaf (no outgoing edges).
            %   - Runs obj.autoValidate() at the end.
            %   - If still invalid after max passes, raises a warning.
            %
            % Output:
            %   removed (double row vector) nodeIDs removed (in removal order)

            p = inputParser;
            addParameter(p,'maxPasses',50,@(x)isnumeric(x)&&isscalar(x)&&x>=1);
            parse(p,varargin{:});
            maxPasses = p.Results.maxPasses;

            removed = [];

            if isempty(obj.nodes)
                obj.autoValidate();
                return
            end

            % -------------------------------------------------------------
            % Pass 1: Remove nodes implicated in validation errors
            % -------------------------------------------------------------
            for pass = 1:maxPasses

                [tf, report] = obj.validateGraph('throwOnError', false);

                if tf
                    break
                end

                % Extract candidate node IDs from error messages (best-effort)
                ids = localExtractNodeIDs(report.errors);

                % Keep only IDs that still exist in the graph
                ids = unique(ids,'stable');
                ids = ids(ismember(ids, [obj.nodes.id]));
                ids = ids(~ismember(ids, removed));

                % Fallback for dangling-edge cases:
                % when validation only mentions a missing endpoint that is already
                % absent from obj.nodes, remove the still-present endpoint(s) of
                % the bad connection(s).
                if isempty(ids) && ~isempty(obj.connections)

                    existingIDs = [obj.nodes.id];

                    badConnMask = ~ismember([obj.connections.sourceNodeID], existingIDs) | ...
                        ~ismember([obj.connections.targetNodeID], existingIDs);

                    badConns = obj.connections(badConnMask);

                    if ~isempty(badConns)
                        candidateIDs = unique([badConns.sourceNodeID, badConns.targetNodeID], 'stable');
                        ids = candidateIDs(ismember(candidateIDs, existingIDs));
                        ids = ids(~ismember(ids, removed));
                    end
                end

                if isempty(ids)
                    % Final fallback: remove latest node
                    ids = obj.nodes(end).id;
                end

                % Remove all identified nodes this pass
                for k = 1:numel(ids)
                    nid = ids(k);

                    if ~ismember(nid, [obj.nodes.id])
                        continue
                    end

                    % Remove connections incident to nid
                    if ~isempty(obj.connections)
                        keep = ~([obj.connections.sourceNodeID] == nid | ...
                            [obj.connections.targetNodeID] == nid);
                        obj.connections = obj.connections(keep);
                    end

                    % Remove node
                    obj.nodes([obj.nodes.id] == nid) = [];
                    removed(end+1) = nid; %#ok<AGROW>
                end

                % Keep topoOrder coherent (best-effort)
                try
                    obj.updateTopoOrder();
                catch
                    obj.topoOrder = [];
                end
            end

            % -------------------------------------------------------------
            % Pass 2: Remove completely disconnected FOLDER nodes
            %   (independent of validateGraph)
            % -------------------------------------------------------------
            if ~isempty(obj.nodes)

                leafIDs = obj.getLeafNodeIDs();  % nodes with no outgoing edges

                if ~isempty(leafIDs)

                    isFolder = strcmpi({obj.nodes.kind}, 'folder');
                    folderLeafMask = isFolder & ismember([obj.nodes.id], leafIDs);
                    folderLeafIDs = [obj.nodes(folderLeafMask).id];

                    for kf = 1:numel(folderLeafIDs)

                        fid = folderLeafIDs(kf);

                        if ~ismember(fid, [obj.nodes.id])
                            continue
                        end

                        % Defensive removal of any residual edges
                        if ~isempty(obj.connections)
                            keep = ~([obj.connections.sourceNodeID] == fid | ...
                                [obj.connections.targetNodeID] == fid);
                            obj.connections = obj.connections(keep);
                        end

                        obj.nodes([obj.nodes.id] == fid) = [];
                        removed(end+1) = fid; %#ok<AGROW>
                    end
                end
            end

            % -------------------------------------------------------------
            % Final validation
            % -------------------------------------------------------------
            try
                obj.updateTopoOrder();
            catch
                obj.topoOrder = [];
            end

            obj.autoValidate();

            if isprop(obj,'b_pipeIsValid') && ~obj.b_pipeIsValid
                warning('PipelineManager:removeInvalidNodes:StillInvalid', ...
                    'Pipeline is still invalid after removing %d node(s). Run obj.diagnosePipeline() for details.', ...
                    numel(removed));
            else
                obj.diagnosePipeline('verbose',true);
                disp('Pipeline successfully fixed!')
            end

            % -------------------------------------------------------------
            function ids = localExtractNodeIDs(errs)
                % Parse integers following "nodeID" or "node" patterns.
                ids = [];
                if isempty(errs)
                    return
                end

                for ii = 1:numel(errs)
                    thisErr = errs{ii};

                    tok = regexp(thisErr, 'nodeID(?:\(s\))?\s*[:=]?\s*(\d+)', 'tokens');
                    if ~isempty(tok)
                        for jj = 1:numel(tok)
                            ids(end+1) = str2double(tok{jj}{1}); %#ok<AGROW>
                        end
                        continue
                    end

                    tok = regexp(thisErr, 'node\s+(\d+)', 'tokens');
                    if ~isempty(tok)
                        for jj = 1:numel(tok)
                            ids(end+1) = str2double(tok{jj}{1}); %#ok<AGROW>
                        end
                    end
                end

                ids = ids(~isnan(ids));
            end
        end

        function reconnectStep(obj, stepRef, varargin)
            %RECONNECTSTEP Explicitly reconnect a step's DATA inputs to explicit sources.
            %
            %   reconnectStep(obj, stepRef, 'input', inputRef)
            %
            %   STEPref (required):
            %       - step tag only (char/string), e.g. 'GSR_3'
            %
            %   inputRef (must be explicit; no auto-connect):
            %       Same syntax as addStep/resolveInputReference:
            %         - 'StepTag'                     allowed only if it resolves to
            %                                        exactly one compatible DATA output
            %         - 'filename.ext'               file injection; must exist in
            %                                        SaveFolderList{1}
            %         - 'StepTag:OutputPortName'     force specific output port
            %         - 'StepTag:filename.ext'       select a concrete file from a
            %                                        file-producing output
            %       For multi-input steps, pass a cell array with one entry per
            %       required DATA input:
            %         {'SrcA:outData', 'SrcB:green.dat'}
            %
            %   BEHAVIOR:
            %       - Disconnects ALL incoming connections to the step's DATA inputs.
            %       - Reconnects using ONLY the provided explicit inputRef(s).
            %       - Validates semantic compatibility (type intersection plus
            %         UnknownDataType wildcard).
            %       - Does not prompt or apply branch/leaf auto-selection logic.
            %       - Uses the same file-output ambiguity rules as addStep:
            %           * file outputs with exactly one declared filename are accepted
            %             without extra selection
            %           * file outputs with multiple declared filenames require an
            %             explicit selected file
            %       - Calls obj.updateTopoOrder() and obj.autoValidate() at the end.

            p = inputParser;
            addRequired(p,'stepRef',@(x)ischar(x)||isstring(x));
            addParameter(p,'input',[],@(x)ischar(x)||isstring(x)||iscell(x)||isempty(x));
            parse(p,stepRef,varargin{:});

            stepRef  = char(string(p.Results.stepRef));
            inputRef = p.Results.input;

            if isempty(strtrim(stepRef))
                error('PipelineManager:reconnectStep:InvalidStepRef', ...
                    'stepRef must be a non-empty step tag.');
            end

            if isempty(inputRef)
                error('PipelineManager:reconnectStep:ExplicitInputRequired', ...
                    'reconnectStep requires an explicit ''input'' argument.');
            end

            % -------------------------------------------------------------
            % Resolve target step (step tag only)
            % -------------------------------------------------------------
            idx = find(strcmpi({obj.nodes.name}, stepRef), 1);
            if isempty(idx)
                error('PipelineManager:reconnectStep:UnknownStep', ...
                    'Unknown step "%s".', stepRef);
            end

            node   = obj.nodes(idx);
            nodeID = node.id;

            if strcmpi(node.kind,'folder')
                error('PipelineManager:reconnectStep:FolderTarget', ...
                    'Folder steps cannot receive inputs.');
            end

            if ~isfield(node,'info') || ~isfield(node.info,'inputs') || isempty(node.info.inputs)
                error('PipelineManager:reconnectStep:NoInputs', ...
                    'Step "%s" (nodeID %d) has no inputs to reconnect.', node.name, nodeID);
            end

            % -------------------------------------------------------------
            % Determine declared DATA inputs (same as addStep)
            % -------------------------------------------------------------
            declaredInputs = node.info.inputs;
            mask = arrayfun(@(x) x.isData, declaredInputs);
            declaredInputs = declaredInputs(mask);
            nRequired = numel(declaredInputs);

            % -------------------------------------------------------------
            % Resolve explicit sources
            % -------------------------------------------------------------
            srcRefs = obj.resolveInputReference(inputRef);

            % Normalize srcRefs container
            srcRefs = srcRefs(:)'; % row vector / row struct array
            nProvided = numel(srcRefs);

            if nProvided ~= nRequired
                error('PipelineManager:reconnectStep:InputCountMismatch', ...
                    'Step "%s" requires %d DATA input(s), but %d provided.', ...
                    node.name, nRequired, nProvided);
            end

            % -------------------------------------------------------------
            % Enforce the same duplicate-function-per-branch rule used by addStep.
            % This must run before disconnecting the current inputs so a rejected
            % reconnect leaves the graph unchanged.
            % -------------------------------------------------------------
            obj.validateReconnectDuplicateFunctionRule(nodeID, srcRefs);

            % -------------------------------------------------------------
            % Disconnect ALL incoming edges to this step's DATA inputs
            % -------------------------------------------------------------
            if ~isempty(obj.connections)
                keep = true(1, numel(obj.connections));

                inNamesAll = {node.info.inputs.name};

                for ii = 1:numel(obj.connections)
                    c = obj.connections(ii);

                    if c.targetNodeID ~= nodeID
                        continue
                    end

                    inIdx = find(strcmpi(inNamesAll, c.targetInputName), 1);

                    if ~isempty(inIdx) && node.info.inputs(inIdx).isData
                        keep(ii) = false;
                    end
                end

                obj.connections = obj.connections(keep);
            end

            % -------------------------------------------------------------
            % Reconnect explicitly (no prompting, no ambiguous auto-selection)
            % -------------------------------------------------------------
            for k = 1:nRequired

                dstIn = declaredInputs(k);
                dstTypes = dstIn.type;

                % Source spec
                if isstruct(srcRefs)
                    srcNodeID  = srcRefs(k).nodeID;

                    forcedOut  = '';
                    forcedFile = '';
                    if isfield(srcRefs(k),'outputName');   forcedOut  = srcRefs(k).outputName;   end
                    if isfield(srcRefs(k),'selectedFile'); forcedFile = srcRefs(k).selectedFile; end
                else
                    srcNodeID  = srcRefs(k);
                    forcedOut  = '';
                    forcedFile = '';
                end

                srcNode = obj.nodes([obj.nodes.id] == srcNodeID);

                if ~isfield(srcNode,'info') || ~isfield(srcNode.info,'outputs') || isempty(srcNode.info.outputs)
                    error('PipelineManager:reconnectStep:SourceNoOutputs', ...
                        'Source node %d has no outputs.', srcNodeID);
                end

                outs = srcNode.info.outputs;

                % ---------------------------------------------------------
                % If user forced an output port, validate + connect
                % ---------------------------------------------------------
                if ~isempty(forcedOut)

                    outIdx = find(strcmpi({outs.name}, forcedOut), 1);
                    if isempty(outIdx)
                        error('PipelineManager:reconnectStep:InvalidSourceOutput', ...
                            'Output "%s" not found in node %d.', forcedOut, srcNodeID);
                    end

                    out = outs(outIdx);

                    if ~out.isData
                        error('PipelineManager:reconnectStep:NonDataOutput', ...
                            'Output "%s" in node %d is not a DATA output.', forcedOut, srcNodeID);
                    end

                    srcTypes = out.type;
                    srcHasWildcard = any(strcmp(srcTypes,'UnknownDataType'));
                    dstHasWildcard = any(strcmp(dstTypes,'UnknownDataType'));
                    isCompatible = srcHasWildcard || dstHasWildcard || ~isempty(intersect(srcTypes, dstTypes));

                    if ~isCompatible
                        error('PipelineManager:reconnectStep:TypeMismatch', ...
                            'Incompatible types: node %d output "%s" -> step "%s" input "%s".', ...
                            srcNodeID, out.name, node.name, dstIn.name);
                    end

                    selectedFile = resolveSelectedFileForOutput(out, forcedFile, srcNode.name);
                    obj.connectNodes(srcNodeID, nodeID, out.name, dstIn.name, selectedFile);
                    continue
                end

                % ---------------------------------------------------------
                % No forced output: require EXACTLY ONE compatible DATA output
                % ---------------------------------------------------------
                compatible = [];

                for j = 1:numel(outs)

                    out = outs(j);

                    if ~out.isData
                        continue
                    end

                    srcTypes = out.type;
                    srcHasWildcard = any(strcmp(srcTypes,'UnknownDataType'));
                    dstHasWildcard = any(strcmp(dstTypes,'UnknownDataType'));
                    isCompatible = srcHasWildcard || dstHasWildcard || ~isempty(intersect(srcTypes, dstTypes));

                    if isCompatible
                        compatible = [compatible j]; %#ok<AGROW>
                    end
                end

                if isempty(compatible)
                    error('PipelineManager:reconnectStep:NoCompatibleOutput', ...
                        'No compatible DATA outputs found in node %d for step "%s" input "%s".', ...
                        srcNodeID, node.name, dstIn.name);
                end

                if numel(compatible) > 1
                    error('PipelineManager:reconnectStep:AmbiguousOutput', ...
                        ['Multiple compatible outputs found in node %d for step "%s" input "%s". ' ...
                        'Use explicit "StepTag:OutputPortName" (or "StepTag:filename.ext" for file outputs).'], ...
                        srcNodeID, node.name, dstIn.name);
                end

                % If user provided selectedFile without explicit outputName, reject
                if ~isempty(forcedFile)
                    error('PipelineManager:reconnectStep:SelectedFileRequiresExplicitOutput', ...
                        ['A selected file was provided without specifying an output port. ' ...
                        'Use the "StepTag:filename.ext" syntax (which sets the output port implicitly).']);
                end

                out = outs(compatible(1));
                selectedFile = resolveSelectedFileForOutput(out, '', srcNode.name);

                obj.connectNodes(srcNodeID, nodeID, out.name, dstIn.name, selectedFile);
            end

            % -------------------------------------------------------------
            % Finalize
            % -------------------------------------------------------------
            obj.updateTopoOrder();
            obj.autoValidate();

            % =========================================================
            % Local helper: resolve file selection for file-producing outputs
            % =========================================================
            function selectedFile = resolveSelectedFileForOutput(outDef, requestedFile, srcNodeName)
                %RESOLVESELECTEDFILEFOROUTPUT Resolve concrete file selection for a source output.
                %
                %   selectedFile = resolveSelectedFileForOutput(outDef, requestedFile, srcNodeName)
                %   applies the same ambiguity rules as addStep:
                %       - non-file outputs -> ''
                %       - file outputs with one declared filename -> auto-select it
                %       - file outputs with multiple declared filenames -> require
                %         requestedFile and validate it against the declared list

                selectedFile = '';

                isFileOutput = isfield(outDef,'outputMode') && strcmpi(outDef.outputMode,'file');
                if ~isFileOutput
                    return
                end

                fileChoices = {};
                if isfield(outDef,'defOutfilename') && ~isempty(outDef.defOutfilename)
                    if iscell(outDef.defOutfilename)
                        fileChoices = cellfun(@(x) char(string(x)), outDef.defOutfilename, 'UniformOutput', false);
                    else
                        fileChoices = {char(string(outDef.defOutfilename))};
                    end
                    fileChoices = fileChoices(~cellfun(@isempty, fileChoices));
                    fileChoices = unique(fileChoices, 'stable');
                end

                if isempty(fileChoices)
                    % Keep empty selection if metadata does not declare a concrete file list.
                    % Downstream validation/runtime may still resolve the file.
                    return
                end

                if numel(fileChoices) == 1
                    if ~isempty(requestedFile) && ~any(strcmpi(requestedFile, fileChoices))
                        error('PipelineManager:reconnectStep:InvalidSelectedFile', ...
                            ['Requested file "%s" is not declared for output "%s" in step "%s". ' ...
                            'Declared file: %s'], ...
                            requestedFile, outDef.name, srcNodeName, fileChoices{1});
                    end
                    selectedFile = fileChoices{1};
                    return
                end

                % Multiple declared files -> explicit selection required
                if isempty(requestedFile)
                    error('PipelineManager:reconnectStep:AmbiguousFileOutput', ...
                        ['Output "%s" in step "%s" can produce multiple declared files. ' ...
                        'Reconnect explicitly using "StepTag:filename.ext".'], ...
                        outDef.name, srcNodeName);
                end

                if ~any(strcmpi(requestedFile, fileChoices))
                    error('PipelineManager:reconnectStep:InvalidSelectedFile', ...
                        ['Requested file "%s" is not declared for output "%s" in step "%s". ' ...
                        'Declared files: %s'], ...
                        requestedFile, outDef.name, srcNodeName, strjoin(fileChoices, ', '));
                end

                selectedFile = requestedFile;
            end
        end

        function showFuncList(obj)
            % Displays a list of analysis function from "obj.funcList" in
            % the command window.
            disp('List of available functions (Caterogy):');
            folderList = erase(obj.truncateFolderList({obj.funcList.folder}),['...' filesep]);
            for i = 1:length(obj.funcList)
                fprintf('%d : %s (%s)\n', i, obj.funcList(i).name, folderList{i});
            end
        end

        function result = executePipeline(obj, varargin)
            %EXECUTEPIPELINE Orchestrate execution across all SaveFolders.
            %
            %   result = executePipeline(obj)
            %   result = executePipeline(obj, 'LeafOutputPolicy', policy)
            %   result = executePipeline(obj, 'ProgressFcn', fcn, 'CancelFcn', fcn)
            %
            %   EXECUTEPIPELINE validates the current DAG, builds a structured
            %   execution plan, executes the pipeline over each SaveFolder/RawFolder
            %   pair, and returns a structured result. The GUI should consume the
            %   returned result instead of reconstructing execution information from
            %   command-window text.
            %
            %   Name-Value options:
            %       LeafOutputPolicy - Optional per-run override for obj.leafOutputPolicy.
            %                          Accepted values match obj.setLeafOutputPolicy.
            %       PrintSummary      - Logical scalar. If true, prints obj.globalPipeLog.
            %                          Default: true.
            %       ProgressFcn       - Optional function handle called with a scalar
            %                          progress-event struct at folder/step boundaries.
            %       CancelFcn         - Optional function handle returning a logical
            %                          scalar. Cancellation is cooperative and is
            %                          checked before folders, before steps, before
            %                          history/preload work, and before loading files
            %                          into RAM. A running analysis function must
            %                          finish before cancellation can be completed.

            p = inputParser;
            addParameter(p, 'LeafOutputPolicy', obj.leafOutputPolicy, @(x)ischar(x)||isstring(x));
            addParameter(p, 'PrintSummary', true, @(x)islogical(x)&&isscalar(x));
            addParameter(p, 'ProgressFcn', [], @(x) isempty(x) || isa(x, 'function_handle'));
            addParameter(p, 'CancelFcn', [], @(x) isempty(x) || isa(x, 'function_handle'));
            parse(p, varargin{:});

            runLeafPolicy = obj.resolveLeafOutputPolicy(p.Results.LeafOutputPolicy);
            printSummary = logical(p.Results.PrintSummary);
            progressFcn = p.Results.ProgressFcn;
            cancelFcn = p.Results.CancelFcn;

            previousRunPolicy = obj.currentLeafOutputPolicy;
            previousSessionTag = obj.currentTempSessionTag;
            cleanupRunState = onCleanup(@() obj.restoreExecutionRunState( ...
                previousRunPolicy, previousSessionTag)); %#ok<NASGU>

            obj.currentLeafOutputPolicy = runLeafPolicy;
            obj.currentTempSessionTag = obj.makeTempSessionTag();
            obj.executionProgressLog = struct([]);
            obj.currentExecutionWasCancelled = false;

            executionStartedOn = datetime('now');
            nFolders = numel(obj.SaveFolderList);

            obj.emitExecutionProgress(progressFcn, 'runStarted', ...
                'numFolders', nFolders, ...
                'status', 'running', ...
                'message', 'Pipeline execution started.');

            % -------------------------------------------------------------
            % 0) Validate workflow before execution
            % -------------------------------------------------------------
            obj.emitExecutionProgress(progressFcn, 'validationStarted', ...
                'numFolders', nFolders, ...
                'status', 'running', ...
                'message', 'Validating pipeline before execution.');

            b_isValid = obj.validateGraph();
            if ~b_isValid
                error('PipelineManager:executePipeline:InvalidGraph', ...
                    'Pipeline validation failed. Run obj.diagnosePipeline() for details. Fix graph errors before execution.');
            end

            % Validate configured parameter values before any folder-level work.
            obj.validateNodeParameters('throwOnError', true);
            obj.validateNodePreflight('throwOnError', true);

            obj.updateTopoOrder();

            if isempty(obj.topoOrder)
                error('PipelineManager:executePipeline:EmptyGraph', ...
                    'Pipeline is empty.');
            end

            if isempty(obj.SaveFolderList)
                error('PipelineManager:executePipeline:NoFolders', ...
                    'No SaveFolder specified.');
            end

            % -------------------------------------------------------------
            % 0a) Refuse legacy-schema SaveFolders (silent-wrong-result risk)
            % -------------------------------------------------------------
            legacyFolders = {};
            legacyMessages = {};
            for f = 1:numel(obj.SaveFolderList)
                [isLegacyFolder, legacyMessage] = isLegacySchemaFolder(obj.SaveFolderList{f});
                if isLegacyFolder
                    legacyFolders{end+1} = obj.SaveFolderList{f}; %#ok<AGROW>
                    legacyMessages{end+1} = legacyMessage; %#ok<AGROW>
                end
            end

            if ~isempty(legacyFolders)
                detailLines = strings(1, numel(legacyFolders));
                for iF = 1:numel(legacyFolders)
                    detailLines(iF) = sprintf('  %s\n    %s', legacyFolders{iF}, legacyMessages{iF});
                end
                error('PipelineManager:executePipeline:LegacySchema', ...
                    'Pipeline execution blocked for legacy-schema SaveFolder(s):\n%s', ...
                    strjoin(detailLines, '\n'));
            end

            obj.emitExecutionProgress(progressFcn, 'validationFinished', ...
                'numFolders', nFolders, ...
                'status', 'completed', ...
                'message', 'Pipeline validation completed.');

            if obj.checkExecutionCancelRequested(cancelFcn, progressFcn, 'before execution planning', ...
                    'numFolders', nFolders)
                obj.currentExecutionWasCancelled = true;
            end

            % -------------------------------------------------------------
            % 0b) RAM-safe compatibility and execution-role checks
            % -------------------------------------------------------------
            if ~obj.currentExecutionWasCancelled
                obj.validateRamSafeCompatibility();
                obj.warnEnforcedExecutionRoles(obj.topoOrder);
            end

            % Build the primary execution summary before any step runs.
            if ~obj.currentExecutionWasCancelled
                executionPlan = obj.getExecutionPlan( ...
                    'LeafOutputPolicy', runLeafPolicy, ...
                    'SaveFolder', obj.SaveFolderList{1});
            else
                executionPlan = struct( ...
                    'createdOn', datetime('now'), ...
                    'leafOutputPolicy', string(runLeafPolicy), ...
                    'tempOutputPrefix', string(obj.tempOutputPrefix), ...
                    'tempSessionTag', string(obj.currentTempSessionTag), ...
                    'saveFolder', "", ...
                    'nodeOrders', struct(), ...
                    'nodeTable', table(), ...
                    'edgeTable', table(), ...
                    'outputPlan', table(), ...
                    'validationReport', obj.diagnosePipeline('verbose', false));
            end
            obj.lastExecutionPlan = executionPlan;

            % -------------------------------------------------------------
            % 0c) Determine whether current DAG requires RawFolder
            % -------------------------------------------------------------
            if ~obj.currentExecutionWasCancelled
                b_pipelineRequiresRawFolder = obj.pipelineRequiresRawFolder();
            else
                b_pipelineRequiresRawFolder = false;
            end

            % -------------------------------------------------------------
            % 0d) Reset current-run global summary log
            % -------------------------------------------------------------
            obj.globalPipeLog = table();

            % -------------------------------------------------------------
            % 1) Loop over folders
            % -------------------------------------------------------------
            for f = 1:numel(obj.SaveFolderList)

                saveFolder = obj.SaveFolderList{f};
                rawFolder  = obj.RawFolderList{f};

                folderStartedOn = datetime('now');
                folderFatalME   = [];
                folderWasSkipped = false;
                folderWasCancelled = false;
                folderSkipMsg    = "";

                obj.current_outFile = {};

                folderNameForMsg = obj.getFolderDisplayName(saveFolder);
                obj.emitExecutionProgress(progressFcn, 'folderStarted', ...
                    'folderIndex', f, ...
                    'numFolders', nFolders, ...
                    'saveFolder', saveFolder, ...
                    'rawFolder', rawFolder, ...
                    'status', 'running', ...
                    'message', sprintf('Running folder %d/%d: %s', f, nFolders, folderNameForMsg));

                if obj.checkExecutionCancelRequested(cancelFcn, progressFcn, 'before folder', ...
                        'folderIndex', f, ...
                        'numFolders', nFolders, ...
                        'saveFolder', saveFolder, ...
                        'rawFolder', rawFolder)

                    folderWasCancelled = true;
                    obj.currentExecutionWasCancelled = true;
                    folderSkipMsg = "Cancelled by user before folder execution.";
                    obj.folderPipeLog = table();
                    nRowsBefore = 0;

                else
                    % ---------------------------------------------------------
                    % 2) Initialize pipeLog table
                    % ---------------------------------------------------------
                    obj.loadPipeLog(saveFolder);

                    if istable(obj.folderPipeLog)
                        nRowsBefore = height(obj.folderPipeLog);
                    else
                        obj.folderPipeLog = table();
                        nRowsBefore = 0;
                    end

                    % ---------------------------------------------------------
                    % 3) Skip this item if RawFolder is missing and DAG requires it
                    % ---------------------------------------------------------
                    if b_pipelineRequiresRawFolder && strcmpi(strtrim(char(string(rawFolder))), 'Missing')

                        folderWasSkipped = true;
                        folderSkipMsg = "Skipped: RawFolder is missing and the current pipeline requires RawFolder input.";

                        warning('PipelineManager:executePipeline:MissingRawFolder', ...
                            ['Skipping SaveFolder item because RawFolder is "Missing" and ' ...
                            'the current pipeline requires RawFolder input.\nSaveFolder: %s'], ...
                            saveFolder);

                        obj.emitExecutionProgress(progressFcn, 'folderSkipped', ...
                            'folderIndex', f, ...
                            'numFolders', nFolders, ...
                            'saveFolder', saveFolder, ...
                            'rawFolder', rawFolder, ...
                            'status', 'skipped', ...
                            'message', char(folderSkipMsg));

                    else
                        % ---------------------------------------------------------
                        % 4) Reset runtime state
                        % ---------------------------------------------------------
                        obj.executionTrace = [];

                        for k = 1:numel(obj.nodes)
                            obj.nodes(k).runtime.preloadedData     = struct();
                            obj.nodes(k).runtime.startedOn         = [];
                            obj.nodes(k).runtime.finishedOn        = [];
                            obj.nodes(k).runtime.b_executed        = false;
                            obj.nodes(k).runtime.lastError         = [];
                            obj.nodes(k).runtime.cooldownRemaining = 0;
                            obj.nodes(k).runtime.filePreferred     = false;

                            % Reset history/cache-derived runtime flags so they cannot leak
                            % from a previous folder or previous run.
                            obj.nodes(k).runtime.leafCachedFile    = [];
                            obj.nodes(k).runtime.leafCachedNodeIDs = [];
                        end

                        % ---------------------------------------------------------
                        % 5) Load data history
                        % ---------------------------------------------------------
                        if obj.checkExecutionCancelRequested(cancelFcn, progressFcn, 'before loading data history', ...
                                'folderIndex', f, ...
                                'numFolders', nFolders, ...
                                'saveFolder', saveFolder, ...
                                'rawFolder', rawFolder)

                            folderWasCancelled = true;
                            obj.currentExecutionWasCancelled = true;
                            folderSkipMsg = "Cancelled by user before loading data history.";

                        else
                            obj.loadDataHistory(saveFolder);
                        end

                        % ---------------------------------------------------------
                        % 6) Apply history-based matching only if enabled
                        % ---------------------------------------------------------
                        if ~folderWasCancelled
                            if obj.checkExecutionCancelRequested(cancelFcn, progressFcn, 'before history preload matching', ...
                                    'folderIndex', f, ...
                                    'numFolders', nFolders, ...
                                    'saveFolder', saveFolder, ...
                                    'rawFolder', rawFolder)

                                folderWasCancelled = true;
                                obj.currentExecutionWasCancelled = true;
                                folderSkipMsg = "Cancelled by user before history preload matching.";

                            elseif obj.b_skipSteps
                                obj.matchHistoryAndSetPreload(saveFolder);
                            else
                                fprintf('[CACHE] Step skipping disabled. Existing files will be ignored for execution planning.\n');
                            end
                        end

                        % ---------------------------------------------------------
                        % 7) Delegate execution
                        % ---------------------------------------------------------
                        if ~folderWasCancelled
                            try
                                folderWasCancelled = obj.runPipelineOnFolder( ...
                                    saveFolder, rawFolder, progressFcn, cancelFcn, f, nFolders);

                                if folderWasCancelled
                                    obj.currentExecutionWasCancelled = true;
                                    folderSkipMsg = "Cancelled by user. The current function finished before PipelineManager stopped.";
                                end

                            catch ME
                                if strcmp(ME.identifier, 'PipelineManager:ExecutionCancelled')
                                    folderWasCancelled = true;
                                    obj.currentExecutionWasCancelled = true;
                                    folderSkipMsg = "Cancelled by user. The current function finished before PipelineManager stopped.";
                                else
                                    folderFatalME = ME;

                                    warning('PipelineManager:executePipeline:FolderFailed', ...
                                        'Execution failed for folder: %s\n%s', ...
                                        saveFolder, ME.message);
                                end
                            end
                        end
                    end
                end

                folderFinishedOn = datetime('now');
                folderDuration_s = seconds(folderFinishedOn - folderStartedOn);

                % ---------------------------------------------------------
                % 8) Summarize current folder execution into globalPipeLog
                % ---------------------------------------------------------
                if istable(obj.folderPipeLog) && height(obj.folderPipeLog) > nRowsBefore
                    folderRunLog = obj.folderPipeLog(nRowsBefore+1:end,:);
                else
                    folderRunLog = table();
                end

                if folderWasCancelled

                    globalStatus = "Cancelled";
                    shortErrMsg  = folderSkipMsg;
                    outputFilesStr = "";

                elseif folderWasSkipped

                    globalStatus = "Skipped";
                    shortErrMsg  = folderSkipMsg;
                    outputFilesStr = "";

                else

                    hasExecuted = false;
                    hasPreloaded = false;
                    hasFailed = false;
                    hasBlocked = false;

                    if ~isempty(folderRunLog)
                        statusStrs = string(folderRunLog.Status);

                        hasExecuted = any(strcmpi(statusStrs, 'executed'));
                        hasPreloaded = any(strcmpi(statusStrs, 'skipped_preloaded'));
                        hasFailed = any(strcmpi(statusStrs, 'failed'));
                        hasBlocked = any(strcmpi(statusStrs, 'skipped_upstream_failed'));
                    end

                    % Treat unexpected folder-level failure as a failure signal too
                    if ~isempty(folderFatalME)
                        hasFailed = true;
                    end

                    if ~hasFailed && ~hasBlocked
                        globalStatus = "Completed";
                    elseif ~(hasExecuted || hasPreloaded)
                        globalStatus = "Failed";
                    else
                        globalStatus = "Partially executed";
                    end

                    % ---------------------------------------------------------
                    % Build short error summary
                    % ---------------------------------------------------------
                    msgList = strings(0,1);

                    if ~isempty(folderRunLog) && any(ismember(folderRunLog.Properties.VariableNames, {'Messages_short','Status'}))
                        keepMask = strcmpi(string(folderRunLog.Status), 'failed') | ...
                            strcmpi(string(folderRunLog.Status), 'skipped_upstream_failed');

                        if any(keepMask)
                            tmpMsgs = string(folderRunLog.Messages_short(keepMask));
                            tmpMsgs = strip(tmpMsgs);
                            tmpMsgs = tmpMsgs(strlength(tmpMsgs) > 0);
                            msgList = [msgList; tmpMsgs(:)]; %#ok<AGROW>
                        end
                    end

                    if ~isempty(folderFatalME)
                        if ~isempty(folderFatalME.stack)
                            fatalShort = sprintf('%s (Function: %s, Line: %d)', ...
                                folderFatalME.message, ...
                                folderFatalME.stack(1).name, ...
                                folderFatalME.stack(1).line);
                        else
                            fatalShort = folderFatalME.message;
                        end
                        msgList(end+1,1) = string(fatalShort); %#ok<AGROW>
                    end

                    msgList = unique(msgList, 'stable');

                    if isempty(msgList)
                        shortErrMsg = "No Errors";
                    else
                        shortErrMsg = strjoin(msgList, " | ");
                    end

                    % ---------------------------------------------------------
                    % Files created during this run only
                    % ---------------------------------------------------------
                    if isempty(obj.current_outFile)
                        outputFilesStr = "";
                    else
                        outFiles = string(obj.current_outFile(:));
                        outFiles = strip(outFiles);
                        outFiles = outFiles(strlength(outFiles) > 0);
                        outFiles = unique(outFiles, 'stable');

                        if isempty(outFiles)
                            outputFilesStr = "";
                        else
                            outputFilesStr = strjoin(outFiles, ", ");
                        end
                    end
                end

                % ---------------------------------------------------------
                % Append one summary row for this folder
                % ---------------------------------------------------------
                newRow = table( ...
                    {char(string(obj.SaveFolderList_truncated{f}))}, ...
                    {char(string(obj.RawFolderList_truncated{f}))}, ...
                    {char(globalStatus)}, ...
                    {char(shortErrMsg)}, ...
                    folderStartedOn, ...
                    folderFinishedOn, ...
                    folderDuration_s, ...
                    {char(outputFilesStr)}, ...
                    'VariableNames', { ...
                    'SaveFolder', ...
                    'RawFolder', ...
                    'Status', ...
                    'Messages_short', ...
                    'StartedOn', ...
                    'FinishedOn', ...
                    'Duration_s', ...
                    'OutputFiles'} );

                obj.globalPipeLog = [obj.globalPipeLog; newRow];

                if folderWasCancelled
                    obj.emitExecutionProgress(progressFcn, 'runCancelled', ...
                        'folderIndex', f, ...
                        'numFolders', nFolders, ...
                        'saveFolder', saveFolder, ...
                        'rawFolder', rawFolder, ...
                        'status', 'cancelled', ...
                        'message', char(folderSkipMsg));
                else
                    obj.emitExecutionProgress(progressFcn, 'folderFinished', ...
                        'folderIndex', f, ...
                        'numFolders', nFolders, ...
                        'saveFolder', saveFolder, ...
                        'rawFolder', rawFolder, ...
                        'status', lower(char(string(globalStatus))), ...
                        'message', sprintf('Folder %d/%d finished with status: %s', f, nFolders, char(globalStatus)));
                end

                % ---------------------------------------------------------
                % 9) Post-execution cleanup (folder-level)
                % ---------------------------------------------------------
                obj.executionTrace = [];
                obj.dataHistory = struct.empty(0,1);
                obj.current_outFile = {};

                if folderWasCancelled
                    break
                end
            end

            executionFinishedOn = datetime('now');
            result = obj.buildExecutionResult(executionPlan, runLeafPolicy, executionStartedOn, executionFinishedOn);

            if ~obj.currentExecutionWasCancelled
                obj.emitExecutionProgress(progressFcn, 'runFinished', ...
                    'numFolders', nFolders, ...
                    'status', char(result.status), ...
                    'message', sprintf('Pipeline execution finished with status: %s', char(result.status)));

                % The final runFinished event is emitted after the first result
                % assembly because it needs the resolved status. Mirror the final
                % progress log back into the returned result so GUI callbacks and
                % result.progressLog expose the same event sequence.
                result.progressLog = obj.executionProgressLog;
            end

            obj.lastExecutionResult = result;

            if printSummary
                fprintf('%s Pipeline execution Global summary %s\n',repmat('=',1,5),repmat('=',1,80))
                disp(obj.globalPipeLog)
                fprintf('%s\n',repmat('=',1,120))
            end

        end

        function [tf, report] = validateNodeParameters(obj, varargin)
            %VALIDATENODEPARAMETERS Validate configured step parameter values.
            %
            %   tf = obj.validateNodeParameters()
            %   [tf, report] = obj.validateNodeParameters('throwOnError', false)
            %
            %   This is a preflight configuration check. It validates the
            %   current value stored in node.info.parameters(k).value using the
            %   same metadata used by the parameter dialog: name, type,
            %   default, and allowed. It is intentionally separate from
            %   validateGraph because graph structure and user configuration
            %   are different validity layers.
            %
            %   The method should be called before execution so invalid loaded
            %   or edited .pipe files cannot run source/import/setup steps
            %   before a bad downstream parameter is discovered.

            p = inputParser;
            addParameter(p, 'throwOnError', false, @(x)islogical(x)&&isscalar(x));
            parse(p, varargin{:});
            throwOnError = p.Results.throwOnError;

            report = struct('errors', {{}}, 'warnings', {{}});
            tf = true;

            if isempty(obj.nodes)
                return
            end

            for iNode = 1:numel(obj.nodes)

                node = obj.nodes(iNode);

                if ~isfield(node, 'kind') || ~strcmpi(node.kind, 'stream')
                    continue
                end

                if ~isfield(node, 'info') || ~isfield(node.info, 'parameters') || isempty(node.info.parameters)
                    continue
                end

                nodeErrors = obj.validateParameterStructArray(node.info.parameters, node.name);

                if ~isempty(nodeErrors)
                    report.errors = [report.errors, nodeErrors]; %#ok<AGROW>
                end
            end

            tf = isempty(report.errors);

            if ~tf && throwOnError
                error('PipelineManager:validateNodeParameters:InvalidParameters', ...
                    '%s', strjoin(report.errors, newline));
            end
        end

        function [tf, report] = validateNodePreflight(obj, varargin)
            %VALIDATENODEPREFLIGHT Run optional folder-aware node preflights.
            %
            %   A pipelineInfo may set supportsPreflight=true. PipelineManager
            %   then calls the analysis function itself as
            %   fcn('preflight', saveFolder, parameters). Preflights run for
            %   every configured SaveFolder before any node executes and
            %   report through the existing pipeline diagnostic surface.

            p = inputParser;
            addParameter(p, 'throwOnError', false, @(x)islogical(x)&&isscalar(x));
            parse(p, varargin{:});
            report = struct('errors', {{}}, 'warnings', {{}});

            for iNode = 1:numel(obj.nodes)
                node = obj.nodes(iNode);
                if ~isfield(node, 'kind') || ~strcmpi(node.kind, 'stream') || ...
                        ~isfield(node, 'info') || ...
                        ~isfield(node.info, 'supportsPreflight') || ...
                        ~isequal(node.info.supportsPreflight, true)
                    continue
                end
                analysisFcn = obj.getCallableFuncName(node);
                if exist(analysisFcn, 'file') ~= 2
                    report.errors{end+1} = sprintf( ... %#ok<AGROW>
                        'Node "%s" analysis function was not found for preflight: %s.', ...
                        node.name, analysisFcn);
                    continue
                end
                parameters = node.info.parameters;
                for iParameter = 1:numel(parameters)
                    if ~isfield(parameters, 'value') || isempty(parameters(iParameter).value)
                        parameters(iParameter).value = parameters(iParameter).default;
                    end
                end
                for iFolder = 1:numel(obj.SaveFolderList)
                    try
                        feval(analysisFcn, 'preflight', ...
                            obj.SaveFolderList{iFolder}, parameters);
                    catch ME
                        report.errors{end+1} = sprintf( ... %#ok<AGROW>
                            'Node "%s" preflight failed for "%s": %s', ...
                            node.name, obj.SaveFolderList{iFolder}, ME.message);
                    end
                end
            end
            tf = isempty(report.errors);
            if ~tf && p.Results.throwOnError
                error('PipelineManager:validateNodePreflight:Failed', ...
                    '%s', strjoin(report.errors, newline));
            end
        end

        function varargout = diagnosePipeline(obj, varargin)
            %DIAGNOSEPIPELINE Build and optionally print a full pipeline diagnostic report.
            %
            %   diagnosePipeline(obj)
            %   diagnosePipeline(obj, 'verbose', true)
            %   report = diagnosePipeline(obj)
            %   report = diagnosePipeline(obj, 'verbose', false)
            %
            %   The returned report is the single public diagnostic interface for
            %   the pipeline. It includes both global graph/parameter validity and
            %   node-level status information that can be consumed by the GUI.
            %
            %   Name-Value options:
            %       verbose - Logical scalar. Default: false.
            %                 If true, prints the full diagnostic report to the
            %                 command window. If false, only returns the report and
            %                 updates cached node runtime validation.
            %
            %   Returned report fields:
            %       isValid        - True only if graph and parameter checks pass.
            %       graphIsValid   - Result from validateGraph.
            %       paramsAreValid - Result from validateNodeParameters.
            %       errors         - Combined graph + parameter errors.
            %       warnings       - Combined graph + parameter warnings.
            %       graphReport    - Raw graph-validation report.
            %       paramReport    - Raw parameter-validation report.
            %       nodeStatus     - One-row-per-node table with status/severity.
            %       hasWarnings    - True when at least one node has warning status.
            %       hasInvalidNonblocking - True when at least one node has
            %                         invalid_nonblocking status.
            %       hasInvalidBlocking - True when at least one node has
            %                         invalid_blocking status.

            p = inputParser;
            addParameter(p, 'verbose', false, @(x) islogical(x) && isscalar(x));
            parse(p, varargin{:});
            verbose = p.Results.verbose;

            [tfGraph, graphReport] = obj.validateGraph('throwOnError', false);
            [tfParams, paramReport] = obj.validateNodeParameters('throwOnError', false);
            [tfPreflight, preflightReport] = obj.validateNodePreflight('throwOnError', false);
            paramReport.errors = [paramReport.errors, preflightReport.errors];
            paramReport.warnings = [paramReport.warnings, preflightReport.warnings];

            report = struct();
            report.isValid        = tfGraph && tfParams && tfPreflight;
            report.graphIsValid   = tfGraph;
            report.paramsAreValid = tfParams && tfPreflight;
            report.preflightIsValid = tfPreflight;
            report.errors         = [graphReport.errors, paramReport.errors];
            report.warnings       = [graphReport.warnings, paramReport.warnings];
            report.graphReport    = graphReport;
            report.paramReport    = paramReport;
            report.nodeStatus     = obj.buildNodeStatusTable(graphReport, paramReport);
            report.hasWarnings = istable(report.nodeStatus) && any(report.nodeStatus.status == "warning");
            report.hasInvalidNonblocking = istable(report.nodeStatus) && ...
                any(report.nodeStatus.status == "invalid_nonblocking");
            report.hasInvalidBlocking = istable(report.nodeStatus) && ...
                any(report.nodeStatus.status == "invalid_blocking");

            obj.updateNodeRuntimeValidation(report.nodeStatus);

            if verbose
                fprintf('\n================ Pipeline Diagnostics ================\n');

                if report.isValid
                    fprintf('Status: VALID\n');
                else
                    fprintf('Status: INVALID\n');
                end

                fprintf('Graph valid:      %d\n', logical(report.graphIsValid));
                fprintf('Parameters valid: %d\n', logical(report.paramsAreValid));

                if ~isempty(report.errors)
                    fprintf('\nErrors (%d):\n', numel(report.errors));
                    for i = 1:numel(report.errors)
                        fprintf('  %2d) %s\n', i, report.errors{i});
                    end
                else
                    fprintf('\nErrors (0)\n');
                end

                if ~isempty(report.warnings)
                    fprintf('\nWarnings (%d):\n', numel(report.warnings));
                    for i = 1:numel(report.warnings)
                        fprintf('  %2d) %s\n', i, report.warnings{i});
                    end
                else
                    fprintf('\nWarnings (0)\n');
                end

                if istable(report.nodeStatus) && ~isempty(report.nodeStatus)
                    invalidMask = report.nodeStatus.status ~= "valid";
                    if any(invalidMask)
                        fprintf('\nNode status (%d non-valid):\n', nnz(invalidMask));
                        rows = find(invalidMask);
                        for iRow = 1:numel(rows)
                            r = rows(iRow);
                            fprintf('  nodeID %d | %s | %s | %s\n', ...
                                report.nodeStatus.nodeID(r), ...
                                char(report.nodeStatus.stepName(r)), ...
                                char(report.nodeStatus.status(r)), ...
                                char(report.nodeStatus.severity(r)));
                        end
                    else
                        fprintf('\nNode status: all nodes valid.\n');
                    end
                end

                fprintf('======================================================\n\n');
            end

            if nargout > 0
                varargout{1} = report;
            end
        end

        function setLeafOutputPolicy(obj, policy)
            %SETLEAFOUTPUTPOLICY Set the default leaf-output persistence policy.
            %
            %   setLeafOutputPolicy(obj, policy)
            %
            %   POLICY must be one of:
            %       'explicit'   - Only explicitly configured save targets are saved.
            %       'saveLeaves' - Save supported DATA leaf outputs permanently.
            %       'viewerTemp' - Save DataViewer-compatible leaf outputs as PMTMP_*.
            %       'transient'  - Allow unsaved DATA leaf outputs and report them.

            obj.leafOutputPolicy = obj.resolveLeafOutputPolicy(policy);
        end

        function orderReport = getNodeOrders(obj, varargin)
            %GETNODEORDERS Return structural, scheduler, and executable order metadata.
            %
            %   orderReport = getNodeOrders(obj)
            %
            %   The returned struct contains raw node-ID vectors and a nodeTable with
            %   one row per existing node. FileSource/folder nodes are virtual input
            %   sources: they may appear in the backend schedule, but they are not
            %   executable analysis steps and do not receive a runIndex.
            %
            %   Returned order vectors:
            %       topoOrder      - structural DAG order.
            %       scheduleOrder  - backend visit/scheduler order, including
            %                        virtual FileSource nodes.
            %       runOrder       - executable stream-node order only.
            %
            %   Returned nodeTable order columns:
            %       topoIndex      - position in topoOrder.
            %       scheduleIndex  - position in scheduleOrder.
            %       runIndex       - user-facing executable order; NaN for
            %                        virtual FileSource nodes.
            %       isExecutable   - true for stream nodes only.
            %       executionRole  - "analysis_step" or "virtual_source".

            p = inputParser;
            addParameter(p, 'RequiredNodeIDs', [], @(x)isnumeric(x)||isempty(x));
            parse(p, varargin{:});
            requiredNodeIDs = p.Results.RequiredNodeIDs;

            if isempty(obj.nodes)
                orderReport = struct();
                orderReport.topoOrder = [];
                orderReport.scheduleOrder = [];
                orderReport.runOrder = [];
                orderReport.nodeTable = table();
                return
            end

            obj.updateTopoOrder();
            topoOrderLocal = obj.topoOrder(:)';

            if isempty(requiredNodeIDs)
                requiredNodeIDs = topoOrderLocal;
            else
                requiredNodeIDs = requiredNodeIDs(:)';
            end

            scheduleOrderLocal = obj.buildExecutionOrder(requiredNodeIDs);
            runOrderLocal = zeros(1,0);

            for iSched = 1:numel(scheduleOrderLocal)
                nodeIDLocal = scheduleOrderLocal(iSched);
                nodeIdxLocal = obj.getNodeIndexByID(nodeIDLocal);

                if strcmpi(obj.nodes(nodeIdxLocal).kind, 'stream')
                    runOrderLocal(end+1) = nodeIDLocal; %#ok<AGROW>
                end
            end

            topoIndexByID = containers.Map('KeyType','double','ValueType','double');
            scheduleIndexByID = containers.Map('KeyType','double','ValueType','double');
            runIndexByID = containers.Map('KeyType','double','ValueType','double');

            for iTopo = 1:numel(topoOrderLocal)
                topoIndexByID(topoOrderLocal(iTopo)) = iTopo;
            end
            for iSched = 1:numel(scheduleOrderLocal)
                scheduleIndexByID(scheduleOrderLocal(iSched)) = iSched;
            end
            for iRun = 1:numel(runOrderLocal)
                runIndexByID(runOrderLocal(iRun)) = iRun;
            end

            nNodes = numel(obj.nodes);
            nodeID = zeros(nNodes,1);
            stepName = strings(nNodes,1);
            functionName = strings(nNodes,1);
            kind = strings(nNodes,1);
            topoIndex = nan(nNodes,1);
            scheduleIndex = nan(nNodes,1);
            runIndex = nan(nNodes,1);
            isExecutable = false(nNodes,1);
            executionRole = strings(nNodes,1);
            isRoot = false(nNodes,1);
            isLeaf = false(nNodes,1);

            for iNode = 1:nNodes
                nodeLocal = obj.nodes(iNode);
                nodeID(iNode) = nodeLocal.id;
                stepName(iNode) = string(nodeLocal.name);
                kind(iNode) = string(nodeLocal.kind);

                isExecutable(iNode) = strcmpi(char(kind(iNode)), 'stream');

                if isExecutable(iNode)
                    functionName(iNode) = string(obj.getCallableFuncName(nodeLocal));
                    executionRole(iNode) = "analysis_step";
                else
                    functionName(iNode) = "FileSource";
                    executionRole(iNode) = "virtual_source";
                end

                if isKey(topoIndexByID, nodeLocal.id)
                    topoIndex(iNode) = topoIndexByID(nodeLocal.id);
                end
                if isKey(scheduleIndexByID, nodeLocal.id)
                    scheduleIndex(iNode) = scheduleIndexByID(nodeLocal.id);
                end
                if isKey(runIndexByID, nodeLocal.id)
                    runIndex(iNode) = runIndexByID(nodeLocal.id);
                end

                if isempty(obj.connections)
                    isRoot(iNode) = true;
                    isLeaf(iNode) = true;
                else
                    isRoot(iNode) = ~any([obj.connections.targetNodeID] == nodeLocal.id);
                    isLeaf(iNode) = ~any([obj.connections.sourceNodeID] == nodeLocal.id);
                end
            end

            nodeTable = table(nodeID, stepName, functionName, kind, topoIndex, ...
                scheduleIndex, runIndex, isExecutable, executionRole, isRoot, isLeaf);

            if ~isempty(nodeTable)
                [~, ord] = sort(nodeTable.topoIndex, 'ascend');
                nodeTable = nodeTable(ord,:);
            end

            orderReport = struct();
            orderReport.topoOrder = topoOrderLocal;
            orderReport.scheduleOrder = scheduleOrderLocal;
            orderReport.runOrder = runOrderLocal;
            orderReport.nodeTable = nodeTable;
        end

        function savePipe(obj,varargin)
            %SAVEPIPE Save the current pipeline DAG to a .pipe file.
            %
            %   savePipe(obj)
            %   savePipe(obj, pipeFile)
            %
            %   The .pipe file is stored as a MATLAB MAT-file with custom extension.
            %
            %   Saved content:
            %       - nodes (runtime-sanitized)
            %       - connections
            %       - activeLeafNodeID
            %       - savedFuncName
            %       - pipelineVersion
            %       - projectFolder
            %       - pipeline execution settings
            %       - savedOn timestamp
            %
            %   Notes:
            %       - Runtime execution state is not persisted.
            %       - topoOrder is not persisted; it is recomputed on load.

            p = inputParser;
            addRequired(p,'obj');
            addOptional(p,'pipeFile',fullfile(pwd,'MyPipeline.pipe'),@(x)ischar(x) || isstring(x));
            parse(p,obj,varargin{:});
            pipeFile = char(string(p.Results.pipeFile));

            % Parse file name and enforce .pipe extension
            [path, filename, ext] = fileparts(pipeFile);
            if isempty(ext) || ~strcmpi(ext, '.pipe')
                ext = '.pipe';
            end

            % If the user did not set a path, use ProjectFolder
            if isempty(path)
                if ~obj.b_inputFromDataViewer
                    path = fullfile(obj.projectFolder, 'PipeLineConfigFiles');
                    [~,~] = mkdir(path);
                else
                    path = obj.projectFolder;
                end
            end

            pipeStruct = struct();
            pipeStruct.schemaVersion   = 1;
            pipeStruct.savedOn         = datetime('now');
            pipeStruct.pipelineVersion = obj.pipelineVersion;
            pipeStruct.projectFolder   = obj.projectFolder;
            pipeStruct.nodes           = sanitizeNodesForSave(obj.nodes);
            pipeStruct.connections     = obj.connections;

            if isprop(obj,'activeLeafNodeID')
                pipeStruct.activeLeafNodeID = obj.activeLeafNodeID;
            else
                pipeStruct.activeLeafNodeID = [];
            end

            pipeStruct.savedFuncName = extractSavedFunctionNames(pipeStruct.nodes);

            % Persist all execution-relevant pipeline settings
            pipeStruct.settings = struct( ...
                'b_skipSteps',              getIfProp(obj,'b_skipSteps', false), ...
                'b_avoidOverwrite',         getIfProp(obj,'b_avoidOverwrite', false), ...
                'b_saveDataBeforeFail',     getIfProp(obj,'b_saveDataBeforeFail', false), ...
                'b_alwaysSaveLeaf',         getIfProp(obj,'b_alwaysSaveLeaf', false), ...
                'leafOutputPolicy',         getIfProp(obj,'leafOutputPolicy', ''), ...
                'ramMode',                  getIfProp(obj,'ramMode', ''), ...
                'ramSafePolicy',            getIfProp(obj,'ramSafePolicy', ''), ...
                'ramLookaheadLength',       getIfProp(obj,'ramLookaheadLength', []), ...
                'ramCooldownSteps',         getIfProp(obj,'ramCooldownSteps', []), ...
                'ramSafetyOverheadPct',     getIfProp(obj,'ramSafetyOverheadPct', []), ...
                'ramSafetyDataMultiplier',  getIfProp(obj,'ramSafetyDataMultiplier', []) );

            save(fullfile(path,[filename ext]), 'pipeStruct','-mat');
            fprintf('Pipeline saved as "%s" in folder "%s".\n',[filename ext],path);

            % =============================================================
            % Local helpers
            % =============================================================
            function nodesOut = sanitizeNodesForSave(nodesIn)
                %SANITIZENODESFORSAVE Remove transient runtime state before saving.

                nodesOut = nodesIn;

                for iNode = 1:numel(nodesOut)
                    if isfield(nodesOut(iNode),'runtime')
                        nodesOut(iNode).runtime = struct();
                    end
                end
            end

            function savedFcn = extractSavedFunctionNames(nodesIn)
                %EXTRACTSAVEDFUNCTIONNAMES Extract one function name per saved step.

                savedFcn = strings(numel(nodesIn),1);

                for iNode = 1:numel(nodesIn)

                    if isfield(nodesIn(iNode),'kind') && strcmpi(nodesIn(iNode).kind,'folder')
                        savedFcn(iNode) = "";
                        continue
                    end

                    fName = "";

                    if isfield(nodesIn(iNode),'info') && isfield(nodesIn(iNode).info,'name') && ...
                            ~isempty(nodesIn(iNode).info.name)
                        fName = string(nodesIn(iNode).info.name);
                    elseif isfield(nodesIn(iNode),'tag') && ~isempty(nodesIn(iNode).tag)
                        tagStr = string(nodesIn(iNode).tag);
                        tok = regexp(char(tagStr), '^(.*)_\d+$', 'tokens', 'once');
                        if ~isempty(tok)
                            fName = string(tok{1});
                        else
                            fName = tagStr;
                        end
                    elseif isfield(nodesIn(iNode),'name') && ~isempty(nodesIn(iNode).name)
                        tagStr = string(nodesIn(iNode).name);
                        tok = regexp(char(tagStr), '^(.*)_\d+$', 'tokens', 'once');
                        if ~isempty(tok)
                            fName = string(tok{1});
                        else
                            fName = tagStr;
                        end
                    end

                    savedFcn(iNode) = fName;
                end
            end

            function val = getIfProp(objLocal, propName, defaultVal)
                %GETIFPROP Return property value if present, otherwise default.

                if isprop(objLocal, propName)
                    val = objLocal.(propName);
                else
                    val = defaultVal;
                end
            end
        end

        function loadPipe(obj,varargin)
            %LOADPIPE Load a pipeline DAG from a .pipe file.
            %
            %   loadPipe(obj)
            %   loadPipe(obj, pipeFile)
            %
            %   Behavior:
            %       - Loads the exact saved DAG (nodes + connections)
            %       - Recomputes topoOrder
            %       - Restores saved execution settings when present
            %       - Checks that all saved analysis functions still exist in funcList
            %       - If some functions are missing, warns and marks the pipeline invalid
            %       - If the .pipe file is an older legacy format, warns and prints a
            %         short CLI summary to help the user rebuild it manually

            p = inputParser;
            addRequired(p,'obj');
            addOptional(p,'pipeFile',fullfile(pwd,'MyPipeline.pipe'),@(x)ischar(x) || isstring(x));
            parse(p,obj,varargin{:});
            pipeFile = char(string(p.Results.pipeFile));

            assert(isfile(pipeFile), 'The file "%s" doesn''t exist!', pipeFile);

            S = load(pipeFile,'-mat');

            if ~isfield(S,'pipeStruct')
                error('PipelineManager:loadPipe:InvalidFile', ...
                    'The file "%s" does not contain a valid pipeStruct variable.', pipeFile);
            end

            pipeStruct = S.pipeStruct;

            % -------------------------------------------------------------
            % Detect old legacy .pipe files
            % -------------------------------------------------------------
            isNewFormat = isstruct(pipeStruct) && isscalar(pipeStruct) && ...
                isfield(pipeStruct,'schemaVersion') && ...
                isfield(pipeStruct,'nodes') && ...
                isfield(pipeStruct,'connections');

            if ~isNewFormat
                warning('PipelineManager:loadPipe:LegacyPipeFormat', ...
                    ['This .pipe file was saved with an older format. ' ...
                    'Please rebuild the pipeline manually. A short summary is shown below to guide step recreation.']);

                printLegacyPipeSummary(pipeStruct, pipeFile);
                return
            end

            % -------------------------------------------------------------
            % Basic payload validation
            % -------------------------------------------------------------
            if pipeStruct.schemaVersion ~= 1
                warning('PipelineManager:loadPipe:UnknownSchemaVersion', ...
                    'Unsupported pipe schema version "%s". The pipeline may not load correctly.', ...
                    char(string(pipeStruct.schemaVersion)));
            end

            if ~isfield(pipeStruct,'nodes') || ~isfield(pipeStruct,'connections')
                error('PipelineManager:loadPipe:MissingFields', ...
                    'The .pipe file is missing required DAG fields.');
            end

            % -------------------------------------------------------------
            % Reset current pipeline and restore saved DAG
            % -------------------------------------------------------------
            obj.clearPipeline();

            obj.nodes       = pipeStruct.nodes;
            obj.connections = pipeStruct.connections;

            if isfield(pipeStruct,'activeLeafNodeID') && isprop(obj,'activeLeafNodeID')
                obj.activeLeafNodeID = pipeStruct.activeLeafNodeID;
            end

            % Restore saved execution settings when present
            if isfield(pipeStruct,'settings') && isstruct(pipeStruct.settings)
                localRestoreSetting('b_skipSteps');
                localRestoreSetting('b_avoidOverwrite');
                localRestoreSetting('b_saveDataBeforeFail');
                localRestoreSetting('b_alwaysSaveLeaf');
                localRestoreSetting('leafOutputPolicy');
                localRestoreSetting('ramMode');
                localRestoreSetting('ramSafePolicy');
                localRestoreSetting('ramLookaheadLength');
                localRestoreSetting('ramCooldownSteps');
                localRestoreSetting('ramSafetyOverheadPct');
                localRestoreSetting('ramSafetyDataMultiplier');
            end

            % Ensure runtime fields exist and start clean
            obj.nodes = normalizeRuntimeFields(obj.nodes);

            % -------------------------------------------------------------
            % Structural validation
            % -------------------------------------------------------------
            structuralValid = false;
            try
                obj.updateTopoOrder();
                [structuralValid, ~] = obj.validateGraph('throwOnError', false);
            catch
                structuralValid = false;
            end

            % -------------------------------------------------------------
            % Validate saved functions against current funcList
            % -------------------------------------------------------------
            savedFcn = strings(0,1);

            if isfield(pipeStruct,'savedFuncName') && ~isempty(pipeStruct.savedFuncName)
                savedFcn = string(pipeStruct.savedFuncName(:));
            else
                savedFcn = extractSavedFunctionNamesFromNodes(obj.nodes);
            end

            savedFcn = savedFcn(strlength(savedFcn) > 0);
            savedFcn = unique(savedFcn, 'stable');

            knownFcn = string({obj.funcList.name});
            missingFcn = savedFcn(~ismember(savedFcn, knownFcn));

            if ~isempty(missingFcn)
                warning('PipelineManager:loadPipe:MissingFunctions', ...
                    ['The loaded pipeline references missing function(s): %s. ' ...
                    'The pipeline was loaded but marked invalid. ' ...
                    'Please try to fix the invalid pipeline before execution.'], ...
                    char(strjoin(missingFcn, ', ')));
            end

            % -------------------------------------------------------------
            % Mark validity
            % -------------------------------------------------------------
            if isprop(obj,'b_pipeIsValid')
                obj.b_pipeIsValid = structuralValid && isempty(missingFcn);
            end

            if ~structuralValid
                warning('PipelineManager:loadPipe:InvalidStructure', ...
                    'The pipeline was loaded but its structure is invalid. Please try to fix the invalid pipeline before execution.');
            end

            fprintf('Pipeline loaded from "%s"\n', pipeFile);

            % =============================================================
            % Local helpers
            % =============================================================
            function localRestoreSetting(fieldName)
                %LOCALRESTORESETTING Restore one saved setting if present.

                if isfield(pipeStruct.settings, fieldName) && isprop(obj, fieldName)
                    obj.(fieldName) = pipeStruct.settings.(fieldName);
                end
            end

            function nodesOut = normalizeRuntimeFields(nodesIn)
                %NORMALIZERUNTIMEFIELDS Ensure runtime exists and is reset.

                nodesOut = nodesIn;

                for iNode = 1:numel(nodesOut)
                    if ~isfield(nodesOut(iNode),'runtime')
                        nodesOut(iNode).runtime = struct();
                    end
                end
            end

            function savedFcnLocal = extractSavedFunctionNamesFromNodes(nodesIn)
                %EXTRACTSAVEDFUNCTIONNAMESFROMNODES Derive function names from nodes.

                savedFcnLocal = strings(numel(nodesIn),1);

                for iNode = 1:numel(nodesIn)

                    if isfield(nodesIn(iNode),'kind') && strcmpi(nodesIn(iNode).kind,'folder')
                        savedFcnLocal(iNode) = "";
                        continue
                    end

                    fName = "";

                    if isfield(nodesIn(iNode),'info') && isfield(nodesIn(iNode).info,'name') && ...
                            ~isempty(nodesIn(iNode).info.name)
                        fName = string(nodesIn(iNode).info.name);
                    elseif isfield(nodesIn(iNode),'tag') && ~isempty(nodesIn(iNode).tag)
                        tagStr = string(nodesIn(iNode).tag);
                        tok = regexp(char(tagStr), '^(.*)_\d+$', 'tokens', 'once');
                        if ~isempty(tok)
                            fName = string(tok{1});
                        else
                            fName = tagStr;
                        end
                    elseif isfield(nodesIn(iNode),'name') && ~isempty(nodesIn(iNode).name)
                        tagStr = string(nodesIn(iNode).name);
                        tok = regexp(char(tagStr), '^(.*)_\d+$', 'tokens', 'once');
                        if ~isempty(tok)
                            fName = string(tok{1});
                        else
                            fName = tagStr;
                        end
                    end

                    savedFcnLocal(iNode) = fName;
                end
            end

            function printLegacyPipeSummary(oldPipe, pipePath)
                %PRINTLEGACYPIPESUMMARY Show a short CLI summary of an old pipeline.

                fprintf('\n============================================================\n');
                fprintf('Legacy pipeline summary from "%s"\n', pipePath);
                fprintf('============================================================\n');

                if isempty(oldPipe)
                    fprintf('The legacy pipeline is empty.\n\n');
                    return
                end

                if ~isstruct(oldPipe)
                    fprintf('Could not interpret the legacy pipeline structure.\n\n');
                    return
                end

                if isfield(oldPipe,'seq')
                    seqList = unique([oldPipe.seq], 'stable');

                    for iSeq = 1:numel(seqList)
                        seqID = seqList(iSeq);
                        idx = find([oldPipe.seq] == seqID);

                        if isfield(oldPipe,'seqIndx')
                            [~, ord] = sort([oldPipe(idx).seqIndx], 'ascend');
                            idx = idx(ord);
                        end

                        fprintf('\nSEQUENCE %d\n', seqID);
                        fprintf('------------------------------------------------------------\n');

                        for ii = 1:numel(idx)
                            step = oldPipe(idx(ii));
                            stepName = '<unknown>';
                            if isfield(step,'name') && ~isempty(step.name)
                                stepName = char(string(step.name));
                            end

                            if isfield(step,'saveFileName') && ~isempty(step.saveFileName)
                                fprintf('  [%d] %s    [saveas: %s]\n', ...
                                    ii, stepName, char(string(step.saveFileName)));
                            else
                                fprintf('  [%d] %s\n', ii, stepName);
                            end
                        end
                    end

                else
                    fprintf('\nSTEPS\n');
                    fprintf('------------------------------------------------------------\n');

                    for ii = 1:numel(oldPipe)
                        stepName = '<unknown>';
                        if isfield(oldPipe(ii),'name') && ~isempty(oldPipe(ii).name)
                            stepName = char(string(oldPipe(ii).name));
                        end

                        if isfield(oldPipe(ii),'saveFileName') && ~isempty(oldPipe(ii).saveFileName)
                            fprintf('  [%d] %s    [saveas: %s]\n', ...
                                ii, stepName, char(string(oldPipe(ii).saveFileName)));
                        else
                            fprintf('  [%d] %s\n', ii, stepName);
                        end
                    end
                end

                fprintf('\nPlease rebuild this pipeline manually.\n\n');
            end
        end

        function clearPipeline(obj)
            %CLEARPIPELINE Reset the entire DAG state.
            %
            %   CLEARPIPELINE(obj) removes:
            %       - All nodes
            %       - All connections
            %       - Cached topological order
            %
            %   Does NOT modify:
            %       - funcList
            %       - fcnDir
            %       - Folder lists
            %       - Accepted type definitions
            %
            %   The class remains fully usable after reset.

            % -------------------------------------------------------------
            % Clear structural graph components
            % -------------------------------------------------------------
            obj.nodes       = obj.nodes([]);        % preserve struct type
            obj.connections = obj.connections([]);  % preserve struct type

            % -------------------------------------------------------------
            % Clear derived/control properties
            % -------------------------------------------------------------
            if isprop(obj,'topoOrder')
                obj.topoOrder = [];
            end

            obj.lastExecutionPlan = struct();
            obj.lastExecutionResult = struct();

            % -------------------------------------------------------------
            % Optional: reset additional control variables if present
            % (Add here if you later introduce execution caches, etc.)
            % -------------------------------------------------------------
            obj.autoValidate();
            fprintf('Pipeline successfully cleared.\n');
        end

        function info = getPipelineInfo(obj, funcName)
            %GETPIPELINEINFO Return the pipelineInfo metadata for an analysis function.
            %
            %   INFO = GETPIPELINEINFO(OBJ, FUNCNAME) returns the pipelineInfo struct
            %   associated with the analysis function FUNCNAME.
            %
            %   This is the single entry point used by DAG/Step-building code to fetch
            %   the function schema (inputs/outputs/parameters/notes).
            %
            %   BEHAVIOR:
            %     - Uses OBJ.funcList as the primary cache.
            %     - If funcList is empty, it will be created (createFcnList).
            %     - Ensures INFO.parameters(k).value is initialized from .default
            %       (so runtime option editing can operate on .value consistently).
            %
            %   INPUT:
            %     funcName (char|string) Name of an analysis function (e.g. 'run_GSR').
            %
            %   OUTPUT:
            %     info (struct) pipelineInfo struct with fields:
            %       .inputs, .outputs, .parameters, .notes, ... (as available)
            %
            %   ERRORS:
            %     - Throws if the function is not found in funcList.

            % -----------------------------
            % Normalize input
            % -----------------------------
            if isstring(funcName); funcName = char(funcName); end
            funcName = char(string(funcName));

            if isempty(funcName)
                error('PipelineManager:getPipelineInfo:EmptyName', ...
                    'Function name cannot be empty.');
            end

            % -----------------------------
            % Ensure funcList is populated
            % -----------------------------
            if isempty(obj.funcList)
                obj.createFcnList();
            end

            % -----------------------------
            % Lookup in funcList cache
            % -----------------------------
            idx = find(strcmpi({obj.funcList.name}, funcName), 1);

            if isempty(idx)
                error('PipelineManager:getPipelineInfo:NotFound', ...
                    'Function "%s" was not found in funcList.', funcName);
            end

            info = obj.funcList(idx).info;

            if ~isstruct(info)
                error('PipelineManager:getPipelineInfo:InvalidInfo', ...
                    'funcList entry for "%s" does not contain a valid pipelineInfo struct.', funcName);
            end

            % -----------------------------
            % Ensure expected fields exist
            % -----------------------------
            if ~isfield(info,'inputs');      info.inputs = struct([]);      end
            if ~isfield(info,'outputs');     info.outputs = struct([]);     end
            if ~isfield(info,'parameters');  info.parameters = struct([]);  end
            if ~isfield(info,'notes');       info.notes = {};               end

            % -----------------------------
            % Initialize runtime parameter values
            % -----------------------------
            if ~isempty(info.parameters)
                for k = 1:numel(info.parameters)
                    if ~isfield(info.parameters(k),'default')
                        info.parameters(k).default = [];
                    end
                    % Always (re)initialize runtime value from default when fetching schema
                    info.parameters(k).value = info.parameters(k).default;
                end
            end
        end

        function outFile = exportPipeErrorLog(obj, outputFolder)
            %EXPORTPIPEERRORLOG Export a CSV summary of errors from the latest pipeline execution.
            %
            %   outFile = exportPipeErrorLog(obj)
            %   outFile = exportPipeErrorLog(obj, outputFolder)
            %
            %   This method summarizes error-related rows from obj.globalPipeLog and
            %   writes them to a timestamped CSV file.
            %
            %   Inputs:
            %       outputFolder - Optional destination folder. Defaults to pwd.
            %
            %   Output:
            %       outFile - Full path to the created CSV file.
            %
            %   Notes:
            %       - Uses obj.globalPipeLog from the latest executePipeline run.
            %       - Exports rows whose status indicates failure / partial execution.
            %       - If no error rows are found, an empty CSV with headers is written.

            if nargin < 2 || isempty(outputFolder)
                outputFolder = pwd;
            end

            outputFolder = char(string(outputFolder));

            if isempty(obj.globalPipeLog) || ~istable(obj.globalPipeLog)
                error('PipelineManager:exportPipeErrorLog:EmptyGlobalLog', ...
                    'globalPipeLog is empty. Run executePipeline first.');
            end

            if ~isfolder(outputFolder)
                mkdir(outputFolder);
            end

            errMask = false(height(obj.globalPipeLog), 1);

            % -------------------------------------------------------------
            % Status-based filtering (primary source of truth)
            % -------------------------------------------------------------
            if ismember('Status', obj.globalPipeLog.Properties.VariableNames)
                statusVals = strip(string(obj.globalPipeLog.Status));

                errMask = strcmpi(statusVals, "Failed") | ...
                    strcmpi(statusVals, "Partially executed");
            end

            % -------------------------------------------------------------
            % Fallback when Status is absent: use message content
            % -------------------------------------------------------------
            if ~ismember('Status', obj.globalPipeLog.Properties.VariableNames) && ...
                    ismember('Messages_short', obj.globalPipeLog.Properties.VariableNames)

                msgVals = strip(string(obj.globalPipeLog.Messages_short));

                errMask = strlength(msgVals) > 0 & ...
                    ~strcmpi(msgVals, "No Errors") & ...
                    ~strcmpi(msgVals, "Missing") & ...
                    ~ismissing(msgVals);
            end

            errorLogTable = obj.globalPipeLog(errMask, :);

            timeStamp = char(datetime('now', 'Format', 'yyyyMMdd_HHmmss'));
            outFile = fullfile(outputFolder, ['pipeErrorLog_' timeStamp '.csv']);

            writetable(errorLogTable, outFile);

            fprintf('Pipeline error log exported: %s\n', outFile);
            fprintf('Rows exported: %d\n', height(errorLogTable));
        end

        function generateScript(obj, filename)
            %GENERATESCRIPT Generate a standalone MATLAB script from the current DAG pipeline.
            %
            %   generateScript(obj, filename)
            %
            %   This method exports the current pipeline as a plain MATLAB script that:
            %       1) Executes each step in pipeline execution order
            %       2) Applies the current step parameters
            %       3) Saves/loads files when required by the graph
            %       4) Creates and deletes temporary files when intermediate file-based
            %          routing is needed
            %
            %   The generated script does not instantiate PipelineManager at runtime.
            %
            %   Runtime assumptions for the generated script:
            %       - Analysis functions are on the MATLAB path
            %       - loadData / saveData are on the MATLAB path
            %       - Enough RAM is available to run in standard in-memory mode
            %
            %   Inputs:
            %       filename - Target .m script path. If no extension is provided,
            %                  ".m" is appended automatically.
            %
            %   Notes:
            %       - The generated script uses placeholder SaveFolder and RawFolder
            %         paths at the top and asks the user to edit them.
            %       - DataViewer-backed pipelines are not supported here because the
            %         generated script must be self-contained and file-based.
            %       - The exported execution order is resolved at generation time from
            %         the current DAG.

            narginchk(2,2);

            if ~(ischar(filename) || (isstring(filename) && isscalar(filename)))
                error('PipelineManager:generateScript:InvalidFilename', ...
                    'filename must be a char vector or string scalar.');
            end

            if obj.b_inputFromDataViewer
                error('PipelineManager:generateScript:DataViewerNotSupported', ...
                    ['Cannot generate a standalone script from a DataViewer-backed pipeline. ' ...
                    'The exported script must start from file-based inputs.']);
            end

            if isempty(obj.nodes)
                error('PipelineManager:generateScript:EmptyPipeline', ...
                    'Pipeline is empty.');
            end

            [isValid, ~] = obj.validateGraph('throwOnError', false);
            if ~isValid
                error('PipelineManager:generateScript:InvalidGraph', ...
                    'Pipeline is invalid. Run obj.diagnosePipeline() before exporting.');
            end

            obj.updateTopoOrder();

            if isempty(obj.topoOrder)
                error('PipelineManager:generateScript:MissingTopoOrder', ...
                    'topoOrder is empty.');
            end

            % Use the resolved execution order from the current graph.
            execOrder = obj.buildExecutionOrder(obj.topoOrder(:)');

            % Normalize output filename
            filename = char(string(filename));
            [outFolder, outName, outExt] = fileparts(filename);
            if isempty(outExt)
                outExt = '.m';
            end
            if isempty(outFolder)
                outFolder = pwd;
            end
            outPath = fullfile(outFolder, [outName outExt]);

            % ---------------------------------------------------------------------
            % Build local lookup maps
            % ---------------------------------------------------------------------
            nodeIdxByID = containers.Map('KeyType','double','ValueType','double');
            topoPosByID = containers.Map('KeyType','double','ValueType','double');

            for iNode = 1:numel(obj.nodes)
                nodeIdxByID(obj.nodes(iNode).id) = iNode;
            end

            for iTopo = 1:numel(obj.topoOrder)
                topoPosByID(obj.topoOrder(iTopo)) = iTopo;
            end

            % Stable variable name per output
            outputVarByKey = containers.Map('KeyType','char','ValueType','char');

            for iNode = 1:numel(obj.nodes)
                nodeLocal = obj.nodes(iNode);

                if ~isfield(nodeLocal,'info') || ~isfield(nodeLocal.info,'outputs') || isempty(nodeLocal.info.outputs)
                    continue
                end

                outputsLocal = sortOutputs(nodeLocal.info.outputs);

                for iOut = 1:numel(outputsLocal)
                    outNameLocal = char(string(outputsLocal(iOut).name));
                    outVarName = sprintf('step_%03d_%s', nodeLocal.id, matlab.lang.makeValidName(outNameLocal));
                    outputVarByKey(makeKeyLocal(nodeLocal.id, outNameLocal)) = outVarName;
                end
            end

            % ---------------------------------------------------------------------
            % Determine which concrete files are required for each file-mode output
            % ---------------------------------------------------------------------
            fileRequirementsByKey = containers.Map('KeyType','char','ValueType','any');

            for iNode = 1:numel(obj.nodes)

                nodeLocal = obj.nodes(iNode);

                if ~strcmpi(nodeLocal.kind,'stream')
                    continue
                end

                if ~isfield(nodeLocal,'info') || ~isfield(nodeLocal.info,'outputs') || isempty(nodeLocal.info.outputs)
                    continue
                end

                outputsLocal = sortOutputs(nodeLocal.info.outputs);

                for iOut = 1:numel(outputsLocal)

                    outDef = outputsLocal(iOut);

                    if ~isfield(outDef,'isData') || ~outDef.isData
                        continue
                    end

                    outNameLocal = char(string(outDef.name));
                    outKey = makeKeyLocal(nodeLocal.id, outNameLocal);

                    req = struct( ...
                        'files', strings(0,1), ...
                        'isTemp', false(0,1));

                    isFileMode = isfield(outDef,'outputMode') && strcmpi(char(string(outDef.outputMode)),'file');

                    if isFileMode
                        outConns = getOutputConnections(nodeLocal.id, outNameLocal);

                        for iConn = 1:numel(outConns)
                            reqFile = resolveConcreteConnectedFileName(nodeLocal, outDef, outConns(iConn));

                            if isempty(reqFile)
                                reqFile = generateTempFileName(nodeLocal, outDef, iConn);
                                req = appendRequiredFile(req, reqFile, true);
                            else
                                req = appendRequiredFile(req, reqFile, false);
                            end
                        end
                    end

                    % Explicit user save target also becomes required
                    saveFileRowsLocal = obj.normalizeOutputSaveFileNameList(outDef);
                    if ~isempty(saveFileRowsLocal)
                        for iSaveReq = 1:numel(saveFileRowsLocal)
                            req = appendRequiredFile(req, char(saveFileRowsLocal(iSaveReq)), false);
                        end
                    end

                    fileRequirementsByKey(outKey) = req;
                end
            end

            % ---------------------------------------------------------------------
            % Build script text
            % ---------------------------------------------------------------------
            scriptLines = {};

            appendLine('%% GENERATED PIPELINE SCRIPT');
            appendLine(sprintf('%% Created on %s', char(datetime('now','Format','yyyy-MM-dd HH:mm:ss'))));
            appendLine('%%');
            appendLine('%% Edit the two paths below before running this script.');
            appendLine('%% The script assumes loadData, saveData, and all pipeline');
            appendLine('%% analysis functions are available on the MATLAB path.');
            appendLine('%%');
            appendLine('%% This exported version runs in standard in-memory mode.');
            appendLine('');

            appendLine('SaveFolder = ''/path/to/save_folder''; % TODO: set the correct SaveFolder path');
            appendLine('RawFolder  = ''/path/to/raw_folder'';  % TODO: set the correct RawFolder path');
            appendLine('');

            appendLine('if strcmp(SaveFolder, ''/path/to/save_folder'')');
            appendLine('    error(''Please edit SaveFolder before running this script.'');');
            appendLine('end');
            appendLine('');
            appendLine('if strcmp(RawFolder, ''/path/to/raw_folder'')');
            appendLine('    warning(''RawFolder still uses the placeholder path. Update it if your pipeline requires RawFolder input.'');');
            appendLine('end');
            appendLine('');
            appendLine('tmpFiles = strings(0,1);');
            appendLine('');
            appendLine('try');
            appendLine('');

            for iExec = 1:numel(execOrder)

                nodeID = execOrder(iExec);
                nodeLocal = obj.nodes(nodeIdxByID(nodeID));

                if strcmpi(nodeLocal.kind,'folder')
                    appendLine(sprintf('    %% Source file node: %s', char(string(nodeLocal.name))));
                    continue
                end

                funcName = getCallableFunctionNameLocal(nodeLocal);

                appendLine(sprintf('    %%%% ------------------------------------------------------------'));
                appendLine(sprintf('    %%%% Step %d | TOPO #%d | %s', iExec, topoPosByID(nodeID), char(string(nodeLocal.name))));
                appendLine(sprintf('    %%%% Function: %s', funcName));
                appendLine(sprintf('    %%%% ------------------------------------------------------------'));

                [callArgs, primaryDataFileExpr] = buildCallArguments(nodeLocal);

                outputsLocal = struct([]);
                if isfield(nodeLocal,'info') && isfield(nodeLocal.info,'outputs') && ~isempty(nodeLocal.info.outputs)
                    outputsLocal = sortOutputs(nodeLocal.info.outputs);
                end

                outVarList = {};
                for iOut = 1:numel(outputsLocal)
                    outVarList{end+1} = outputVarByKey(makeKeyLocal(nodeLocal.id, char(string(outputsLocal(iOut).name)))); %#ok<AGROW>
                end

                if isempty(outVarList)
                    callLine = sprintf('    %s(%s);', funcName, strjoin(callArgs, ', '));
                elseif numel(outVarList) == 1
                    callLine = sprintf('    %s = %s(%s);', outVarList{1}, funcName, strjoin(callArgs, ', '));
                else
                    callLine = sprintf('    [%s] = %s(%s);', strjoin(outVarList, ', '), funcName, strjoin(callArgs, ', '));
                end

                appendLine(sprintf('    fprintf(''Running: %s\\n'');', char(string(nodeLocal.name))));
                appendLine(callLine);

                % Post-call save / file materialization
                for iOut = 1:numel(outputsLocal)

                    outDef = outputsLocal(iOut);

                    if ~isfield(outDef,'isData') || ~outDef.isData
                        continue
                    end

                    outNameLocal = char(string(outDef.name));
                    outKey = makeKeyLocal(nodeLocal.id, outNameLocal);
                    outVar = outputVarByKey(outKey);

                    % File-mode output: materialize required files
                    if isfield(outDef,'outputMode') && strcmpi(char(string(outDef.outputMode)),'file')

                        req = fileRequirementsByKey(outKey);

                        if ~isempty(req.files)
                            targetExpr = buildTargetPathCellExpr(req.files);
                            appendLine(sprintf('    localMaterializeOutputFiles(%s, %s);', outVar, targetExpr));

                            for iReq = 1:numel(req.files)
                                if req.isTemp(iReq)
                                    appendLine(sprintf('    tmpFiles(end+1,1) = string(fullfile(SaveFolder, %s));', matlabLiteral(req.files(iReq))));
                                end
                            end
                        end

                        % Data-mode output: explicit save target only
                    else
                        saveFileNameRowsLocal = obj.normalizeOutputSaveFileNameList(outDef);

                        for iSaveLocal = 1:numel(saveFileNameRowsLocal)
                            saveFileNameLocal = char(saveFileNameRowsLocal(iSaveLocal));
                            appendLine(sprintf('    saveData(fullfile(SaveFolder, %s), %s);', ...
                                matlabLiteral(saveFileNameLocal), outVar));
                        end
                    end
                end

                % Metadata note for readability
                if ~isempty(primaryDataFileExpr)
                    appendLine(sprintf('    %% Primary metadata source: %s', primaryDataFileExpr));
                end

                appendLine(sprintf('    fprintf(''Completed: %s\\n\\n'');', char(string(nodeLocal.name))));
                appendLine('');
            end

            appendLine('    tmpFiles = unique(tmpFiles, ''stable'');');
            appendLine('    localCleanupTempFiles(tmpFiles);');
            appendLine('    fprintf(''Pipeline script completed successfully.\\n'');');
            appendLine('');
            appendLine('catch ME');
            appendLine('    try');
            appendLine('        tmpFiles = unique(tmpFiles, ''stable'');');
            appendLine('        localCleanupTempFiles(tmpFiles);');
            appendLine('    catch');
            appendLine('    end');
            appendLine('    rethrow(ME);');
            appendLine('end');
            appendLine('');

            % ---------------------------------------------------------------------
            % Local helper functions inside generated script
            % ---------------------------------------------------------------------
            appendLine('function localMaterializeOutputFiles(outValue, targetPaths)');
            appendLine('%LOCALMATERIALIZEOUTPUTFILES Ensure required output files exist on disk.');
            appendLine('    targetPaths = string(targetPaths(:));');
            appendLine('    if isempty(targetPaths)');
            appendLine('        return');
            appendLine('    end');
            appendLine('');
            appendLine('    sourceFiles = localNormalizeExistingFiles(outValue);');
            appendLine('');
            appendLine('    if ~isempty(sourceFiles)');
            appendLine('        for ii = 1:numel(targetPaths)');
            appendLine('            dstPath = char(targetPaths(ii));');
            appendLine('            dstFolder = fileparts(dstPath);');
            appendLine('            if ~isempty(dstFolder) && ~isfolder(dstFolder)');
            appendLine('                mkdir(dstFolder);');
            appendLine('            end');
            appendLine('');
            appendLine('            srcPath = localPickSourceFile(sourceFiles, targetPaths(ii));');
            appendLine('            srcPath = localToAbsolutePath(srcPath);');
            appendLine('            dstPath = localToAbsolutePath(dstPath);');
            appendLine('');
            appendLine('            if strcmpi(string(srcPath), string(dstPath))');
            appendLine('                continue');
            appendLine('            end');
            appendLine('');
            appendLine('            [ok, msg] = copyfile(srcPath, dstPath);');
            appendLine('            if ~ok');
            appendLine('                error(''GeneratedPipeline:CopyFailed'', ...');
            appendLine('                    ''Failed to copy file "%s" -> "%s". %s'', srcPath, dstPath, msg);');
            appendLine('            end');
            appendLine('        end');
            appendLine('        return');
            appendLine('    end');
            appendLine('');
            appendLine('    for ii = 1:numel(targetPaths)');
            appendLine('        dstPath = char(targetPaths(ii));');
            appendLine('        dstFolder = fileparts(dstPath);');
            appendLine('        if ~isempty(dstFolder) && ~isfolder(dstFolder)');
            appendLine('            mkdir(dstFolder);');
            appendLine('        end');
            appendLine('        saveData(dstPath, outValue);');
            appendLine('    end');
            appendLine('end');
            appendLine('');

            appendLine('function sourceFiles = localNormalizeExistingFiles(outValue)');
            appendLine('%LOCALNORMALIZEEXISTINGFILES Extract existing file paths from an output value.');
            appendLine('    sourceFiles = strings(0,1);');
            appendLine('');
            appendLine('    if ischar(outValue) || (isstring(outValue) && isscalar(outValue))');
            appendLine('        tmp = string(outValue);');
            appendLine('        if isfile(char(tmp))');
            appendLine('            sourceFiles = string(localToAbsolutePath(char(tmp)));');
            appendLine('        end');
            appendLine('        return');
            appendLine('    end');
            appendLine('');
            appendLine('    if isstring(outValue)');
            appendLine('        tmp = outValue(:);');
            appendLine('        keep = false(size(tmp));');
            appendLine('        for ii = 1:numel(tmp)');
            appendLine('            if isfile(char(tmp(ii)))');
            appendLine('                keep(ii) = true;');
            appendLine('                tmp(ii) = string(localToAbsolutePath(char(tmp(ii))));');
            appendLine('            end');
            appendLine('        end');
            appendLine('        sourceFiles = tmp(keep);');
            appendLine('        sourceFiles = unique(sourceFiles, ''stable'');');
            appendLine('        return');
            appendLine('    end');
            appendLine('');
            appendLine('    if iscell(outValue)');
            appendLine('        try');
            appendLine('            tmp = string(outValue(:));');
            appendLine('            keep = false(size(tmp));');
            appendLine('            for ii = 1:numel(tmp)');
            appendLine('                if isfile(char(tmp(ii)))');
            appendLine('                    keep(ii) = true;');
            appendLine('                    tmp(ii) = string(localToAbsolutePath(char(tmp(ii))));');
            appendLine('                end');
            appendLine('            end');
            appendLine('            sourceFiles = tmp(keep);');
            appendLine('            sourceFiles = unique(sourceFiles, ''stable'');');
            appendLine('        catch');
            appendLine('            sourceFiles = strings(0,1);');
            appendLine('        end');
            appendLine('    end');
            appendLine('end');
            appendLine('');

            appendLine('function srcPath = localPickSourceFile(sourceFiles, targetPath)');
            appendLine('%LOCALPICKSOURCEFILE Choose the best source file for one target path.');
            appendLine('    if isempty(sourceFiles)');
            appendLine('        error(''GeneratedPipeline:MissingSourceFile'', ''No source file is available.'');');
            appendLine('    end');
            appendLine('');
            appendLine('    if numel(sourceFiles) == 1');
            appendLine('        srcPath = char(sourceFiles(1));');
            appendLine('        return');
            appendLine('    end');
            appendLine('');
            appendLine('    [~, tgtBase, tgtExt] = fileparts(char(targetPath));');
            appendLine('    tgtName = string(tgtBase) + string(tgtExt);');
            appendLine('');
            appendLine('    for ii = 1:numel(sourceFiles)');
            appendLine('        [~, srcBase, srcExt] = fileparts(char(sourceFiles(ii)));');
            appendLine('        srcName = string(srcBase) + string(srcExt);');
            appendLine('        if strcmpi(srcName, tgtName)');
            appendLine('            srcPath = char(sourceFiles(ii));');
            appendLine('            return');
            appendLine('        end');
            appendLine('    end');
            appendLine('');
            appendLine('    srcPath = char(sourceFiles(1));');
            appendLine('end');
            appendLine('');

            appendLine('function absPath = localToAbsolutePath(pathIn)');
            appendLine('%LOCALTOABSOLUTEPATH Convert a relative path to an absolute path when possible.');
            appendLine('    absPath = char(string(pathIn));');
            appendLine('');
            appendLine('    if isfile(absPath)');
            appendLine('        f = dir(absPath);');
            appendLine('        if ~isempty(f) && isfield(f, ''folder'')');
            appendLine('            absPath = fullfile(f.folder, f.name);');
            appendLine('            return');
            appendLine('        end');
            appendLine('    end');
            appendLine('');
            appendLine('    [folderPart, namePart, extPart] = fileparts(absPath);');
            appendLine('    if isempty(folderPart)');
            appendLine('        absPath = fullfile(pwd, [namePart extPart]);');
            appendLine('    end');
            appendLine('end');
            appendLine('');

            appendLine('function md = localGetMetaData(primaryDataPath, saveFolder)');
            appendLine('%LOCALGETMETADATA Best-effort metadata resolution for legacy functions.');
            appendLine('    md = [];');
            appendLine('');
            appendLine('    if nargin >= 1 && ~isempty(primaryDataPath)');
            appendLine('        md = loadData(primaryDataPath, ''InfoOnly'', true);');
            appendLine('        return');
            appendLine('    end');
            appendLine('');
            appendLine('    infoFile = fullfile(saveFolder, ''AcqInfos.mat'');');
            appendLine('    if ~isfile(infoFile)');
            appendLine('        return');
            appendLine('    end');
            appendLine('');
            appendLine('    S = load(infoFile);');
            appendLine('    if isfield(S, ''AcqInfoStream'')');
            appendLine('        md = S.AcqInfoStream;');
            appendLine('        return');
            appendLine('    end');
            appendLine('');
            appendLine('    fns = fieldnames(S);');
            appendLine('    if ~isempty(fns)');
            appendLine('        md = S.(fns{1});');
            appendLine('    end');
            appendLine('end');
            appendLine('');

            appendLine('function localCleanupTempFiles(tempFilesLocal)');
            appendLine('%LOCALCLEANUPTEMPFILES Delete temporary files created by this script.');
            appendLine('    tempFilesLocal = string(tempFilesLocal(:));');
            appendLine('    tempFilesLocal = unique(tempFilesLocal, ''stable'');');
            appendLine('');
            appendLine('    for ii = 1:numel(tempFilesLocal)');
            appendLine('        fpath = char(tempFilesLocal(ii));');
            appendLine('        if isfile(fpath)');
            appendLine('            delete(fpath);');
            appendLine('        end');
            appendLine('    end');
            appendLine('end');
            appendLine('');

            % ---------------------------------------------------------------------
            % Write file
            % ---------------------------------------------------------------------
            if ~isfolder(outFolder)
                mkdir(outFolder);
            end

            fid = fopen(outPath, 'w');
            if fid == -1
                error('PipelineManager:generateScript:FileOpenFailed', ...
                    'Could not open "%s" for writing.', outPath);
            end

            cleaner = onCleanup(@() fclose(fid)); %#ok<NASGU>
            fprintf(fid, '%s\n', scriptLines{:});

            fprintf('Pipeline script generated: %s\n', outPath);

            % =====================================================================
            % Local helper functions for the generator
            % =====================================================================
            function appendLine(str)
                scriptLines{end+1,1} = str; %#ok<AGROW>
            end

            function key = makeKeyLocal(nodeIDLocal, outputNameLocal)
                key = sprintf('%d:%s', nodeIDLocal, char(string(outputNameLocal)));
            end

            function outputsSorted = sortOutputs(outputsIn)
                outputsSorted = outputsIn;

                if isempty(outputsSorted)
                    return
                end

                pos = inf(1,numel(outputsSorted));
                for kk = 1:numel(outputsSorted)
                    if isfield(outputsSorted(kk),'position') && ~isempty(outputsSorted(kk).position)
                        pos(kk) = outputsSorted(kk).position;
                    else
                        pos(kk) = kk;
                    end
                end

                [~, ord] = sort(pos, 'ascend');
                outputsSorted = outputsSorted(ord);
            end

            function argsSorted = sortArguments(argsIn)
                argsSorted = argsIn;

                if isempty(argsSorted)
                    return
                end

                pos = inf(1,numel(argsSorted));
                for kk = 1:numel(argsSorted)
                    if isfield(argsSorted(kk),'position') && ~isempty(argsSorted(kk).position)
                        pos(kk) = argsSorted(kk).position;
                    else
                        pos(kk) = kk;
                    end
                end

                [~, ord] = sort(pos, 'ascend');
                argsSorted = argsSorted(ord);
            end

            function connsOut = getOutputConnections(sourceNodeIDLocal, sourceOutputNameLocal)
                connsOut = struct([]);

                if isempty(obj.connections)
                    return
                end

                mask = [obj.connections.sourceNodeID] == sourceNodeIDLocal & ...
                    strcmpi({obj.connections.sourceOutputName}, char(string(sourceOutputNameLocal)));

                connsOut = obj.connections(mask);
            end

            function req = appendRequiredFile(req, fileNameLocal, isTempLocal)
                fileNameLocal = string(fileNameLocal);
                if strlength(strtrim(fileNameLocal)) == 0
                    return
                end

                idx = find(strcmpi(req.files, fileNameLocal), 1, 'first');

                if isempty(idx)
                    req.files(end+1,1) = fileNameLocal; %#ok<AGROW>
                    req.isTemp(end+1,1) = logical(isTempLocal); %#ok<AGROW>
                else
                    req.isTemp(idx) = req.isTemp(idx) && logical(isTempLocal);
                end
            end

            function reqFile = resolveConcreteConnectedFileName(srcNodeLocal, outDefLocal, connLocal)
                reqFile = '';

                if isfield(connLocal,'selectedFile') && ~isempty(connLocal.selectedFile)
                    reqFile = char(string(connLocal.selectedFile));
                    return
                end

                defNames = {};
                if isfield(outDefLocal,'defOutfilename') && ~isempty(outDefLocal.defOutfilename)
                    if ischar(outDefLocal.defOutfilename) || isstring(outDefLocal.defOutfilename)
                        defNames = {char(string(outDefLocal.defOutfilename))};
                    elseif iscell(outDefLocal.defOutfilename)
                        defNames = cellfun(@(x) char(string(x)), outDefLocal.defOutfilename, 'UniformOutput', false);
                        defNames = defNames(~cellfun(@isempty, defNames));
                    end
                end

                defNames = unique(defNames, 'stable');

                if numel(defNames) == 1
                    reqFile = defNames{1};
                    return
                end

                if strcmpi(srcNodeLocal.kind,'folder')
                    reqFile = char(string(srcNodeLocal.name));
                end
            end

            function tempFileName = generateTempFileName(nodeLocal, outDefLocal, idxLocal)
                extLocal = '.dat';

                if isfield(outDefLocal,'defOutfilename') && ~isempty(outDefLocal.defOutfilename)
                    defNameLocal = outDefLocal.defOutfilename;
                    if iscell(defNameLocal) && ~isempty(defNameLocal)
                        defNameLocal = defNameLocal{1};
                    end
                    if ischar(defNameLocal) || isstring(defNameLocal)
                        [~,~,extMaybe] = fileparts(char(string(defNameLocal)));
                        if ~isempty(extMaybe)
                            extLocal = extMaybe;
                        end
                    end
                end

                tempFileName = sprintf('%sSCRIPT_%s_%s_%02d%s', ...
                    obj.tempOutputPrefix, ...
                    matlab.lang.makeValidName(char(string(nodeLocal.name))), ...
                    matlab.lang.makeValidName(char(string(outDefLocal.name))), ...
                    idxLocal, ...
                    extLocal);
            end

            function funcNameLocal = getCallableFunctionNameLocal(nodeLocal)
                funcNameLocal = '';

                if isfield(nodeLocal,'info') && isfield(nodeLocal.info,'name') && ~isempty(nodeLocal.info.name)
                    funcNameLocal = char(string(nodeLocal.info.name));
                    return
                end

                if isfield(nodeLocal,'tag') && ~isempty(nodeLocal.tag)
                    tagStrLocal = string(nodeLocal.tag);
                    suffixLocal = "_" + string(nodeLocal.id);
                    if contains(tagStrLocal, suffixLocal)
                        funcNameLocal = char(extractBefore(tagStrLocal, suffixLocal));
                        return
                    end
                end

                funcNameLocal = char(string(nodeLocal.name));
            end

            function [argList, primaryDataFileExprLocal] = buildCallArguments(nodeLocal)
                argList = {};
                primaryDataFileExprLocal = '';

                argsLocal = struct([]);
                if isfield(nodeLocal,'info') && isfield(nodeLocal.info,'arguments') && ~isempty(nodeLocal.info.arguments)
                    argsLocal = sortArguments(nodeLocal.info.arguments);
                else
                    argsLocal = synthesizeArguments(nodeLocal);
                end

                if isfield(nodeLocal.info,'inputs') && ~isempty(nodeLocal.info.inputs)
                    dataInputsLocal = nodeLocal.info.inputs(arrayfun(@(x) isfield(x,'isData') && x.isData, nodeLocal.info.inputs));
                    if ~isempty(dataInputsLocal)
                        [~, primaryDataFileExprLocal] = buildDataInputExpression(nodeLocal, char(string(dataInputsLocal(1).name)));
                    end
                end

                for iArg = 1:numel(argsLocal)

                    argLocal = argsLocal(iArg);
                    argNameLocal = char(string(argLocal.name));

                    callTypeLocal = 'positional';
                    if isfield(argLocal,'callType') && ~isempty(argLocal.callType)
                        callTypeLocal = lower(char(string(argLocal.callType)));
                    end

                    isDataLocal = isfield(argLocal,'isData') && argLocal.isData;

                    if isfield(argLocal,'kind') && strcmpi(argLocal.kind,'input')

                        if isDataLocal
                            [valueExprLocal, ~] = buildDataInputExpression(nodeLocal, argNameLocal);
                        else
                            valueExprLocal = buildNonDataInputExpression(nodeLocal, argNameLocal, primaryDataFileExprLocal);
                        end

                        if strcmpi(callTypeLocal,'namevalue')
                            argList{end+1} = matlabLiteral(argNameLocal); %#ok<AGROW>
                            argList{end+1} = valueExprLocal; %#ok<AGROW>
                        else
                            argList{end+1} = valueExprLocal; %#ok<AGROW>
                        end

                    elseif isfield(argLocal,'kind') && strcmpi(argLocal.kind,'parameter')

                        paramValueLocal = getCurrentParameterValue(nodeLocal, argNameLocal);
                        paramExprLocal = matlabLiteral(paramValueLocal);

                        if strcmpi(callTypeLocal,'namevalue')
                            argList{end+1} = matlabLiteral(argNameLocal); %#ok<AGROW>
                            argList{end+1} = paramExprLocal; %#ok<AGROW>
                        else
                            argList{end+1} = paramExprLocal; %#ok<AGROW>
                        end
                    else
                        error('PipelineManager:generateScript:UnsupportedArgumentKind', ...
                            'Unsupported argument kind for step "%s".', char(string(nodeLocal.name)));
                    end
                end
            end

            function argsSynth = synthesizeArguments(nodeLocal)
                argsSynth = struct('name', {}, 'kind', {}, 'position', {}, 'callType', {}, 'isData', {});

                posCounter = 0;

                if isfield(nodeLocal,'info') && isfield(nodeLocal.info,'inputs') && ~isempty(nodeLocal.info.inputs)
                    for iIn = 1:numel(nodeLocal.info.inputs)
                        posCounter = posCounter + 1;
                        argsSynth(end+1) = struct( ... %#ok<AGROW>
                            'name', nodeLocal.info.inputs(iIn).name, ...
                            'kind', 'input', ...
                            'position', posCounter, ...
                            'callType', 'positional', ...
                            'isData', isfield(nodeLocal.info.inputs(iIn),'isData') && nodeLocal.info.inputs(iIn).isData);
                    end
                end

                if isfield(nodeLocal,'info') && isfield(nodeLocal.info,'parameters') && ~isempty(nodeLocal.info.parameters)
                    for iP = 1:numel(nodeLocal.info.parameters)
                        posCounter = posCounter + 1;
                        argsSynth(end+1) = struct( ... %#ok<AGROW>
                            'name', nodeLocal.info.parameters(iP).name, ...
                            'kind', 'parameter', ...
                            'position', posCounter, ...
                            'callType', 'namevalue', ...
                            'isData', false);
                    end
                end
            end

            function [valueExprLocal, fileExprLocal] = buildDataInputExpression(nodeLocal, inputNameLocal)
                valueExprLocal = '';
                fileExprLocal = '';

                if isempty(obj.connections)
                    error('PipelineManager:generateScript:MissingInputConnection', ...
                        'Missing data connection for step "%s" input "%s".', ...
                        char(string(nodeLocal.name)), inputNameLocal);
                end

                connMask = [obj.connections.targetNodeID] == nodeLocal.id & ...
                    strcmpi({obj.connections.targetInputName}, inputNameLocal);

                connHits = obj.connections(connMask);

                if isempty(connHits)
                    error('PipelineManager:generateScript:MissingInputConnection', ...
                        'Missing data connection for step "%s" input "%s".', ...
                        char(string(nodeLocal.name)), inputNameLocal);
                end

                connLocal = connHits(1);
                srcNodeLocal = obj.nodes(nodeIdxByID(connLocal.sourceNodeID));

                srcOutNameLocal = char(string(connLocal.sourceOutputName));
                srcOutDefLocal = getSourceOutputDefinition(srcNodeLocal, srcOutNameLocal);

                if strcmpi(srcNodeLocal.kind,'folder')
                    srcFileNameLocal = char(string(srcNodeLocal.name));
                    valueExprLocal = sprintf('loadData(fullfile(SaveFolder, %s))', matlabLiteral(srcFileNameLocal));
                    fileExprLocal = sprintf('fullfile(SaveFolder, %s)', matlabLiteral(srcFileNameLocal));
                    return
                end

                isFileModeLocal = isfield(srcOutDefLocal,'outputMode') && strcmpi(char(string(srcOutDefLocal.outputMode)),'file');

                if isFileModeLocal
                    srcFileNameLocal = resolveConcreteConnectedFileName(srcNodeLocal, srcOutDefLocal, connLocal);

                    if isempty(srcFileNameLocal)
                        srcFileNameLocal = generateTempFileName(srcNodeLocal, srcOutDefLocal, 1);
                    end

                    valueExprLocal = sprintf('loadData(fullfile(SaveFolder, %s))', matlabLiteral(srcFileNameLocal));
                    fileExprLocal = sprintf('fullfile(SaveFolder, %s)', matlabLiteral(srcFileNameLocal));
                    return
                end

                srcKeyLocal = makeKeyLocal(srcNodeLocal.id, srcOutNameLocal);

                if ~isKey(outputVarByKey, srcKeyLocal)
                    error('PipelineManager:generateScript:MissingSourceVariable', ...
                        'Missing source output variable for node %d output "%s".', ...
                        srcNodeLocal.id, srcOutNameLocal);
                end

                valueExprLocal = outputVarByKey(srcKeyLocal);
                fileExprLocal = '';
            end

            function valueExprLocal = buildNonDataInputExpression(nodeLocal, inputNameLocal, primaryDataFileExprLocal)
                valueExprLocal = '';

                % Try semantic type first
                inDefLocal = [];
                if isfield(nodeLocal,'info') && isfield(nodeLocal.info,'inputs') && ~isempty(nodeLocal.info.inputs)
                    idxLocal = find(strcmpi({nodeLocal.info.inputs.name}, inputNameLocal), 1, 'first');
                    if ~isempty(idxLocal)
                        inDefLocal = nodeLocal.info.inputs(idxLocal);
                    end
                end

                inputNameLowerLocal = lower(strtrim(inputNameLocal));
                inputTypesLocal = strings(0,1);

                if ~isempty(inDefLocal) && isfield(inDefLocal,'type') && ~isempty(inDefLocal.type)
                    if ischar(inDefLocal.type) || (isstring(inDefLocal.type) && isscalar(inDefLocal.type))
                        inputTypesLocal = string(inDefLocal.type);
                    else
                        inputTypesLocal = string(inDefLocal.type(:));
                    end
                end

                if strcmp(inputNameLowerLocal,'savefolder') || any(strcmpi(inputTypesLocal,'SaveFolder'))
                    valueExprLocal = 'SaveFolder';
                    return
                end

                if strcmp(inputNameLowerLocal,'rawfolder') || any(strcmpi(inputTypesLocal,'RawFolder'))
                    valueExprLocal = 'RawFolder';
                    return
                end

                if strcmp(inputNameLowerLocal,'metadata') || any(strcmpi(inputTypesLocal,'metaData'))
                    if isempty(primaryDataFileExprLocal)
                        valueExprLocal = 'localGetMetaData([], SaveFolder)';
                    else
                        valueExprLocal = sprintf('localGetMetaData(%s, SaveFolder)', primaryDataFileExprLocal);
                    end
                    return
                end

                error('PipelineManager:generateScript:UnsupportedNonDataInput', ...
                    'Unsupported non-data input "%s" in step "%s".', ...
                    inputNameLocal, char(string(nodeLocal.name)));
            end

            function outDefLocal = getSourceOutputDefinition(srcNodeLocal, outputNameLocal)
                if ~isfield(srcNodeLocal,'info') || ~isfield(srcNodeLocal.info,'outputs') || isempty(srcNodeLocal.info.outputs)
                    error('PipelineManager:generateScript:MissingOutputDefinition', ...
                        'Source node "%s" has no output definitions.', char(string(srcNodeLocal.name)));
                end

                idxLocal = find(strcmpi({srcNodeLocal.info.outputs.name}, outputNameLocal), 1, 'first');
                if isempty(idxLocal)
                    error('PipelineManager:generateScript:MissingOutputDefinition', ...
                        'Output "%s" was not found in source node "%s".', ...
                        outputNameLocal, char(string(srcNodeLocal.name)));
                end

                outDefLocal = srcNodeLocal.info.outputs(idxLocal);
            end

            function paramValueLocal = getCurrentParameterValue(nodeLocal, paramNameLocal)
                paramValueLocal = [];

                if ~isfield(nodeLocal,'info') || ~isfield(nodeLocal.info,'parameters') || isempty(nodeLocal.info.parameters)
                    error('PipelineManager:generateScript:MissingParameter', ...
                        'Step "%s" has no parameters.', char(string(nodeLocal.name)));
                end

                idxLocal = find(strcmpi({nodeLocal.info.parameters.name}, paramNameLocal), 1, 'first');
                if isempty(idxLocal)
                    error('PipelineManager:generateScript:MissingParameter', ...
                        'Parameter "%s" was not found in step "%s".', ...
                        paramNameLocal, char(string(nodeLocal.name)));
                end

                paramDefLocal = nodeLocal.info.parameters(idxLocal);

                candidateFieldsLocal = {'value','currentValue','selectedValue','defaultValue','default'};

                for iFld = 1:numel(candidateFieldsLocal)
                    fldLocal = candidateFieldsLocal{iFld};
                    if isfield(paramDefLocal, fldLocal)
                        paramValueLocal = paramDefLocal.(fldLocal);
                        return
                    end
                end
            end

            function exprLocal = buildTargetPathCellExpr(fileNamesLocal)
                partsLocal = strings(0,1);

                for iF = 1:numel(fileNamesLocal)
                    partsLocal(end+1,1) = "fullfile(SaveFolder, " + string(matlabLiteral(fileNamesLocal(iF))) + ")"; %#ok<AGROW>
                end

                exprLocal = ['{' strjoin(cellstr(partsLocal.'), ', ') '}'];
            end

            function txtLocal = matlabLiteral(valueLocal)
                if ischar(valueLocal)
                    txtLocal = ['''' strrep(valueLocal, '''', '''''') ''''];
                    return
                end

                if isstring(valueLocal)
                    if isempty(valueLocal)
                        txtLocal = 'string.empty';
                        return
                    end

                    if isscalar(valueLocal)
                        strLocal = char(valueLocal);
                        strLocal = strrep(strLocal, '"', '""');
                        txtLocal = ['"' strLocal '"'];
                        return
                    end

                    error('PipelineManager:generateScript:UnsupportedStringArray', ...
                        'String arrays are not currently supported in generateScript literals.');
                end

                if isnumeric(valueLocal) || islogical(valueLocal)
                    txtLocal = mat2str(valueLocal);
                    return
                end

                if isempty(valueLocal)
                    txtLocal = '[]';
                    return
                end

                if isa(valueLocal,'function_handle')
                    txtLocal = ['@' func2str(valueLocal)];
                    return
                end

                if iscell(valueLocal)
                    szLocal = size(valueLocal);
                    rowsLocal = cell(szLocal(1),1);

                    for iRow = 1:szLocal(1)
                        colsLocal = cell(1, szLocal(2));
                        for iCol = 1:szLocal(2)
                            colsLocal{iCol} = matlabLiteral(valueLocal{iRow,iCol});
                        end
                        rowsLocal{iRow} = strjoin(colsLocal, ', ');
                    end

                    txtLocal = ['{' strjoin(rowsLocal, '; ') '}'];
                    return
                end

                if isstruct(valueLocal) && isscalar(valueLocal)
                    fnLocal = fieldnames(valueLocal);
                    partsLocal = cell(1, 2*numel(fnLocal));

                    idxPart = 1;
                    for iFld = 1:numel(fnLocal)
                        partsLocal{idxPart} = matlabLiteral(fnLocal{iFld});
                        partsLocal{idxPart+1} = matlabLiteral(valueLocal.(fnLocal{iFld}));
                        idxPart = idxPart + 2;
                    end

                    txtLocal = ['struct(' strjoin(partsLocal, ', ') ')'];
                    return
                end

                error('PipelineManager:generateScript:UnsupportedLiteralType', ...
                    'Unsupported parameter literal type: %s', class(valueLocal));
            end
        end

        function [stepTag, srcNodeID] = ensureFileSourceStep(obj, filePath, varargin)
            %ENSUREFILESOURCESTEP Create or reuse a FileSource step for one file.
            %
            %   [stepTag, srcNodeID] = ensureFileSourceStep(obj, filePath)
            %   [stepTag, srcNodeID] = ensureFileSourceStep(..., 'SemanticTypes', types)
            %
            % This public wrapper is used by DataViewer-managed PipelineManagerTool
            % launch. It keeps the existing private FileSource-node creation logic as
            % the single implementation point.

            p = inputParser;
            addRequired(p, 'filePath', @(x)ischar(x)||isstring(x));
            addParameter(p, 'SemanticTypes', {'UnknownDataType'}, ...
                @(x)ischar(x)||isstring(x)||iscell(x));
            parse(p, filePath, varargin{:});

            semanticTypes = p.Results.SemanticTypes;
            if ischar(semanticTypes) || (isstring(semanticTypes) && isscalar(semanticTypes))
                semanticTypes = {char(string(semanticTypes))};
            else
                semanticTypes = cellstr(string(semanticTypes(:)));
            end

            semanticTypes = semanticTypes(~cellfun(@isempty, semanticTypes));
            if isempty(semanticTypes)
                semanticTypes = {'UnknownDataType'};
            end

            srcNodeID = obj.ensureFileSourceNode(p.Results.filePath, semanticTypes);

            idx = find([obj.nodes.id] == srcNodeID, 1, 'first');
            if isempty(idx)
                error('PipelineManager:ensureFileSourceStep:InternalError', ...
                    'FileSource node was not found after creation.');
            end

            stepTag = char(string(obj.nodes(idx).name));

            try
                obj.updateTopoOrder();
                obj.autoValidate();
            catch
                % Keep source creation usable even before the graph has downstream
                % steps. Later validation will report actionable graph issues.
            end

            if isprop(obj, 'activeLeafNodeID')
                obj.activeLeafNodeID = srcNodeID;
            end
        end

        %%%%%%--Pipeline Visualization  -----------------------------------
        function varargout = viewExecutionPlan(obj, varargin)
            %VIEWEXECUTIONPLAN Print a user-facing execution plan.
            %
            % Pipeline visualization is handled by the PipelineManager GUI. This
            % CLI method prints backend-owned tables from getExecutionPlan so callers
            % can inspect order and output-persistence metadata without parsing
            % presentation text.
            %
            % Display convention:
            %   - Virtual input sources are FileSource/folder nodes. They are graph
            %     roots and may appear in the scheduler visit order, but they do not
            %     execute functions and do not load data into RAM by themselves.
            %   - Executable analysis steps are stream nodes. Their runIndex is the
            %     user-facing execution order.

            p = inputParser;
            addParameter(p, 'LeafOutputPolicy', obj.leafOutputPolicy, @(x)ischar(x)||isstring(x));
            addParameter(p, 'SaveFolder', '', @(x)ischar(x)||isstring(x));
            parse(p, varargin{:});

            plan = obj.getExecutionPlan( ...
                'LeafOutputPolicy', p.Results.LeafOutputPolicy, ...
                'SaveFolder', p.Results.SaveFolder);

            fprintf('\n================ PIPELINE EXECUTION PLAN ================\n');
            fprintf('Output policy:   %s\n', char(plan.leafOutputPolicy));
            fprintf('TempSessionTag:  %s\n', char(plan.tempSessionTag));
            if isfield(plan, 'saveFolder') && strlength(string(plan.saveFolder)) > 0
                fprintf('SaveFolder:      %s\n', char(string(plan.saveFolder)));
            end
            fprintf('\n');

            nodeTable = table();
            if isfield(plan, 'nodeTable') && istable(plan.nodeTable)
                nodeTable = plan.nodeTable;
            end

            edgeTable = table();
            if isfield(plan, 'edgeTable') && istable(plan.edgeTable)
                edgeTable = plan.edgeTable;
            end

            % -------------------------------------------------------------
            % Virtual sources
            % -------------------------------------------------------------
            sourceTable = buildVirtualSourceDisplayTable(nodeTable, edgeTable);
            fprintf('--- Virtual input sources (not executable steps) ---\n');
            if isempty(sourceTable)
                fprintf('  <none>\n\n');
            else
                disp(sourceTable)
            end

            % -------------------------------------------------------------
            % Executable steps
            % -------------------------------------------------------------
            runTable = buildRunDisplayTable(nodeTable);
            fprintf('--- Executable analysis steps ---\n');
            if isempty(runTable)
                fprintf('  <none>\n\n');
            else
                disp(runTable)
            end

            fprintf('--- Data flow ---\n');
            if isempty(edgeTable)
                fprintf('  <none>\n\n');
            else
                disp(edgeTable)
            end

            fprintf('--- Output persistence plan ---\n');
            if isfield(plan, 'outputPlan') && istable(plan.outputPlan) && ~isempty(plan.outputPlan)
                disp(plan.outputPlan)
            else
                fprintf('  <none>\n\n');
            end

            fprintf('=========================================================\n\n');

            if nargout > 0
                varargout{1} = plan;
            end

            % =============================================================
            % Local helpers
            % =============================================================
            function T = buildVirtualSourceDisplayTable(nodeTableLocal, edgeTableLocal)
                T = table();

                if ~istable(nodeTableLocal) || isempty(nodeTableLocal)
                    return
                end

                if ismember('executionRole', nodeTableLocal.Properties.VariableNames)
                    sourceRows = nodeTableLocal(strcmpi(string(nodeTableLocal.executionRole), "virtual_source"), :);
                elseif ismember('isExecutable', nodeTableLocal.Properties.VariableNames)
                    sourceRows = nodeTableLocal(~logical(nodeTableLocal.isExecutable), :);
                else
                    sourceRows = nodeTableLocal(strcmpi(string(nodeTableLocal.kind), "folder"), :);
                end

                if isempty(sourceRows)
                    return
                end

                [~, ord] = sort(sourceRows.scheduleIndex, 'ascend', 'MissingPlacement', 'last');
                sourceRows = sourceRows(ord, :);

                sourceIndex = (1:height(sourceRows)).';
                nodeID = sourceRows.nodeID;
                sourceFile = sourceRows.stepName;
                scheduleIndex = sourceRows.scheduleIndex;
                feedsStep = strings(height(sourceRows), 1);
                sourceType = strings(height(sourceRows), 1);

                for iRow = 1:height(sourceRows)
                    if istable(edgeTableLocal) && ~isempty(edgeTableLocal) && ...
                            all(ismember({'sourceNodeID','targetStep'}, edgeTableLocal.Properties.VariableNames))

                        eRows = edgeTableLocal(edgeTableLocal.sourceNodeID == sourceRows.nodeID(iRow), :);

                        if ~isempty(eRows)
                            feedsStep(iRow) = strjoin(unique(string(eRows.targetStep), 'stable'), ', ');

                            if ismember('sourceTypes', eRows.Properties.VariableNames)
                                typeVals = strings(0,1);
                                for iEdge = 1:height(eRows)
                                    try
                                        typeVals = [typeVals; string(eRows.sourceTypes{iEdge}(:))]; %#ok<AGROW>
                                    catch
                                    end
                                end
                                typeVals = unique(typeVals(strlength(strtrim(typeVals)) > 0), 'stable');
                                if ~isempty(typeVals)
                                    sourceType(iRow) = strjoin(typeVals, ' / ');
                                end
                            end
                        end
                    end
                end

                T = table(sourceIndex, nodeID, sourceFile, scheduleIndex, feedsStep, sourceType);
            end

            function T = buildRunDisplayTable(nodeTableLocal)
                T = table();

                if ~istable(nodeTableLocal) || isempty(nodeTableLocal)
                    return
                end

                if ismember('isExecutable', nodeTableLocal.Properties.VariableNames)
                    runRows = nodeTableLocal(logical(nodeTableLocal.isExecutable), :);
                else
                    runRows = nodeTableLocal(strcmpi(string(nodeTableLocal.kind), "stream"), :);
                end

                if isempty(runRows)
                    return
                end

                [~, ord] = sort(runRows.runIndex, 'ascend', 'MissingPlacement', 'last');
                runRows = runRows(ord, :);

                keepVars = {'runIndex','nodeID','stepName','functionName','scheduleIndex','topoIndex','isLeaf'};
                keepVars = keepVars(ismember(keepVars, runRows.Properties.VariableNames));
                T = runRows(:, keepVars);
            end
        end

        function plan = getExecutionPlan(obj, varargin)
            %GETEXECUTIONPLAN Return structured execution and output-persistence plan.
            %
            %   plan = getExecutionPlan(obj)
            %   plan = getExecutionPlan(obj, 'LeafOutputPolicy', policy)
            %
            %   This method does not execute functions. It summarizes graph order,
            %   data flow, validation state, and planned output persistence so CLI
            %   callers and GUI frontends consume the same backend-owned data.

            p = inputParser;
            addParameter(p, 'LeafOutputPolicy', obj.leafOutputPolicy, @(x)ischar(x)||isstring(x));
            addParameter(p, 'SaveFolder', '', @(x)ischar(x)||isstring(x));
            parse(p, varargin{:});

            policy = obj.resolveLeafOutputPolicy(p.Results.LeafOutputPolicy);
            saveFolder = char(string(p.Results.SaveFolder));
            if isempty(saveFolder) && ~isempty(obj.SaveFolderList)
                saveFolder = obj.SaveFolderList{1};
            end

            if isempty(obj.currentTempSessionTag)
                obj.currentTempSessionTag = obj.makeTempSessionTag();
            end

            validationReport = obj.diagnosePipeline('verbose', false);
            nodeOrders = obj.getNodeOrders();
            edgeTable = obj.buildEdgeTable();
            outputPlan = obj.buildOutputPlan(policy, saveFolder);

            plan = struct();
            plan.createdOn = datetime('now');
            plan.leafOutputPolicy = string(policy);
            plan.tempOutputPrefix = string(obj.tempOutputPrefix);
            plan.tempSessionTag = string(obj.currentTempSessionTag);
            plan.saveFolder = string(saveFolder);
            plan.nodeOrders = nodeOrders;
            plan.nodeTable = nodeOrders.nodeTable;
            plan.edgeTable = edgeTable;
            plan.outputPlan = outputPlan;
            plan.validationReport = validationReport;
        end

    end

    methods (Access = private)


        function policy = resolveLeafOutputPolicy(~, policyIn)
            %RESOLVELEAFOUTPUTPOLICY Validate and normalize a leaf-output policy.

            allowed = {'explicit','saveLeaves','viewerTemp','transient'};
            policy = char(string(policyIn));
            policy = strtrim(policy);

            if isempty(policy)
                policy = 'explicit';
                return
            end

            idx = find(strcmpi(policy, allowed), 1, 'first');
            if isempty(idx)
                error('PipelineManager:LeafOutputPolicy:InvalidPolicy', ...
                    'Invalid leafOutputPolicy "%s". Allowed values: %s', ...
                    policy, strjoin(allowed, ', '));
            end

            policy = allowed{idx};
        end

        function sessionTag = makeTempSessionTag(~)
            %MAKETEMPSESSIONTAG Create a compact unique tag for PMTMP_* files.

            timePart = char(datetime('now','Format','yyyyMMdd_HHmmss_SSS'));
            randPart = char(string(randi([1000 9999])));
            sessionTag = [timePart '_' randPart];
        end

        function baseName = makeTempOutputBaseName(obj, nodeLocal, outDef)
            %MAKETEMPOUTPUTBASENAME Build an extensionless same-folder PMTMP_* name.

            if isempty(obj.currentTempSessionTag)
                obj.currentTempSessionTag = obj.makeTempSessionTag();
            end

            stepTag = matlab.lang.makeValidName(char(string(nodeLocal.name)));
            outTag  = matlab.lang.makeValidName(char(string(outDef.name)));
            baseName = sprintf('%s%s_%s_%s', ...
                obj.tempOutputPrefix, obj.currentTempSessionTag, stepTag, outTag);
        end

        function tf = isManagerSaveableOutput(~, outDef)
            %ISMANAGERSAVEABLEOUTPUT True for DATA outputs saved by PipelineManager.

            tf = false;

            if ~isfield(outDef,'isData') || ~logical(outDef.isData)
                return
            end

            outputMode = 'data';
            if isfield(outDef,'outputMode') && ~isempty(outDef.outputMode)
                outputMode = lower(strtrim(char(string(outDef.outputMode))));
            end

            tf = ~strcmpi(outputMode, 'file');
        end

        function names = normalizeOutputSaveFileNameList(~, outDef)
            %NORMALIZEOUTPUTSAVEFILENAMELIST Return non-empty manager-save targets.
            %
            %   saveFileName is expected to be scalar for each output, but legacy
            %   or empty struct-array defaults can leave it as {}, string arrays,
            %   or other text-like containers. This helper centralizes the
            %   normalization so planning, execution, and script export do not call
            %   char(string(...)) on non-scalar containers.

            names = strings(0,1);

            if ~isfield(outDef, 'saveFileName') || isempty(outDef.saveFileName)
                return
            end

            raw = outDef.saveFileName;

            try
                if ischar(raw) || (isstring(raw) && isscalar(raw))
                    vals = string(raw);
                elseif isstring(raw)
                    vals = raw(:);
                elseif iscell(raw)
                    if isempty(raw)
                        return
                    end
                    vals = string(raw(:));
                else
                    vals = string(raw);
                    vals = vals(:);
                end
            catch
                return
            end

            vals = strip(vals);
            vals = vals(strlength(vals) > 0);
            vals = vals(~ismissing(vals));

            if isempty(vals)
                return
            end

            names = unique(vals(:), 'stable');
        end

        function tf = outputHasDownstreamConsumer(obj, nodeID, outputName)
            %OUTPUTHASDOWNSTREAMCONSUMER True if an output feeds another node.

            tf = false;
            if isempty(obj.connections)
                return
            end

            tf = any([obj.connections.sourceNodeID] == nodeID & ...
                strcmpi({obj.connections.sourceOutputName}, char(string(outputName))));
        end

        function tf = isViewerCompatibleOutputCandidate(~, outDef)
            %ISVIEWERCOMPATIBLEOUTPUTCANDIDATE Pre-execution viewer compatibility.
            %
            % Image/ImageTimeSeries outputs are direct candidates. ProcessedData is
            % a candidate because it may be saved as a UMT file with kind='image',
            % which is verified after execution from the produced file.

            tf = false;

            if ~isfield(outDef,'isData') || ~logical(outDef.isData)
                return
            end

            types = strings(0,1);
            if isfield(outDef,'type') && ~isempty(outDef.type)
                types = string(outDef.type(:));
            end

            tf = any(strcmpi(types, "Image")) || ...
                any(strcmpi(types, "ImageTimeSeries")) || ...
                any(strcmpi(types, "ProcessedData"));
        end

        function fName = inferLeafOutputFileName(obj, nodeLocal, outDef, asTemp)
            %INFERLEAFOUTPUTFILENAME Return a folder-bound base filename for leaf saving.

            if nargin < 4
                asTemp = false;
            end

            if asTemp
                fName = obj.makeTempOutputBaseName(nodeLocal, outDef);
                return
            end

            fName = '';

            if isfield(outDef,'defOutfilename') && ~isempty(outDef.defOutfilename)
                def = outDef.defOutfilename;
                if iscell(def)
                    def = def(~cellfun(@isempty, def));
                    if ~isempty(def)
                        def = def{1};
                    else
                        def = '';
                    end
                end
                fName = char(string(def));
            end

            if isempty(strtrim(fName))
                stepTag = matlab.lang.makeValidName(char(string(nodeLocal.name)));
                outTag = matlab.lang.makeValidName(char(string(outDef.name)));
                fName = sprintf('%s_%s', stepTag, outTag);
            end
        end

        function fileList = normalizeDefaultOutputFileList(~, outDef)
            %NORMALIZEDEFAULTOUTPUTFILELIST Return declared default output files.

            fileList = strings(0,1);

            if ~isfield(outDef,'defOutfilename') || isempty(outDef.defOutfilename)
                return
            end

            def = outDef.defOutfilename;
            if ischar(def) || (isstring(def) && isscalar(def))
                fileList = string(def);
            elseif isstring(def)
                fileList = def(:);
            elseif iscell(def)
                try
                    fileList = string(def(:));
                catch
                    fileList = strings(0,1);
                end
            end

            fileList = strip(fileList(:));
            fileList = fileList(strlength(fileList) > 0);
            fileList = unique(fileList, 'stable');
        end

        function edgeTable = buildEdgeTable(obj)
            %BUILDEDGETABLE Return one row per graph connection.

            if isempty(obj.connections)
                edgeTable = table();
                return
            end

            n = numel(obj.connections);
            sourceNodeID = zeros(n,1);
            sourceStep = strings(n,1);
            sourceOutput = strings(n,1);
            selectedFile = strings(n,1);
            targetNodeID = zeros(n,1);
            targetStep = strings(n,1);
            targetInput = strings(n,1);
            sourceTypes = cell(n,1);

            for i = 1:n
                c = obj.connections(i);
                sourceNodeID(i) = c.sourceNodeID;
                targetNodeID(i) = c.targetNodeID;
                sourceOutput(i) = string(c.sourceOutputName);
                targetInput(i) = string(c.targetInputName);

                if isfield(c,'selectedFile') && ~isempty(c.selectedFile)
                    selectedFile(i) = string(c.selectedFile);
                else
                    selectedFile(i) = "";
                end

                try
                    sourceStep(i) = string(obj.nodes(obj.getNodeIndexByID(c.sourceNodeID)).name);
                catch
                    sourceStep(i) = "<missing>";
                end

                try
                    targetStep(i) = string(obj.nodes(obj.getNodeIndexByID(c.targetNodeID)).name);
                catch
                    targetStep(i) = "<missing>";
                end

                if isfield(c,'sourceOutputType') && ~isempty(c.sourceOutputType)
                    sourceTypes{i} = cellstr(string(c.sourceOutputType(:)));
                else
                    sourceTypes{i} = {};
                end
            end

            edgeTable = table(sourceNodeID, sourceStep, sourceOutput, selectedFile, ...
                targetNodeID, targetStep, targetInput, sourceTypes);
        end

        function outputPlan = buildOutputPlan(obj, policy, saveFolder)
            %BUILDOUTPUTPLAN Build one row per declared/planned output artifact.

            if isempty(obj.nodes)
                outputPlan = table();
                return
            end

            policy = obj.resolveLeafOutputPolicy(policy);

            nodeID = zeros(0,1);
            stepTag = strings(0,1);
            functionName = strings(0,1);
            outputName = strings(0,1);
            outputMode = strings(0,1);
            outputTypes = cell(0,1);
            isData = false(0,1);
            isFinalOutput = false(0,1);
            isSaveable = false(0,1);
            isViewerCompatibleCandidate = false(0,1);
            plannedPersistence = strings(0,1);
            plannedFileName = strings(0,1);
            plannedFilePath = strings(0,1);
            reason = strings(0,1);

            reservedAutoNames = strings(0,1);

            obj.updateTopoOrder();
            nodeIDsToVisit = obj.topoOrder(:)';
            if isempty(nodeIDsToVisit)
                nodeIDsToVisit = [obj.nodes.id];
            end

            for iNodeID = 1:numel(nodeIDsToVisit)
                nodeLocal = obj.nodes(obj.getNodeIndexByID(nodeIDsToVisit(iNodeID)));

                if ~isfield(nodeLocal,'info') || ~isfield(nodeLocal.info,'outputs') || isempty(nodeLocal.info.outputs)
                    continue
                end

                for iOut = 1:numel(nodeLocal.info.outputs)
                    outDef = nodeLocal.info.outputs(iOut);

                    outNameLocal = char(string(outDef.name));
                    outModeLocal = 'data';
                    if isfield(outDef,'outputMode') && ~isempty(outDef.outputMode)
                        outModeLocal = lower(strtrim(char(string(outDef.outputMode))));
                    end

                    outIsData = isfield(outDef,'isData') && logical(outDef.isData);
                    saveable = obj.isManagerSaveableOutput(outDef);
                    finalOut = outIsData && ~obj.outputHasDownstreamConsumer(nodeLocal.id, outNameLocal);
                    viewerCandidate = obj.isViewerCompatibleOutputCandidate(outDef);

                    typeList = {};
                    if isfield(outDef,'type') && ~isempty(outDef.type)
                        typeList = cellstr(string(outDef.type(:)));
                    end

                    fileRows = strings(0,1);
                    persistenceLocal = "";
                    reasonLocal = "";

                    if strcmpi(outModeLocal, 'file')
                        fileRows = obj.normalizeDefaultOutputFileList(outDef);
                        if isempty(fileRows)
                            fileRows = "";
                        end
                        persistenceLocal = "already_file";
                        reasonLocal = "Function-owned file output.";

                    else
                        saveFileRows = obj.normalizeOutputSaveFileNameList(outDef);

                        if saveable && ~isempty(saveFileRows)
                            fileRows = saveFileRows;
                            persistenceLocal = "saved_explicit";
                            reasonLocal = "Explicit save target configured.";

                        elseif finalOut
                            switch lower(policy)
                                case 'saveleaves'
                                    [resolvedName, reservedAutoNames] = obj.resolveAutoFinalOutputFileName( ...
                                        nodeLocal, outDef, saveFolder, reservedAutoNames, ...
                                        'asTemp', false);
                                    fileRows = string(resolvedName);
                                    persistenceLocal = "saved_final";
                                    reasonLocal = "Output policy=saveLeaves.";

                                case 'viewertemp'
                                    if viewerCandidate
                                        [resolvedName, reservedAutoNames] = obj.resolveAutoFinalOutputFileName( ...
                                            nodeLocal, outDef, saveFolder, reservedAutoNames, ...
                                            'asTemp', true);
                                        fileRows = string(resolvedName);
                                        persistenceLocal = "saved_temp";
                                        reasonLocal = "Output policy=viewerTemp and output can be opened by DataViewer.";
                                    else
                                        fileRows = "";
                                        persistenceLocal = "unsaved_reported";
                                        reasonLocal = "Output policy=viewerTemp, but output is not a DataViewer-compatible candidate.";
                                    end

                                case 'transient'
                                    fileRows = "";
                                    persistenceLocal = "transient_explicit";
                                    reasonLocal = "Output policy=transient.";

                                otherwise
                                    fileRows = "";
                                    persistenceLocal = "unsaved_reported";
                                    reasonLocal = "No explicit save target and output policy=explicit.";
                            end
                        else
                            fileRows = "";
                            persistenceLocal = "not_final_intermediate";
                            reasonLocal = "Output feeds another step or is not DATA.";
                        end
                    end

                    for iFile = 1:numel(fileRows)
                        thisFile = string(fileRows(iFile));
                        thisPath = "";
                        if strlength(thisFile) > 0 && ~isempty(saveFolder)
                            thisPath = string(fullfile(saveFolder, char(thisFile)));
                        end

                        nodeID(end+1,1) = nodeLocal.id; %#ok<AGROW>
                        stepTag(end+1,1) = string(nodeLocal.name); %#ok<AGROW>
                        functionName(end+1,1) = string(obj.getCallableFuncName(nodeLocal)); %#ok<AGROW>
                        outputName(end+1,1) = string(outNameLocal); %#ok<AGROW>
                        outputMode(end+1,1) = string(outModeLocal); %#ok<AGROW>
                        outputTypes{end+1,1} = typeList; %#ok<AGROW>
                        isData(end+1,1) = outIsData; %#ok<AGROW>
                        isFinalOutput(end+1,1) = finalOut; %#ok<AGROW>
                        isSaveable(end+1,1) = saveable; %#ok<AGROW>
                        isViewerCompatibleCandidate(end+1,1) = viewerCandidate; %#ok<AGROW>
                        plannedPersistence(end+1,1) = persistenceLocal; %#ok<AGROW>
                        plannedFileName(end+1,1) = thisFile; %#ok<AGROW>
                        plannedFilePath(end+1,1) = thisPath; %#ok<AGROW>
                        reason(end+1,1) = reasonLocal; %#ok<AGROW>
                    end
                end
            end

            outputPlan = table(nodeID, stepTag, functionName, outputName, outputMode, ...
                outputTypes, isData, isFinalOutput, isSaveable, ...
                isViewerCompatibleCandidate, plannedPersistence, plannedFileName, ...
                plannedFilePath, reason);
        end

        function evt = emitExecutionProgress(obj, progressFcn, eventType, varargin)
            %EMITEXECUTIONPROGRESS Emit and record one execution-progress event.
            %
            %   The event struct intentionally uses a fixed field set so GUI and
            %   test callbacks can consume it without checking many optional fields.

            evt = struct( ...
                'type', string(eventType), ...
                'timestamp', datetime('now'), ...
                'folderIndex', NaN, ...
                'numFolders', NaN, ...
                'saveFolder', "", ...
                'rawFolder', "", ...
                'stepIndex', NaN, ...
                'numSteps', NaN, ...
                'stepID', NaN, ...
                'stepTag', "", ...
                'functionName', "", ...
                'status', "", ...
                'message', "", ...
                'location', "");

            for iArg = 1:2:numel(varargin)
                key = char(string(varargin{iArg}));
                val = varargin{iArg+1};

                if isfield(evt, key)
                    switch key
                        case {'type','saveFolder','rawFolder','stepTag','functionName','status','message','location'}
                            evt.(key) = string(val);
                        case {'folderIndex','numFolders','stepIndex','numSteps','stepID'}
                            if isempty(val)
                                evt.(key) = NaN;
                            else
                                evt.(key) = double(val);
                            end
                        otherwise
                            evt.(key) = val;
                    end
                end
            end

            if isempty(obj.executionProgressLog)
                obj.executionProgressLog = evt;
            else
                obj.executionProgressLog(end+1) = evt; %#ok<AGROW>
            end

            if ~isempty(progressFcn)
                progressFcn(evt);
            end
        end

        function tf = checkExecutionCancelRequested(obj, cancelFcn, progressFcn, location, varargin)
            %CHECKEXECUTIONCANCELREQUESTED Query cooperative execution-cancel state.
            %
            %   Cancellation is checked at PipelineManager-owned boundaries only.
            %   Analysis functions are not interrupted while they are running.

            tf = false;

            if isempty(cancelFcn)
                return
            end

            try
                tf = logical(cancelFcn());
            catch ME
                error('PipelineManager:executePipeline:CancelFcnFailed', ...
                    'CancelFcn failed while checking cancellation at "%s". %s', ...
                    char(string(location)), ME.message);
            end

            if isempty(tf) || ~isscalar(tf)
                error('PipelineManager:executePipeline:InvalidCancelFcnReturn', ...
                    'CancelFcn must return a logical scalar while checking cancellation at "%s".', ...
                    char(string(location)));
            end

            if ~tf
                return
            end

            obj.currentExecutionWasCancelled = true;

            obj.emitExecutionProgress(progressFcn, 'cancelRequested', ...
                'location', location, ...
                'status', 'stopping', ...
                'message', 'Stop requested. The current function will finish before PipelineManager stops.', ...
                varargin{:});
        end

        function throwIfExecutionCancelled(obj, cancelFcn, progressFcn, location, varargin)
            %THROWIFEXECUTIONCANCELLED Abort manager-owned work when cancel is requested.
            %
            %   This is used before file-to-RAM loading and other manager-owned
            %   expensive operations. The caller catches the specific identifier and
            %   converts it to a normal cancelled execution result.

            if obj.checkExecutionCancelRequested(cancelFcn, progressFcn, location, varargin{:})
                error('PipelineManager:ExecutionCancelled', ...
                    'Pipeline execution was cancelled by user request.');
            end
        end

        function name = getFolderDisplayName(~, folderPath)
            %GETFOLDERDISPLAYNAME Return a compact folder name for progress messages.

            [~, name] = fileparts(char(string(folderPath)));
            if isempty(name)
                name = char(string(folderPath));
            end
        end

        function result = buildExecutionResult(obj, executionPlan, policy, startedOn, finishedOn)
            %BUILDEXECUTIONRESULT Build the public result struct for executePipeline.

            if isfield(executionPlan, 'outputPlan') && istable(executionPlan.outputPlan)
                outputManifest = obj.buildOutputManifestFromPlan(executionPlan.outputPlan);
            else
                outputManifest = table();
            end

            isFinalViewer = false(0,1);
            isUnsavedFinal = false(0,1);
            if ~isempty(outputManifest)
                isFinalViewer = outputManifest.IsFinalOutput & outputManifest.IsViewerCompatible & outputManifest.FileExists;
                isUnsavedFinal = outputManifest.IsFinalOutput & ...
                    ismember(outputManifest.ActualPersistence, ["unsaved_reported", "transient_explicit", "unsupported_save"]);
            end

            result = struct();
            if obj.currentExecutionWasCancelled
                result.status = "cancelled";
            else
                result.status = obj.summarizeGlobalExecutionStatus();
            end
            result.startedOn = startedOn;
            result.finishedOn = finishedOn;
            result.duration_s = seconds(finishedOn - startedOn);
            result.leafOutputPolicy = string(policy);
            result.tempOutputPrefix = string(obj.tempOutputPrefix);
            if isfield(executionPlan, 'tempSessionTag')
                result.tempSessionTag = string(executionPlan.tempSessionTag);
            else
                result.tempSessionTag = string(obj.currentTempSessionTag);
            end
            result.executionPlan = executionPlan;
            result.globalPipeLog = obj.globalPipeLog;
            result.progressLog = obj.executionProgressLog;
            result.outputManifest = outputManifest;
            result.createdFiles = obj.buildCreatedFilesTableFromGlobalLog();
            result.viewerCompatibleFinalOutputs = outputManifest(isFinalViewer, :);
            result.unsavedFinalOutputs = outputManifest(isUnsavedFinal, :);
        end

        function createdFiles = buildCreatedFilesTableFromGlobalLog(obj)
            %BUILDCREATEDFILESTABLEFROMGLOBALLOG Return files actually created in the latest run.
            %
            %   CREATEDFILES is an execution report table derived from
            %   globalPipeLog.OutputFiles. Unlike outputPlan, this table reflects
            %   what was actually created for the current run, which is essential
            %   for source/import functions whose file manifests contain possible
            %   outputs that vary by recording session.

            saveFolderCol = strings(0,1);
            rawFolderCol = strings(0,1);
            fileName = strings(0,1);
            filePath = strings(0,1);
            fileExists = false(0,1);
            isTemporary = false(0,1);

            if isempty(obj.globalPipeLog) || ~istable(obj.globalPipeLog) || ...
                    ~ismember('OutputFiles', obj.globalPipeLog.Properties.VariableNames)
                createdFiles = table(saveFolderCol, rawFolderCol, fileName, filePath, ...
                    fileExists, isTemporary, ...
                    'VariableNames', {'SaveFolder','RawFolder','FileName','FilePath', ...
                    'FileExists','IsTemporary'});
                return
            end

            for iRow = 1:height(obj.globalPipeLog)

                if iRow <= numel(obj.SaveFolderList)
                    saveFolder = string(obj.SaveFolderList{iRow});
                else
                    saveFolder = string(obj.globalPipeLog.SaveFolder{iRow});
                end

                if iRow <= numel(obj.RawFolderList)
                    rawFolder = string(obj.RawFolderList{iRow});
                else
                    rawFolder = string(obj.globalPipeLog.RawFolder{iRow});
                end

                rawList = string(obj.globalPipeLog.OutputFiles{iRow});
                if strlength(strtrim(rawList)) == 0
                    continue
                end

                filesThisRow = split(rawList, ',');
                filesThisRow = strip(filesThisRow);
                filesThisRow = filesThisRow(strlength(filesThisRow) > 0);
                filesThisRow = unique(filesThisRow, 'stable');

                for iFile = 1:numel(filesThisRow)
                    fName = filesThisRow(iFile);
                    fPath = string(fullfile(char(saveFolder), char(fName)));

                    saveFolderCol(end+1,1) = saveFolder; %#ok<AGROW>
                    rawFolderCol(end+1,1) = rawFolder; %#ok<AGROW>
                    fileName(end+1,1) = fName; %#ok<AGROW>
                    filePath(end+1,1) = fPath; %#ok<AGROW>
                    fileExists(end+1,1) = isfile(char(fPath)); %#ok<AGROW>
                    isTemporary(end+1,1) = startsWith(fName, string(obj.tempOutputPrefix)); %#ok<AGROW>
                end
            end

            createdFiles = table(saveFolderCol, rawFolderCol, fileName, filePath, ...
                fileExists, isTemporary, ...
                'VariableNames', {'SaveFolder','RawFolder','FileName','FilePath', ...
                'FileExists','IsTemporary'});
        end

        function manifest = buildOutputManifestFromPlan(obj, outputPlan)
            %BUILDOUTPUTMANIFESTFROMPLAN Resolve planned outputs against disk.

            if isempty(outputPlan) || ~istable(outputPlan)
                manifest = table();
                return
            end

            saveFolderCol = strings(0,1);
            rawFolderCol = strings(0,1);
            nodeID = zeros(0,1);
            stepTag = strings(0,1);
            functionName = strings(0,1);
            outputName = strings(0,1);
            outputMode = strings(0,1);
            outputTypes = cell(0,1);
            isFinalOutput = false(0,1);
            plannedPersistence = strings(0,1);
            actualPersistence = strings(0,1);
            plannedFileName = strings(0,1);
            actualFileName = strings(0,1);
            filePath = strings(0,1);
            fileExists = false(0,1);
            isTemporary = false(0,1);
            isViewerCompatible = false(0,1);
            compatibilityReason = strings(0,1);

            for iFolder = 1:numel(obj.SaveFolderList)
                saveFolder = string(obj.SaveFolderList{iFolder});
                rawFolder = string(obj.RawFolderList{iFolder});

                for iRow = 1:height(outputPlan)
                    plannedFile = string(outputPlan.plannedFileName(iRow));
                    [actualPath, actualName, existsFlag] = obj.resolveActualOutputFile(char(saveFolder), plannedFile);

                    actualPersist = string(outputPlan.plannedPersistence(iRow));
                    if ~existsFlag && actualPersist == "already_file"
                        actualPersist = "not_produced";
                    elseif ~existsFlag && any(actualPersist == ["saved_explicit","saved_final","saved_temp"])
                        actualPersist = "missing_expected_file";
                    end

                    if ismember('isFinalOutput', outputPlan.Properties.VariableNames)
                        finalFlag = logical(outputPlan.isFinalOutput(iRow));
                    elseif ismember('isLeafOutput', outputPlan.Properties.VariableNames)
                        % Backward-compatible fallback for old execution-plan structs.
                        finalFlag = logical(outputPlan.isLeafOutput(iRow));
                    else
                        finalFlag = false;
                    end

                    [viewerOK, viewerReason] = obj.classifyViewerCompatibleFile( ...
                        actualPath, outputPlan.outputTypes{iRow}, finalFlag);

                    saveFolderCol(end+1,1) = saveFolder; %#ok<AGROW>
                    rawFolderCol(end+1,1) = rawFolder; %#ok<AGROW>
                    nodeID(end+1,1) = outputPlan.nodeID(iRow); %#ok<AGROW>
                    stepTag(end+1,1) = outputPlan.stepTag(iRow); %#ok<AGROW>
                    functionName(end+1,1) = outputPlan.functionName(iRow); %#ok<AGROW>
                    outputName(end+1,1) = outputPlan.outputName(iRow); %#ok<AGROW>
                    outputMode(end+1,1) = outputPlan.outputMode(iRow); %#ok<AGROW>
                    outputTypes{end+1,1} = outputPlan.outputTypes{iRow}; %#ok<AGROW>
                    isFinalOutput(end+1,1) = finalFlag; %#ok<AGROW>
                    plannedPersistence(end+1,1) = outputPlan.plannedPersistence(iRow); %#ok<AGROW>
                    actualPersistence(end+1,1) = actualPersist; %#ok<AGROW>
                    plannedFileName(end+1,1) = plannedFile; %#ok<AGROW>
                    actualFileName(end+1,1) = string(actualName); %#ok<AGROW>
                    filePath(end+1,1) = string(actualPath); %#ok<AGROW>
                    fileExists(end+1,1) = existsFlag; %#ok<AGROW>
                    isTemporary(end+1,1) = startsWith(string(actualName), string(obj.tempOutputPrefix)); %#ok<AGROW>
                    isViewerCompatible(end+1,1) = viewerOK; %#ok<AGROW>
                    compatibilityReason(end+1,1) = string(viewerReason); %#ok<AGROW>
                end
            end

            manifest = table(saveFolderCol, rawFolderCol, nodeID, stepTag, functionName, ...
                outputName, outputMode, outputTypes, isFinalOutput, plannedPersistence, ...
                actualPersistence, plannedFileName, actualFileName, filePath, fileExists, ...
                isTemporary, isViewerCompatible, compatibilityReason, ...
                'VariableNames', {'SaveFolder','RawFolder','NodeID','StepTag','FunctionName', ...
                'OutputName','OutputMode','OutputTypes','IsFinalOutput','PlannedPersistence', ...
                'ActualPersistence','PlannedFileName','ActualFileName','FilePath','FileExists', ...
                'IsTemporary','IsViewerCompatible','CompatibilityReason'});
        end

        function [actualPath, actualName, existsFlag] = resolveActualOutputFile(~, saveFolder, plannedFile)
            %RESOLVEACTUALOUTPUTFILE Resolve exact or extension-inferred output file.

            actualPath = "";
            actualName = "";
            existsFlag = false;

            plannedFile = string(plannedFile);
            if strlength(plannedFile) == 0
                return
            end

            candidatePath = fullfile(saveFolder, char(plannedFile));
            if isfile(candidatePath)
                actualPath = string(candidatePath);
                [~,b,e] = fileparts(candidatePath);
                actualName = string(b) + string(e);
                existsFlag = true;
                return
            end

            [folderPart, baseName, extName] = fileparts(char(plannedFile));
            if ~isempty(extName)
                return
            end

            searchFolder = saveFolder;
            if ~isempty(folderPart)
                searchFolder = fullfile(saveFolder, folderPart);
            end

            hits = dir(fullfile(searchFolder, [baseName '.*']));
            hits = hits(~[hits.isdir]);
            if isempty(hits)
                return
            end

            actualPath = string(fullfile(hits(1).folder, hits(1).name));
            actualName = string(hits(1).name);
            existsFlag = true;
        end

        function [fileName, reservedNames] = resolveAutoFinalOutputFileName(obj, nodeLocal, outDef, saveFolder, reservedNames, varargin)
            %RESOLVEAUTOFINALOUTPUTFILENAME Resolve automatic final-output filename.
            %
            % This is the single backend resolver for filenames created by automatic
            % output policies. It keeps repeated processing steps from reusing the
            % same default output filename by including the step tag when needed.

            p = inputParser;
            addParameter(p, 'asTemp', false, @(x)islogical(x)&&isscalar(x));
            parse(p, varargin{:});
            asTemp = p.Results.asTemp;

            if nargin < 5 || isempty(reservedNames)
                reservedNames = strings(0,1);
            else
                reservedNames = string(reservedNames(:));
            end

            if nargin < 4 || isempty(saveFolder)
                saveFolder = '';
            end

            if asTemp
                candidateName = string(obj.makeTempOutputBaseName(nodeLocal, outDef));
                [fileName, reservedNames] = obj.makeAutoFinalFileNameUnique( ...
                    candidateName, saveFolder, reservedNames);
                return
            end

            defaultNames = obj.normalizeDefaultOutputFileList(outDef);

            if ~isempty(defaultNames)
                candidateName = defaultNames(1);
            else
                stepTag = matlab.lang.makeValidName(char(string(nodeLocal.name)));
                outTag = matlab.lang.makeValidName(char(string(outDef.name)));
                candidateName = string(sprintf('%s_%s', stepTag, outTag));
            end

            if obj.isRepeatedProcessingStep(nodeLocal.id)
                candidateName = obj.prependStepTagToFileName(candidateName, nodeLocal.name);
            end

            [fileName, reservedNames] = obj.makeAutoFinalFileNameUnique( ...
                candidateName, saveFolder, reservedNames);
        end

        function fileName = getPlannedFinalOutputFileName(obj, nodeID, outputName, persistenceState)
            %GETPLANNEDFINALOUTPUTFILENAME Return the planned filename for one output.

            fileName = '';

            if isempty(obj.lastExecutionPlan) || ~isstruct(obj.lastExecutionPlan) || ...
                    ~isfield(obj.lastExecutionPlan, 'outputPlan') || ...
                    ~istable(obj.lastExecutionPlan.outputPlan) || ...
                    isempty(obj.lastExecutionPlan.outputPlan)
                return
            end

            outputPlan = obj.lastExecutionPlan.outputPlan;

            requiredVars = {'nodeID','outputName','plannedPersistence','plannedFileName'};
            if ~all(ismember(requiredVars, outputPlan.Properties.VariableNames))
                return
            end

            rows = outputPlan(outputPlan.nodeID == nodeID & ...
                strcmpi(string(outputPlan.outputName), string(outputName)) & ...
                string(outputPlan.plannedPersistence) == string(persistenceState), :);

            rows = rows(strlength(strtrim(string(rows.plannedFileName))) > 0, :);

            if isempty(rows)
                return
            end

            fileName = char(string(rows.plannedFileName(1)));
        end

        function tf = isRepeatedProcessingStep(obj, nodeID)
            %ISREPEATEDPROCESSINGSTEP True when the same function appears multiple times.

            tf = false;

            if isempty(obj.nodes)
                return
            end

            try
                nodeLocal = obj.nodes(obj.getNodeIndexByID(nodeID));
            catch
                return
            end

            if ~isfield(nodeLocal, 'kind') || ~strcmpi(nodeLocal.kind, 'stream')
                return
            end

            thisFunction = string(obj.getCallableFuncName(nodeLocal));
            if strlength(thisFunction) == 0
                return
            end

            nMatch = 0;

            for iNode = 1:numel(obj.nodes)
                otherNode = obj.nodes(iNode);

                if ~isfield(otherNode, 'kind') || ~strcmpi(otherNode.kind, 'stream')
                    continue
                end

                otherFunction = string(obj.getCallableFuncName(otherNode));

                if strcmpi(otherFunction, thisFunction)
                    nMatch = nMatch + 1;
                end
            end

            tf = nMatch > 1;
        end

        function fileName = prependStepTagToFileName(~, fileNameIn, stepTag)
            %PREPENDSTEPTAGTOFILENAME Prefix a filename with the step tag.

            fileNameIn = string(fileNameIn);
            stepTag = string(matlab.lang.makeValidName(char(string(stepTag))));

            [folderPart, basePart, extPart] = fileparts(char(fileNameIn));

            if isempty(basePart)
                basePart = matlab.lang.makeValidName(char(fileNameIn));
            end

            prefix = stepTag + "_";
            if startsWith(string(basePart), prefix, 'IgnoreCase', true)
                newBase = string(basePart);
            else
                newBase = prefix + string(basePart);
            end

            if isempty(folderPart)
                fileName = char(newBase + string(extPart));
            else
                fileName = char(fullfile(folderPart, char(newBase + string(extPart))));
            end
        end

        function [uniqueName, reservedNames] = makeAutoFinalFileNameUnique(obj, candidateName, saveFolder, reservedNames)
            %MAKEAUTOFINALFILENAMEUNIQUE Avoid duplicate automatic output names.

            candidateName = string(strtrim(string(candidateName)));

            if strlength(candidateName) == 0
                uniqueName = '';
                return
            end

            if nargin < 4 || isempty(reservedNames)
                reservedNames = strings(0,1);
            else
                reservedNames = string(reservedNames(:));
            end

            [folderPart, basePart, extPart] = fileparts(char(candidateName));

            if isempty(basePart)
                basePart = matlab.lang.makeValidName(char(candidateName));
            end

            suffixIdx = 0;
            uniqueCandidate = candidateName;

            while obj.autoFinalFileNameIsReserved(uniqueCandidate, saveFolder, reservedNames)
                suffixIdx = suffixIdx + 1;

                if isempty(folderPart)
                    uniqueCandidate = string(sprintf('%s_%d%s', basePart, suffixIdx, extPart));
                else
                    uniqueCandidate = string(fullfile(folderPart, sprintf('%s_%d%s', basePart, suffixIdx, extPart)));
                end
            end

            uniqueName = char(uniqueCandidate);
            reservedNames(end+1,1) = uniqueCandidate;
            reservedNames = unique(reservedNames, 'stable');
        end

        function tf = autoFinalFileNameIsReserved(obj, candidateName, saveFolder, reservedNames)
            %AUTOFINALFILENAMEISRESERVED True when an automatic filename is taken.

            candidateName = string(candidateName);
            reservedNames = string(reservedNames(:));

            tf = any(strcmpi(reservedNames, candidateName));

            if tf
                return
            end

            if isempty(saveFolder) || strlength(string(saveFolder)) == 0
                return
            end

            if ~(isprop(obj, 'b_avoidOverwrite') && obj.b_avoidOverwrite)
                return
            end

            candidatePath = fullfile(char(string(saveFolder)), char(candidateName));

            if isfile(candidatePath)
                tf = true;
                return
            end

            [folderPart, basePart, extPart] = fileparts(char(candidateName));

            if ~isempty(extPart)
                return
            end

            searchFolder = char(string(saveFolder));
            if ~isempty(folderPart)
                searchFolder = fullfile(searchFolder, folderPart);
            end

            if ~isfolder(searchFolder)
                return
            end

            hits = dir(fullfile(searchFolder, [basePart '.*']));
            hits = hits(~[hits.isdir]);
            tf = ~isempty(hits);
        end

        function [tf, reason] = classifyViewerCompatibleFile(~, filePath, outputTypes, isFinalOutput)
            %CLASSIFYVIEWERCOMPATIBLEFILE Runtime DataViewer compatibility check.

            tf = false;
            reason = "";

            if ~isFinalOutput
                reason = "Not a final output.";
                return
            end

            if isempty(filePath) || strlength(string(filePath)) == 0 || ~isfile(char(string(filePath)))
                reason = "No existing file.";
                return
            end

            types = string(outputTypes(:));
            [~,~,ext] = fileparts(char(string(filePath)));
            ext = lower(string(ext));

            if ext == ".dat"
                if any(strcmpi(types, "Image")) || any(strcmpi(types, "ImageTimeSeries"))
                    tf = true;
                    reason = "DAT image/image-time-series output.";
                else
                    reason = "DAT file is not declared as image data.";
                end
                return
            end

            if ext == ".umt"
                try
                    S = loadData(char(string(filePath)));
                    if isstruct(S) && isfield(S, 'kind') && strcmpi(char(string(S.kind)), 'image')
                        tf = true;
                        reason = "UMT kind=image output.";
                    else
                        reason = "UMT file is not kind=image.";
                    end
                catch ME
                    reason = "Could not inspect UMT kind: " + string(ME.message);
                end
                return
            end

            reason = "Unsupported DataViewer file extension.";
        end

        function status = summarizeGlobalExecutionStatus(obj)
            %SUMMARIZEGLOBALEXECUTIONSTATUS Summarize the latest globalPipeLog.

            status = "unknown";
            if isempty(obj.globalPipeLog) || ~istable(obj.globalPipeLog) || ...
                    ~ismember('Status', obj.globalPipeLog.Properties.VariableNames)
                return
            end

            vals = string(obj.globalPipeLog.Status);
            if obj.currentExecutionWasCancelled || any(strcmpi(vals, "Cancelled"))
                status = "cancelled";
            elseif all(vals == "Completed")
                status = "completed";
            elseif all(vals == "Skipped")
                status = "skipped";
            elseif any(vals == "Failed") && ~any(vals == "Completed" | vals == "Partially executed")
                status = "failed";
            elseif any(vals == "Failed" | vals == "Partially executed")
                status = "completed_with_errors";
            else
                status = lower(strjoin(unique(vals, 'stable'), "_"));
            end
        end

        function loadDataHistory(obj, folder)
            %LOADDATAHISTORY Load/initialize obj.dataHistory from folder-bound dataHistory.mat.
            %
            %   - If dataHistory.mat does not exist: obj.dataHistory = struct.empty(0,1)
            %   - If file exists but is corrupted/missing variable: reset to empty
            %   - Removes entries whose referenced file no longer exists in the folder
            %   - If cleanup occurs, overwrites dataHistory.mat with the cleaned struct
            %
            % Expected MAT variable name: dataHistory

            dataHist = struct.empty(0,1); %#ok<NASGU>
            historyFile = fullfile(folder, 'dataHistory.mat');

            % No file => empty local copy
            if ~isfile(historyFile)
                obj.dataHistory = struct.empty(0,1);
                return
            end

            % Load safely
            try
                S = load(historyFile);
            catch
                % Corrupted/unreadable file => reset local copy
                obj.dataHistory = struct.empty(0,1);
                return
            end

            if ~isfield(S, 'dataHistory') || ~isstruct(S.dataHistory)
                % Corrupted/unexpected => reset local copy
                obj.dataHistory = struct.empty(0,1);
                return
            end

            dataHist = S.dataHistory;

            if isempty(dataHist)
                obj.dataHistory = struct.empty(0,1);
                return
            end

            % -------------------------------------------------------------
            % Check if all files listed in dataHistory still exist
            % -------------------------------------------------------------
            keepIdx = true(numel(dataHist), 1);

            for i = 1:numel(dataHist)
                if ~isfield(dataHist(i), 'file') || isempty(dataHist(i).file)
                    keepIdx(i) = false;
                    continue
                end

                f = char(string(dataHist(i).file));
                filePath = fullfile(folder, f);

                if ~isfile(filePath)
                    keepIdx(i) = false;
                end
            end

            % -------------------------------------------------------------
            % Clean-up: remove missing/invalid entries
            % -------------------------------------------------------------
            if any(~keepIdx)
                dataHist = dataHist(keepIdx);

                % Persist cleaned history back to disk so stale entries do not keep
                % reappearing in later sessions.
                historyStructToSave = struct('dataHistory', dataHist); %#ok<NASGU>
                save(historyFile, '-struct', 'historyStructToSave');
            end

            % Save local copy
            obj.dataHistory = dataHist;
        end

        function saveDataHistory(obj, SaveFolder)
            %SAVEDATAHISTORY Save obj.dataHistory to folder-bound dataHistory.mat.
            %
            % Behavior:
            %   - If dataHistory.mat does not exist, it is created.
            %   - If it exists, it is overwritten with obj.dataHistory.
            %   - Before saving, a light validation pass removes duplicate entries
            %     that point to the same output file.
            %
            % Duplicate rule:
            %   - Entries are considered duplicates if they share the same `file`.
            %   - When duplicates are found, the last occurrence is kept because it
            %     represents the most recent in-memory provenance for that file.
            %
            % NOTE:
            %   Appending is done by modifying obj.dataHistory in memory, then calling
            %   this function once (atomic write).

            historyFile = fullfile(SaveFolder, 'dataHistory.mat');

            historyEntries = obj.dataHistory;

            % Ensure a consistent empty representation
            if isempty(historyEntries)
                historyEntries = struct.empty(0,1);
                historyStructToSave = struct('dataHistory', historyEntries); %#ok<NASGU>
                save(historyFile, '-struct', 'historyStructToSave');
                return
            end

            % -------------------------------------------------------------
            % Light validation: remove duplicate file entries
            % Keep the last occurrence as the most recent provenance record.
            % -------------------------------------------------------------
            nEntries = numel(historyEntries);
            keepMask = true(nEntries, 1);
            seenKeys = containers.Map('KeyType', 'char', 'ValueType', 'double');
            removedCount = 0;

            for ii = nEntries:-1:1

                hasFile = isfield(historyEntries(ii), 'file') && ...
                    ~isempty(historyEntries(ii).file);

                if ~hasFile
                    % Leave malformed/incomplete entries untouched in this light pass
                    continue
                end

                file_i = char(string(historyEntries(ii).file));
                dupKey = lower(strtrim(file_i));

                if isKey(seenKeys, dupKey)
                    keepMask(ii) = false;
                    removedCount = removedCount + 1;
                else
                    seenKeys(dupKey) = ii;
                end
            end

            if removedCount > 0
                historyEntries = historyEntries(keepMask);
                warning('PipelineManager:saveDataHistory:DuplicateEntriesRemoved', ...
                    ['Removed %d duplicate dataHistory entrie(s) before saving.\n' ...
                    'Duplicate detection used the `file` field and kept the most recent entry.'], ...
                    removedCount);
            end

            historyStructToSave = struct('dataHistory', historyEntries); %#ok<NASGU>
            save(historyFile, '-struct', 'historyStructToSave');
        end

        function entry = generateDataHistoryEntry(obj, nodePath, outputFileName, saveFolder, rawFolder)
            %GENERATEDATAHISTORYENTRY Create a properly formatted dataHistory entry.
            %
            %   ENTRY = GENERATEDATAHISTORYENTRY(OBJ, NODEPATH, OUTPUTFILENAME, SAVEFOLDER, RAWFOLDER)
            %   builds a folder-bound history record for OUTPUTFILENAME.
            %
            %   The entry stores:
            %     - entry.file            : filename (folder-bound)
            %     - entry.timestamp       : datetime
            %     - entry.pipelineVersion : OBJ.pipelineVersion
            %     - entry.info(k)         : ordered provenance steps
            %
            %   Provenance behavior:
            %     - For regular processing nodes, a step is appended to entry.info.
            %     - If a node consumes a concrete data file coming from a file-source
            %       proxy node (node.kind == 'folder'), and a matching entry exists in
            %       obj.dataHistory for that file, that prior provenance is prepended
            %       before the current processing step.
            %     - Synthetic file-source nodes are not recorded as provenance steps
            %       when the corresponding source file already has a dataHistory entry.
            %       In that case, the input file history replaces the proxy step.
            %     - Files produced by upstream generated function nodes do NOT trigger
            %       file-history prepending here, because their provenance is already
            %       represented explicitly by the upstream nodes present in NODEPATH.
            %
            %   For each step entry.info(k):
            %     - name / version
            %     - parameters : copy of node.info.parameters
            %     - inputs(j)  : struct with fields:
            %         .name   : input port name
            %         .source : for data inputs:
            %                   "<UpstreamNodeName>:<selectedFile|fileName|outputPort>"
            %                   for SaveFolder/RawFolder:
            %                   exact passed value
            %                   for metaData:
            %                   [] (ignored for now)

            entry = struct();
            entry.file            = char(string(outputFileName));
            entry.timestamp       = datetime('now');
            entry.pipelineVersion = obj.pipelineVersion;
            entry.info            = struct( ...
                'name',       {}, ...
                'version',    {}, ...
                'parameters', {}, ...
                'inputs',     {} );

            % Track file histories already prepended during this entry build
            prependedFiles = containers.Map('KeyType', 'char', 'ValueType', 'logical');

            for iStep = 1:numel(nodePath)

                node = nodePath(iStep);

                % ---------------------------------------------------------
                % Special handling for file-source proxy nodes
                % ---------------------------------------------------------
                if obj.isHistoryProxyNode(node)

                    proxyFile = obj.resolveProxyNodeFile(node);

                    if ~isempty(proxyFile)
                        prependFileHistoryOnce(proxyFile);

                        % Do not append the proxy step itself when the
                        % represented file already has its own dataHistory.
                        if hasKnownHistory(proxyFile)
                            continue
                        end
                    end
                end

                % ---------------------------------------------------------
                % 1) Build current node step info
                % ---------------------------------------------------------
                stepInfo = struct();
                stepInfo.name    = node.info.name;
                stepInfo.version = node.info.version;

                if isfield(node.info, 'parameters') && ~isempty(node.info.parameters)
                    stepInfo.parameters = node.info.parameters;
                else
                    stepInfo.parameters = struct.empty(0,1);
                end

                inputs = struct('name', {}, 'source', {});

                if isfield(node.info, 'inputs') && ~isempty(node.info.inputs)

                    for iIn = 1:numel(node.info.inputs)

                        inDef  = node.info.inputs(iIn);
                        inName = char(string(inDef.name));

                        thisIn = struct();
                        thisIn.name   = inName;
                        thisIn.source = [];

                        if isfield(inDef, 'isData') && inDef.isData

                            [srcToken, resolvedInputFile, isProxyBackedInput] = ...
                                obj.resolveDataInputSource(node, inName);

                            thisIn.source = srcToken;

                            % Only prepend file history when the input is backed by
                            % a file-source proxy node. Do NOT prepend when the
                            % file is simply the persisted output of an upstream
                            % generated function already represented in nodePath.
                            if isProxyBackedInput && ~isempty(resolvedInputFile)
                                prependFileHistoryOnce(resolvedInputFile);
                            end

                        else
                            % Placeholders: store exact values (metaData ignored for now)
                            switch lower(inName)
                                case 'savefolder'
                                    thisIn.source = char(string(saveFolder));
                                case 'rawfolder'
                                    thisIn.source = char(string(rawFolder));
                                case 'metadata'
                                    thisIn.source = []; % ignored for now
                                otherwise
                                    thisIn.source = [];
                            end
                        end

                        inputs(end+1) = thisIn; %#ok<AGROW>
                    end
                end

                stepInfo.inputs = inputs;

                % ---------------------------------------------------------
                % 2) Append current processing step
                % ---------------------------------------------------------
                entry.info = obj.appendInfoWithBoundaryDedup(entry.info, stepInfo);
            end

            % =============================================================
            % Local helpers
            % =============================================================
            function prependFileHistoryOnce(fileNameLocal)
                %PREPENDFILEHISTORYONCE Prepend prior file provenance once per file.
                %
                %   PREPENDFILEHISTORYONCE(FILENAMELOCAL) prepends the corresponding
                %   dataHistory.info chain only the first time that file is encountered
                %   during entry assembly.

                if isempty(fileNameLocal)
                    return
                end

                fKeyLocal = lower(strtrim(char(string(fileNameLocal))));
                if isKey(prependedFiles, fKeyLocal)
                    return
                end

                histInfoLocal = obj.getHistoryInfoForFile(fileNameLocal);
                if isempty(histInfoLocal)
                    return
                end

                entry.info = obj.appendInfoWithBoundaryDedup(entry.info, histInfoLocal);
                prependedFiles(fKeyLocal) = true;
            end

            function tf = hasKnownHistory(fileNameLocal)
                %HASKNOWNHISTORY True when a folder-bound file already has dataHistory.
                tf = ~isempty(obj.getHistoryInfoForFile(fileNameLocal));
            end
        end

        function infoOut = getHistoryInfoForFile(obj,fileNameLocal)
            %GETHISTORYINFOFORFILE Return prior provenance info for a folder-bound file.
            %
            %   INFOOUT = GETHISTORYINFOFORFILE(FILENAMELOCAL) searches obj.dataHistory
            %   for an entry whose `file` matches the provided folder-bound filename.
            %   If found, returns the corresponding `.info` field; otherwise returns [].

            infoOut = struct('name', {}, 'version', {}, 'parameters', {}, 'inputs', {});

            if isempty(obj.dataHistory)
                return
            end

            matchIdx = [];

            for iHist = numel(obj.dataHistory):-1:1
                hasFile = isfield(obj.dataHistory(iHist), 'file') && ~isempty(obj.dataHistory(iHist).file);
                if ~hasFile
                    continue
                end

                histFile = char(string(obj.dataHistory(iHist).file));
                if strcmpi(histFile, char(string(fileNameLocal)))
                    matchIdx = iHist;
                    break
                end
            end

            if isempty(matchIdx)
                return
            end

            if isfield(obj.dataHistory(matchIdx), 'info') && ~isempty(obj.dataHistory(matchIdx).info)
                infoOut = obj.dataHistory(matchIdx).info;
            end
        end

        function fileNameOut = resolveProxyNodeFile(obj,nodeLocal)
            %RESOLVEPROXYNODEFILE Resolve the concrete file represented by a proxy node.
            %
            %   FILENAMEOUT = RESOLVEPROXYNODEFILE(NODELOCAL) returns the folder-bound
            %   file name represented by a FileSource-like node.
            %
            %   Resolution priority:
            %       1) selectedFile on any outgoing connection
            %       2) fileName stored in obj.dataStore for one of the node outputs

            fileNameOut = '';

            outConns = obj.connections([obj.connections.sourceNodeID] == nodeLocal.id);

            % Priority 1: explicit selectedFile on outgoing connection
            for iConnLocal = 1:numel(outConns)
                if isfield(outConns(iConnLocal), 'selectedFile') && ~isempty(outConns(iConnLocal).selectedFile)
                    fileNameOut = char(string(outConns(iConnLocal).selectedFile));
                    return
                end
            end

            % Priority 2: file-backed record in dataStore
            for iConnLocal = 1:numel(outConns)

                srcOutNameLocal = char(string(outConns(iConnLocal).sourceOutputName));
                keyLocal = obj.makeKey(nodeLocal.id, srcOutNameLocal);

                if ~isempty(obj.dataStore) && isa(obj.dataStore, 'containers.Map') && obj.dataStore.isKey(keyLocal)
                    recLocal = obj.dataStore(keyLocal);

                    if isstruct(recLocal) && isfield(recLocal, 'fileName') && ~isempty(recLocal.fileName)
                        filePathLocal = char(string(recLocal.fileName));
                        [~, fBaseLocal, fExtLocal] = fileparts(filePathLocal);
                        fileNameOut = [fBaseLocal fExtLocal];
                        return
                    end
                end
            end
        end

        function tf = isHistoryProxyNode(~, nodeLocal)
            %ISHISTORYPROXYNODE True for file-source proxy nodes.
            %
            %   TF = ISHISTORYPROXYNODE(~, NODELOCAL) returns true when NODELOCAL
            %   represents an existing file source rather than a generated processing
            %   step.
            %
            %   Current rule:
            %       - node.kind == 'folder'  -> true
            %       - node.kind == 'stream'  -> false
            %
            %   This avoids relying on function-name string comparisons such as
            %   'FileSource'.

            tf = false;

            if isfield(nodeLocal, 'kind') && ~isempty(nodeLocal.kind)
                tf = strcmpi(char(string(nodeLocal.kind)), 'folder');
            end
        end

        function infoAcc = appendInfoWithBoundaryDedup(obj,infoAcc, infoToAppend)
            %APPENDINFOWITHBOUNDARYDEDUP Append provenance steps with edge dedup.
            %
            %   INFOACC = APPENDINFOWITHBOUNDARYDEDUP(INFOACC, INFOTOAPPEND)
            %   appends INFOTOAPPEND to INFOACC. If the last step of INFOACC is
            %   identical to the first step of INFOTOAPPEND, the duplicated first
            %   step in INFOTOAPPEND is removed before concatenation.

            if isempty(infoToAppend)
                return
            end

            if isempty(infoAcc)
                infoAcc = infoToAppend;
                return
            end

            firstAppend = infoToAppend(1);
            lastAcc     = infoAcc(end);

            if obj.isSameStep(lastAcc, firstAppend)
                infoToAppend = infoToAppend(2:end);
            end

            if ~isempty(infoToAppend)
                infoAcc = [infoAcc; infoToAppend];
            end
        end

        function tf = isSameStep(~,A, B)
            %ISSAMESTEP Compare two provenance step structs.
            %
            %   TF = ISSAMESTEP(A,B) returns true when the two step records refer
            %   to the same analysis step and parameters.

            tf = ...
                isfield(A, 'name')       && isfield(B, 'name')       && ...
                isfield(A, 'version')    && isfield(B, 'version')    && ...
                isfield(A, 'parameters') && isfield(B, 'parameters') && ...
                strcmpi(char(string(A.name)), char(string(B.name))) && ...
                strcmpi(char(string(A.version)), char(string(B.version))) && ...
                isequal(A.parameters, B.parameters);
        end

        function [sourceToken, resolvedFile, isProxyBacked] = resolveDataInputSource(obj, nodeLocal, inputNameLocal)
            %RESOLVEDATAINPUTSOURCE Resolve source token and concrete file for a DATA input.
            %
            %   [SOURCETOKEN, RESOLVEDFILE, ISPROXYBACKED] =
            %   RESOLVEDATAINPUTSOURCE(OBJ, NODELOCAL, INPUTNAMELOCAL) returns:
            %       - sourceToken    : the string stored in provenance inputs.source
            %       - resolvedFile   : folder-bound concrete file name when known, else ''
            %       - isProxyBacked  : true only when the upstream source node is a
            %                          file-source proxy node (node.kind == 'folder')
            %
            %   UNIFIED TOKEN POLICY:
            %       - File-source proxy nodes always use the concrete filename token:
            %             "<ProxyNodeName>:<filename>"
            %       - File-producing outputs (outputMode == 'file') use the concrete
            %         filename token:
            %             "<SrcNodeName>:<filename>"
            %       - Data-producing outputs (outputMode == 'data') use the output
            %         port token:
            %             "<SrcNodeName>:<sourceOutputName>"
            %
            %   IMPORTANT:
            %       File-source proxy nodes must always resolve to filename tokens,
            %       otherwise the compared token becomes the proxy port name
            %       (typically "data"), which breaks history matching against
            %       generated-file provenance such as "...:green.dat".

            sourceToken   = [];
            resolvedFile  = '';
            isProxyBacked = false;

            % -------------------------------------------------------------
            % Resolve upstream edge for this input
            % -------------------------------------------------------------
            connIdxLocal = find( ...
                [obj.connections.targetNodeID] == nodeLocal.id & ...
                strcmpi({obj.connections.targetInputName}, inputNameLocal), ...
                1, 'first');

            if isempty(connIdxLocal)
                error('PipelineManager:resolveDataInputSource:MissingDataEdge', ...
                    'Missing input connection for node %d input "%s".', ...
                    nodeLocal.id, char(string(inputNameLocal)));
            end

            connLocal = obj.connections(connIdxLocal);

            srcNodeIDLocal   = connLocal.sourceNodeID;
            srcOutNameLocal  = char(string(connLocal.sourceOutputName));
            srcIdxLocal      = obj.getNodeIndexByID(srcNodeIDLocal);
            srcNodeLocal     = obj.nodes(srcIdxLocal);
            srcNodeNameLocal = char(string(srcNodeLocal.name));

            % -------------------------------------------------------------
            % Determine whether the upstream source is a file-source proxy
            % -------------------------------------------------------------
            isProxyBacked = obj.isHistoryProxyNode(srcNodeLocal);

            % -------------------------------------------------------------
            % Determine upstream output metadata
            % -------------------------------------------------------------
            outputModeLocal = 'data';   % default assumption
            defOutListLocal = {};

            if isfield(srcNodeLocal, 'info') && isfield(srcNodeLocal.info, 'outputs') && ~isempty(srcNodeLocal.info.outputs)
                outNamesLocal = {srcNodeLocal.info.outputs.name};
                iOutLocal = find(strcmpi(outNamesLocal, srcOutNameLocal), 1, 'first');

                if ~isempty(iOutLocal)
                    outDefLocal = srcNodeLocal.info.outputs(iOutLocal);

                    if isfield(outDefLocal, 'outputMode') && ~isempty(outDefLocal.outputMode)
                        outputModeLocal = lower(strtrim(char(string(outDefLocal.outputMode))));
                    end

                    if isfield(outDefLocal, 'defOutfilename')
                        if ischar(outDefLocal.defOutfilename) || isstring(outDefLocal.defOutfilename)
                            tmpLocal = strtrim(char(string(outDefLocal.defOutfilename)));
                            if ~isempty(tmpLocal)
                                defOutListLocal = {tmpLocal};
                            end
                        elseif iscell(outDefLocal.defOutfilename)
                            defOutListLocal = cellfun(@(x) strtrim(char(string(x))), ...
                                outDefLocal.defOutfilename, 'UniformOutput', false);
                            defOutListLocal = defOutListLocal(~cellfun(@isempty, defOutListLocal));
                        end
                    end
                end
            end

            % -------------------------------------------------------------
            % CASE 1: File-source proxy nodes
            % These must always resolve to filename tokens.
            % -------------------------------------------------------------
            if isProxyBacked

                % Priority 1: explicit selected file on the connection
                if isfield(connLocal, 'selectedFile') && ~isempty(connLocal.selectedFile)
                    resolvedFile = char(string(connLocal.selectedFile));
                    sourceToken  = [srcNodeNameLocal ':' resolvedFile];
                    return
                end

                % Priority 2: concrete file from dataStore
                keyLocal = obj.makeKey(srcNodeIDLocal, srcOutNameLocal);

                if ~isempty(obj.dataStore) && isa(obj.dataStore, 'containers.Map') && obj.dataStore.isKey(keyLocal)
                    recLocal = obj.dataStore(keyLocal);

                    if isstruct(recLocal) && isfield(recLocal, 'fileName') && ~isempty(recLocal.fileName)
                        filePathLocal = char(string(recLocal.fileName));
                        [~, fBaseLocal, fExtLocal] = fileparts(filePathLocal);
                        resolvedFile = [fBaseLocal fExtLocal];
                        sourceToken  = [srcNodeNameLocal ':' resolvedFile];
                        return
                    end
                end

                % Priority 3: declared default filename when unambiguous
                if numel(defOutListLocal) == 1
                    resolvedFile = defOutListLocal{1};
                    sourceToken  = [srcNodeNameLocal ':' resolvedFile];
                    return
                end

                % Fallback: use source node name itself if it already looks like a file
                % (common for file-source nodes created from an existing file path).
                [~, fBaseLocal, fExtLocal] = fileparts(srcNodeNameLocal);
                if ~isempty(fBaseLocal) || ~isempty(fExtLocal)
                    resolvedFile = [fBaseLocal fExtLocal];
                    if ~isempty(resolvedFile)
                        sourceToken = [srcNodeNameLocal ':' resolvedFile];
                        return
                    end
                end

                % Last fallback
                sourceToken = [srcNodeNameLocal ':' srcOutNameLocal];
                return
            end

            % -------------------------------------------------------------
            % CASE 2: File-producing outputs
            % Provenance token uses the concrete filename when known.
            % -------------------------------------------------------------
            if strcmpi(outputModeLocal, 'file')

                % Priority 1: explicit selected file on the connection
                if isfield(connLocal, 'selectedFile') && ~isempty(connLocal.selectedFile)
                    resolvedFile = char(string(connLocal.selectedFile));
                    sourceToken  = [srcNodeNameLocal ':' resolvedFile];
                    return
                end

                % Priority 2: concrete file from dataStore
                keyLocal = obj.makeKey(srcNodeIDLocal, srcOutNameLocal);

                if ~isempty(obj.dataStore) && isa(obj.dataStore, 'containers.Map') && obj.dataStore.isKey(keyLocal)
                    recLocal = obj.dataStore(keyLocal);

                    if isstruct(recLocal) && isfield(recLocal, 'fileName') && ~isempty(recLocal.fileName)
                        filePathLocal = char(string(recLocal.fileName));
                        [~, fBaseLocal, fExtLocal] = fileparts(filePathLocal);
                        resolvedFile = [fBaseLocal fExtLocal];
                        sourceToken  = [srcNodeNameLocal ':' resolvedFile];
                        return
                    end
                end

                % Priority 3: declared default filename when unambiguous
                if numel(defOutListLocal) == 1
                    resolvedFile = defOutListLocal{1};
                    sourceToken  = [srcNodeNameLocal ':' resolvedFile];
                    return
                end

                % Fallback
                sourceToken = [srcNodeNameLocal ':' srcOutNameLocal];
                return
            end

            % -------------------------------------------------------------
            % CASE 3: Data-producing outputs
            % Provenance token uses the output port name.
            % -------------------------------------------------------------
            sourceToken = [srcNodeNameLocal ':' srcOutNameLocal];

            % Still expose a resolved file for internal logic if one exists
            keyLocal = obj.makeKey(srcNodeIDLocal, srcOutNameLocal);

            if ~isempty(obj.dataStore) && isa(obj.dataStore, 'containers.Map') && obj.dataStore.isKey(keyLocal)
                recLocal = obj.dataStore(keyLocal);

                if isstruct(recLocal) && isfield(recLocal, 'fileName') && ~isempty(recLocal.fileName)
                    filePathLocal = char(string(recLocal.fileName));
                    [~, fBaseLocal, fExtLocal] = fileparts(filePathLocal);
                    resolvedFile = [fBaseLocal fExtLocal];
                end
            end
        end
    end

    methods (Access = private)

        %%%%%%--Helpers for "addStep" and "rmStep" methods ----------------

        function saveasList = normalizeSaveAsInput(~, saveasRaw)

            %NORMALIZESAVEASINPUT Normalize saveas input to a string column vector.

            if isempty(saveasRaw)
                saveasList = strings(0,1);
            elseif ischar(saveasRaw) || (isstring(saveasRaw) && isscalar(saveasRaw))
                saveasList = string(saveasRaw);
                saveasList = saveasList(:);
            elseif isstring(saveasRaw)
                saveasList = saveasRaw(:);
            elseif iscell(saveasRaw)
                saveasList = string(saveasRaw(:));
            else
                saveasList = strings(0,1);
            end
        end

        function nodeOut = applySaveAsToNodeOutputs(obj, nodeIn, saveList, funcName)
            %APPLYSAVEASTONODEOUTPUTS Apply saveas rules to SAVEABLE outputs only.
            %
            % Saveable outputs are:
            %   isData == true AND outputMode ~= 'file'
            %
            % For outputMode='file':
            %   saveFileName is irrelevant and is cleared here for consistency.

            nodeOut = nodeIn;

            if ~isfield(nodeOut.info,'outputs') || isempty(nodeOut.info.outputs)
                if ~isempty(saveList)
                    error('addStep:SaveAsNoOutputs', ...
                        'saveas was provided but function "%s" has no outputs.', funcName);
                end
                return
            end

            % Clear all saveFileName fields first. For file outputs this field is
            % irrelevant and should stay empty.
            for iOut = 1:numel(nodeOut.info.outputs)
                nodeOut.info.outputs(iOut).saveFileName = '';
            end

            if isempty(saveList) || (numel(saveList)==1 && strlength(strtrim(saveList(1)))==0)
                return
            end

            saveableIdx = obj.getSaveableOutputIdx(nodeOut);
            nSaveable = numel(saveableIdx);

            if nSaveable == 0
                error('addStep:SaveAsNoSaveableOutputs', ...
                    ['Function "%s" has no manager-saveable outputs.\n' ...
                    'Outputs with outputMode="file" are already file-backed and cannot use saveas.'], ...
                    funcName);
            end

            saveList = string(saveList(:));
            saveList = strip(saveList);

            if numel(saveList) == 1
                if nSaveable ~= 1
                    error('addStep:SaveAsAmbiguous', ...
                        ['Function "%s" has %d saveable outputs. ' ...
                        'Provide saveas as a list with %d filenames.'], ...
                        funcName, nSaveable, nSaveable);
                end
            else
                if numel(saveList) ~= nSaveable
                    error('addStep:SaveAsCountMismatch', ...
                        ['Function "%s" has %d saveable outputs but saveas has %d filenames.'], ...
                        funcName, nSaveable, numel(saveList));
                end
            end

            for iMap = 1:numel(saveList)

                outIdx = saveableIdx(iMap);
                fName  = saveList(iMap);

                if strlength(fName) == 0
                    error('addStep:SaveAsEmpty', ...
                        'saveas contains an empty filename (position %d).', iMap);
                end

                fName = string(strtrim(fName));
                [~, base, ext] = fileparts(char(fName));
                fName = string(base) + string(ext);

                defExt = "";
                hasDefaultBaseName = false;

                if isfield(nodeOut.info.outputs(outIdx),'defOutfilename') && ...
                        ~isempty(nodeOut.info.outputs(outIdx).defOutfilename)

                    def = nodeOut.info.outputs(outIdx).defOutfilename;

                    if iscell(def) && ~isempty(def)
                        def = def{1};
                    end

                    if isstring(def) || ischar(def)
                        def = strtrim(char(string(def)));

                        if ~isempty(def)
                            hasDefaultBaseName = true;
                            [~,~,defExt] = fileparts(def);
                        end
                    end
                end

                if strlength(defExt) > 0

                    [~, base2, ~] = fileparts(char(fName));
                    fName = string(base2) + string(defExt);

                else
                    [~,~,userExt] = fileparts(char(fName));

                    if isempty(userExt) && ~hasDefaultBaseName
                        error('addStep:SaveAsNoExtension', ...
                            ['Output "%s" has no default filename/extension; ' ...
                            'provide an extension in saveas.'], ...
                            nodeOut.info.outputs(outIdx).name);
                    end
                end

                nodeOut.info.outputs(outIdx).saveFileName = char(fName);
            end
        end

        function nodeOut = resolveNodeSaveNameCollisions(obj, nodeIn, varargin)
            %RESOLVENODESAVENAMECOLLISIONS Resolve save-target filename collisions for one node.
            %
            % Only SAVEABLE outputs participate in collision resolution.
            % saveFileName values present on file outputs are ignored.

            p = inputParser;
            addParameter(p, 'excludeNodeID', [], @(x) isempty(x) || (isnumeric(x) && isscalar(x)));
            parse(p, varargin{:});
            excludeNodeID = p.Results.excludeNodeID;

            nodeOut = nodeIn;

            sfForCheck = "";
            if isprop(obj,'SaveFolderList') && ~isempty(obj.SaveFolderList)
                sfForCheck = string(obj.SaveFolderList{1});
            end

            if ~isfield(nodeOut.info,'outputs') || isempty(nodeOut.info.outputs)
                return
            end

            saveableIdx = obj.getSaveableOutputIdx(nodeOut);

            if isempty(saveableIdx)
                return
            end

            outIdxToFix = [];
            reqNames = strings(0,1);

            for iK = 1:numel(saveableIdx)
                iOut = saveableIdx(iK);
                if isfield(nodeOut.info.outputs(iOut),'saveFileName') && ~isempty(nodeOut.info.outputs(iOut).saveFileName)
                    outIdxToFix(end+1) = iOut; %#ok<AGROW>
                    reqNames(end+1,1) = string(nodeOut.info.outputs(iOut).saveFileName); %#ok<AGROW>
                end
            end

            if isempty(outIdxToFix)
                return
            end

            [fixedNames, ~] = obj.resolveUniqueSaveNames(sfForCheck, reqNames, excludeNodeID);

            for iFix = 1:numel(outIdxToFix)
                nodeOut.info.outputs(outIdxToFix(iFix)).saveFileName = char(fixedNames(iFix));
            end
        end

        function [fixedNames, bChanged] = resolveUniqueSaveNames(obj, saveFolder, requestedNames, excludeNodeID)
            %RESOLVEUNIQUESAVENAMES Ensure save filenames are unique vs disk and pipeline.
            %
            % Only SAVEABLE outputs participate in the reserved-name set.
            % saveFileName on outputMode='file' outputs is ignored.

            bChanged = false;

            if nargin < 4
                excludeNodeID = [];
            end

            if nargin < 3 || isempty(requestedNames)
                fixedNames = strings(0,1);
                return
            end

            if ischar(requestedNames) || (isstring(requestedNames) && isscalar(requestedNames))
                fixedNames = string(requestedNames);
            elseif isstring(requestedNames)
                fixedNames = requestedNames;
            elseif iscell(requestedNames)
                fixedNames = string(requestedNames);
            else
                fixedNames = strings(0,1);
            end
            fixedNames = strip(fixedNames(:));

            if isempty(fixedNames)
                return
            end

            if nargin < 2 || isempty(saveFolder)
                sf = '';
            else
                sf = char(string(saveFolder));
            end

            for iN = 1:numel(fixedNames)
                [~,b,e] = fileparts(char(fixedNames(iN)));
                fixedNames(iN) = string(b) + string(e);
            end

            reserved = strings(0,1);
            for iNode = 1:numel(obj.nodes)

                if ~isempty(excludeNodeID)
                    if isfield(obj.nodes(iNode),'id') && obj.nodes(iNode).id == excludeNodeID
                        continue
                    end
                end

                if ~isfield(obj.nodes(iNode),'info') || ~isfield(obj.nodes(iNode).info,'outputs')
                    continue
                end

                outs = obj.nodes(iNode).info.outputs;
                saveableIdx = obj.getSaveableOutputIdx(obj.nodes(iNode));

                for iK = 1:numel(saveableIdx)
                    iOut = saveableIdx(iK);
                    if isfield(outs(iOut),'saveFileName') && ~isempty(outs(iOut).saveFileName)
                        reserved(end+1,1) = string(outs(iOut).saveFileName); %#ok<AGROW>
                    end
                end
            end
            reserved = unique(strip(reserved), 'stable');

            chosen = strings(0,1);

            for iName = 1:numel(fixedNames)

                orig = fixedNames(iName);
                cand = orig;

                diskHit = false;
                if ~isempty(sf)
                    diskHit = isfile(fullfile(sf, char(cand)));
                end
                pipeHit = any(strcmpi(cand, reserved)) || any(strcmpi(cand, chosen));

                if diskHit || pipeHit

                    if diskHit && pipeHit
                        warning('PipelineManager:SaveAsCollision', ...
                            'Requested save filename "%s" already exists in folder and is already reserved in the pipeline.', char(cand));
                    elseif diskHit
                        warning('PipelineManager:SaveAsCollision', ...
                            'Requested save filename "%s" already exists in folder.', char(cand));
                    else
                        warning('PipelineManager:SaveAsCollision', ...
                            'Requested save filename "%s" is already reserved in the pipeline.', char(cand));
                    end

                    if isprop(obj,'b_avoidOverwrite') && obj.b_avoidOverwrite

                        [~, base0, ext0] = fileparts(char(cand));

                        tok = regexp(base0, '^(.*)_(\d+)$', 'tokens', 'once');
                        if ~isempty(tok)
                            baseStem = tok{1};
                            n0 = str2double(tok{2});
                            if isnan(n0) || n0 < 0
                                n0 = 0;
                            end
                            startN = n0 + 1;
                        else
                            baseStem = base0;
                            startN   = 1;
                        end

                        nTry = startN;
                        while true
                            cand2 = string(baseStem) + "_" + string(nTry) + string(ext0);

                            diskHit2 = false;
                            if ~isempty(sf)
                                diskHit2 = isfile(fullfile(sf, char(cand2)));
                            end
                            pipeHit2 = any(strcmpi(cand2, reserved)) || any(strcmpi(cand2, chosen));

                            if ~(diskHit2 || pipeHit2)
                                cand = cand2;
                                bChanged = true;
                                warning('PipelineManager:SaveAsRenamed', ...
                                    'Renaming save filename "%s" -> "%s" (avoid overwrite enabled).', char(orig), char(cand));
                                break
                            end

                            nTry = nTry + 1;
                        end
                    end
                end

                fixedNames(iName) = cand;
                chosen(end+1,1) = cand; %#ok<AGROW>
            end
        end

        function saveableIdx = getSaveableOutputIdx(~, nodeOrNodeLike)
            %GETSAVEABLEOUTPUTIDX Return indices of manager-saveable outputs.
            %
            % Saveable outputs are:
            %   isData == true AND outputMode ~= 'file'
            %
            % Accepts either:
            %   - a full node struct with node.info.outputs
            %   - a node-like struct with .outputs directly

            saveableIdx = [];

            outs = struct([]);

            if isstruct(nodeOrNodeLike) && isfield(nodeOrNodeLike,'info') && ...
                    isfield(nodeOrNodeLike.info,'outputs') && ~isempty(nodeOrNodeLike.info.outputs)
                outs = nodeOrNodeLike.info.outputs;
            elseif isstruct(nodeOrNodeLike) && isfield(nodeOrNodeLike,'outputs') && ~isempty(nodeOrNodeLike.outputs)
                outs = nodeOrNodeLike.outputs;
            else
                return
            end

            mask = false(1, numel(outs));

            for iOut = 1:numel(outs)

                isDataLocal = isfield(outs(iOut),'isData') && outs(iOut).isData;

                outModeLocal = 'data';
                if isfield(outs(iOut),'outputMode') && ~isempty(outs(iOut).outputMode)
                    outModeLocal = lower(strtrim(char(string(outs(iOut).outputMode))));
                end

                mask(iOut) = isDataLocal && ~strcmpi(outModeLocal, 'file');
            end

            saveableIdx = find(mask);
        end

        function showBranches(obj)
            %SHOWBRANCHES Display all root-to-leaf branches in the command window.
            %
            %   showBranches(obj) prints each branch using the current DAG
            %   structure and the active node names.


            leafIDs = obj.getLeafNodeIDs();

            for i = 1:numel(leafIDs)
                path = obj.branchPathFromLeaf(leafIDs(i));
                fprintf('\nBranch %d:\n',i);
                for j = 1:numel(path)
                    idx = find([obj.nodes.id]==path(j),1);
                    fprintf('  %s\n',obj.nodes(idx).name);
                end
            end
        end

        function stepTag = generateStepTag(obj, funcName)
            %GENERATESTEPTAG Generate unique step instance tag.

            funcName = char(string(funcName));
            existing = 0;
            % Count existing instances
            if ~isempty(obj.nodes)
                existing = startsWith({obj.nodes.name}, [funcName '_']);
            end
            count = sum(existing) + 1;

            stepTag = sprintf('%s_%d', funcName, count);
        end

        function ref = resolveInputReference(obj, inputRef)
            %RESOLVEINPUTREFERENCE Resolve user input reference(s) to upstream sources.
            %
            % Supported inputRef formats:
            %   1) File name/path:
            %          'green.dat'
            %          'D:\...\green.dat'
            %          'D:/.../green.dat'
            %      -> struct with nodeID + outputName='data' + selectedFile
            %
            %   2) Step tag:
            %          'GSR_1'
            %      -> nodeID
            %
            %   3) StepTag:Token:
            %          'StepTag:OutputPortName'
            %          'StepTag:filename.ext'
            %      -> struct with nodeID + outputName (+ selectedFile if token is filename)
            %
            % Important:
            %   File/path resolution is attempted before StepTag:Token parsing because
            %   Windows full paths contain a colon after the drive letter, e.g. D:\data\a.dat.

            if iscell(inputRef)
                % Resolve each entry independently, but normalize the result to a
                % struct array. This supports mixed multi-input syntax such as:
                %   {'StepA', 'D:\folder\red.dat', 'StepB:outB'}
                ref = struct( ...
                    'nodeID', {}, ...
                    'outputName', {}, ...
                    'selectedFile', {});

                for iCell = 1:numel(inputRef)
                    r = obj.resolveInputReference(inputRef{iCell});

                    if isstruct(r)
                        for iRef = 1:numel(r)
                            thisRef = r(iRef);

                            if ~isfield(thisRef, 'nodeID')
                                error('PipelineManager:resolveInputReference:InvalidReferenceStruct', ...
                                    'Resolved input reference at position %d is missing nodeID.', iCell);
                            end

                            if ~isfield(thisRef, 'outputName')
                                thisRef.outputName = '';
                            end

                            if ~isfield(thisRef, 'selectedFile')
                                thisRef.selectedFile = '';
                            end

                            ref(end+1) = thisRef; %#ok<AGROW>
                        end

                    elseif isnumeric(r)
                        for iRef = 1:numel(r)
                            ref(end+1) = struct( ... %#ok<AGROW>
                                'nodeID', r(iRef), ...
                                'outputName', '', ...
                                'selectedFile', '');
                        end

                    else
                        error('PipelineManager:resolveInputReference:UnsupportedResolvedReference', ...
                            'Resolved input reference at position %d has unsupported class "%s".', ...
                            iCell, class(r));
                    end
                end

                return
            end

            inputRef = char(string(inputRef));
            inputRef = strtrim(inputRef);

            if isempty(inputRef)
                error('PipelineManager:resolveInputReference:EmptyInput', ...
                    'Input reference cannot be empty.');
            end

            % -------------------------------------------------------------
            % 0) Existing file name/path
            %
            % This must run before StepTag:Token parsing because Windows paths use
            % a drive-letter colon, e.g. D:\folder\red.dat.
            % -------------------------------------------------------------
            [bFileRef, fileBase, filePathForNode] = iResolveAsExistingFileReference(inputRef);

            if bFileRef
                srcID = obj.ensureFileSourceNode(filePathForNode, {'UnknownDataType'});

                ref = struct( ...
                    'nodeID',       srcID, ...
                    'outputName',   'data', ...
                    'selectedFile', fileBase);
                return
            end

            % If it looks like a file path but did not resolve, stop here with a
            % file-specific error instead of parsing the drive-letter colon as a
            % StepTag:Token separator.
            if iLooksLikePathReference(inputRef)
                error('PipelineManager:resolveInputReference:FileNotFound', ...
                    'Input file path could not be resolved in the execution SaveFolder: "%s".', ...
                    inputRef);
            end

            % -------------------------------------------------------------
            % 1) StepTag:Token form
            % -------------------------------------------------------------
            colonPos = strfind(inputRef, ':');

            if ~isempty(colonPos)

                if numel(colonPos) ~= 1
                    error('PipelineManager:resolveInputReference:InvalidColonSyntax', ...
                        'Input "%s" is invalid. Use at most one ":" separator for StepTag:Token syntax.', ...
                        inputRef);
                end

                stepTag = strtrim(inputRef(1:colonPos-1));
                token   = strtrim(inputRef(colonPos+1:end));

                if isempty(stepTag) || isempty(token)
                    error('PipelineManager:resolveInputReference:InvalidStepTokenSyntax', ...
                        'Input "%s" is invalid. Use "StepTag:Token".', inputRef);
                end

                idxStep = find(strcmpi({obj.nodes.name}, stepTag), 1);

                if isempty(idxStep)
                    error('PipelineManager:resolveInputReference:StepNotFound', ...
                        'Step "%s" not found.', stepTag);
                end

                n = obj.nodes(idxStep);

                if ~isfield(n, 'info') || ~isfield(n.info, 'outputs') || isempty(n.info.outputs)
                    error('PipelineManager:resolveInputReference:StepHasNoOutputs', ...
                        'Step "%s" has no outputs.', stepTag);
                end

                outs = n.info.outputs;

                % A) Token matches output port name
                outNames = {outs.name};
                outIdx = find(strcmpi(outNames, token), 1);

                if ~isempty(outIdx)
                    ref = struct( ...
                        'nodeID',       n.id, ...
                        'outputName',   outs(outIdx).name, ...
                        'selectedFile', '');
                    return
                end

                % B) Token treated as filename; must be listed in a file output
                fileOutIdx = find(arrayfun(@(o) isfield(o, 'outputMode') && ...
                    strcmpi(o.outputMode, 'file'), outs));

                if isempty(fileOutIdx)
                    error('PipelineManager:resolveInputReference:NoFileOutputs', ...
                        'Step "%s" has no file outputs. Cannot select file "%s".', ...
                        stepTag, token);
                end

                matchIdx = [];

                for ii = 1:numel(fileOutIdx)

                    o = outs(fileOutIdx(ii));

                    if ~isfield(o, 'defOutfilename') || isempty(o.defOutfilename)
                        continue
                    end

                    defFiles = iNormalizeFileList(o.defOutfilename);

                    if any(strcmpi(defFiles, token))
                        matchIdx(end+1) = fileOutIdx(ii); %#ok<AGROW>
                    end
                end

                if isempty(matchIdx)
                    error('PipelineManager:resolveInputReference:FileNotDeclaredByStep', ...
                        'File "%s" is not listed as an available output for step "%s".', ...
                        token, stepTag);
                end

                if numel(matchIdx) > 1
                    error('PipelineManager:resolveInputReference:AmbiguousStepFile', ...
                        ['File "%s" matches multiple file outputs on step "%s". ' ...
                        'Use "StepTag:OutputName" to disambiguate.'], ...
                        token, stepTag);
                end

                ref = struct( ...
                    'nodeID',       n.id, ...
                    'outputName',   outs(matchIdx).name, ...
                    'selectedFile', token);
                return
            end

            % -------------------------------------------------------------
            % 2) Step tag
            % -------------------------------------------------------------
            idx = find(strcmpi({obj.nodes.name}, inputRef), 1);

            if ~isempty(idx)
                ref = obj.nodes(idx).id;
                return
            end

            % -------------------------------------------------------------
            % 3) Produced file name, legacy saveFileName lookup
            % -------------------------------------------------------------
            producers = [];

            for iNode = 1:numel(obj.nodes)
                if isfield(obj.nodes(iNode), 'saveFileName') && ...
                        strcmpi(char(string(obj.nodes(iNode).saveFileName)), inputRef)
                    producers(end+1) = obj.nodes(iNode).id; %#ok<AGROW>
                end
            end

            if numel(producers) == 1
                ref = producers;
                return

            elseif numel(producers) > 1
                error('PipelineManager:resolveInputReference:AmbiguousProducedFile', ...
                    'Multiple steps produce "%s".', inputRef);
            end

            error('PipelineManager:resolveInputReference:UnresolvedInput', ...
                'Input "%s" could not be resolved.', inputRef);

            % =====================================================================
            % Local helpers
            % =====================================================================

            function [tf, fileBaseLocal, filePathLocal] = iResolveAsExistingFileReference(refIn)
                %IRESOLVEASEXISTINGFILEREFERENCE Resolve filename/full path first.

                tf = false;
                fileBaseLocal = '';
                filePathLocal = '';

                refIn = char(string(refIn));
                refIn = strtrim(refIn);

                if isempty(refIn) || isempty(obj.SaveFolderList)
                    return
                end

                [folderPart, basePart, extPart] = fileparts(refIn);
                fileBaseCandidate = [basePart extPart];

                if isempty(fileBaseCandidate)
                    return
                end

                candidates = strings(0,1);

                % Full/relative path candidate as typed.
                if iLooksLikePathReference(refIn)
                    candidates(end+1,1) = string(refIn); %#ok<AGROW>
                end

                % Folder-bound candidate. This is the canonical PipelineManager
                % interpretation of a file input: file lives in SaveFolder.
                candidates(end+1,1) = string(fullfile(obj.SaveFolderList{1}, fileBaseCandidate)); %#ok<AGROW>

                % Plain ref may itself be a file in current folder when caller passes
                % relative paths from cwd. Keep it as a final candidate.
                candidates(end+1,1) = string(refIn); %#ok<AGROW>

                candidates = unique(candidates, 'stable');

                for iCand = 1:numel(candidates)
                    candidatePath = char(candidates(iCand));

                    if isfile(candidatePath)
                        [~, fBase, fExt] = fileparts(candidatePath);
                        fileBaseLocal = [fBase fExt];

                        % Always bind the graph source to the SaveFolder version when it
                        % exists. This keeps batch execution folder-relative.
                        folderBoundPath = fullfile(obj.SaveFolderList{1}, fileBaseLocal);

                        if isfile(folderBoundPath)
                            filePathLocal = folderBoundPath;
                        else
                            filePathLocal = candidatePath;
                        end

                        tf = true;
                        return
                    end
                end
            end

            function tf = iLooksLikePathReference(refIn)
                %ILOOKSLIKEPATHREFERENCE True for full/relative filesystem paths.

                refIn = char(string(refIn));

                tf = contains(refIn, filesep) || ...
                    contains(refIn, '/') || ...
                    contains(refIn, '\') || ...
                    ~isempty(regexp(refIn, '^[A-Za-z]:[\\/]', 'once')) || ...
                    startsWith(refIn, '\\') || ...
                    startsWith(refIn, '//');
            end

            function fileList = iNormalizeFileList(fileSpec)
                %INORMALIZEFILELIST Normalize defOutfilename-like metadata.

                fileList = {};

                if isempty(fileSpec)
                    return
                end

                try
                    if ischar(fileSpec) || (isstring(fileSpec) && isscalar(fileSpec))
                        fileList = {char(string(fileSpec))};

                    elseif isstring(fileSpec)
                        fileList = cellstr(fileSpec(:));

                    elseif iscell(fileSpec)
                        fileList = cellfun(@(x) char(string(x)), ...
                            fileSpec(:), 'UniformOutput', false);
                    end
                catch
                    fileList = {};
                end

                fileList = fileList(~cellfun(@isempty, fileList));

                for iFile = 1:numel(fileList)
                    [~, b, e] = fileparts(fileList{iFile});
                    fileList{iFile} = [b e];
                end

                fileList = unique(fileList, 'stable');
            end
        end

        function leafIDs = getLeafNodeIDs(obj)
            %GETLEAFNODEIDS Return node IDs with no outgoing connections.
            %
            %   leafIDs = getLeafNodeIDs(obj) returns the current set of leaf
            %   nodes in the DAG.


            allIDs = [obj.nodes.id];

            if isempty(obj.connections)
                leafIDs = allIDs;
                return
            end

            srcIDs = [obj.connections.sourceNodeID];

            leafIDs = allIDs(~ismember(allIDs,srcIDs));
        end

        function funcNames = getUpstreamFunctionNames(obj,nodeID)
            %GETUPSTREAMFUNCTIONNAMES Return upstream function names for one node.
            %
            %   funcNames = getUpstreamFunctionNames(obj, nodeID) walks upstream
            %   from NODEID and collects stream-node function names.

            visited = [];
            stack = nodeID;
            funcNames = {};

            while ~isempty(stack)

                current = stack(end);
                stack(end) = [];

                if ismember(current,visited)
                    continue
                end

                visited(end+1) = current;

                idx = find([obj.nodes.id]==current,1);

                if isempty(idx)
                    continue
                end

                nodeLocal = obj.nodes(idx);

                if strcmpi(nodeLocal.kind,'stream')
                    funcNameLocal = obj.getNodeFunctionName(nodeLocal);
                    if ~isempty(funcNameLocal)
                        funcNames{end+1} = funcNameLocal; %#ok<AGROW>
                    end
                end

                % --- Safe parent lookup ---
                if isempty(obj.connections)
                    parents = [];
                else
                    mask = [obj.connections.targetNodeID] == current;
                    parents = obj.connections(mask);
                end

                if ~isempty(parents)
                    stack = [stack [parents.sourceNodeID]]; %#ok<AGROW>
                end
            end

            funcNames = unique(funcNames, 'stable');
        end

        function funcNames = getDownstreamFunctionNames(obj,nodeID)
            %GETDOWNSTREAMFUNCTIONNAMES Return downstream stream function names.
            %
            %   funcNames = obj.getDownstreamFunctionNames(nodeID) walks downstream
            %   from NODEID and collects stream-node function names. The starting
            %   node is not included.

            visited = [];
            funcNames = {};

            if isempty(obj.connections)
                return
            end

            childConns = obj.connections([obj.connections.sourceNodeID] == nodeID);
            stack = [childConns.targetNodeID];

            while ~isempty(stack)

                current = stack(end);
                stack(end) = [];

                if ismember(current, visited)
                    continue
                end

                visited(end+1) = current; %#ok<AGROW>

                idx = find([obj.nodes.id] == current, 1);

                if isempty(idx)
                    continue
                end

                nodeLocal = obj.nodes(idx);

                if strcmpi(nodeLocal.kind, 'stream')
                    funcNameLocal = obj.getNodeFunctionName(nodeLocal);
                    if ~isempty(funcNameLocal)
                        funcNames{end+1} = funcNameLocal; %#ok<AGROW>
                    end
                end

                childConns = obj.connections([obj.connections.sourceNodeID] == current);
                if ~isempty(childConns)
                    stack = [stack [childConns.targetNodeID]]; %#ok<AGROW>
                end
            end

            funcNames = unique(funcNames, 'stable');
        end

        function funcName = getNodeFunctionName(~, nodeLocal)
            %GETNODEFUNCTIONNAME Return the base function name for a stream node.
            %
            %   FUNCNAME = GETNODEFUNCTIONNAME(~, NODELOCAL) prefers the modern
            %   pipelineInfo function name. If unavailable, it strips only a final
            %   numeric step suffix, preserving function names that contain
            %   underscores such as run_HemoCorrection_1.

            funcName = '';

            if isfield(nodeLocal, 'info') && isfield(nodeLocal.info, 'name') && ...
                    ~isempty(nodeLocal.info.name)
                funcName = char(string(nodeLocal.info.name));
                return
            end

            if isfield(nodeLocal, 'name') && ~isempty(nodeLocal.name)
                nodeName = char(string(nodeLocal.name));
                tok = regexp(nodeName, '^(.*)_\d+$', 'tokens', 'once');

                if ~isempty(tok)
                    funcName = tok{1};
                else
                    funcName = nodeName;
                end
            end
        end

        function validateReconnectDuplicateFunctionRule(obj, targetNodeID, srcRefs)
            %VALIDATERECONNECTDUPLICATEFUNCTIONRULE Enforce branch duplicate rules.
            %
            %   This preflight guard mirrors addStep duplicate-function validation
            %   and adds a reconnect-specific downstream-overlap check. It runs
            %   before the graph is modified so rejected reconnect attempts leave
            %   the current connections unchanged.

            targetIdx = find([obj.nodes.id] == targetNodeID, 1);

            if isempty(targetIdx)
                error('PipelineManager:reconnectStep:InvalidTargetNode', ...
                    'Target node %d does not exist.', targetNodeID);
            end

            targetNode = obj.nodes(targetIdx);
            targetFunc = obj.getNodeFunctionName(targetNode);

            if isempty(targetFunc)
                return
            end

            srcNodeIDs = localSourceNodeIDs(srcRefs);
            downstreamFuncs = obj.getDownstreamFunctionNames(targetNodeID);

            for iSrc = 1:numel(srcNodeIDs)

                srcNodeID = srcNodeIDs(iSrc);

                if srcNodeID == targetNodeID
                    error('PipelineManager:reconnectStep:DuplicateFunctionInBranch', ...
                        'Reconnect would create a self-dependent branch for step "%s".', ...
                        targetNode.name);
                end

                upstreamFuncs = obj.getUpstreamFunctionNames(srcNodeID);

                % Same rule as addStep: the target function cannot already exist
                % upstream of the proposed source branch.
                if any(strcmpi(upstreamFuncs, targetFunc))
                    error('PipelineManager:reconnectStep:DuplicateFunctionInBranch', ...
                        ['Reconnect rejected because function "%s" already exists upstream ' ...
                        'of the proposed source for step "%s".'], ...
                        targetFunc, targetNode.name);
                end

                % Reconnect-specific rule: a proposed upstream branch cannot contain
                % a function that already exists downstream of the target step,
                % otherwise the resulting root-to-leaf branch would contain the same
                % function twice even though the target function itself is unique.
                overlap = intersect(lower(string(upstreamFuncs)), lower(string(downstreamFuncs)), 'stable');

                if ~isempty(overlap)
                    overlapStr = strjoin(overlap, ', ');
                    error('PipelineManager:reconnectStep:DuplicateFunctionInBranch', ...
                        ['Reconnect rejected because proposed upstream function(s) [%s] ' ...
                        'already exist downstream of step "%s".'], ...
                        char(overlapStr), targetNode.name);
                end
            end

            % =========================================================
            % Local helper
            % =========================================================
            function ids = localSourceNodeIDs(refs)
                if isempty(refs)
                    ids = [];
                    return
                end

                if isstruct(refs)
                    ids = [refs.nodeID];
                else
                    ids = refs;
                end

                ids = ids(:).';
            end
        end

        function updateTopoOrder(obj)
            %UPDATETOPOORDER Compute and cache topological order of the DAG.

            if isempty(obj.nodes)
                obj.topoOrder = [];
                return
            end

            nodeIDs = [obj.nodes.id];
            nNodes  = numel(nodeIDs);

            % -------------------------------------------------------------
            % If no connections → topo order is insertion-independent
            % Every node has in-degree zero
            % -------------------------------------------------------------
            if isempty(obj.connections)
                obj.topoOrder = nodeIDs;
                return
            end

            % -------------------------------------------------------------
            % Compute in-degree
            % -------------------------------------------------------------
            inDegree = zeros(1,nNodes);

            for i = 1:numel(obj.connections)
                tgt = obj.connections(i).targetNodeID;
                idx = find(nodeIDs == tgt,1);
                if ~isempty(idx)
                    inDegree(idx) = inDegree(idx) + 1;
                end
            end

            % -------------------------------------------------------------
            % Kahn's algorithm
            % -------------------------------------------------------------
            queue = nodeIDs(inDegree == 0);
            topo  = [];

            while ~isempty(queue)

                current = queue(1);
                queue(1) = [];

                topo(end+1) = current; %#ok<AGROW>

                % ---- SAFELY handle empty connections ----
                if isempty(obj.connections)
                    continue
                end

                outgoingIdx = [obj.connections.sourceNodeID] == current;
                outgoing    = obj.connections(outgoingIdx);

                for j = 1:numel(outgoing)

                    tgt = outgoing(j).targetNodeID;
                    idx = find(nodeIDs == tgt,1);

                    inDegree(idx) = inDegree(idx) - 1;

                    if inDegree(idx) == 0
                        queue(end+1) = tgt; %#ok<AGROW>
                    end
                end
            end

            % -------------------------------------------------------------
            % Cycle detection
            % -------------------------------------------------------------
            if numel(topo) ~= nNodes
                error('PipelineManager:updateTopoOrder:CycleDetected', ...
                    'Graph contains a cycle.');
            end

            obj.topoOrder = topo;
        end

        function srcNodeID = ensureFileSourceNode(obj, filePath, semanticType)
            %ENSUREFILESOURCENODE Create or reuse a folder source node for a file.
            %
            %   srcNodeID = ensureFileSourceNode(obj, filePath, semanticType)
            %
            %   semanticType must be a cell array of char.
            %   Reuse is based on:
            %       - folder node
            %       - node.name == filename
            %       - compatible semantic type
            %
            %   File existence is checked using the first SaveFolder.
            %
            %   FileSource nodes are graph proxies for existing files. They are not
            %   executed as pipeline steps. Runtime file access should be carried by
            %   connections with selectedFile populated, which happens when callers pass
            %   filename/full-path inputs through resolveInputReference.

            filePath = char(string(filePath));

            if isempty(strtrim(filePath))
                error('PipelineManager:ensureFileSourceNode:InvalidFile', ...
                    'Invalid file.');
            end

            if nargin < 3 || isempty(semanticType)
                semanticType = {'UnknownDataType'};
            elseif ischar(semanticType) || (isstring(semanticType) && isscalar(semanticType))
                semanticType = {char(string(semanticType))};
            elseif isstring(semanticType)
                semanticType = cellstr(semanticType(:));
            elseif iscell(semanticType)
                semanticType = cellfun(@(x) char(string(x)), semanticType(:), 'UniformOutput', false);
            else
                semanticType = {'UnknownDataType'};
            end

            semanticType = semanticType(:).';
            semanticType = semanticType(~cellfun(@isempty, semanticType));

            if isempty(semanticType)
                semanticType = {'UnknownDataType'};
            end

            [~, filename, ext] = fileparts(filePath);
            filename = [filename ext];

            if isempty(filename)
                error('PipelineManager:ensureFileSourceNode:InvalidFile', ...
                    'Invalid file name.');
            end

            % -------------------------------------------------------------
            % Validate file existence using first SaveFolder
            % -------------------------------------------------------------
            if isempty(obj.SaveFolderList)
                error('PipelineManager:ensureFileSourceNode:EmptySaveFolderList', ...
                    'SaveFolderList is empty.');
            end

            testPath = fullfile(obj.SaveFolderList{1}, filename);

            if ~isfile(testPath)
                error('PipelineManager:ensureFileSourceNode:FileNotFound', ...
                    'File "%s" not found in execution folder "%s".', ...
                    filename, obj.SaveFolderList{1});
            end

            % -------------------------------------------------------------
            % Try to reuse existing folder node
            % -------------------------------------------------------------
            for i = 1:numel(obj.nodes)

                n = obj.nodes(i);

                if ~isfield(n, 'kind') || ~strcmpi(char(string(n.kind)), 'folder')
                    continue
                end

                if ~isfield(n, 'name') || ~strcmpi(char(string(n.name)), filename)
                    continue
                end

                if ~isfield(n, 'info') || ~isfield(n.info, 'outputs') || isempty(n.info.outputs)
                    continue
                end

                out = n.info.outputs(1);

                if ~isfield(out, 'isData') || ~logical(out.isData)
                    continue
                end

                existingTypes = {};
                if isfield(out, 'type') && ~isempty(out.type)
                    existingTypes = cellstr(string(out.type(:)));
                end

                requiredTypes = semanticType;

                srcHasWildcard = any(strcmp(existingTypes, 'UnknownDataType'));
                dstHasWildcard = any(strcmp(requiredTypes, 'UnknownDataType'));

                isCompatible = srcHasWildcard || dstHasWildcard || ...
                    ~isempty(intersect(existingTypes, requiredTypes));

                if isCompatible
                    % Upgrade/normalize older FileSource nodes so the GUI sees this as a
                    % concrete file-backed data source.
                    obj.nodes(i).info.name = 'FileSource';

                    obj.nodes(i).info.outputs(1).name = 'data';
                    obj.nodes(i).info.outputs(1).type = existingTypes;
                    obj.nodes(i).info.outputs(1).isData = true;
                    obj.nodes(i).info.outputs(1).outputMode = 'file';
                    obj.nodes(i).info.outputs(1).defOutfilename = filename;
                    obj.nodes(i).info.outputs(1).saveFileName = '';
                    obj.nodes(i).info.outputs(1).position = 1;
                    obj.nodes(i).info.outputs(1).description = sprintf('Data from %s', filename);

                    if isempty(obj.nodes(i).info.outputs(1).type)
                        obj.nodes(i).info.outputs(1).type = semanticType;
                    end

                    srcNodeID = n.id;
                    return
                end
            end

            % -------------------------------------------------------------
            % Create new folder node
            % -------------------------------------------------------------
            info = PipelineManager.createPipelineInfo();
            info.name = 'FileSource';

            info.outputs(1).name = 'data';
            info.outputs(1).type = semanticType;
            info.outputs(1).isData = true;
            info.outputs(1).outputMode = 'file';
            info.outputs(1).defOutfilename = filename;
            info.outputs(1).saveFileName = '';
            info.outputs(1).position = 1;
            info.outputs(1).description = sprintf('Data from %s', filename);

            node = obj.createNodeFromFuncInfo( ...
                filename, ...
                info, ...
                'kind', 'folder');

            obj.nodes = [obj.nodes, node];
            srcNodeID = node.id;
        end

        function connectNodes(obj, srcNodeID, dstNodeID, srcOutputName, dstInputName, selectedFile)
            %CONNECTNODES Add a directed connection (edge) between nodes.
            %
            %   CONNECTNODES(OBJ, SRCNODEID, DSTNODEID, SRCOUTPUTNAME, DSTINPUTNAME)
            %   CONNECTNODES(..., SELECTEDFILE)
            %
            %   SELECTEDFILE is optional and only used for file-based outputs where the
            %   upstream output represents a "manifest" and the user selected one file
            %   to consume. Use '' when not applicable.
            %
            %   Structural guarantees enforced:
            %       - No self-edges
            %       - No duplicate edges
            %       - One connection per target input port
            %       - Folder nodes cannot receive inputs
            %       - No cycles (DAG invariant)
            %
            %   Side effects:
            %       - Updates topological order

            if nargin < 6 || isempty(selectedFile)
                selectedFile = '';
            end

            % --- Normalize names ---
            srcOutputName = char(string(srcOutputName));
            dstInputName  = char(string(dstInputName));
            selectedFile  = char(string(selectedFile)); % allow '' / string / char

            % --- Check node existence ---
            if ~ismember(srcNodeID, [obj.nodes.id])
                error('PipelineManager:connectNodes:InvalidSourceNode', ...
                    'Source node %d does not exist.', srcNodeID);
            end

            if ~ismember(dstNodeID, [obj.nodes.id])
                error('PipelineManager:connectNodes:InvalidTargetNode', ...
                    'Target node %d does not exist.', dstNodeID);
            end

            % --- Prevent self-edge ---
            if srcNodeID == dstNodeID
                error('PipelineManager:connectNodes:SelfEdge', ...
                    'Cannot create self-edge on node %d.', srcNodeID);
            end

            % --- Resolve nodes ---
            srcIdx = find([obj.nodes.id] == srcNodeID, 1);
            dstIdx = find([obj.nodes.id] == dstNodeID, 1);

            srcNode = obj.nodes(srcIdx);
            dstNode = obj.nodes(dstIdx);

            % --- Prevent inputs into folder nodes ---
            if strcmpi(dstNode.kind, 'folder')
                error('PipelineManager:connectNodes:FolderInput', ...
                    'Folder nodes cannot receive inputs.');
            end

            % --- Resolve ports ---
            outIdx = find(strcmpi({srcNode.info.outputs.name}, srcOutputName), 1);
            if isempty(outIdx)
                error('PipelineManager:connectNodes:InvalidSourceOutput', ...
                    'Output "%s" not found in node %d.', srcOutputName, srcNodeID);
            end

            inIdx = find(strcmpi({dstNode.info.inputs.name}, dstInputName), 1);
            if isempty(inIdx)
                error('PipelineManager:connectNodes:InvalidTargetInput', ...
                    'Input "%s" not found in node %d.', dstInputName, dstNodeID);
            end

            % --- Prevent duplicate edges (exact same edge) ---
            if ~isempty(obj.connections)
                isDuplicate = obj.connections( ...
                    [obj.connections.sourceNodeID] == srcNodeID & ...
                    [obj.connections.targetNodeID] == dstNodeID & ...
                    strcmpi({obj.connections.sourceOutputName}, srcOutputName) & ...
                    strcmpi({obj.connections.targetInputName}, dstInputName));

                if ~isempty(isDuplicate)
                    error('PipelineManager:connectNodes:DuplicateEdge', ...
                        'Duplicate connection from node %d to node %d (%s → %s).', ...
                        srcNodeID, dstNodeID, srcOutputName, dstInputName);
                end
            end

            % --- Enforce one connection per target input port ---
            if ~isempty(obj.connections)
                alreadyWired = obj.connections( ...
                    [obj.connections.targetNodeID] == dstNodeID & ...
                    strcmpi({obj.connections.targetInputName}, dstInputName));

                if ~isempty(alreadyWired)
                    error('PipelineManager:connectNodes:InputAlreadyConnected', ...
                        'Target node %d input "%s" is already connected.', ...
                        dstNodeID, dstInputName);
                end
            end

            % --- Create candidate connection ---
            conn.sourceNodeID     = srcNodeID;
            conn.targetNodeID     = dstNodeID;
            conn.sourceOutputName = srcOutputName;
            conn.targetInputName  = dstInputName;

            % --- Cache semantic types directly from node metadata ---
            conn.sourceOutputType = srcNode.info.outputs(outIdx).type;
            conn.targetInputType  = dstNode.info.inputs(inIdx).type;

            % --- NEW: optional selected file (legacy manifest support) ---
            conn.selectedFile     = selectedFile;

            % --- Temporarily add to test cycle ---
            if isempty(obj.connections)
                obj.connections = conn;
            else
                obj.connections(end+1) = conn;
            end

            % --- Check for cycle ---
            try
                obj.updateTopoOrder();
            catch ME
                obj.connections(end) = [];
                rethrow(ME);
            end
        end

        function [tf, report] = validateGraph(obj, varargin)
            %VALIDATEGRAPH Validate the current DAG structure.
            %
            %   tf = validateGraph(obj)
            %   [tf, report] = validateGraph(obj, 'throwOnError', tf)
            %
            % Validates:
            %   - Unique node IDs
            %   - Connections reference existing nodes
            %   - Referenced source outputs / target inputs exist
            %   - No self edges
            %   - No duplicate edges (based on actual edge identity)
            %   - Folder nodes have no incoming edges
            %   - DATA-flow semantic compatibility via type intersection
            %   - All required DATA inputs of stream nodes connected exactly once
            %   - Graph is acyclic (topo order computable)
            %
            % Notes:
            %   - Duplicate-edge detection uses:
            %         sourceNodeID + targetNodeID + sourceOutputName + targetInputName + selectedFile
            %     so distinct input ports or distinct file selections are not collapsed.
            %   - Required input validation is done by actual target input port name,
            %     not by semantic compatibility alone.

            p = inputParser;
            addParameter(p, 'throwOnError', false, @(x)islogical(x)&&isscalar(x));
            parse(p, varargin{:});
            throwOnError = p.Results.throwOnError;

            report = struct('errors', {{}}, 'warnings', {{}});
            tf = true;

            % -----------------------------
            % Empty graph is valid
            % -----------------------------
            if isempty(obj.nodes)
                return
            end

            nodeIDs = [obj.nodes.id];

            % -----------------------------
            % NodeID uniqueness
            % -----------------------------
            if numel(unique(nodeIDs)) ~= numel(nodeIDs)
                report.errors{end+1} = 'Duplicate node IDs detected in obj.nodes.';
            end

            % -----------------------------
            % Connections checks
            % -----------------------------
            if ~isempty(obj.connections)

                srcIDs = [obj.connections.sourceNodeID];
                dstIDs = [obj.connections.targetNodeID];

                % (a) endpoints exist
                missingSrc = setdiff(unique(srcIDs), nodeIDs);
                missingDst = setdiff(unique(dstIDs), nodeIDs);

                for i = 1:numel(missingSrc)
                    report.errors{end+1} = sprintf( ...
                        'Connection references missing source nodeID %d.', missingSrc(i));
                end
                for i = 1:numel(missingDst)
                    report.errors{end+1} = sprintf( ...
                        'Connection references missing target nodeID %d.', missingDst(i));
                end

                % (b) no self edges
                selfMask = srcIDs == dstIDs;
                if any(selfMask)
                    bad = find(selfMask);
                    for k = 1:numel(bad)
                        c = obj.connections(bad(k));
                        report.errors{end+1} = sprintf( ...
                            'Self-edge detected on nodeID %d.', c.sourceNodeID);
                    end
                end

                % (c) duplicates by actual edge identity
                sig = strings(1, numel(obj.connections));
                for i = 1:numel(obj.connections)
                    c = obj.connections(i);

                    srcOut = '';
                    dstIn  = '';
                    selFile = '';

                    if isfield(c,'sourceOutputName') && ~isempty(c.sourceOutputName)
                        srcOut = char(string(c.sourceOutputName));
                    end
                    if isfield(c,'targetInputName') && ~isempty(c.targetInputName)
                        dstIn = char(string(c.targetInputName));
                    end
                    if isfield(c,'selectedFile') && ~isempty(c.selectedFile)
                        selFile = char(string(c.selectedFile));
                    end

                    sig(i) = sprintf('%d|%d|%s|%s|%s', ...
                        c.sourceNodeID, ...
                        c.targetNodeID, ...
                        lower(strtrim(srcOut)), ...
                        lower(strtrim(dstIn)), ...
                        lower(strtrim(selFile)));
                end

                if numel(unique(sig)) ~= numel(sig)
                    report.errors{end+1} = ...
                        'Duplicate edges detected (same source node, target node, source output, target input, and selected file).';
                end

                % (d) per-connection structural + semantic checks
                for i = 1:numel(obj.connections)

                    c = obj.connections(i);

                    % Skip deeper checks if endpoints are missing
                    if ~ismember(c.sourceNodeID, nodeIDs) || ~ismember(c.targetNodeID, nodeIDs)
                        continue
                    end

                    srcIdx = find(nodeIDs == c.sourceNodeID, 1, 'first');
                    dstIdx = find(nodeIDs == c.targetNodeID, 1, 'first');

                    srcNode = obj.nodes(srcIdx);
                    dstNode = obj.nodes(dstIdx);

                    % Folder nodes cannot receive inputs
                    if strcmpi(dstNode.kind, 'folder')
                        report.errors{end+1} = sprintf( ...
                            'Folder nodeID %d ("%s") has an incoming edge (%d -> %d).', ...
                            dstNode.id, dstNode.name, c.sourceNodeID, c.targetNodeID);
                        continue
                    end

                    % Source output must exist
                    if ~isfield(srcNode,'info') || ~isfield(srcNode.info,'outputs') || isempty(srcNode.info.outputs)
                        report.errors{end+1} = sprintf( ...
                            'Source nodeID %d ("%s") has no outputs metadata.', ...
                            srcNode.id, srcNode.name);
                        continue
                    end

                    srcOutIdx = find(strcmpi({srcNode.info.outputs.name}, c.sourceOutputName), 1, 'first');
                    if isempty(srcOutIdx)
                        report.errors{end+1} = sprintf( ...
                            'Connection references missing source output "%s" on nodeID %d ("%s").', ...
                            char(string(c.sourceOutputName)), srcNode.id, srcNode.name);
                        continue
                    end
                    srcOutDef = srcNode.info.outputs(srcOutIdx);

                    % Target input must exist
                    if ~isfield(dstNode,'info') || ~isfield(dstNode.info,'inputs') || isempty(dstNode.info.inputs)
                        report.errors{end+1} = sprintf( ...
                            'Target nodeID %d ("%s") has no inputs metadata.', ...
                            dstNode.id, dstNode.name);
                        continue
                    end

                    dstInIdx = find(strcmpi({dstNode.info.inputs.name}, c.targetInputName), 1, 'first');
                    if isempty(dstInIdx)
                        report.errors{end+1} = sprintf( ...
                            'Connection references missing target input "%s" on nodeID %d ("%s").', ...
                            char(string(c.targetInputName)), dstNode.id, dstNode.name);
                        continue
                    end
                    dstInDef = dstNode.info.inputs(dstInIdx);

                    % Connections are only valid for DATA ports
                    srcIsData = isfield(srcOutDef,'isData') && srcOutDef.isData;
                    dstIsData = isfield(dstInDef,'isData') && dstInDef.isData;

                    if ~srcIsData
                        report.errors{end+1} = sprintf( ...
                            'Connection uses non-DATA source output "%s" on nodeID %d ("%s").', ...
                            char(string(c.sourceOutputName)), srcNode.id, srcNode.name);
                        continue
                    end

                    if ~dstIsData
                        report.errors{end+1} = sprintf( ...
                            'Connection targets non-DATA input "%s" on nodeID %d ("%s").', ...
                            char(string(c.targetInputName)), dstNode.id, dstNode.name);
                        continue
                    end

                    % Semantic compatibility
                    srcTypes = {};
                    dstTypes = {};

                    if isfield(srcOutDef,'type') && ~isempty(srcOutDef.type)
                        if ischar(srcOutDef.type) || isstring(srcOutDef.type)
                            srcTypes = {char(string(srcOutDef.type))};
                        else
                            srcTypes = srcOutDef.type;
                        end
                    elseif isfield(c,'sourceOutputType')
                        srcTypes = c.sourceOutputType;
                    end

                    if isfield(dstInDef,'type') && ~isempty(dstInDef.type)
                        if ischar(dstInDef.type) || isstring(dstInDef.type)
                            dstTypes = {char(string(dstInDef.type))};
                        else
                            dstTypes = dstInDef.type;
                        end
                    elseif isfield(c,'targetInputType')
                        dstTypes = c.targetInputType;
                    end

                    if isempty(srcTypes) || isempty(dstTypes)
                        report.errors{end+1} = sprintf( ...
                            'Missing semantic type for connection %d ("%s") -> %d ("%s").', ...
                            c.sourceNodeID, char(string(c.sourceOutputName)), ...
                            c.targetNodeID, char(string(c.targetInputName)));
                        continue
                    end

                    srcHasWildcard = any(strcmp(srcTypes,'UnknownDataType'));
                    dstHasWildcard = any(strcmp(dstTypes,'UnknownDataType'));

                    if ~(srcHasWildcard || dstHasWildcard)
                        if isempty(intersect(srcTypes, dstTypes))
                            report.errors{end+1} = sprintf( ...
                                ['Semantic type mismatch: nodeID %d ("%s") output "%s" -> ' ...
                                'nodeID %d ("%s") input "%s".'], ...
                                srcNode.id, srcNode.name, char(string(c.sourceOutputName)), ...
                                dstNode.id, dstNode.name, char(string(c.targetInputName)));
                        end
                    end
                end
            end

            % -----------------------------
            % Required DATA inputs connected exactly once
            % -----------------------------
            streamIdx = find(strcmpi({obj.nodes.kind}, 'stream'));

            for ii = 1:numel(streamIdx)

                n = obj.nodes(streamIdx(ii));

                if ~isfield(n,'info') || ~isfield(n.info,'inputs') || isempty(n.info.inputs)
                    continue
                end

                for k = 1:numel(n.info.inputs)

                    inDef = n.info.inputs(k);

                    % Only enforce for DATA ports
                    if ~isfield(inDef,'isData') || ~inDef.isData
                        continue
                    end

                    nIncoming = 0;

                    if ~isempty(obj.connections)
                        for jj = 1:numel(obj.connections)
                            c = obj.connections(jj);

                            if c.targetNodeID ~= n.id
                                continue
                            end

                            if strcmpi(char(string(c.targetInputName)), char(string(inDef.name)))
                                nIncoming = nIncoming + 1;
                            end
                        end
                    end

                    if nIncoming == 0
                        report.errors{end+1} = sprintf( ...
                            'Node "%s" (nodeID %d) missing required data input "%s".', ...
                            n.name, n.id, char(string(inDef.name)));
                    elseif nIncoming > 1
                        report.errors{end+1} = sprintf( ...
                            'Node "%s" (nodeID %d) has multiple connections to data input "%s".', ...
                            n.name, n.id, char(string(inDef.name)));
                    end
                end
            end

            % -----------------------------
            % Cycle detection
            % -----------------------------
            try
                obj.updateTopoOrder();
            catch ME
                report.errors{end+1} = ...
                    sprintf('Topological sort failed (cycle suspected): %s', ME.message);
            end

            % -----------------------------
            % Finalize
            % -----------------------------
            tf = isempty(report.errors);

            if ~tf && throwOnError
                error('PipelineManager:validateGraph:InvalidGraph', ...
                    '%s', strjoin(report.errors, '\n'));
            end
        end

        function autoValidate(obj)
            %AUTOVALIDATE Run graph/parameter validation and refresh node status.
            %
            %   autoValidate(obj) performs the same validation layers used by
            %   diagnosePipeline, but prints only a concise error summary when the
            %   pipeline is invalid. It also refreshes nodes(i).runtime.validation
            %   so GUI code can read the latest cached node-level status.

            [tfGraph, graphReport] = obj.validateGraph('throwOnError', false);
            [tfParams, paramReport] = obj.validateNodeParameters('throwOnError', false);
            [tfPreflight, preflightReport] = obj.validateNodePreflight('throwOnError', false);
            paramReport.errors = [paramReport.errors, preflightReport.errors];
            paramReport.warnings = [paramReport.warnings, preflightReport.warnings];

            tf = tfGraph && tfParams && tfPreflight;

            report = struct();
            report.errors = [graphReport.errors, paramReport.errors];
            report.warnings = [graphReport.warnings, paramReport.warnings];
            report.nodeStatus = obj.buildNodeStatusTable(graphReport, paramReport);
            report.hasInvalidNonblocking = istable(report.nodeStatus) && ...
                any(report.nodeStatus.status == "invalid_nonblocking");
            report.hasInvalidBlocking = istable(report.nodeStatus) && ...
                any(report.nodeStatus.status == "invalid_blocking");

            obj.updateNodeRuntimeValidation(report.nodeStatus);

            if isprop(obj,'b_pipeIsValid')
                obj.b_pipeIsValid = tf;
            end

            if ~tf
                fprintf('\nPipeline is INVALID.\n');

                nErr = numel(report.errors);
                nShow = min(5, nErr);

                for i = 1:nShow
                    fprintf('  - %s\n', report.errors{i});
                end

                if nErr > nShow
                    fprintf('  ... (%d more errors)\n', nErr - nShow);
                end

                fprintf('Run obj.diagnosePipeline() for full report.\n\n');
            end
        end

        function nodeStatus = buildNodeStatusTable(obj, graphReport, paramReport)
            %BUILDNODESTATUSTABLE Build one node-level diagnostic table.
            %
            %   nodeStatus = obj.buildNodeStatusTable(graphReport, paramReport)
            %   derives GUI-friendly node validity from the same graph and
            %   parameter validation rules used by diagnosePipeline.
            %
            %   Status values:
            %       "valid"               - no node-specific issues detected
            %       "warning"             - non-critical node warning
            %       "invalid_nonblocking" - stale/unused node issue that does
            %                               not block safe execution
            %       "invalid_blocking"    - node blocks safe execution

            if isempty(obj.nodes)
                nodeStatus = table( ...
                    zeros(0,1), strings(0,1), strings(0,1), strings(0,1), ...
                    strings(0,1), strings(0,1), cell(0,1), ...
                    'VariableNames', {'nodeID','stepName','functionName','functionType', ...
                    'status','severity','messages'});
                return
            end

            nNodes = numel(obj.nodes);

            nodeID = zeros(nNodes,1);
            stepName = strings(nNodes,1);
            functionName = strings(nNodes,1);
            functionType = strings(nNodes,1);
            status = repmat("valid", nNodes, 1);
            severity = repmat("none", nNodes, 1);
            messages = cell(nNodes,1);

            for iNode = 1:nNodes
                node = obj.nodes(iNode);

                nodeID(iNode) = node.id;
                stepName(iNode) = string(node.name);
                messages{iNode} = strings(0,1);

                if isfield(node, 'info') && isfield(node.info, 'name') && ~isempty(node.info.name)
                    functionName(iNode) = string(node.info.name);
                elseif isfield(node, 'kind') && strcmpi(node.kind, 'folder')
                    functionName(iNode) = "FileSource";
                else
                    functionName(iNode) = string(node.name);
                end

                try
                    classInfo = obj.classifyFunctionType(node);
                    functionType(iNode) = string(classInfo.role);
                catch
                    functionType(iNode) = "invalid";
                    addNodeMessage(node.id, "blocking", ...
                        sprintf('Could not classify node "%s".', char(string(node.name))));
                end
            end

            nodeIDs = nodeID(:).';

            % -------------------------------------------------------------
            % Non-blocking node hygiene checks
            % -------------------------------------------------------------
            % A disconnected file-source/folder node is stale graph state. It
            % does not block execution because no stream step depends on it, but
            % the GUI should still highlight it so the user can remove it.
            for iNode = 1:nNodes
                node = obj.nodes(iNode);

                if ~isfield(node, 'kind') || ~strcmpi(node.kind, 'folder')
                    continue
                end

                hasOutgoing = false;
                if ~isempty(obj.connections)
                    hasOutgoing = any([obj.connections.sourceNodeID] == node.id);
                end

                if ~hasOutgoing
                    addNodeMessage(node.id, "nonblocking", ...
                        sprintf(['Unused file-source node "%s" has no outgoing DATA connections. ' ...
                        'It can be removed without blocking pipeline execution.'], ...
                        char(string(node.name))));
                end
            end

            % -------------------------------------------------------------
            % Node ID uniqueness
            % -------------------------------------------------------------
            uniqueNodeIDs = unique(nodeIDs, 'stable');
            for iUnique = 1:numel(uniqueNodeIDs)
                if nnz(nodeIDs == uniqueNodeIDs(iUnique)) > 1
                    addNodeMessage(uniqueNodeIDs(iUnique), "blocking", ...
                        sprintf('Duplicate nodeID %d detected.', uniqueNodeIDs(iUnique)));
                end
            end

            % -------------------------------------------------------------
            % Connection-level structural checks
            % -------------------------------------------------------------
            if ~isempty(obj.connections)

                connSig = strings(1, numel(obj.connections));

                for iConn = 1:numel(obj.connections)
                    c = obj.connections(iConn);

                    srcOut = '';
                    dstIn  = '';
                    selFile = '';
                    if isfield(c,'sourceOutputName') && ~isempty(c.sourceOutputName)
                        srcOut = char(string(c.sourceOutputName));
                    end
                    if isfield(c,'targetInputName') && ~isempty(c.targetInputName)
                        dstIn = char(string(c.targetInputName));
                    end
                    if isfield(c,'selectedFile') && ~isempty(c.selectedFile)
                        selFile = char(string(c.selectedFile));
                    end

                    connSig(iConn) = sprintf('%d|%d|%s|%s|%s', ...
                        c.sourceNodeID, c.targetNodeID, lower(strtrim(srcOut)), ...
                        lower(strtrim(dstIn)), lower(strtrim(selFile)));

                    srcExists = ismember(c.sourceNodeID, nodeIDs);
                    dstExists = ismember(c.targetNodeID, nodeIDs);

                    if ~srcExists && dstExists
                        addNodeMessage(c.targetNodeID, "blocking", ...
                            sprintf('Input connection references missing source nodeID %d.', c.sourceNodeID));
                        continue
                    elseif srcExists && ~dstExists
                        addNodeMessage(c.sourceNodeID, "blocking", ...
                            sprintf('Output connection references missing target nodeID %d.', c.targetNodeID));
                        continue
                    elseif ~srcExists && ~dstExists
                        continue
                    end

                    if c.sourceNodeID == c.targetNodeID
                        addNodeMessage(c.sourceNodeID, "blocking", ...
                            sprintf('Self-edge detected on nodeID %d.', c.sourceNodeID));
                        continue
                    end

                    srcIdx = find(nodeIDs == c.sourceNodeID, 1, 'first');
                    dstIdx = find(nodeIDs == c.targetNodeID, 1, 'first');
                    srcNode = obj.nodes(srcIdx);
                    dstNode = obj.nodes(dstIdx);

                    if isfield(dstNode,'kind') && strcmpi(dstNode.kind, 'folder')
                        addNodeMessage(dstNode.id, "blocking", ...
                            sprintf('Folder node "%s" has an incoming edge.', char(string(dstNode.name))));
                        continue
                    end

                    if ~isfield(srcNode,'info') || ~isfield(srcNode.info,'outputs') || isempty(srcNode.info.outputs)
                        addNodeMessage(srcNode.id, "blocking", ...
                            sprintf('Source node "%s" has no output metadata.', char(string(srcNode.name))));
                        continue
                    end

                    srcOutIdx = find(strcmpi({srcNode.info.outputs.name}, c.sourceOutputName), 1, 'first');
                    if isempty(srcOutIdx)
                        addNodeMessage(srcNode.id, "blocking", ...
                            sprintf('Missing source output "%s".', char(string(c.sourceOutputName))));
                        continue
                    end
                    srcOutDef = srcNode.info.outputs(srcOutIdx);

                    if ~isfield(dstNode,'info') || ~isfield(dstNode.info,'inputs') || isempty(dstNode.info.inputs)
                        addNodeMessage(dstNode.id, "blocking", ...
                            sprintf('Target node "%s" has no input metadata.', char(string(dstNode.name))));
                        continue
                    end

                    dstInIdx = find(strcmpi({dstNode.info.inputs.name}, c.targetInputName), 1, 'first');
                    if isempty(dstInIdx)
                        addNodeMessage(dstNode.id, "blocking", ...
                            sprintf('Missing target input "%s".', char(string(c.targetInputName))));
                        continue
                    end
                    dstInDef = dstNode.info.inputs(dstInIdx);

                    srcIsData = isfield(srcOutDef,'isData') && srcOutDef.isData;
                    dstIsData = isfield(dstInDef,'isData') && dstInDef.isData;

                    if ~srcIsData
                        addNodeMessage(srcNode.id, "blocking", ...
                            sprintf('Connection uses non-DATA source output "%s".', char(string(c.sourceOutputName))));
                        continue
                    end
                    if ~dstIsData
                        addNodeMessage(dstNode.id, "blocking", ...
                            sprintf('Connection targets non-DATA input "%s".', char(string(c.targetInputName))));
                        continue
                    end

                    srcTypes = normalizeTypeList(srcOutDef, c, 'sourceOutputType');
                    dstTypes = normalizeTypeList(dstInDef, c, 'targetInputType');

                    if isempty(srcTypes) || isempty(dstTypes)
                        addNodeMessage(srcNode.id, "blocking", ...
                            sprintf('Missing semantic type for output "%s".', char(string(c.sourceOutputName))));
                        addNodeMessage(dstNode.id, "blocking", ...
                            sprintf('Missing semantic type for input "%s".', char(string(c.targetInputName))));
                        continue
                    end

                    srcHasWildcard = any(strcmp(srcTypes,'UnknownDataType'));
                    dstHasWildcard = any(strcmp(dstTypes,'UnknownDataType'));

                    if ~(srcHasWildcard || dstHasWildcard) && isempty(intersect(srcTypes, dstTypes))
                        addNodeMessage(srcNode.id, "blocking", ...
                            sprintf('Semantic type mismatch on output "%s".', char(string(c.sourceOutputName))));
                        addNodeMessage(dstNode.id, "blocking", ...
                            sprintf('Semantic type mismatch on input "%s".', char(string(c.targetInputName))));
                    end
                end

                % Duplicate connection signatures
                [uniqueSig, ~, sigIdx] = unique(connSig); %#ok<ASGLU>
                for iSig = 1:numel(uniqueSig)
                    dupIdx = find(sigIdx == iSig);
                    if numel(dupIdx) <= 1
                        continue
                    end
                    for iDup = 1:numel(dupIdx)
                        c = obj.connections(dupIdx(iDup));
                        if ismember(c.sourceNodeID, nodeIDs)
                            addNodeMessage(c.sourceNodeID, "blocking", 'Duplicate outgoing connection detected.');
                        end
                        if ismember(c.targetNodeID, nodeIDs)
                            addNodeMessage(c.targetNodeID, "blocking", 'Duplicate incoming connection detected.');
                        end
                    end
                end
            end

            % -------------------------------------------------------------
            % Required DATA input checks
            % -------------------------------------------------------------
            for iNode = 1:nNodes
                node = obj.nodes(iNode);

                if ~isfield(node,'kind') || ~strcmpi(node.kind, 'stream')
                    continue
                end
                if ~isfield(node,'info') || ~isfield(node.info,'inputs') || isempty(node.info.inputs)
                    continue
                end

                for iIn = 1:numel(node.info.inputs)
                    inDef = node.info.inputs(iIn);
                    if ~isfield(inDef,'isData') || ~inDef.isData
                        continue
                    end

                    nIncoming = 0;
                    if ~isempty(obj.connections)
                        nIncoming = nnz([obj.connections.targetNodeID] == node.id & ...
                            strcmpi({obj.connections.targetInputName}, char(string(inDef.name))));
                    end

                    if nIncoming == 0
                        addNodeMessage(node.id, "blocking", ...
                            sprintf('Missing required DATA input "%s".', char(string(inDef.name))));
                    elseif nIncoming > 1
                        addNodeMessage(node.id, "blocking", ...
                            sprintf('Multiple connections to DATA input "%s".', char(string(inDef.name))));
                    end
                end
            end

            % -------------------------------------------------------------
            % Parameter checks
            % -------------------------------------------------------------
            for iNode = 1:nNodes
                node = obj.nodes(iNode);

                if ~isfield(node,'kind') || ~strcmpi(node.kind, 'stream')
                    continue
                end
                if ~isfield(node,'info') || ~isfield(node.info,'parameters') || isempty(node.info.parameters)
                    continue
                end

                paramErrors = obj.validateParameterStructArray(node.info.parameters, node.name);
                for iErr = 1:numel(paramErrors)
                    addNodeMessage(node.id, "blocking", paramErrors{iErr});
                end
            end

            % -------------------------------------------------------------
            % Cycle/global fallback. If the graph report contains a cycle/topology
            % error and no specific node was already marked, mark every node.
            % -------------------------------------------------------------
            allGlobalErrors = [graphReport.errors, paramReport.errors];
            for iErr = 1:numel(allGlobalErrors)
                errText = string(allGlobalErrors{iErr});
                if contains(lower(errText), 'cycle') || contains(lower(errText), 'topological')
                    for iNode = 1:nNodes
                        addNodeMessage(nodeID(iNode), "blocking", char(errText));
                    end
                end
            end

            nodeStatus = table( ...
                nodeID, stepName, functionName, functionType, status, severity, messages, ...
                'VariableNames', {'nodeID','stepName','functionName','functionType', ...
                'status','severity','messages'});

            % =============================================================
            % Local helpers
            % =============================================================
            function addNodeMessage(nodeIDLocal, severityLocal, msgLocal)
                idxLocal = find(nodeID == nodeIDLocal, 1, 'first');
                if isempty(idxLocal)
                    return
                end

                msgLocal = string(msgLocal);
                if isempty(messages{idxLocal})
                    messages{idxLocal} = msgLocal(:);
                else
                    messages{idxLocal} = unique([messages{idxLocal}(:); msgLocal(:)], 'stable');
                end

                severity(idxLocal) = maxSeverity(severity(idxLocal), string(severityLocal));
                status(idxLocal) = statusFromSeverity(severity(idxLocal));
            end

            function outSeverity = maxSeverity(a, b)
                levels = ["none", "warning", "nonblocking", "blocking"];
                ia = find(levels == string(a), 1, 'first');
                ib = find(levels == string(b), 1, 'first');
                if isempty(ia); ia = 1; end
                if isempty(ib); ib = 1; end
                outSeverity = levels(max(ia, ib));
            end

            function outStatus = statusFromSeverity(sev)
                switch char(string(sev))
                    case 'none'
                        outStatus = "valid";
                    case 'warning'
                        outStatus = "warning";
                    case 'nonblocking'
                        outStatus = "invalid_nonblocking";
                    otherwise
                        outStatus = "invalid_blocking";
                end
            end

            function typeList = normalizeTypeList(portDef, connDef, fallbackField)
                typeList = {};

                if isfield(portDef,'type') && ~isempty(portDef.type)
                    rawType = portDef.type;
                elseif isfield(connDef, fallbackField) && ~isempty(connDef.(fallbackField))
                    rawType = connDef.(fallbackField);
                else
                    return
                end

                if ischar(rawType) || (isstring(rawType) && isscalar(rawType))
                    typeList = {char(string(rawType))};
                elseif iscell(rawType)
                    typeList = cellfun(@(x) char(string(x)), rawType(:).', 'UniformOutput', false);
                elseif isstring(rawType)
                    typeList = cellstr(rawType(:).');
                end
            end
        end

        function updateNodeRuntimeValidation(obj, nodeStatus)
            %UPDATENODERUNTIMEVALIDATION Cache node diagnostics in runtime state.
            %
            %   The GUI may read nodes(i).runtime.validation, but only
            %   PipelineManager should write it. This cache is refreshed by
            %   diagnosePipeline and autoValidate and is not saved as pipeline
            %   definition metadata.

            if isempty(obj.nodes) || ~istable(nodeStatus) || isempty(nodeStatus)
                return
            end

            for iNode = 1:numel(obj.nodes)
                idxStatus = find(nodeStatus.nodeID == obj.nodes(iNode).id, 1, 'first');

                if isempty(idxStatus)
                    validation = struct( ...
                        'status', "valid", ...
                        'severity', "none", ...
                        'messages', strings(0,1), ...
                        'lastCheckedOn', datetime('now'));
                else
                    msgLocal = strings(0,1);
                    if iscell(nodeStatus.messages)
                        msgLocal = string(nodeStatus.messages{idxStatus});
                        msgLocal = msgLocal(:);
                    end

                    validation = struct( ...
                        'status', string(nodeStatus.status(idxStatus)), ...
                        'severity', string(nodeStatus.severity(idxStatus)), ...
                        'messages', msgLocal, ...
                        'lastCheckedOn', datetime('now'));
                end

                if ~isfield(obj.nodes(iNode), 'runtime') || ~isstruct(obj.nodes(iNode).runtime)
                    obj.nodes(iNode).runtime = struct();
                end

                obj.nodes(iNode).runtime.validation = validation;
            end
        end

        function node = createNodeFromFuncInfo(obj, funcName, info, varargin)
            %CREATENODEFROMFUNCINFO Create a DAG node from pipelineInfo.
            %
            %   NODE = CREATENODEFROMFUNCINFO(OBJ, FUNCNAME, INFO)
            %   NODE = CREATENODEFROMFUNCINFO(OBJ, FUNCNAME, INFO, 'Name', Value, ...)
            %
            %   Creates a standardized node struct from a pipelineInfo schema and
            %   initializes runtime bookkeeping.
            %
            %   The node stores:
            %       - id              Unique node id (auto-assigned)
            %       - name            User-facing step tag (defaults to funcName)
            %       - info            pipelineInfo (parameters include runtime .value)
            %       - kind            'stream' by default (vs. 'folder' for file sources)
            %       - b_save2File      Save flag (default false)
            %       - saveFileName     Output filename (default "")
            %       - pos             Optional layout hint (default [NaN NaN])
            %       - tag             Internal tag string (default "<funcName>_<id>")
            %       - runtime         Execution bookkeeping struct
            %
            %   Name-Value pairs:
            %       Any provided Name must correspond to an existing field of NODE.
            %       Otherwise, an error is thrown. This prevents silent typos and keeps
            %       node schema consistent.
            %
            %   Notes:
            %     - This factory intentionally does not perform graph wiring.
            %     - This factory does not validate semantic compatibility; validation
            %       happens at the PipelineManager level.
            %
            %   Examples:
            %       info = obj.getPipelineInfo('GSR');
            %       n = obj.createNodeFromFuncInfo('GSR', info, 'name','GSR_1');
            %
            %       n = obj.createNodeFromFuncInfo('GSR', info, ...
            %           'b_save2File', true, 'saveFileName', "out.mat");

            % -----------------------------
            % Validate inputs
            % -----------------------------
            funcName = char(string(funcName));
            assert(~isempty(funcName), 'PipelineManager:createNodeFromFuncInfo:InvalidFuncName', ...
                'Invalid function name.');

            assert(isstruct(info), 'PipelineManager:createNodeFromFuncInfo:InvalidInfo', ...
                'Invalid pipelineInfo struct.');

            if mod(numel(varargin), 2) ~= 0
                error('PipelineManager:createNodeFromFuncInfo:BadNameValue', ...
                    'Name-Value arguments must come in pairs.');
            end

            % -----------------------------
            % Allocate unique node ID
            % -----------------------------
            % Prefer obj.nextNodeID if it exists; otherwise fall back to max+1.
            if isprop(obj, 'nextNodeID') && ~isempty(obj.nextNodeID) && isnumeric(obj.nextNodeID)
                nodeID = obj.nextNodeID;
                obj.nextNodeID = obj.nextNodeID + 1;
            else
                if isempty(obj.nodes)
                    nodeID = 1;
                else
                    nodeID = max([obj.nodes.id]) + 1;
                end
            end

            % -----------------------------
            % Initialize parameter runtime values
            % -----------------------------
            if isfield(info, 'parameters') && ~isempty(info.parameters)
                for k = 1:numel(info.parameters)

                    if ~isfield(info.parameters(k), 'default')
                        info.parameters(k).default = [];
                    end

                    % Runtime value field (used by GUI/CLI parameter editing)
                    info.parameters(k).value = info.parameters(k).default;
                end
            end

            % -----------------------------
            % Runtime template
            % -----------------------------
            runtime = struct( ...
                'b_paramsSet', false, ...
                'b_executed',  false, ...
                'lastError',   [], ...
                'startedOn',   [], ...
                'finishedOn',  [] );

            % -----------------------------
            % Construct node (canonical schema)
            % -----------------------------
            node = struct();

            node.id   = nodeID;
            node.name = funcName;     % Will often be overridden by addStep() with stepTag
            node.info = info;
            node.kind = 'stream';     % Default node kind (vs. 'folder')

            % % Save behavior (managed by PipelineManager)
            % node.b_save2File  = false;
            % node.saveFileName = "";

            % Optional layout metadata (for future graph UI)
            node.pos = [NaN NaN];

            % Internal tag (stable-ish debug label; user-facing name is node.name)
            node.tag = string(funcName) + "_" + string(nodeID);

            node.runtime = runtime;

            % -----------------------------
            % Apply Name-Value overrides (strict)
            % -----------------------------
            if ~isempty(varargin)
                allowed = fieldnames(node);

                for ii = 1:2:numel(varargin)
                    key = varargin{ii};
                    val = varargin{ii+1};

                    if isstring(key); key = char(key); end
                    assert(ischar(key) && ~isempty(key), ...
                        'PipelineManager:createNodeFromFuncInfo:InvalidFieldName', ...
                        'Override field name must be a non-empty char/string.');

                    % Strict: must already exist in node schema
                    if ~any(strcmp(key, allowed))
                        error('PipelineManager:createNodeFromFuncInfo:UnknownField', ...
                            'Unknown node field "%s". Allowed fields are: %s', ...
                            key, strjoin(allowed', ', '));
                    end

                    node.(key) = val;
                end
            end
        end

        function selection = promptUserToSelectSource(obj, requiredType, mode, candidates)
            %PROMPTUSERTOSELECTSOURCE  Select data source for an input port.
            %
            %   selection = PROMPTUSERTOSELECTSOURCE(obj, requiredType, mode, candidates)
            %
            %   MODE:
            %       'file'      → select file from folder
            %       'upstream'  → choose upstream stream node output
            %       'both'      → choose between file or upstream
            %
            %   requiredType must be a cell array of char.
            %
            %   OUTPUT STRUCTURE:
            %       selection.type        → 'file' | 'upstream'
            %       selection.nodeID      → (only for upstream)
            %       selection.path        → (only for file)
            %       selection.outputName
            %       selection.typeStr     → cell array of char
            %       selection.category    → 'data' | 'file'

            arguments
                obj
                requiredType
                mode
                candidates = []
            end

            % Determine required category from semantic type
            if any(strcmp(requiredType,'Filename'))
                requiredCategory = 'file';
            else
                requiredCategory = 'data';
            end

            switch lower(mode)

                % =========================================================
                % FILE SELECTION
                % =========================================================
                case 'file'

                    [file, path] = uigetfile('*.*', ...
                        sprintf('Select file (%s)', strjoin(requiredType,'/')), ...
                        obj.SaveFolderList{1});

                    if isequal(file,0)
                        selection = [];
                        return
                    end

                    selection.type        = 'file';
                    selection.nodeID      = [];
                    selection.path        = fullfile(path,file);
                    selection.outputName  = 'data';   % folder nodes expose output 'data'
                    selection.typeStr     = requiredType;
                    selection.category    = requiredCategory;

                    % =========================================================
                    % UPSTREAM SELECTION
                    % =========================================================
                case 'upstream'

                    if isempty(candidates)
                        selection = [];
                        return
                    end

                    for k = 1:numel(candidates)
                        fprintf('%d) Node %d → %s (%s)\n', ...
                            k, ...
                            candidates(k).nodeID, ...
                            candidates(k).outputName, ...
                            strjoin(candidates(k).type,'/'));
                    end

                    idx = input('Select upstream source: ');

                    if isempty(idx) || idx < 1 || idx > numel(candidates)
                        selection = [];
                        return
                    end

                    chosen = candidates(idx);

                    selection.type        = 'upstream';
                    selection.nodeID      = chosen.nodeID;
                    selection.path        = [];
                    selection.outputName  = chosen.outputName;
                    selection.typeStr     = chosen.type;
                    selection.category    = 'data';

                    % =========================================================
                    % BOTH OPTIONS
                    % =========================================================
                case 'both'

                    fprintf('1) Select file from folder\n');
                    fprintf('2) Select upstream node output\n');

                    choice = input('Select option: ');

                    if choice == 1
                        selection = obj.promptUserToSelectSource(requiredType, 'file');
                    elseif choice == 2
                        selection = obj.promptUserToSelectSource(requiredType, 'upstream', candidates);
                    else
                        selection = [];
                    end

                otherwise
                    error('PipelineManager:promptUserToSelectSource:InvalidMode', ...
                        'Unknown mode "%s".', mode);
            end
        end

        function loadPipeLog(obj, SaveFolder)
            %LOADPIPELOG Load per-folder pipeLog table from SaveFolder.
            %
            %   LOADPIPELOG(OBJ, SAVEFOLDER) loads "pipeLog.mat" if it exists and sets
            %   OBJ.folderPipeLog. If missing, initializes an empty table.

            logFile = fullfile(SaveFolder,'pipeLog.mat');

            if ~isfile(logFile)
                obj.folderPipeLog = table();
                return
            end

            S = load(logFile,'pipeLog');

            if ~isfield(S,'pipeLog') || ~istable(S.pipeLog)
                obj.folderPipeLog = table();
                return
            end

            obj.folderPipeLog = S.pipeLog;
        end

        function savePipeLog(obj, SaveFolder)
            %SAVEPIPELOG Save per-folder pipeLog table to SaveFolder.
            %
            %   SAVEPIPELOG(OBJ, SAVEFOLDER) writes OBJ.folderPipeLog to "pipeLog.mat".
            %   Enforces max row limit OBJ.maxLogRows by dropping oldest rows first.

            if ~istable(obj.folderPipeLog)
                obj.folderPipeLog = table();
            end

            if isprop(obj,'maxLogRows') && ~isempty(obj.maxLogRows) && height(obj.folderPipeLog) > obj.maxLogRows
                obj.folderPipeLog(1:height(obj.folderPipeLog) - obj.maxLogRows,:) = [];
            end

            pipeLog = obj.folderPipeLog; %#ok<NASGU>
            save(fullfile(SaveFolder,'pipeLog.mat'),'pipeLog');
        end

        function updatePipeLog(obj, SaveFolder, node, status, varargin)
            %UPDATEPIPELOG Append a step-level entry to per-folder pipeLog and PipelineSummary.
            %
            %   updatePipeLog(obj, SaveFolder, node, status)
            %   updatePipeLog(..., 'inputSource', str)
            %   updatePipeLog(..., 'outputFiles', files)
            %   updatePipeLog(..., 'errMsg', err)
            %   updatePipeLog(..., 'errMsgShort', shortErr)
            %
            % If 'inputSource' is not provided (or empty), it is generated automatically
            % from obj.connections + obj.nodes + obj.dataStore using the format:
            %   "SrcStep:SrcOutput/filename; SrcStep2:SrcOutput/filename2"
            % If a filename is not available in dataStore, the "/filename" part is omitted.
            %
            % If 'outputFiles' is not provided (or empty), it is generated automatically
            % from obj.dataStore for outputs produced by this step using:
            %   - standard outputs: key = "<stepID>:<outputName>"
            %   - legacy file lists: any key starting with "<stepID>:" that has a non-empty fileName
            %
            % Special case:
            %   If status == 'skipped_preloaded' and node.runtime.preloadedData is set,
            %   inputSource defaults to "PRELOADED" and outputFiles defaults to the list of
            %   preloaded filenames (unless user overrides).
            %
            % Error message behavior:
            %   - If errMsg is an MException and errMsgShort is provided, then:
            %       Messages_short = errMsgShort
            %       Messages       = extended getReport(errMsg)
            %   - If errMsg is an MException and errMsgShort is not provided, then:
            %       Messages_short = basic getReport(errMsg)
            %       Messages       = extended getReport(errMsg)
            %   - If errMsg is text, Messages_short uses errMsgShort when provided,
            %     otherwise both message fields use errMsg.
            %   - If errMsg is empty, both message fields default to "No Errors".

            % ---------------------------------------------------------
            % Parse optional inputs
            % ---------------------------------------------------------
            inputSource = '';
            outputFiles = [];
            errMsg      = [];
            errMsgShort = [];

            for i = 1:2:numel(varargin)
                key = lower(char(string(varargin{i})));
                val = varargin{i+1};

                switch key
                    case 'inputsource'
                        inputSource = val;
                    case 'outputfiles'
                        outputFiles = val;
                    case 'errmsg'
                        errMsg = val;
                    case 'errmsgshort'
                        errMsgShort = val;
                    otherwise
                        error('PipelineManager:updatePipeLog:UnknownOption', ...
                            'Unknown option "%s".', char(string(varargin{i})));
                end
            end

            inputSource = char(string(inputSource));

            % ---------------------------------------------------------
            % Default inputSource/outputFiles for preloaded steps (if not provided)
            % runtime.preloadedData.(output) = struct('file',...,'info',...)
            % ---------------------------------------------------------
            if isempty(strtrim(inputSource)) && strcmpi(status,'skipped_preloaded') && ...
                    isfield(node,'runtime') && isfield(node.runtime,'preloadedData') && ...
                    isstruct(node.runtime.preloadedData) && ~isempty(fieldnames(node.runtime.preloadedData))

                inputSource = 'PRELOADED';

                if isempty(outputFiles)
                    flds = fieldnames(node.runtime.preloadedData);
                    files = strings(0,1);

                    for iF = 1:numel(flds)
                        rec = node.runtime.preloadedData.(flds{iF});
                        if isstruct(rec) && isfield(rec,'file') && ~isempty(rec.file)
                            files(end+1,1) = string(rec.file); %#ok<AGROW>
                        end
                    end

                    outputFiles = files;
                end
            end

            % ---------------------------------------------------------
            % Auto-generate inputSource if not provided
            % ---------------------------------------------------------
            if isempty(strtrim(inputSource))
                inputSource = buildInputSourceFromGraph(node.id);
            end

            % ---------------------------------------------------------
            % Auto-generate outputFiles if not provided
            % ---------------------------------------------------------
            if isempty(outputFiles)
                outputFiles = inferOutputFilesFromDataStore(node);
            end

            % ---------------------------------------------------------
            % Normalize outputFiles to char row
            % ---------------------------------------------------------
            if isempty(outputFiles)
                outFilesStr = '';
            elseif iscell(outputFiles)
                outFilesStr = char(strjoin(string(outputFiles), ', '));
            else
                outFilesStr = char(strjoin(string(outputFiles), ', '));
            end

            % ---------------------------------------------------------
            % Normalize error messages
            % ---------------------------------------------------------
            if isa(errMsg,'MException')

                MessageLong = getReport(errMsg,'extended','hyperlinks','off');

                if isempty(errMsgShort)
                    MessageShort = getReport(errMsg,'basic','hyperlinks','off');
                else
                    MessageShort = char(string(errMsgShort));
                end

            elseif isempty(errMsg)

                MessageLong  = 'No Errors';
                MessageShort = 'No Errors';

            else

                MessageLong = char(string(errMsg));

                if isempty(errMsgShort)
                    MessageShort = MessageLong;
                else
                    MessageShort = char(string(errMsgShort));
                end
            end

            % ---------------------------------------------------------
            % Timing fields
            % ---------------------------------------------------------
            startedOn  = [];
            finishedOn = [];
            dur_s      = NaN;

            if isfield(node,'runtime')
                if isfield(node.runtime,'startedOn');  startedOn  = node.runtime.startedOn;  end
                if isfield(node.runtime,'finishedOn'); finishedOn = node.runtime.finishedOn; end
            end

            if ~isempty(startedOn) && ~isempty(finishedOn)
                dur_s = seconds(finishedOn - startedOn);
            end

            % ---------------------------------------------------------
            % Resolve callable FunctionName (best effort)
            % ---------------------------------------------------------
            funcName = "";
            if isfield(node,'tag') && ~isempty(node.tag)
                tagStr = string(node.tag);
                suffix = "_" + string(node.id);
                if contains(tagStr, suffix)
                    funcName = extractBefore(tagStr, suffix);
                end
            end
            if strlength(funcName) == 0
                funcName = string(node.name);
            end

            % ---------------------------------------------------------
            % Build a new log row (folder log does NOT include SaveFolder)
            % ---------------------------------------------------------
            newRow = table( ...
                {char(string(node.name))}, ...
                {char(funcName)}, ...
                node.id, ...
                {status}, ...
                startedOn, ...
                finishedOn, ...
                dur_s, ...
                {inputSource}, ...
                {outFilesStr}, ...
                {MessageShort}, ...
                {MessageLong}, ...
                'VariableNames', { ...
                'NodeTag','FunctionName','NodeID','Status', ...
                'StartedOn','FinishedOn','Duration_s', ...
                'InputSource','OutputFiles', ...
                'Messages_short','Messages'} );

            % ---------------------------------------------------------
            % Append to per-folder pipeLog (in-memory)
            % ---------------------------------------------------------
            obj.folderPipeLog = [obj.folderPipeLog; newRow];

            % Enforce maxLogRows (drop oldest)
            if isprop(obj,'maxLogRows') && ~isempty(obj.maxLogRows) && height(obj.folderPipeLog) > obj.maxLogRows
                obj.folderPipeLog(1:height(obj.folderPipeLog) - obj.maxLogRows,:) = [];
            end

            % ---------------------------------------------------------
            % Append to global PipelineSummary (includes SaveFolder truncated)
            % ---------------------------------------------------------
            if isprop(obj,'SaveFolderList_truncated') && isprop(obj,'SaveFolderList') && ...
                    isprop(obj,'current_saveFolder') && ~isempty(obj.current_saveFolder)

                sf = obj.SaveFolderList_truncated(strcmp(obj.current_saveFolder,obj.SaveFolderList));
                if isempty(sf); sf = {SaveFolder}; end
            else
                sf = {SaveFolder};
            end

            globalRow = addvars(newRow, sf, 'Before','NodeTag', 'NewVariableNames','SaveFolder');
            obj.PipelineSummary = [obj.PipelineSummary; globalRow];

            % ---------------------------------------------------------
            % Persist per-folder log
            % ---------------------------------------------------------
            obj.savePipeLog(SaveFolder);

            % =========================================================
            % Local: build inputSource from connections + dataStore
            % =========================================================
            function srcStr = buildInputSourceFromGraph(dstNodeID)
                srcParts = strings(0,1);

                if isempty(obj.connections)
                    srcStr = '';
                    return
                end

                for iConn = 1:numel(obj.connections)

                    conn = obj.connections(iConn);

                    if conn.targetNodeID ~= dstNodeID
                        continue
                    end

                    srcIdx  = obj.getNodeIndexByID(conn.sourceNodeID);
                    srcName = string(obj.nodes(srcIdx).name);
                    outName = string(conn.sourceOutputName);

                    fileStr = "";
                    if isfield(conn,'selectedFile') && ~isempty(conn.selectedFile)
                        fileStr = string(conn.selectedFile);
                    else
                        keyUsed = makeKeyLocal(conn.sourceNodeID, conn.sourceOutputName);

                        if ~isempty(obj.dataStore) && isa(obj.dataStore,'containers.Map') && obj.dataStore.isKey(keyUsed)
                            rec = obj.dataStore(keyUsed);
                            if isfield(rec,'fileName') && strlength(string(rec.fileName)) > 0
                                [~,fn,ext] = fileparts(char(string(rec.fileName)));
                                fileStr = string(fn) + string(ext);
                            end
                        end
                    end

                    if strlength(fileStr) > 0
                        srcParts(end+1,1) = srcName + ":" + outName + "/" + fileStr; %#ok<AGROW>
                    else
                        srcParts(end+1,1) = srcName + ":" + outName; %#ok<AGROW>
                    end
                end

                if isempty(srcParts)
                    srcStr = '';
                else
                    srcParts = sort(srcParts);
                    srcStr = char(strjoin(srcParts, '; '));
                end
            end

            % =========================================================
            % Local: infer output files from dataStore for this step
            % =========================================================
            function files = inferOutputFilesFromDataStore(nodeLocal)

                files = strings(0,1);

                if isempty(obj.dataStore) || ~isa(obj.dataStore,'containers.Map')
                    return
                end

                if isfield(nodeLocal,'info') && isfield(nodeLocal.info,'outputs') && ~isempty(nodeLocal.info.outputs)
                    for iOut = 1:numel(nodeLocal.info.outputs)
                        outName = string(nodeLocal.info.outputs(iOut).name);
                        key = makeKeyLocal(nodeLocal.id, outName);
                        if obj.dataStore.isKey(key)
                            rec = obj.dataStore(key);
                            if isfield(rec,'fileName') && strlength(string(rec.fileName)) > 0
                                [~,fn,ext] = fileparts(char(string(rec.fileName)));
                                files(end+1,1) = string(fn) + string(ext); %#ok<AGROW>
                            end
                        end
                    end
                end

                prefix = sprintf('%d:', nodeLocal.id);
                allKeys = string(obj.dataStore.keys);
                hit = find(startsWith(allKeys, prefix));

                for iHit = 1:numel(hit)
                    idx = hit(iHit);
                    rec = obj.dataStore(char(allKeys(idx)));
                    if isfield(rec,'fileName') && strlength(string(rec.fileName)) > 0
                        [~,fn,ext] = fileparts(char(string(rec.fileName)));
                        files(end+1,1) = string(fn) + string(ext); %#ok<AGROW>
                    end
                end

                files = unique(files, 'stable');
            end

            function key = makeKeyLocal(stepID, outputName)
                key = sprintf('%d:%s', stepID, char(string(outputName)));
            end
        end

        function logRAMDecision(obj, nodeID, inputName, modeStr, detailStr)
            %LOGRAMDECISION Record RAM decision for a node input (CLI + pipeLog-friendly).
            %
            %   logRAMDecision(obj, nodeID, inputName, modeStr, detailStr)
            %
            % INPUTS:
            %   nodeID     (double) Node id.
            %   inputName  (char/string) Input port name (typically the DATA input).
            %   modeStr    (char/string) One of: 'RAM', 'FILE', 'FILEPREFERRED', 'COOLDOWN'
            %   detailStr  (char/string) Optional short detail (e.g., filename or reason).
            %
            % Notes:
            %   - This function only prints to CLI for now.
            %   - You can later integrate it into updatePipeLog by passing errMsg/messages.

            if nargin < 5
                detailStr = '';
            end

            try
                nodeIdx = obj.getNodeIndexByID(nodeID);
                stepName = char(string(obj.nodes(nodeIdx).name));
            catch
                stepName = sprintf('node%d', nodeID);
            end

            inName = char(string(inputName));
            mStr   = upper(char(string(modeStr)));
            dStr   = char(string(detailStr));

            if isempty(strtrim(dStr))
                fprintf('[RAM] %s | %s | %s\n', stepName, inName, mStr);
            else
                fprintf('[RAM] %s | %s | %s | %s\n', stepName, inName, mStr, dStr);
            end
        end

        %%%%%%--Pipeline Execution ----------------------------------------
        function savedFiles = applyAlwaysSaveLeafPolicyAfterNode(obj, nodeID, saveFolder)
            %APPLYALWAYSSAVELEAFPOLICYAFTERNODE Backward-compatible wrapper.
            %
            %   This legacy method now delegates to the current leaf-output policy.
            %   When obj.b_alwaysSaveLeaf is true, applyLeafOutputPolicyAfterNode
            %   treats the effective policy as 'saveLeaves'.

            savedFiles = obj.applyLeafOutputPolicyAfterNode(nodeID, saveFolder);
        end

        function savedFiles = applyLeafOutputPolicyAfterNode(obj, nodeID, saveFolder)
            %APPLYLEAFOUTPUTPOLICYAFTERNODE Persist final outputs according to policy.
            %
            % This method acts on DATA outputs that are outputMode='data', have no
            % explicit save target, and do not feed another step. Every auto-saved
            % file remains folder-bound in SaveFolder.

            savedFiles = strings(0,1);

            policy = obj.currentLeafOutputPolicy;
            if isempty(policy)
                policy = obj.leafOutputPolicy;
            end
            policy = obj.resolveLeafOutputPolicy(policy);

            if isprop(obj,'b_alwaysSaveLeaf') && obj.b_alwaysSaveLeaf
                policy = 'saveLeaves';
            end

            if any(strcmpi(policy, {'explicit','transient'}))
                return
            end

            nodeIdx = obj.getNodeIndexByID(nodeID);
            node = obj.nodes(nodeIdx);

            if ~isfield(node,'info') || ~isfield(node.info,'outputs') || isempty(node.info.outputs)
                return
            end

            dataOutIdx = [];
            requested  = strings(0,1);

            for iOut = 1:numel(node.info.outputs)

                outDef = node.info.outputs(iOut);

                if ~obj.isManagerSaveableOutput(outDef)
                    continue
                end

                if obj.outputHasDownstreamConsumer(node.id, char(string(outDef.name)))
                    continue
                end

                if ~isempty(obj.normalizeOutputSaveFileNameList(outDef))
                    continue
                end

                switch lower(policy)
                    case 'saveleaves'
                        fName = obj.getPlannedFinalOutputFileName(node.id, outDef.name, "saved_final");
                        if isempty(fName)
                            [fName, ~] = obj.resolveAutoFinalOutputFileName( ...
                                node, outDef, saveFolder, strings(0,1), 'asTemp', false);
                        end
                        reasonOK = ~isempty(fName);

                    case 'viewertemp'
                        if ~obj.isViewerCompatibleOutputCandidate(outDef)
                            reasonOK = false;
                            fName = '';
                        else
                            fName = obj.getPlannedFinalOutputFileName(node.id, outDef.name, "saved_temp");
                            if isempty(fName)
                                [fName, ~] = obj.resolveAutoFinalOutputFileName( ...
                                    node, outDef, saveFolder, strings(0,1), 'asTemp', true);
                            end
                            reasonOK = true;
                        end

                    otherwise
                        reasonOK = false;
                        fName = '';
                end

                if ~reasonOK || isempty(strtrim(fName))
                    continue
                end

                dataOutIdx(end+1,1) = iOut; %#ok<AGROW>
                requested(end+1,1) = string(fName); %#ok<AGROW>
            end

            if isempty(dataOutIdx)
                return
            end

            % Names should already be resolved by getExecutionPlan. This guard is
            % kept as a last line of defense when this method is called outside a
            % normal executePipeline run.
            if isprop(obj,'b_avoidOverwrite') && obj.b_avoidOverwrite
                [fixedNames, ~] = obj.resolveUniqueSaveNames(saveFolder, requested);
            else
                fixedNames = requested;
            end

            overrideFileNames = struct();
            for k = 1:numel(dataOutIdx)
                outName = char(string(node.info.outputs(dataOutIdx(k)).name));
                outFld = matlab.lang.makeValidName(outName);
                overrideFileNames.(outFld) = char(fixedNames(k));
            end

            savedFiles = obj.saveNodeDataOutputs( ...
                node, ...
                saveFolder, ...
                'overrideFileNames', overrideFileNames, ...
                'skipIfAlreadySaved', false, ...
                'updateDataHistoryOnMove', true);

            if ~isempty(savedFiles)
                savedFiles = unique(string(savedFiles(:)), 'stable');
            end
        end



        function validateRamSafeCompatibility(obj)
            %VALIDATERAMSAFECOMPATIBILITY Validate RAM-safe compatibility of the DAG.
            %
            %   VALIDATERAMSAFECOMPATIBILITY(OBJ) checks whether all DATA inputs in
            %   stream nodes are compatible with ramMode='ramsafe'.
            %
            %   In RAM-safe mode, PipelineManager prefers passing filenames instead of
            %   arrays. Any required DATA input with supportsFile==false is considered
            %   incompatible with strict RAM-safe execution.
            %
            %   POLICY:
            %       - 'strict'     : raise an error before execution
            %       - 'bestEffort' : emit a warning before execution; runtime may
            %                        still load such inputs into RAM
            %
            %   NOTES:
            %       - Validation is global to the DAG and is not folder-dependent.
            %       - Folder nodes are ignored.
            %       - Only inputs with isData==true are checked.

            if ~strcmpi(obj.ramMode, 'ramsafe')
                return
            end

            policy = 'strict';
            if isprop(obj,'ramSafePolicy') && ~isempty(obj.ramSafePolicy)
                policy = lower(char(string(obj.ramSafePolicy)));
            end

            isStrict = strcmpi(policy,'strict');

            if isempty(obj.topoOrder)
                obj.updateTopoOrder();
            end

            if isempty(obj.nodes)
                return
            end

            offenders = strings(0,1);

            for iNode = 1:numel(obj.nodes)

                node = obj.nodes(iNode);

                if ~isfield(node,'kind') || ~strcmpi(node.kind,'stream')
                    continue
                end

                if ~isfield(node,'info') || ~isfield(node.info,'inputs') || isempty(node.info.inputs)
                    continue
                end

                nodeTag  = '';
                funcName = '';

                if isfield(node,'name') && ~isempty(node.name)
                    nodeTag = char(string(node.name));
                end
                if isfield(node,'info') && isfield(node.info,'name') && ~isempty(node.info.name)
                    funcName = char(string(node.info.name));
                end

                for iIn = 1:numel(node.info.inputs)

                    inDef = node.info.inputs(iIn);

                    if ~isfield(inDef,'isData') || ~inDef.isData
                        continue
                    end

                    supportsFile = false;
                    if isfield(inDef,'supportsFile')
                        supportsFile = logical(inDef.supportsFile);
                    end

                    if ~supportsFile
                        offenders(end+1,1) = sprintf( ...
                            'node tag="%s" | function="%s" | nodeID=%d | input="%s" | supportsFile=%d', ...
                            nodeTag, funcName, node.id, char(string(inDef.name)), supportsFile); %#ok<AGROW>
                    end
                end
            end

            if isempty(offenders)
                return
            end

            msg = sprintf([ ...
                'RAM-safe mode compatibility check failed.\n' ...
                'The following DATA inputs do not support file input (supportsFile==false):\n' ...
                '  - %s\n\n' ...
                'Actionable options:\n' ...
                '  1) Switch to obj.ramMode = ''auto''\n' ...
                '  2) Keep obj.ramMode = ''ramsafe'' and set obj.ramSafePolicy = ''bestEffort''\n' ...
                '  3) Update the affected analysis function(s) so the input port supports filenames'], ...
                char(strjoin(offenders, newline + "  - ")));

            if isStrict
                error('PipelineManager:RAMSafe:UnsupportedFileInput', '%s', msg);
            else
                warning('PipelineManager:RAMSafe:UnsupportedFileInput', '%s', msg);
            end
        end

        function wasCancelled = runPipelineOnFolder(obj, saveFolder, rawFolder, progressFcn, cancelFcn, folderIndex, numFolders)
            %RUNPIPELINEONFOLDER Execute the current DAG on a single SaveFolder.
            %
            %   RUNPIPELINEONFOLDER(OBJ, SAVEFOLDER, RAWFOLDER) executes the current
            %   pipeline DAG for one target SAVEFOLDER / RAWFOLDER pair.
            %
            %   Responsibilities:
            %       - Initialize per-folder runtime registries
            %       - Compute consumer counts and required steps
            %       - Optionally apply history-based skipping when b_skipSteps is true
            %       - Build a RAM-aware execution order from the required subgraph
            %       - Support per-output preload injection (runtime.preloadedData)
            %       - Build function arguments from pipelineInfo.arguments
            %       - Execute stream steps and register their outputs
            %       - Persist requested DATA outputs to disk
            %       - Update dataHistory and pipeLog
            %       - Skip downstream dependent steps after a failure
            %       - Optionally recover the current in-RAM data before failure
            %       - Cleanup temporary files
            %
            %   Skip / failure behavior:
            %       - If obj.b_skipSteps is true, steps satisfied by cached/preloaded
            %         outputs may be omitted from execution.
            %       - If a step fails during argument resolution, function execution,
            %         output registration, or save-to-file, that step is marked as
            %         failed and its downstream dependent steps are skipped.
            %       - Independent branches continue executing.
            %
            %   Notes:
            %       - obj.topoOrder remains the structural DAG order.
            %       - execOrder is the runtime order used for execution.
            %       - The skipped-step report intentionally uses obj.topoOrder so the
            %         CLI output remains stable and structurally readable.

            wasCancelled = false;

            if nargin < 4
                progressFcn = [];
            end
            if nargin < 5
                cancelFcn = [];
            end
            if nargin < 6 || isempty(folderIndex)
                folderIndex = NaN;
            end
            if nargin < 7 || isempty(numFolders)
                numFolders = numel(obj.SaveFolderList);
            end

            % -------------------------------------------------------------
            % Basic checks
            % -------------------------------------------------------------
            if isempty(obj.topoOrder)
                error('PipelineManager:runPipelineOnFolder:MissingTopoOrder', ...
                    'topoOrder is empty. Call updateTopoOrder() first.');
            end

            if obj.checkExecutionCancelRequested(cancelFcn, progressFcn, 'before folder runtime initialization', ...
                    'folderIndex', folderIndex, ...
                    'numFolders', numFolders, ...
                    'saveFolder', saveFolder, ...
                    'rawFolder', rawFolder)
                wasCancelled = true;
                return
            end

            % -------------------------------------------------------------
            % Initialize per-folder runtime registries
            % -------------------------------------------------------------
            obj.dataStore     = containers.Map('KeyType','char','ValueType','any');
            obj.consumerCount = containers.Map('KeyType','char','ValueType','double');
            obj.tempFiles     = strings(0,1);

            % Precompute consumer counts for DATA edges
            obj.buildConsumerCount();

            % -------------------------------------------------------------
            % Compute required steps
            % -------------------------------------------------------------
            if obj.b_skipSteps
                requiredNodeIDs = obj.computeRequiredNodes();
            else
                requiredNodeIDs = obj.topoOrder(:)';  % Force full pipeline rerun
            end

            % Build runtime execution order on the required subgraph.
            % File-producing setup roots are scheduled before the RAM-aware
            % DATA-processing order so side-effect artifacts such as events.mat
            % are created before downstream steps that may read them from disk.
            execOrder = obj.buildExecutionOrder(requiredNodeIDs);

            % -------------------------------------------------------------
            % CLI: report cache/skip information only when skipping is enabled
            % -------------------------------------------------------------
            if obj.b_skipSteps
                reportCacheAndSkipInfo(requiredNodeIDs);

                if isempty(requiredNodeIDs)
                    fprintf('[CACHE] Nothing to execute: all branches satisfied by cached outputs.\n');
                    obj.cleanupTemps();
                    return
                end
            end

            % -------------------------------------------------------------
            % Failure bookkeeping
            % -------------------------------------------------------------
            failedNodeIDs  = zeros(1,0);
            blockedNodeIDs = zeros(1,0);

            nExecutableSteps = 0;
            for iExecCount = 1:numel(execOrder)
                idxCount = obj.getNodeIndexByID(execOrder(iExecCount));
                if strcmpi(obj.nodes(idxCount).kind, 'stream')
                    nExecutableSteps = nExecutableSteps + 1;
                end
            end
            stepCounter = 0;

            % -------------------------------------------------------------
            % Main execution loop
            % -------------------------------------------------------------
            for ii = 1:numel(execOrder)

                nodeID  = execOrder(ii);
                nodeIdx = obj.getNodeIndexByID(nodeID);
                node    = obj.nodes(nodeIdx);

                [parentIDs, directInputKeys] = getIncomingInfo(nodeID);

                % Folder steps do not execute functions
                if strcmpi(node.kind,'folder')
                    obj.executionTrace(end+1) = nodeID;
                    continue
                end

                stepCounter = stepCounter + 1;

                if obj.checkExecutionCancelRequested(cancelFcn, progressFcn, 'before step', ...
                        'folderIndex', folderIndex, ...
                        'numFolders', numFolders, ...
                        'saveFolder', saveFolder, ...
                        'rawFolder', rawFolder, ...
                        'stepIndex', stepCounter, ...
                        'numSteps', nExecutableSteps, ...
                        'stepID', nodeID, ...
                        'stepTag', node.name, ...
                        'functionName', obj.getCallableFuncName(node))
                    wasCancelled = true;
                    break
                end

                obj.emitExecutionProgress(progressFcn, 'stepStarted', ...
                    'folderIndex', folderIndex, ...
                    'numFolders', numFolders, ...
                    'saveFolder', saveFolder, ...
                    'rawFolder', rawFolder, ...
                    'stepIndex', stepCounter, ...
                    'numSteps', nExecutableSteps, ...
                    'stepID', nodeID, ...
                    'stepTag', node.name, ...
                    'functionName', obj.getCallableFuncName(node), ...
                    'status', 'running', ...
                    'message', sprintf('Running step %d/%d: %s', stepCounter, nExecutableSteps, char(string(node.name))));

                % Runtime bookkeeping
                obj.nodes(nodeIdx).runtime.startedOn = datetime('now');

                % ---------------------------------------------------------
                % 1) Preloaded step (history reuse)
                % ---------------------------------------------------------
                if tryHandlePreloadedStep(nodeID, nodeIdx, node, saveFolder)
                    obj.emitExecutionProgress(progressFcn, 'stepSkipped', ...
                        'folderIndex', folderIndex, ...
                        'numFolders', numFolders, ...
                        'saveFolder', saveFolder, ...
                        'rawFolder', rawFolder, ...
                        'stepIndex', stepCounter, ...
                        'numSteps', nExecutableSteps, ...
                        'stepID', nodeID, ...
                        'stepTag', node.name, ...
                        'functionName', obj.getCallableFuncName(node), ...
                        'status', 'skipped_preloaded', ...
                        'message', sprintf('Step satisfied by existing output: %s', char(string(node.name))));

                    if obj.checkExecutionCancelRequested(cancelFcn, progressFcn, 'after preloaded step', ...
                            'folderIndex', folderIndex, ...
                            'numFolders', numFolders, ...
                            'saveFolder', saveFolder, ...
                            'rawFolder', rawFolder, ...
                            'stepIndex', stepCounter, ...
                            'numSteps', nExecutableSteps, ...
                            'stepID', nodeID, ...
                            'stepTag', node.name, ...
                            'functionName', obj.getCallableFuncName(node))
                        wasCancelled = true;
                        break
                    end
                    continue
                end

                % ---------------------------------------------------------
                % 1b) Skip step if any direct parent failed or was blocked
                % ---------------------------------------------------------
                blockedParents = getBlockedParents(parentIDs, failedNodeIDs, blockedNodeIDs);

                if ~isempty(blockedParents)

                    if ~ismember(nodeID, blockedNodeIDs)
                        blockedNodeIDs(end+1) = nodeID; %#ok<AGROW>
                    end

                    % This step will never consume its direct inputs, so release
                    % consumer reservations for its incoming DATA edges.
                    releaseConsumedInputs(directInputKeys);

                    blockedNames = strings(0,1);
                    for iBP = 1:numel(blockedParents)
                        bpIdx = obj.getNodeIndexByID(blockedParents(iBP));
                        blockedNames(end+1,1) = string(obj.nodes(bpIdx).name); %#ok<AGROW>
                    end

                    if isempty(blockedNames)
                        blockMsg = 'Blocked by failed upstream dependency.';
                    else
                        blockMsg = sprintf('Blocked by failed upstream step(s): %s', ...
                            char(strjoin(blockedNames, ', ')));
                    end

                    obj.nodes(nodeIdx).runtime.b_executed = false;
                    obj.nodes(nodeIdx).runtime.lastError  = [];
                    obj.nodes(nodeIdx).runtime.finishedOn = datetime('now');

                    obj.updatePipeLog(saveFolder, obj.nodes(nodeIdx), ...
                        'skipped_upstream_failed', ...
                        'inputSource', 'N/A', ...
                        'outputFiles', 'N/A', ...
                        'errMsg',      blockMsg);

                    obj.emitExecutionProgress(progressFcn, 'stepSkipped', ...
                        'folderIndex', folderIndex, ...
                        'numFolders', numFolders, ...
                        'saveFolder', saveFolder, ...
                        'rawFolder', rawFolder, ...
                        'stepIndex', stepCounter, ...
                        'numSteps', nExecutableSteps, ...
                        'stepID', nodeID, ...
                        'stepTag', node.name, ...
                        'functionName', obj.getCallableFuncName(node), ...
                        'status', 'skipped_upstream_failed', ...
                        'message', blockMsg);

                    continue
                end

                % ---------------------------------------------------------
                % 2) Build call arguments + execute + register outputs
                %    Failures here are step-local and should not abort
                %    independent branches.
                % ---------------------------------------------------------
                consumedKeys = {};
                createdFiles = strings(0,1);

                try
                    [consumedKeys, createdFiles] = executeAndRegisterStep(node, saveFolder, rawFolder);

                catch ME

                    if strcmp(ME.identifier, 'PipelineManager:ExecutionCancelled')
                        wasCancelled = true;
                        obj.nodes(nodeIdx).runtime.b_executed = false;
                        obj.nodes(nodeIdx).runtime.lastError  = [];
                        obj.nodes(nodeIdx).runtime.finishedOn = datetime('now');
                        break
                    end

                    if ~ismember(nodeID, failedNodeIDs)
                        failedNodeIDs(end+1) = nodeID; %#ok<AGROW>
                    end

                    obj.nodes(nodeIdx).runtime.b_executed = false;
                    obj.nodes(nodeIdx).runtime.lastError  = ME;
                    obj.nodes(nodeIdx).runtime.finishedOn = datetime('now');

                    shortErrMsg = buildShortErrorMessage(ME);

                    obj.updatePipeLog(saveFolder, obj.nodes(nodeIdx), ...
                        'failed', ...
                        'inputSource', 'N/A', ...
                        'outputFiles', 'N/A', ...
                        'errMsg',       ME, ...
                        'errMsgShort',  shortErrMsg);

                    warning('PipelineManager:StepFailed', ...
                        'Step "%s" failed and will be marked as failed. Downstream dependent steps will be skipped. Error: %s', ...
                        char(string(obj.nodes(nodeIdx).name)), ...
                        shortErrMsg);

                    obj.emitExecutionProgress(progressFcn, 'stepFailed', ...
                        'folderIndex', folderIndex, ...
                        'numFolders', numFolders, ...
                        'saveFolder', saveFolder, ...
                        'rawFolder', rawFolder, ...
                        'stepIndex', stepCounter, ...
                        'numSteps', nExecutableSteps, ...
                        'stepID', nodeID, ...
                        'stepTag', node.name, ...
                        'functionName', obj.getCallableFuncName(node), ...
                        'status', 'failed', ...
                        'message', shortErrMsg);

                    % Recovery must happen before consumed inputs are released.
                    [recoveryFiles, recoveryStep, bRecoveryFromTemp] = ...
                        tryRecoverDataBeforeFail(nodeIdx, saveFolder, rawFolder);

                    if ~isempty(recoveryFiles)

                        appendCurrentOutFiles(recoveryFiles);

                        if ~bRecoveryFromTemp
                            for iRecFile = 1:numel(recoveryFiles)
                                appendDataHistoryEntryForStep( ...
                                    recoveryStep, char(string(recoveryFiles(iRecFile))), ...
                                    saveFolder, rawFolder);
                            end
                            obj.saveDataHistory(saveFolder);
                        end

                        warning('PipelineManager:RecoveryFileCreated', ...
                            'Recovery file created after failure in step "%s": %s', ...
                            char(string(obj.nodes(nodeIdx).name)), ...
                            char(strjoin(recoveryFiles, ', ')));
                    end

                    % The step attempted to consume these inputs, so release them only
                    % after any recovery save has been attempted.
                    releaseConsumedInputs(consumedKeys);

                    % Setup steps create folder-level artifacts that later steps may
                    % read implicitly. If one fails, continuing the remaining folder
                    % execution risks using stale or missing artifacts.
                    if obj.isSetupExecutionNode(obj.nodes(nodeIdx))
                        rethrow(ME);
                    end

                    if obj.checkExecutionCancelRequested(cancelFcn, progressFcn, 'after failed step', ...
                            'folderIndex', folderIndex, ...
                            'numFolders', numFolders, ...
                            'saveFolder', saveFolder, ...
                            'rawFolder', rawFolder, ...
                            'stepIndex', stepCounter, ...
                            'numSteps', nExecutableSteps, ...
                            'stepID', nodeID, ...
                            'stepTag', node.name, ...
                            'functionName', obj.getCallableFuncName(node))
                        wasCancelled = true;
                        break
                    end

                    continue
                end

                % Mark step as satisfied in this run BEFORE building nodePath
                obj.executionTrace(end+1) = nodeID;

                % ---------------------------------------------------------
                % Update data history
                % ---------------------------------------------------------
                for indF = 1:numel(createdFiles)
                    appendDataHistoryEntryForStep(node, char(string(createdFiles(indF))), saveFolder, rawFolder);
                    obj.saveDataHistory(saveFolder);
                end

                % ---------------------------------------------------------
                % Finalize successful step
                % ---------------------------------------------------------
                releaseConsumedInputs(consumedKeys);

                obj.nodes(nodeIdx).runtime.b_executed = true;
                obj.nodes(nodeIdx).runtime.finishedOn = datetime('now');

                obj.updatePipeLog(saveFolder, obj.nodes(nodeIdx), 'executed');
                obj.enforceSingleRamValueAfterNode(nodeID, saveFolder);

                leafFiles = obj.applyLeafOutputPolicyAfterNode(nodeID, saveFolder);

                if ~isempty(leafFiles)
                    leafFiles = string(leafFiles(:));
                    leafFiles = unique(leafFiles, 'stable');

                    % Include policy-materialized leaf files in the actual
                    % current-run file report. This is separate from outputPlan,
                    % which is only the pre-execution plan.
                    appendCurrentOutFiles(leafFiles);

                    % Do not duplicate history entries already appended from createdFiles.
                    createdFilesStr = string(createdFiles(:));

                    for iLeaf = 1:numel(leafFiles)
                        if ~any(strcmpi(leafFiles(iLeaf), createdFilesStr))
                            appendDataHistoryEntryForStep(node, char(leafFiles(iLeaf)), saveFolder, rawFolder);
                        end
                    end

                    obj.saveDataHistory(saveFolder);
                end

                obj.tickCooldown(nodeID);

                obj.emitExecutionProgress(progressFcn, 'stepFinished', ...
                    'folderIndex', folderIndex, ...
                    'numFolders', numFolders, ...
                    'saveFolder', saveFolder, ...
                    'rawFolder', rawFolder, ...
                    'stepIndex', stepCounter, ...
                    'numSteps', nExecutableSteps, ...
                    'stepID', nodeID, ...
                    'stepTag', node.name, ...
                    'functionName', obj.getCallableFuncName(node), ...
                    'status', 'completed', ...
                    'message', sprintf('Completed step %d/%d: %s', stepCounter, nExecutableSteps, char(string(node.name))));

                if obj.checkExecutionCancelRequested(cancelFcn, progressFcn, 'after step', ...
                        'folderIndex', folderIndex, ...
                        'numFolders', numFolders, ...
                        'saveFolder', saveFolder, ...
                        'rawFolder', rawFolder, ...
                        'stepIndex', stepCounter, ...
                        'numSteps', nExecutableSteps, ...
                        'stepID', nodeID, ...
                        'stepTag', node.name, ...
                        'functionName', obj.getCallableFuncName(node))
                    wasCancelled = true;
                    break
                end
            end

            % -------------------------------------------------------------
            % Final cleanup
            % -------------------------------------------------------------
            obj.cleanupTemps();

            % =============================================================
            % Local helpers
            % =============================================================

            function reportCacheAndSkipInfo(requiredIDs)
                %REPORTCACHEANDSKIPINFO Print cache hits and skipped-step summary.

                leafIDsLocal = obj.getLeafNodeIDs();

                % Report fully cached branches
                for iLeafMsg = 1:numel(leafIDsLocal)
                    leafIdxMsg  = obj.getNodeIndexByID(leafIDsLocal(iLeafMsg));
                    leafNodeMsg = obj.nodes(leafIdxMsg);

                    if isfield(leafNodeMsg,'runtime') && ...
                            isfield(leafNodeMsg.runtime,'leafCachedFile') && ...
                            ~isempty(leafNodeMsg.runtime.leafCachedFile)

                        if isfield(leafNodeMsg.runtime,'leafCachedNodeIDs') && ...
                                ~isempty(leafNodeMsg.runtime.leafCachedNodeIDs)

                            idsMsg = leafNodeMsg.runtime.leafCachedNodeIDs;
                            nmMsg  = strings(0,1);

                            for iTmp = 1:numel(idsMsg)
                                nmMsg(end+1,1) = string( ...
                                    obj.nodes(obj.getNodeIndexByID(idsMsg(iTmp))).name); %#ok<AGROW>
                            end

                            fprintf('[CACHE] Whole branch satisfied by "%s": %s\n', ...
                                char(string(leafNodeMsg.runtime.leafCachedFile)), ...
                                char(strjoin(nmMsg, ' -> ')));
                        else
                            fprintf('[CACHE] Whole branch satisfied by "%s" at step "%s"\n', ...
                                char(string(leafNodeMsg.runtime.leafCachedFile)), ...
                                char(string(leafNodeMsg.name)));
                        end
                    end
                end

                % Report partially skipped steps
                if isempty(requiredIDs)
                    return
                end

                reqMask = false(1, numel(obj.nodes));
                for iReq = 1:numel(requiredIDs)
                    reqMask(obj.getNodeIndexByID(requiredIDs(iReq))) = true;
                end

                skippedSteps = strings(0,1);

                % Intentionally reported in structural topological order
                for iTopo = 1:numel(obj.topoOrder)
                    nid = obj.topoOrder(iTopo);
                    idx = obj.getNodeIndexByID(nid);

                    if strcmpi(obj.nodes(idx).kind,'stream') && ~reqMask(idx)
                        skippedSteps(end+1,1) = string(obj.nodes(idx).name); %#ok<AGROW>
                    end
                end

                if ~isempty(skippedSteps)
                    fprintf('[CACHE] Skipping %d step(s): %s\n', ...
                        numel(skippedSteps), char(strjoin(skippedSteps, ', ')));
                end
            end

            function [parentIDs, directInputKeys] = getIncomingInfo(stepID)
                %GETINCOMINGINFO Return direct parent step IDs and direct input keys.

                if isempty(obj.connections)
                    parentIDs = [];
                    directInputKeys = {};
                    return
                end

                incomingConns = obj.connections([obj.connections.targetNodeID] == stepID);

                if isempty(incomingConns)
                    parentIDs = [];
                    directInputKeys = {};
                    return
                end

                parentIDs = unique([incomingConns.sourceNodeID], 'stable');

                directInputKeys = cell(0,1);
                for iConn = 1:numel(incomingConns)
                    directInputKeys{end+1,1} = obj.makeKey( ... %#ok<AGROW>
                        incomingConns(iConn).sourceNodeID, ...
                        incomingConns(iConn).sourceOutputName);
                end
                directInputKeys = unique(directInputKeys, 'stable');
            end

            function tfHandled = tryHandlePreloadedStep(stepID, stepIdx, stepNode, saveFolderLocal)
                %TRYHANDLEPRELOADEDSTEP Register preload-backed outputs and skip execution.

                tfHandled = false;

                if ~(obj.b_skipSteps && ...
                        isfield(stepNode,'runtime') && ...
                        isfield(stepNode.runtime,'preloadedData') && ...
                        isstruct(stepNode.runtime.preloadedData) && ...
                        ~isempty(fieldnames(stepNode.runtime.preloadedData)))
                    return
                end

                outConns = obj.connections([obj.connections.sourceNodeID] == stepID);

                for iConn = 1:numel(outConns)

                    srcOutName = char(string(outConns(iConn).sourceOutputName));
                    fld = matlab.lang.makeValidName(srcOutName);

                    % Determine which file satisfies this output
                    if isfield(outConns(iConn),'selectedFile') && ...
                            ~isempty(outConns(iConn).selectedFile)

                        fName = char(string(outConns(iConn).selectedFile));

                    elseif isfield(stepNode.runtime.preloadedData, fld)

                        preRec = stepNode.runtime.preloadedData.(fld);

                        if isstruct(preRec) && isfield(preRec,'file') && ~isempty(preRec.file)
                            fName = char(string(preRec.file));
                        else
                            continue
                        end
                    else
                        continue
                    end

                    fPath = fullfile(saveFolderLocal, fName);
                    if ~isfile(fPath)
                        error('PipelineManager:runPipelineOnFolder:MissingPreloadFile', ...
                            'Preloaded file does not exist: %s', fPath);
                    end

                    key = obj.makeKey(stepID, srcOutName);

                    % Store file reference only (RAM mode handled by resolver)
                    obj.dataStore(key) = struct( ...
                        'ramValue', [], ...
                        'fileName', string(fPath), ...
                        'isTemp',   false, ...
                        'remainingConsumers', obj.getConsumerCount(key) );
                end

                preFlds = fieldnames(stepNode.runtime.preloadedData);
                usedFiles = strings(0,1);

                for iF = 1:numel(preFlds)
                    rec = stepNode.runtime.preloadedData.(preFlds{iF});
                    if isstruct(rec) && isfield(rec,'file') && ~isempty(rec.file)
                        usedFiles(end+1,1) = string(rec.file); %#ok<AGROW>
                    end
                end

                usedFiles = unique(usedFiles,'stable');

                if ~isempty(usedFiles)
                    fprintf('[CACHE] Step "%s" satisfied by preload: %s\n', ...
                        char(string(stepNode.name)), char(strjoin(usedFiles, ', ')));
                end

                obj.nodes(stepIdx).runtime.b_executed = false;
                obj.nodes(stepIdx).runtime.finishedOn = datetime('now');
                obj.executionTrace(end+1) = stepID;

                obj.updatePipeLog(saveFolderLocal, obj.nodes(stepIdx), 'skipped_preloaded');
                obj.enforceSingleRamValueAfterNode(stepID, saveFolderLocal);
                leafFilesLocal = obj.applyLeafOutputPolicyAfterNode(stepID, saveFolderLocal);
                if ~isempty(leafFilesLocal)
                    appendCurrentOutFiles(leafFilesLocal);
                end
                obj.tickCooldown(stepID);

                tfHandled = true;
            end

            function blockedParents = getBlockedParents(parentIDsLocal, failedIDsLocal, blockedIDsLocal)
                %GETBLOCKEDPARENTS Return direct parents that failed or were blocked.

                blockedParents = parentIDsLocal( ...
                    ismember(parentIDsLocal, failedIDsLocal) | ...
                    ismember(parentIDsLocal, blockedIDsLocal));

                blockedParents = unique(blockedParents, 'stable');
            end

            function [consumedKeysLocal, createdFilesLocal] = executeAndRegisterStep(stepNode, saveFolderLocal, rawFolderLocal)
                %EXECUTEANDREGISTERSTEP Resolve inputs, run the function, and register outputs.

                [posArgs, nvArgs, consumedKeysLocal] = obj.resolveAndBuildArguments( ...
                    stepNode, saveFolderLocal, rawFolderLocal, cancelFcn, progressFcn);

                funcName = obj.getCallableFuncName(stepNode);

                if isfield(stepNode.info,'outputs') && ~isempty(stepNode.info.outputs)
                    nOut = numel(unique({stepNode.info.outputs.name}, 'stable'));
                else
                    nOut = 0;
                end

                outCell = cell(1, nOut);
                f = str2func(funcName);

                obj.throwIfExecutionCancelled(cancelFcn, progressFcn, 'before function execution', ...
                    'stepID', stepNode.id, ...
                    'stepTag', stepNode.name, ...
                    'functionName', funcName, ...
                    'message', sprintf('Stop requested before running function "%s".', funcName));

                if nOut == 0
                    f(posArgs{:}, nvArgs{:});
                    outCell = {};
                else
                    if isfield(stepNode.info,'legacyOpts') && stepNode.info.legacyOpts
                        [outCell{:}] = f(posArgs{:});
                    else
                        [outCell{:}] = f(posArgs{:}, nvArgs{:});
                    end
                end

                createdFilesLocal = obj.registerOutputs(stepNode, outCell, saveFolderLocal);
                appendCurrentOutFiles(createdFilesLocal);

                savedFiles = obj.saveNodeDataOutputs(stepNode, saveFolderLocal);
                if ~isempty(savedFiles)
                    createdFilesLocal = [createdFilesLocal; savedFiles];
                    createdFilesLocal = unique(createdFilesLocal, 'stable');
                    appendCurrentOutFiles(savedFiles);
                end
            end

            function shortErrMsg = buildShortErrorMessage(ME)
                %BUILDSHORTERRORMESSAGE Build a concise error message from the first stack frame.

                if ~isempty(ME.stack)
                    failFcn  = string(ME.stack(1).name);
                    failLine = ME.stack(1).line;
                    shortErrMsg = sprintf('%s (Function: %s, Line: %d)', ...
                        ME.message, char(failFcn), failLine);
                else
                    shortErrMsg = ME.message;
                end
            end

            function [recoveryFiles, recoveryStep, bRecoveryFromTemp] = ...
                    tryRecoverDataBeforeFail(failedStepIdx, saveFolderLocal, rawFolderLocal)
                %TRYRECOVERDATABEFOREFAIL Try to save current in-RAM data to a recovery file.

                recoveryFiles = strings(0,1);
                recoveryStep = struct([]);
                bRecoveryFromTemp = false;

                if ~(obj.b_saveDataBeforeFail && ~isempty(obj.dataStore) && isa(obj.dataStore, 'containers.Map'))
                    return
                end

                dsKeys = obj.dataStore.keys;
                recoveryKey = '';
                recoveryRec = [];

                for iKey = 1:numel(dsKeys)
                    keyTmp = char(string(dsKeys{iKey}));
                    recTmp = obj.dataStore(keyTmp);

                    if isfield(recTmp,'ramValue') && ~isempty(recTmp.ramValue)
                        recoveryKey = keyTmp;
                        recoveryRec = recTmp;
                        break
                    end
                end

                if isempty(recoveryKey)
                    return
                end

                tok = regexp(recoveryKey, '^(\d+):(.*)$', 'tokens', 'once');
                if isempty(tok)
                    return
                end

                srcStepID  = str2double(tok{1});
                srcOutName = char(string(tok{2}));
                srcStepIdx = obj.getNodeIndexByID(srcStepID);
                recoveryStep = obj.nodes(srcStepIdx);

                outMatch = [];
                if isfield(recoveryStep,'info') && isfield(recoveryStep.info,'outputs') && ~isempty(recoveryStep.info.outputs)
                    for iOut = 1:numel(recoveryStep.info.outputs)
                        if strcmpi(char(string(recoveryStep.info.outputs(iOut).name)), srcOutName)
                            outMatch = iOut;
                            break
                        end
                    end
                end

                if isempty(outMatch) || ...
                        ~isfield(recoveryStep.info.outputs(outMatch), 'defOutfilename') || ...
                        isempty(recoveryStep.info.outputs(outMatch).defOutfilename)
                    recoveryStep = struct([]);
                    return
                end

                defFile = char(string(recoveryStep.info.outputs(outMatch).defOutfilename));
                [~, baseName, ext] = fileparts(defFile);

                if isempty(ext)
                    ext = '.mat';
                end

                failedStepTag = regexprep(char(string(obj.nodes(failedStepIdx).name)), '[^\w-]', '_');
                recoveryFile = sprintf('%s_recovered_before_%s%s', ...
                    baseName, failedStepTag, ext);

                overrideFileNames = struct();
                outFld = matlab.lang.makeValidName(srcOutName);
                overrideFileNames.(outFld) = recoveryFile;

                bRecoveryFromTemp = isfield(recoveryRec, 'fileName') && ...
                    strlength(string(recoveryRec.fileName)) > 0 && ...
                    isfile(char(string(recoveryRec.fileName))) && ...
                    isfield(recoveryRec, 'isTemp') && logical(recoveryRec.isTemp);

                try
                    recoveryFiles = obj.saveNodeDataOutputs( ...
                        recoveryStep, saveFolderLocal, ...
                        'overrideFileNames',       overrideFileNames, ...
                        'skipIfAlreadySaved',      true, ...
                        'updateDataHistoryOnMove', true);
                catch recoveryME
                    warning('PipelineManager:RecoverySaveFailed', ...
                        'Failed to create recovery file after failure in step "%s". Error: %s', ...
                        char(string(obj.nodes(failedStepIdx).name)), ...
                        recoveryME.message);

                    recoveryFiles = strings(0,1);
                    recoveryStep = struct([]);
                    bRecoveryFromTemp = false;
                end
            end

            function appendDataHistoryEntryForStep(stepNode, fileName, saveFolderLocal, rawFolderLocal)
                %APPENDDATAHISTORYENTRYFORSTEP Create and append one dataHistory entry.

                upNodes = obj.getUpstreamNodes(stepNode.id);
                if ~isempty(upNodes)
                    upIDs = [upNodes.id]';
                else
                    upIDs = [];
                end
                upIDs = unique([upIDs; stepNode.id]);

                traceIDs = obj.executionTrace(:);
                nodePathIDs = traceIDs(ismember(traceIDs, upIDs));
                nodePath = obj.nodes(arrayfun(@obj.getNodeIndexByID, nodePathIDs));

                entry = obj.generateDataHistoryEntry(nodePath, fileName, saveFolderLocal, rawFolderLocal);

                % Prepend provenance if the first nodePath step is satisfied by preload
                if obj.b_skipSteps && numel(nodePathIDs) >= 2

                    firstID = nodePathIDs(1);
                    nextID  = nodePathIDs(2);

                    firstIdx  = obj.getNodeIndexByID(firstID);
                    firstNode = obj.nodes(firstIdx);

                    if isfield(firstNode,'runtime') && ...
                            isfield(firstNode.runtime,'preloadedData') && ...
                            isstruct(firstNode.runtime.preloadedData) && ...
                            ~isempty(fieldnames(firstNode.runtime.preloadedData))

                        connIdx2 = find( ...
                            [obj.connections.sourceNodeID] == firstID & ...
                            [obj.connections.targetNodeID] == nextID, ...
                            1, 'first');

                        if ~isempty(connIdx2)
                            srcOutName2 = char(string(obj.connections(connIdx2).sourceOutputName));
                            fld2 = matlab.lang.makeValidName(srcOutName2);

                            if isfield(firstNode.runtime.preloadedData, fld2)

                                preRec2 = firstNode.runtime.preloadedData.(fld2);

                                if isstruct(preRec2) && isfield(preRec2,'info') && ~isempty(preRec2.info)

                                    preInfo = preRec2.info;

                                    if ~isempty(entry.info) && ~isempty(preInfo)

                                        A = preInfo(end);
                                        B = entry.info(1);

                                        sameStep = isfield(A,'name') && isfield(B,'name') && ...
                                            strcmpi(char(string(A.name)), char(string(B.name))) && ...
                                            isfield(A,'version') && isfield(B,'version') && ...
                                            strcmpi(char(string(A.version)), char(string(B.version))) && ...
                                            isfield(A,'parameters') && isfield(B,'parameters') && ...
                                            isequal(A.parameters, B.parameters);

                                        if sameStep
                                            preInfo(end) = [];
                                        end
                                    end

                                    entry.info = [preInfo; entry.info]; %#ok<AGROW>
                                end
                            end
                        end
                    end
                end

                % Remove older history entries that point to the same overwritten file
                if ~isempty(obj.dataHistory)

                    keepMask = true(size(obj.dataHistory));

                    for iHist = 1:numel(obj.dataHistory)
                        sameFile = isfield(obj.dataHistory(iHist), 'file') && ...
                            strcmpi(char(string(obj.dataHistory(iHist).file)), ...
                            char(string(fileName)));

                        if sameFile
                            keepMask(iHist) = false;
                        end
                    end

                    obj.dataHistory = obj.dataHistory(keepMask);
                end

                % Append fresh provenance for the current on-disk file
                if isempty(obj.dataHistory)
                    obj.dataHistory = entry;
                else
                    obj.dataHistory(end+1) = entry;
                end
            end

            function appendCurrentOutFiles(fileList)
                %APPENDCURRENTOUTFILES Track files created during the current folder run.

                if isempty(fileList)
                    return
                end

                obj.current_outFile = [obj.current_outFile; cellstr(fileList(:))];
                obj.current_outFile = unique(obj.current_outFile, 'stable');
            end

            function releaseConsumedInputs(keys)
                %RELEASECONSUMEDINPUTS Decrement consumer counters for a list of keys.

                for kk = 1:numel(keys)
                    obj.decrementConsumers(keys{kk});
                end
            end
        end

        function tf = isSetupExecutionNode(obj, nodeLocal)
            %ISSETUPEXECUTIONNODE True for setup/artifact-producing steps.
            %
            %   Setup steps are stream nodes that have no DATA input and no DATA
            %   output, but interact with RawFolder/SaveFolder and either declare a
            %   non-DATA file output or declare no outputs at all. They are executed
            %   before the normal RAM-aware DATA-processing schedule because their
            %   folder-level side effects may be read implicitly by later functions.

            classInfo = obj.classifyFunctionType(nodeLocal);
            tf = strcmpi(classInfo.role, 'setup');
        end

        function classInfo = classifyFunctionType(~, nodeLocal)
            %CLASSIFYFUNCTIONTYPE Classify a node from its pipelineInfo shape.
            %
            %   classInfo = CLASSIFYFUNCTIONTYPE(~, nodeLocal) returns a struct used
            %   for execution scheduling, sanity checks, and documentation building.
            %
            %   Roles:
            %       source              - no DATA input, at least one DATA output
            %       transform           - at least one DATA input and DATA output
            %       setup               - no DATA input/output, but folder-level
            %                             setup side effects are likely
            %       export_report_sink  - at least one DATA input, no DATA output
            %       standalone          - no DATA input/output and no folder context
            %       folder_source       - file-source proxy node
            %       invalid             - malformed/non-struct node metadata
            %
            %   Setup classification intentionally does not require declared outputs.
            %   This keeps custom function pipelineInfo compact for folder-level
            %   preparation steps that create files by side effect.

            classInfo = struct( ...
                'role',                'invalid', ...
                'phase',               'invalid', ...
                'hasDataInput',         false, ...
                'hasDataOutput',        false, ...
                'hasFolderInput',       false, ...
                'hasDeclaredOutputs',   false, ...
                'hasNonDataFileOutput', false, ...
                'isExecutionEnforced',  false, ...
                'enforcedOrder',        '', ...
                'reason',              'Malformed node metadata.');

            if ~isstruct(nodeLocal) || ~isscalar(nodeLocal)
                return
            end

            if ~isfield(nodeLocal, 'kind') || isempty(nodeLocal.kind)
                return
            end

            nodeKind = lower(strtrim(char(string(nodeLocal.kind))));

            if strcmpi(nodeKind, 'folder')
                classInfo.role   = 'folder_source';
                classInfo.phase  = 'source';
                classInfo.reason = 'File-source proxy node.';
                return
            end

            if ~strcmpi(nodeKind, 'stream')
                classInfo.role   = 'standalone';
                classInfo.phase  = 'normal';
                classInfo.reason = sprintf('Unsupported node kind "%s".', nodeKind);
                return
            end

            inputs = struct([]);
            outputs = struct([]);

            if isfield(nodeLocal, 'info') && isstruct(nodeLocal.info)
                if isfield(nodeLocal.info, 'inputs') && ~isempty(nodeLocal.info.inputs)
                    inputs = nodeLocal.info.inputs;
                end
                if isfield(nodeLocal.info, 'outputs') && ~isempty(nodeLocal.info.outputs)
                    outputs = nodeLocal.info.outputs;
                end
            end

            hasDataInput = false;
            hasFolderInput = false;

            for iIn = 1:numel(inputs)
                inDef = inputs(iIn);

                if isfield(inDef, 'isData') && ~isempty(inDef.isData) && logical(inDef.isData)
                    hasDataInput = true;
                end

                inName = '';
                if isfield(inDef, 'name') && ~isempty(inDef.name)
                    inName = lower(strtrim(char(string(inDef.name))));
                end

                inTypes = {};
                if isfield(inDef, 'type') && ~isempty(inDef.type)
                    if ischar(inDef.type) || (isstring(inDef.type) && isscalar(inDef.type))
                        inTypes = {char(string(inDef.type))};
                    elseif iscell(inDef.type)
                        inTypes = cellfun(@(x) char(string(x)), inDef.type(:).', 'UniformOutput', false);
                    elseif isstring(inDef.type)
                        inTypes = cellstr(inDef.type(:).');
                    end
                end

                hasFolderInput = hasFolderInput || ...
                    any(strcmpi(inName, {'savefolder','rawfolder'})) || ...
                    any(strcmpi(inTypes, 'SaveFolder')) || ...
                    any(strcmpi(inTypes, 'RawFolder'));
            end

            hasDataOutput = false;
            hasDeclaredOutputs = ~isempty(outputs);
            hasNonDataFileOutput = false;

            for iOut = 1:numel(outputs)
                outDef = outputs(iOut);

                outIsData = false;
                if isfield(outDef, 'isData') && ~isempty(outDef.isData)
                    outIsData = logical(outDef.isData);
                end

                outMode = '';
                if isfield(outDef, 'outputMode') && ~isempty(outDef.outputMode)
                    outMode = lower(strtrim(char(string(outDef.outputMode))));
                end

                hasDataOutput = hasDataOutput || outIsData;
                hasNonDataFileOutput = hasNonDataFileOutput || ...
                    (~outIsData && strcmpi(outMode, 'file'));
            end

            classInfo.hasDataInput         = hasDataInput;
            classInfo.hasDataOutput        = hasDataOutput;
            classInfo.hasFolderInput       = hasFolderInput;
            classInfo.hasDeclaredOutputs   = hasDeclaredOutputs;
            classInfo.hasNonDataFileOutput = hasNonDataFileOutput;

            if ~hasDataInput && hasDataOutput
                classInfo.role   = 'source';
                classInfo.phase  = 'source_first';
                classInfo.reason = ['No DATA input and at least one DATA output; ' ...
                    'treated as a data-import/source step.'];
                return
            end

            if hasDataInput && hasDataOutput
                classInfo.role   = 'transform';
                classInfo.phase  = 'normal';
                classInfo.reason = 'Has DATA input and DATA output.';
                return
            end

            if ~hasDataInput && ~hasDataOutput
                if hasFolderInput && (hasNonDataFileOutput || ~hasDeclaredOutputs)
                    classInfo.role               = 'setup';
                    classInfo.phase              = 'setup_second';
                    classInfo.isExecutionEnforced = true;
                    classInfo.enforcedOrder      = 'Executed before the RAM-aware DATA-processing schedule.';

                    if hasNonDataFileOutput
                        classInfo.reason = ['No DATA input/output, has folder context, ' ...
                            'and declares a non-DATA file output.'];
                    else
                        classInfo.reason = ['No DATA input/output, has folder context, ' ...
                            'and declares no outputs; treated as a folder-level setup side-effect step.'];
                    end
                    return
                end

                classInfo.role   = 'standalone';
                classInfo.phase  = 'normal';
                classInfo.reason = 'No DATA input/output and no folder-level setup signature.';
                return
            end

            % Remaining case: has DATA input but no DATA output.
            classInfo.role                = 'export_report_sink';
            classInfo.phase               = 'terminal';
            classInfo.isExecutionEnforced = true;
            classInfo.enforcedOrder       = ['Terminal step: it is scheduled only after ' ...
                'its upstream DATA input dependencies are satisfied and does not feed downstream DATA branches.'];
            classInfo.reason              = 'Has DATA input but no DATA output.';
        end

        function warnEnforcedExecutionRoles(obj, nodeIDs)
            %WARNENFORCEDEXECUTIONROLES Warn about special execution roles.
            %
            %   WARNENFORCEDEXECUTIONROLES(obj, nodeIDs) emits one warning per setup
            %   or export/report/sink stream node. These roles use enforced execution
            %   semantics rather than only the RAM-aware branch-continuation order.

            if nargin < 2 || isempty(nodeIDs)
                if isempty(obj.nodes)
                    return
                end
                nodeIDs = [obj.nodes.id];
            end

            nodeIDs = nodeIDs(:).';
            nodeIDs = unique(nodeIDs, 'stable');

            for iNode = 1:numel(nodeIDs)
                nid = nodeIDs(iNode);

                if isempty(obj.nodes) || ~ismember(nid, [obj.nodes.id])
                    continue
                end

                nodeIdx = obj.getNodeIndexByID(nid);
                nodeLocal = obj.nodes(nodeIdx);
                classInfo = obj.classifyFunctionType(nodeLocal);

                if ~classInfo.isExecutionEnforced
                    continue
                end

                switch lower(classInfo.role)
                    case 'setup'
                        warning('PipelineManager:ExecutionRole:SetupStep', ...
                            ['Step "%s" was classified as SETUP. Its execution order is enforced: %s\n' ...
                            'Reason: %s'], ...
                            char(string(nodeLocal.name)), ...
                            classInfo.enforcedOrder, ...
                            classInfo.reason);

                    case 'export_report_sink'
                        warning('PipelineManager:ExecutionRole:SinkStep', ...
                            ['Step "%s" was classified as EXPORT/REPORT/SINK. Its execution order is enforced: %s\n' ...
                            'Reason: %s'], ...
                            char(string(nodeLocal.name)), ...
                            classInfo.enforcedOrder, ...
                            classInfo.reason);
                end
            end
        end

        function execOrder = buildExecutionOrder(obj, requiredNodeIDs)
            %BUILDEXECUTIONORDER Build the runtime execution order for the DAG.
            %
            %   execOrder = buildExecutionOrder(obj, requiredNodeIDs)
            %
            %   Returns a deterministic runtime order restricted to REQUIREDNODEIDS.
            %
            %   Scheduling model:
            %       1) DATA source/import stream steps and file-source proxy nodes run
            %          first in creation/topological order. Source/import steps may
            %          initialize SaveFolder by deleting conflicting output files.
            %       2) setup steps run second in creation/topological order. This
            %          prevents setup artifacts such as events.mat from being deleted
            %          by import functions.
            %       3) all remaining nodes, including export/report/sink nodes, are
            %          scheduled by a branch-locality heuristic. Sinks are not delayed
            %          to a global final phase; a terminal sink/report/export runs as
            %          soon as its input branch is ready.
            %
            %   Priority among ready post-setup nodes:
            %       1) continue from the most recently executed node
            %       2) run ready terminal sinks while their input is still hot
            %       3) if the active branch is blocked by a downstream merge, pull
            %          ready sibling prerequisite branches for that merge forward
            %       4) prefer nodes with longer remaining downstream path
            %       5) preserve original topological order as a deterministic tie-breaker
            %
            %   Notes:
            %       - This method does not modify obj.topoOrder.
            %       - RAM/file routing is still handled by the RAM policy methods.
            %       - Scheduling is computed on the induced subgraph defined by
            %         REQUIREDNODEIDS.

            if isempty(obj.nodes)
                execOrder = [];
                return
            end

            if isempty(obj.topoOrder)
                obj.updateTopoOrder();
            end

            if nargin < 2 || isempty(requiredNodeIDs)
                requiredNodeIDs = obj.topoOrder(:).';
            else
                requiredNodeIDs = requiredNodeIDs(:).';
            end

            % Keep only valid node IDs and preserve first occurrence order.
            allNodeIDs = [obj.nodes.id];
            requiredNodeIDs = requiredNodeIDs(ismember(requiredNodeIDs, allNodeIDs));
            requiredNodeIDs = unique(requiredNodeIDs, 'stable');

            if isempty(requiredNodeIDs)
                execOrder = [];
                return
            end

            % -------------------------------------------------------------
            % Fixed early phases.
            % -------------------------------------------------------------
            sourceNodeIDs = zeros(1,0);
            setupNodeIDs  = zeros(1,0);

            for iTopo = 1:numel(obj.topoOrder)
                nid = obj.topoOrder(iTopo);
                if ~ismember(nid, requiredNodeIDs)
                    continue
                end

                nodeIdx = obj.getNodeIndexByID(nid);
                classInfo = obj.classifyFunctionType(obj.nodes(nodeIdx));

                switch lower(classInfo.role)
                    case {'source','folder_source'}
                        sourceNodeIDs(end+1) = nid; %#ok<AGROW>
                    case 'setup'
                        setupNodeIDs(end+1) = nid; %#ok<AGROW>
                end
            end

            earlyNodeIDs = [sourceNodeIDs, setupNodeIDs];
            mainNodeIDs = requiredNodeIDs(~ismember(requiredNodeIDs, earlyNodeIDs));

            if isempty(mainNodeIDs)
                execOrder = earlyNodeIDs;
                return
            end

            nEarly = numel(earlyNodeIDs);
            nReq   = numel(mainNodeIDs);

            % -------------------------------------------------------------
            % Build ID -> position maps.
            % -------------------------------------------------------------
            reqPos  = containers.Map('KeyType','double','ValueType','double');
            topoPos = containers.Map('KeyType','double','ValueType','double');

            for i = 1:nReq
                reqPos(mainNodeIDs(i)) = i;
            end

            for i = 1:numel(obj.topoOrder)
                topoPos(obj.topoOrder(i)) = i;
            end

            % -------------------------------------------------------------
            % Build in-degree, parent, and child adjacency for the post-setup
            % induced subgraph. Edges from early source/setup nodes are ignored
            % because those nodes have already been scheduled.
            % -------------------------------------------------------------
            inDegree = zeros(1, nReq);
            parents  = cell(1, nReq);
            children = cell(1, nReq);

            if ~isempty(obj.connections)
                for iConn = 1:numel(obj.connections)

                    srcID = obj.connections(iConn).sourceNodeID;
                    dstID = obj.connections(iConn).targetNodeID;

                    if ~isKey(reqPos, dstID)
                        continue
                    end

                    % Source/setup/folder-source dependencies are satisfied by the
                    % fixed early phase and should not block the post-setup queue.
                    if ~isKey(reqPos, srcID)
                        continue
                    end

                    srcIdx = reqPos(srcID);
                    dstIdx = reqPos(dstID);

                    inDegree(dstIdx) = inDegree(dstIdx) + 1;
                    parents{dstIdx}(end+1) = srcID; %#ok<AGROW>
                    children{srcIdx}(end+1) = dstID; %#ok<AGROW>
                end
            end

            % -------------------------------------------------------------
            % Classify post-setup nodes and identify merge nodes.
            % -------------------------------------------------------------
            roleByReqIdx = strings(1, nReq);
            isSink       = false(1, nReq);
            isMerge      = false(1, nReq);

            for i = 1:nReq
                nodeIdx = obj.getNodeIndexByID(mainNodeIDs(i));
                classInfo = obj.classifyFunctionType(obj.nodes(nodeIdx));
                roleByReqIdx(i) = string(classInfo.role);
                isSink(i) = strcmpi(classInfo.role, 'export_report_sink');
                isMerge(i) = numel(unique(parents{i}, 'stable')) > 1;
            end

            % -------------------------------------------------------------
            % Precompute depth-to-leaf and downstream merge sets.
            %   depth = 0 for a leaf.
            %   downstreamMerges{i} contains merge node IDs reachable from node i.
            % -------------------------------------------------------------
            depth = zeros(1, nReq);
            downstreamMerges = cell(1, nReq);
            reqTopo = obj.topoOrder(ismember(obj.topoOrder, mainNodeIDs));

            for i = numel(reqTopo):-1:1

                nid  = reqTopo(i);
                nIdx = reqPos(nid);
                kids = children{nIdx};

                mergeSet = zeros(1,0);

                if isempty(kids)
                    depth(nIdx) = 0;
                else
                    kidDepth = zeros(1, numel(kids));

                    for j = 1:numel(kids)
                        kidIdx = reqPos(kids(j));
                        kidDepth(j) = depth(kidIdx);

                        if isMerge(kidIdx)
                            mergeSet(end+1) = kids(j); %#ok<AGROW>
                        end

                        if ~isempty(downstreamMerges{kidIdx})
                            mergeSet = [mergeSet, downstreamMerges{kidIdx}]; %#ok<AGROW>
                        end
                    end

                    depth(nIdx) = 1 + max(kidDepth);
                end

                downstreamMerges{nIdx} = unique(mergeSet, 'stable');
            end

            % -------------------------------------------------------------
            % Priority-based Kahn traversal.
            % -------------------------------------------------------------
            ready = mainNodeIDs(inDegree == 0);
            execOrderMain = zeros(1, nReq);

            nOut = 0;
            lastNodeID = [];

            while ~isempty(ready)

                bestIdx   = 1;
                bestScore = -inf;

                focusMergeIDs = zeros(1,0);
                if ~isempty(lastNodeID) && isKey(reqPos, lastNodeID)
                    focusMergeIDs = downstreamMerges{reqPos(lastNodeID)};
                end

                for i = 1:numel(ready)

                    nid   = ready(i);
                    nIdx  = reqPos(nid);
                    score = 0;

                    parentIDs = parents{nIdx};
                    childIDs  = children{nIdx};

                    % Priority 1: continue consuming the most recently produced data.
                    if ~isempty(lastNodeID) && any(parentIDs == lastNodeID)
                        score = score + 1200;

                        % Terminal report/export/sink should run immediately while
                        % its input is still hot instead of being delayed globally.
                        if isSink(nIdx)
                            score = score + 500;
                        end
                    end

                    % Priority 2: if the active branch is waiting for a downstream
                    % merge, pull sibling prerequisite branches for that same merge
                    % close to the active branch.
                    if ~isempty(focusMergeIDs)
                        candidateMergeIDs = downstreamMerges{nIdx};
                        if isMerge(nIdx)
                            candidateMergeIDs = unique([candidateMergeIDs, nid], 'stable');
                        end

                        if ~isempty(intersect(focusMergeIDs, candidateMergeIDs))
                            score = score + 700;
                        end
                    end

                    % Priority 3: ready merge nodes should run immediately after the
                    % final prerequisite branch becomes available.
                    if isMerge(nIdx)
                        if ~isempty(lastNodeID) && any(parentIDs == lastNodeID)
                            score = score + 900;
                        else
                            score = score + 300;
                        end
                    end

                    % Priority 4: prefer nodes with more downstream work remaining.
                    score = score + 10 * depth(nIdx);

                    % Small preference for nodes that currently have no outgoing DATA
                    % consumers only when they are sinks. This prevents unrelated leaf
                    % transforms from beating branch-continuation work.
                    if isSink(nIdx) && isempty(childIDs)
                        score = score + 20;
                    end

                    % Priority 5: stable tie-break using original topo order.
                    score = score - 1e-6 * topoPos(nid);

                    if score > bestScore
                        bestScore = score;
                        bestIdx   = i;
                    end
                end

                pickID = ready(bestIdx);
                ready(bestIdx) = [];

                nOut = nOut + 1;
                execOrderMain(nOut) = pickID;
                lastNodeID = pickID;

                pickIdx = reqPos(pickID);
                kids = children{pickIdx};

                for j = 1:numel(kids)

                    kidID  = kids(j);
                    kidIdx = reqPos(kidID);

                    inDegree(kidIdx) = inDegree(kidIdx) - 1;

                    if inDegree(kidIdx) == 0
                        ready(end+1) = kidID; %#ok<AGROW>
                    end
                end
            end

            execOrderMain = execOrderMain(1:nOut);

            if nOut ~= nReq
                error('PipelineManager:buildExecutionOrder:InvalidSchedule', ...
                    'Failed to compute a complete execution order.');
            end

            execOrder = [earlyNodeIDs, execOrderMain];

            if numel(execOrder) ~= (nEarly + nReq)
                error('PipelineManager:buildExecutionOrder:InvalidSchedule', ...
                    'Failed to compute a complete execution order.');
            end
        end

        function tf = lookaheadRequiresRAM(obj, dstNodeID)
            %LOOKAHEADREQUIRESRAM Return true if upcoming nodes (on same branch) require RAM input.
            %
            % Uses obj.ramLookaheadLength (L). If L<=0, returns false.
            %
            % Definition (minimal / merge-agnostic):
            %   - Scan forward in topoOrder after dstNodeID.
            %   - Collect the next L stream nodes for which dstNodeID is an ancestor (upstream).
            %   - If any of those nodes has any DATA input with supportsFile==false -> true.

            tf = false;

            if ~isprop(obj,'ramLookaheadLength') || isempty(obj.ramLookaheadLength) || obj.ramLookaheadLength <= 0
                return
            end

            L = double(obj.ramLookaheadLength);

            if isempty(obj.topoOrder)
                return
            end

            idxDst = find(obj.topoOrder == dstNodeID, 1, 'first');
            if isempty(idxDst)
                return
            end

            nFound = 0;

            for iTopo = idxDst+1:numel(obj.topoOrder)

                nid = obj.topoOrder(iTopo);
                nIdx = obj.getNodeIndexByID(nid);
                n = obj.nodes(nIdx);

                if ~isfield(n,'kind') || ~strcmpi(n.kind,'stream')
                    continue
                end

                % Keep only nodes in the same downstream branch of dstNodeID
                if ~isUpstreamAncestor(nid, dstNodeID)
                    continue
                end

                nFound = nFound + 1;

                % If this upcoming node requires RAM anywhere -> true
                if nodeRequiresRAM(n)
                    tf = true;
                    return
                end

                if nFound >= L
                    return
                end
            end

            % ---- local helpers (single nesting level only) ----
            function tf2 = isUpstreamAncestor(nodeID, ancestorID)
                tf2 = false;
                up = obj.getUpstreamNodes(nodeID);
                if isempty(up)
                    return
                end
                tf2 = any([up.id] == ancestorID);
            end

            function tf2 = nodeRequiresRAM(node)
                tf2 = false;

                if ~isfield(node,'info') || ~isfield(node.info,'inputs') || isempty(node.info.inputs)
                    return
                end

                for iIn = 1:numel(node.info.inputs)

                    inDef = node.info.inputs(iIn);

                    if ~isfield(inDef,'isData') || ~inDef.isData
                        continue
                    end

                    supportsFile = false;
                    if isfield(inDef,'supportsFile')
                        supportsFile = logical(inDef.supportsFile);
                    end

                    if ~supportsFile
                        tf2 = true;
                        return
                    end
                end
            end
        end

        function enforceSingleRamValueAfterNode(obj, nodeID, saveFolder)
            %ENFORCESINGLERAMVALUEAFTERNODE Keep only latest-node outputs in RAM.
            %
            %   ENFORCESINGLERAMVALUEAFTERNODE(OBJ, NODEID, SAVEFOLDER) enforces the
            %   auto-mode policy that only DATA outputs produced by the most recently
            %   processed node remain RAM-backed.
            %
            %   POLICY IN AUTO MODE:
            %       - Keep RAM for DATA outputs produced by NODEID.
            %       - For older RAM-backed outputs:
            %           * if still needed downstream, ensure file backing exists
            %             before clearing RAM
            %           * if no longer needed, simply clear RAM
            %
            %   FILE-BACKING RULE:
            %       - If remainingConsumers > 0 and no valid file exists, the method
            %         writes the value either to:
            %           * the user-requested persistent saveFileName, or
            %           * a temporary file
            %       - If a fileName is registered but the file is missing on disk,
            %         a warning is emitted before recovering.
            %
            %   NOTES:
            %       - Only applies when obj.ramMode == 'auto'.
            %       - Does not delete files; it only clears ramValue and ensures that
            %         needed outputs are file-backed.

            if ~strcmpi(obj.ramMode,'auto')
                return
            end

            if isempty(obj.dataStore) || ~isa(obj.dataStore,'containers.Map')
                return
            end

            nodeIdx = obj.getNodeIndexByID(nodeID);
            node    = obj.nodes(nodeIdx);

            % ---------------------------------------------------------
            % Determine keys for DATA outputs of this node (keep RAM)
            % ---------------------------------------------------------
            keepKeys = strings(0,1);

            if isfield(node,'info') && isfield(node.info,'outputs') && ~isempty(node.info.outputs)
                for iOut = 1:numel(node.info.outputs)
                    outDef = node.info.outputs(iOut);
                    if isfield(outDef,'isData') && outDef.isData
                        outName = char(string(outDef.name));
                        keepKeys(end+1,1) = string(obj.makeKey(nodeID, outName)); %#ok<AGROW>
                    end
                end
            end

            % ---------------------------------------------------------
            % Walk dataStore and clear RAM for non-latest records
            % ---------------------------------------------------------
            allKeys = string(obj.dataStore.keys);

            for iKey = 1:numel(allKeys)

                keyStr = allKeys(iKey);

                if any(strcmp(keyStr, keepKeys))
                    continue
                end

                rec = obj.dataStore(char(keyStr));

                if ~isfield(rec,'ramValue') || isempty(rec.ramValue)
                    continue
                end

                % ---------------------------------------------------------
                % If still needed downstream, ensure file backing exists
                % ---------------------------------------------------------
                if isfield(rec,'remainingConsumers') && rec.remainingConsumers > 0

                    hasNamedFile = isfield(rec,'fileName') && strlength(string(rec.fileName)) > 0;
                    hasValidFile = hasNamedFile && isfile(rec.fileName);

                    if hasNamedFile && ~hasValidFile
                        warning('PipelineManager:RAMSpill:MissingBackingFile', ...
                            ['Registered backing file is missing for key "%s".\n' ...
                            'Recorded path: %s\n' ...
                            'Recreating file backing before clearing RAM.'], ...
                            char(keyStr), char(string(rec.fileName)));
                    end

                    if ~hasValidFile

                        % Parse key "<srcNodeID>:<portName>"
                        parts = split(keyStr, ":");
                        if numel(parts) >= 2
                            srcNodeID = str2double(parts(1));
                            portName  = char(join(parts(2:end), ":"));
                        else
                            srcNodeID = nodeID;
                            portName  = 'data';
                        end

                        % Prefer spilling directly to requested persistent saveFileName if defined
                        dstSaveName = resolveRequestedSaveName(srcNodeID, portName);

                        if ~isempty(dstSaveName)
                            dstPath = fullfile(saveFolder, dstSaveName);
                            saveData(dstPath, rec.ramValue);

                            rec.fileName = string(dstPath);
                            rec.isTemp   = false;
                        else
                            tmpFile = obj.writeTempData(rec.ramValue, saveFolder, srcNodeID, portName);
                            rec.fileName = string(tmpFile);
                            rec.isTemp   = true;
                        end
                    end
                end

                % ---------------------------------------------------------
                % Clear RAM value (do not delete file here)
                % ---------------------------------------------------------
                rec.ramValue = [];
                obj.dataStore(char(keyStr)) = rec;
            end

            % =========================================================
            % Local helper: map (srcNodeID, portName) -> saveFileName if set
            % =========================================================
            function fName = resolveRequestedSaveName(srcNodeID, portName)

                fName = '';

                if isempty(srcNodeID) || isnan(srcNodeID)
                    return
                end

                try
                    srcIdx = obj.getNodeIndexByID(srcNodeID);
                catch
                    return
                end

                srcNode = obj.nodes(srcIdx);

                if ~isfield(srcNode,'info') || ~isfield(srcNode.info,'outputs') || isempty(srcNode.info.outputs)
                    return
                end

                outNames = {srcNode.info.outputs.name};
                iOut = find(strcmpi(outNames, portName), 1, 'first');
                if isempty(iOut)
                    return
                end

                outDef = srcNode.info.outputs(iOut);

                saveNameRows = obj.normalizeOutputSaveFileNameList(outDef);
                if isempty(saveNameRows)
                    return
                end

                fName = char(saveNameRows(1));
                fName = strtrim(fName);
            end
        end

        function buildConsumerCount(obj)
            %BUILDCONSUMERCOUNT Count outgoing edges per (sourceNodeID, sourceOutputName).
            % No 'kind' field exists; all connections are assumed data-flow edges.

            if isempty(obj.connections)
                return
            end

            for iConn = 1:numel(obj.connections)
                conn = obj.connections(iConn);
                keyLocal = obj.makeKey(conn.sourceNodeID, conn.sourceOutputName);

                if obj.consumerCount.isKey(keyLocal)
                    obj.consumerCount(keyLocal) = obj.consumerCount(keyLocal) + 1;
                else
                    obj.consumerCount(keyLocal) = 1;
                end
            end
        end

        function req = computeRequiredNodes(obj)
            %COMPUTEREQUIREDNODES Compute nodes required to produce all leaf outputs.
            %
            % Stops upstream traversal only when ALL required output ports of a node
            % are preloaded (runtime.preloadedData has .file for each required port).
            %
            % Full-branch skipping:
            %   If a leaf node has runtime.leafCachedFile set, that leaf is excluded
            %   from traversal (whole branch satisfied).

            leafIDs = obj.getLeafNodeIDs();

            % Exclude fully cached leaves (whole branch satisfied by a file)
            if ~isempty(leafIDs)
                keep = true(size(leafIDs));
                for iLeaf = 1:numel(leafIDs)
                    idx = obj.getNodeIndexByID(leafIDs(iLeaf));
                    if isfield(obj.nodes(idx),'runtime') && ...
                            isfield(obj.nodes(idx).runtime,'leafCachedFile') && ...
                            ~isempty(obj.nodes(idx).runtime.leafCachedFile)
                        keep(iLeaf) = false;
                    end
                end
                leafIDs = leafIDs(keep);
            end

            allIDs = [obj.nodes.id];

            % If all leaves are cached, nothing is required
            if isempty(leafIDs)
                req = [];
                return
            end

            reqSet = false(1, numel(obj.nodes));          % index by node array
            requiredPorts = cell(1, numel(obj.nodes));    % ports required from each node

            for iLeaf2 = 1:numel(leafIDs)
                dfsUpstream(leafIDs(iLeaf2));
            end

            req = allIDs(reqSet);

            % ----- nested-inside-nested preserved (requested) -----
            function dfsUpstream(nid)

                nodeIdx = obj.getNodeIndexByID(nid);
                reqSet(nodeIdx) = true;

                % Guard against empty connection registries with no fields
                if isempty(obj.connections) || ...
                        ~isstruct(obj.connections) || ...
                        ~isfield(obj.connections, 'targetNodeID')
                    return
                end

                parentConns = obj.connections([obj.connections.targetNodeID] == nid);

                if isempty(parentConns)
                    return
                end

                for iConn = 1:numel(parentConns)

                    srcID     = parentConns(iConn).sourceNodeID;
                    srcOutStr = char(string(parentConns(iConn).sourceOutputName));

                    srcIdx = obj.getNodeIndexByID(srcID);
                    requiredPorts{srcIdx}(end+1) = string(srcOutStr); %#ok<AGROW>

                    if isCutPoint(srcIdx)
                        reqSet(srcIdx) = true;
                        continue
                    end

                    dfsUpstream(srcID);
                end
            end

            function tf = isCutPoint(srcIdx)
                % Cut if ALL required output ports for this node are preloaded.

                tf = false;

                ports = requiredPorts{srcIdx};
                if isempty(ports)
                    return
                end

                ports = unique(string(ports), 'stable');

                nodeLocal = obj.nodes(srcIdx);

                if ~isfield(nodeLocal,'runtime') || ...
                        ~isfield(nodeLocal.runtime,'preloadedData') || ...
                        ~isstruct(nodeLocal.runtime.preloadedData)
                    return
                end

                preloadStruct = nodeLocal.runtime.preloadedData;

                for iPort = 1:numel(ports)
                    fld = matlab.lang.makeValidName(char(ports(iPort)));

                    if ~isfield(preloadStruct, fld)
                        return
                    end

                    preRec = preloadStruct.(fld);

                    if ~(isstruct(preRec) && isfield(preRec,'file') && ~isempty(preRec.file))
                        return
                    end
                end

                tf = true;
            end
        end

        function [posArgs, nvArgs, consumedKeys] = resolveAndBuildArguments(obj, node, saveFolder, rawFolder, cancelFcn, progressFcn)
            %RESOLVEANDBUILDARGUMENTS Build positional and name-value args from node.info.arguments.

            posArgs = {};
            nvArgs  = {};
            consumedKeys = {};

            if nargin < 5
                cancelFcn = [];
            end
            if nargin < 6
                progressFcn = [];
            end

            nodeIDLocal = node.id;
            params = obj.buildParamsStruct(node);

            args = node.info.arguments;
            [~, ord] = sort([args.position]);
            args = args(ord);

            for iArg = 1:numel(args)

                arg = args(iArg);
                argName = char(string(arg.name));

                if strcmpi(arg.kind,'input')

                    if isfield(arg,'isData') && arg.isData
                        [val, keyUsed] = obj.resolveDataInputValue(nodeIDLocal, argName, saveFolder, cancelFcn, progressFcn);
                        posArgs{end+1} = val; %#ok<AGROW>
                        if ~isempty(keyUsed)
                            consumedKeys{end+1} = keyUsed; %#ok<AGROW>
                        end

                    else
                        switch lower(argName)
                            case 'savefolder'
                                posArgs{end+1} = saveFolder; %#ok<AGROW>
                            case 'rawfolder'
                                posArgs{end+1} = rawFolder; %#ok<AGROW>
                            case 'metadata'
                                posArgs{end+1} = obj.getMetaData(node,saveFolder); %#ok<AGROW>
                            otherwise
                                warning('Unknown non-data input "%s" for step %s — passing empty.', argName, string(node.id));
                                posArgs{end+1} = []; %#ok<AGROW>
                        end
                    end

                else % parameter

                    if isfield(node.info,'legacyOpts') && node.info.legacyOpts && strcmpi(argName,'opts')
                        posArgs{end+1} = params; %#ok<AGROW>
                        continue
                    end

                    if ~isfield(params, argName)
                        val = [];
                    else
                        val = params.(argName);
                    end

                    if strcmpi(arg.callType,'namevalue')
                        nvArgs(end+1:end+2) = {argName, val};
                    else
                        posArgs{end+1} = val; %#ok<AGROW>
                    end
                end
            end
        end

        function params = buildParamsStruct(obj, nodeLocal) %#ok<INUSL>
            %BUILDPARAMSSTRUCT Build scalar struct of parameters from node.info.parameters.

            params = struct();
            if isfield(nodeLocal.info,'parameters') && ~isempty(nodeLocal.info.parameters)
                for iP = 1:numel(nodeLocal.info.parameters)
                    nm = char(string(nodeLocal.info.parameters(iP).name));
                    if isfield(nodeLocal.info.parameters(iP),'value')
                        params.(nm) = nodeLocal.info.parameters(iP).value;
                    else
                        params.(nm) = nodeLocal.info.parameters(iP).default;
                    end
                end
            end
        end

        function [valOut, keyUsed] = resolveDataInputValue(obj, dstNodeID, dstInputName, saveFolder, cancelFcn, progressFcn)
            %RESOLVEDATAINPUTVALUE Resolve a DATA input value according to RAM policy.
            %
            %   [VALOUT, KEYUSED] = RESOLVEDATAINPUTVALUE(OBJ, DSTNODEID, DSTINPUTNAME, SAVEFOLDER)
            %   resolves the value passed to a DATA input port. Depending on the
            %   active RAM mode and the destination input capabilities, the returned
            %   value is either:
            %       - an in-memory array loaded from disk or reused directly from RAM
            %       - a filename pointing to file-backed data.
            %
            %   INPUTS:
            %       dstNodeID    (double) Target node identifier.
            %       dstInputName (char|string) Target DATA input port name.
            %       saveFolder   (char|string) Current execution SaveFolder.
            %
            %   OUTPUTS:
            %       valOut  Resolved input value (array or filename).
            %       keyUsed Registry key used to access upstream dataStore entry.
            %
            %   BEHAVIOR:
            %       - In 'ramsafe' mode:
            %           * supportsFile==true  -> pass filename
            %           * supportsFile==false -> either error ('strict') or warn and
            %             load into RAM ('bestEffort')
            %       - In 'auto' mode:
            %           * respects explicit file mode requests
            %           * respects explicit RAM mode requests
            %           * forces RAM when the destination cannot accept files
            %           * otherwise selects RAM/file using lookahead and safety test
            %       - Whenever the chosen delivery mode is RAM, an existing upstream
            %         ramValue is reused directly before attempting any file reload.
            %
            %   NOTES:
            %       - Uses queryRAM() to estimate whether file rehydration is safe.
            %       - Updates per-node runtime cooldown/file-preference flags only in
            %         'auto' mode.
            %       - Does not change the pipeline topology or consumer bookkeeping.

            valOut = [];
            keyUsed = '';

            if nargin < 5
                cancelFcn = [];
            end
            if nargin < 6
                progressFcn = [];
            end

            % -------------------------------------------------------------
            % Locate incoming connection for this input
            % -------------------------------------------------------------
            connIdx = find( ...
                [obj.connections.targetNodeID] == dstNodeID & ...
                strcmpi({obj.connections.targetInputName}, char(string(dstInputName))), ...
                1, 'first');

            if isempty(connIdx)
                error('PipelineManager:runPipelineOnFolder:MissingInput', ...
                    'Missing input connection for node %d input "%s".', ...
                    dstNodeID, char(string(dstInputName)));
            end

            conn = obj.connections(connIdx);

            % -------------------------------------------------------------
            % Destination input metadata
            % -------------------------------------------------------------
            dstIdx  = obj.getNodeIndexByID(dstNodeID);
            dstNode = obj.nodes(dstIdx);

            supportsFile = false;
            dataMode     = 'either'; % 'either'|'ram'|'file'

            if isfield(dstNode,'info') && isfield(dstNode.info,'inputs') && ~isempty(dstNode.info.inputs)
                inNames = {dstNode.info.inputs.name};
                iIn = find(strcmpi(inNames, char(string(dstInputName))), 1, 'first');

                if ~isempty(iIn)
                    inDef = dstNode.info.inputs(iIn);

                    if isfield(inDef,'supportsFile')
                        supportsFile = logical(inDef.supportsFile);
                    end

                    if isfield(inDef,'dataMode') && ~isempty(inDef.dataMode)
                        dataMode = lower(strtrim(char(string(inDef.dataMode))));
                    end
                end
            end

            % -------------------------------------------------------------
            % RAM-safe mode
            % -------------------------------------------------------------
            if strcmpi(obj.ramMode,'ramsafe')

                if supportsFile
                    valOut = resolveAsFilename(conn);
                    obj.logRAMDecision(dstNodeID, dstInputName, 'FILE', 'RAM-safe mode');
                    return
                end

                policy = 'strict';
                if isprop(obj,'ramSafePolicy') && ~isempty(obj.ramSafePolicy)
                    policy = lower(strtrim(char(string(obj.ramSafePolicy))));
                end

                if strcmp(policy, 'besteffort')
                    policy = 'best effort';
                elseif strcmp(policy, 'best_effort')
                    policy = 'best effort';
                elseif strcmp(policy, 'best-effort')
                    policy = 'best effort';
                end

                if strcmpi(policy,'strict')
                    fpath = resolveAsFilename(conn);
                    error('PipelineManager:RAMSafe:UnsupportedFileInputRuntime', ...
                        ['RAM-safe strict mode cannot execute node %d ("%s") input "%s" ' ...
                        'because supportsFile=false.\n' ...
                        'Input file resolved to: %s'], ...
                        dstNodeID, char(string(dstNode.name)), char(string(dstInputName)), fpath);
                end

                % Best-effort: prefer already-available RAM before reloading from file
                [hasRamValue, ramValue] = resolveAsRamValue(conn);
                if hasRamValue
                    obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', 'ramsafe-bestEffort: reused existing ramValue');
                    valOut = ramValue;
                    return
                end

                fpath = resolveAsFilename(conn);

                warning('PipelineManager:RAMSafe:BestEffortFallback', ...
                    ['RAM-safe bestEffort fallback for node %d ("%s") input "%s": ' ...
                    'supportsFile=false, loading input into RAM.\n' ...
                    'Resolved file: %s'], ...
                    dstNodeID, char(string(dstNode.name)), char(string(dstInputName)), fpath);

                if ~canLoadFileIntoRAM(fpath)
                    warning('PipelineManager:runPipelineOnFolder:RAMSafetyMarginExceeded', ...
                        ['RAM safety margin test failed for RAM-safe bestEffort fallback.\n' ...
                        'Attempting to load anyway (may trigger out-of-memory).\n' ...
                        'File: %s'], fpath);
                    obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', ['ramsafe-bestEffort (safety failed): ' fpath]);
                else
                    obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', ['ramsafe-bestEffort: ' fpath]);
                end

                try
                    obj.throwIfExecutionCancelled(cancelFcn, progressFcn, 'before loading input file into RAM', ...
                        'stepID', dstNodeID, ...
                        'stepTag', dstNode.name, ...
                        'functionName', obj.getCallableFuncName(dstNode), ...
                        'message', sprintf('Stop requested before loading input "%s" into RAM.', char(string(dstInputName))));
                    valOut = loadData(fpath);
                catch ME
                    if strcmp(ME.identifier, 'PipelineManager:ExecutionCancelled')
                        rethrow(ME);
                    end
                    error('PipelineManager:runPipelineOnFolder:LoadFailed', ...
                        'Failed to load bestEffort RAM-safe input "%s" for node %d. %s', ...
                        char(string(dstInputName)), dstNodeID, ME.message);
                end
                return
            end

            % -------------------------------------------------------------
            % Auto mode: explicit file request
            % -------------------------------------------------------------
            if strcmpi(dataMode,'file') && supportsFile
                valOut = resolveAsFilename(conn);
                obj.logRAMDecision(dstNodeID, dstInputName, 'FILE', 'dataMode=file');
                return
            end

            % -------------------------------------------------------------
            % Auto mode: explicit RAM request
            % -------------------------------------------------------------
            if strcmpi(dataMode,'ram')

                [hasRamValue, ramValue] = resolveAsRamValue(conn);
                if hasRamValue
                    obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', 'dataMode=ram: reused existing ramValue');
                    valOut = ramValue;
                    return
                end

                fpath = resolveAsFilename(conn);

                if ~canLoadFileIntoRAM(fpath)
                    warning('PipelineManager:runPipelineOnFolder:RAMSafetyMarginExceeded', ...
                        ['RAM safety margin test failed for explicit RAM input.\n' ...
                        'Attempting to load anyway (may trigger out-of-memory).\n' ...
                        'File: %s'], fpath);
                    obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', ['dataMode=ram (safety failed): ' fpath]);
                else
                    obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', ['dataMode=ram: ' fpath]);
                end

                try
                    obj.throwIfExecutionCancelled(cancelFcn, progressFcn, 'before loading input file into RAM', ...
                        'stepID', dstNodeID, ...
                        'stepTag', dstNode.name, ...
                        'functionName', obj.getCallableFuncName(dstNode), ...
                        'message', sprintf('Stop requested before loading input "%s" into RAM.', char(string(dstInputName))));
                    valOut = loadData(fpath);
                catch ME
                    if strcmp(ME.identifier, 'PipelineManager:ExecutionCancelled')
                        rethrow(ME);
                    end
                    error('PipelineManager:runPipelineOnFolder:LoadFailed', ...
                        'Failed to load explicit RAM input "%s" for node %d. %s', ...
                        char(string(dstInputName)), dstNodeID, ME.message);
                end
                return
            end

            % -------------------------------------------------------------
            % Auto mode: destination requires RAM
            % -------------------------------------------------------------
            if ~supportsFile

                [hasRamValue, ramValue] = resolveAsRamValue(conn);
                if hasRamValue
                    obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', 'forced: reused existing ramValue');
                    valOut = ramValue;
                    return
                end

                fpath = resolveAsFilename(conn);

                if ~canLoadFileIntoRAM(fpath)
                    warning('PipelineManager:runPipelineOnFolder:RAMSafetyMarginExceeded', ...
                        ['RAM safety margin test failed for required RAM input.\n' ...
                        'Attempting to load anyway (may trigger out-of-memory).\n' ...
                        'File: %s'], fpath);
                    obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', ['forced (safety failed): ' fpath]);
                else
                    obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', ['forced: ' fpath]);
                end

                try
                    obj.throwIfExecutionCancelled(cancelFcn, progressFcn, 'before loading input file into RAM', ...
                        'stepID', dstNodeID, ...
                        'stepTag', dstNode.name, ...
                        'functionName', obj.getCallableFuncName(dstNode), ...
                        'message', sprintf('Stop requested before loading input "%s" into RAM.', char(string(dstInputName))));
                    valOut = loadData(fpath);
                catch ME
                    if strcmp(ME.identifier, 'PipelineManager:ExecutionCancelled')
                        rethrow(ME);
                    end
                    error('PipelineManager:runPipelineOnFolder:LoadFailed', ...
                        'Failed to load required RAM input "%s" for node %d. %s', ...
                        char(string(dstInputName)), dstNodeID, ME.message);
                end
                return
            end

            % -------------------------------------------------------------
            % Initialize runtime flags
            % -------------------------------------------------------------
            if ~isfield(obj.nodes(dstIdx),'runtime') || isempty(obj.nodes(dstIdx).runtime)
                obj.nodes(dstIdx).runtime = struct();
            end
            if ~isfield(obj.nodes(dstIdx).runtime,'cooldownRemaining') || isempty(obj.nodes(dstIdx).runtime.cooldownRemaining)
                obj.nodes(dstIdx).runtime.cooldownRemaining = 0;
            end
            if ~isfield(obj.nodes(dstIdx).runtime,'filePreferred') || isempty(obj.nodes(dstIdx).runtime.filePreferred)
                obj.nodes(dstIdx).runtime.filePreferred = false;
            end

            % -------------------------------------------------------------
            % File-preferred / cooldown gates
            % -------------------------------------------------------------
            if obj.nodes(dstIdx).runtime.filePreferred
                valOut = resolveAsFilename(conn);
                obj.logRAMDecision(dstNodeID, dstInputName, 'FILEPREFERRED', valOut);
                return
            end

            if obj.nodes(dstIdx).runtime.cooldownRemaining > 0
                valOut = resolveAsFilename(conn);
                obj.logRAMDecision(dstNodeID, dstInputName, 'COOLDOWN', valOut);
                return
            end

            % -------------------------------------------------------------
            % Auto mode: lookahead bias
            % -------------------------------------------------------------
            mustLoadForUpcoming = obj.lookaheadRequiresRAM(dstNodeID);

            if mustLoadForUpcoming

                [hasRamValue, ramValue] = resolveAsRamValue(conn);
                if hasRamValue
                    obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', 'lookahead: reused existing ramValue');
                    valOut = ramValue;
                    return
                end

                fpath = resolveAsFilename(conn);

                if ~canLoadFileIntoRAM(fpath)
                    warning('PipelineManager:runPipelineOnFolder:RAMSafetyMarginExceeded', ...
                        ['RAM safety margin test failed, but upcoming steps require RAM.\n' ...
                        'Attempting to load anyway (may trigger out-of-memory).\n' ...
                        'File: %s'], fpath);
                    obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', ['lookahead (safety failed): ' fpath]);
                else
                    obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', ['lookahead: ' fpath]);
                end

                try
                    obj.throwIfExecutionCancelled(cancelFcn, progressFcn, 'before loading input file into RAM', ...
                        'stepID', dstNodeID, ...
                        'stepTag', dstNode.name, ...
                        'functionName', obj.getCallableFuncName(dstNode), ...
                        'message', sprintf('Stop requested before loading input "%s" into RAM.', char(string(dstInputName))));
                    valOut = loadData(fpath);
                catch ME
                    if strcmp(ME.identifier, 'PipelineManager:ExecutionCancelled')
                        rethrow(ME);
                    end
                    error('PipelineManager:runPipelineOnFolder:LoadFailed', ...
                        'Failed to load lookahead-required RAM input "%s" for node %d. %s', ...
                        char(string(dstInputName)), dstNodeID, ME.message);
                end
                return
            end

            % -------------------------------------------------------------
            % Auto mode: choose RAM vs file by safety test
            % -------------------------------------------------------------
            [hasRamValue, ramValue] = resolveAsRamValue(conn);
            if hasRamValue
                obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', 'auto: reused existing ramValue');
                valOut = ramValue;
                return
            end

            fpath = resolveAsFilename(conn);

            if canLoadFileIntoRAM(fpath)
                obj.logRAMDecision(dstNodeID, dstInputName, 'RAM', fpath);

                try
                    obj.throwIfExecutionCancelled(cancelFcn, progressFcn, 'before loading input file into RAM', ...
                        'stepID', dstNodeID, ...
                        'stepTag', dstNode.name, ...
                        'functionName', obj.getCallableFuncName(dstNode), ...
                        'message', sprintf('Stop requested before loading input "%s" into RAM.', char(string(dstInputName))));
                    valOut = loadData(fpath);
                catch ME
                    if strcmp(ME.identifier, 'PipelineManager:ExecutionCancelled')
                        rethrow(ME);
                    end
                    error('PipelineManager:runPipelineOnFolder:LoadFailed', ...
                        'Failed to load auto-selected RAM input "%s" for node %d. %s', ...
                        char(string(dstInputName)), dstNodeID, ME.message);
                end
            else
                obj.nodes(dstIdx).runtime.cooldownRemaining = obj.ramCooldownSteps;
                obj.nodes(dstIdx).runtime.filePreferred     = true;
                obj.logRAMDecision(dstNodeID, dstInputName, 'FILE', ['safety fallback: ' fpath]);
                valOut = fpath;
            end

            % =========================
            % Local helpers
            % =========================
            function [tf, ramValue2] = resolveAsRamValue(connLocal)
                %RESOLVEASRAMVALUE Return existing upstream RAM value if available.
                %
                %   [TF, RAMVALUE2] = RESOLVEASRAMVALUE(CONNLOCAL) returns TF=true only
                %   when the upstream dataStore record exists and has a non-empty
                %   ramValue already available.

                tf = false;
                ramValue2 = [];

                keyUsed = obj.makeKey(connLocal.sourceNodeID, connLocal.sourceOutputName);

                if isempty(obj.dataStore) || ~isa(obj.dataStore,'containers.Map') || ~obj.dataStore.isKey(keyUsed)
                    return
                end

                rec = obj.dataStore(keyUsed);

                if isstruct(rec) && isfield(rec,'ramValue') && ~isempty(rec.ramValue)
                    tf = true;
                    ramValue2 = rec.ramValue;
                end
            end

            function fpath2 = resolveAsFilename(connLocal)

                % Priority 1: explicit selected file
                if isfield(connLocal,'selectedFile') && ~isempty(connLocal.selectedFile)
                    fpath2 = fullfile(saveFolder, char(string(connLocal.selectedFile)));
                    if ~isfile(fpath2)
                        error('PipelineManager:runPipelineOnFolder:MissingSelectedFile', ...
                            'Selected input file does not exist: %s', fpath2);
                    end
                    return
                end

                % Priority 2: dataStore record
                keyUsed = obj.makeKey(connLocal.sourceNodeID, connLocal.sourceOutputName);

                if isempty(obj.dataStore) || ~isa(obj.dataStore,'containers.Map') || ~obj.dataStore.isKey(keyUsed)
                    error('PipelineManager:runPipelineOnFolder:MissingUpstreamData', ...
                        'Upstream data not available for key "%s".', keyUsed);
                end

                rec = obj.dataStore(keyUsed);

                if isfield(rec,'fileName') && strlength(string(rec.fileName)) > 0 && isfile(rec.fileName)
                    fpath2 = char(string(rec.fileName));
                    return
                end

                if isfield(rec,'fileName') && strlength(string(rec.fileName)) > 0 && ~isfile(rec.fileName)
                    warning('PipelineManager:runPipelineOnFolder:MissingBackingFile', ...
                        ['Data record for key "%s" points to a missing file.\n' ...
                        'Recorded path: %s\n' ...
                        'Attempting to recreate file backing from RAM value.'], ...
                        keyUsed, char(string(rec.fileName)));
                end

                % Spill RAM value to temp so we can return a filename
                if isfield(rec,'ramValue') && ~isempty(rec.ramValue)
                    obj.throwIfExecutionCancelled(cancelFcn, progressFcn, 'before spilling RAM value to temporary file', ...
                        'stepID', dstNodeID, ...
                        'stepTag', dstNode.name, ...
                        'functionName', obj.getCallableFuncName(dstNode), ...
                        'message', sprintf('Stop requested before preparing file input "%s".', char(string(dstInputName))));
                    tmp = obj.writeTempData(rec.ramValue, saveFolder, connLocal.sourceNodeID, char(string(connLocal.sourceOutputName)));
                    rec.fileName = string(tmp);
                    rec.isTemp   = true;
                    obj.dataStore(keyUsed) = rec;
                    fpath2 = char(string(tmp));
                    return
                end

                error('PipelineManager:runPipelineOnFolder:InvalidDataRecord', ...
                    'No valid fileName (and no RAM value) for key "%s".', keyUsed);
            end

            function tf = canLoadFileIntoRAM(fpathLocal)
                d = dir(fpathLocal);
                if isempty(d)
                    tf = false;
                    return
                end

                dataBytes = double(d.bytes);

                [availBytes, ~] = queryRAM();

                if isempty(availBytes) || ~isfinite(double(availBytes)) || double(availBytes) <= 0
                    tf = true;
                    return
                end

                availBytes = double(availBytes);
                requiredBytes = dataBytes * double(obj.ramSafetyDataMultiplier) + ...
                    double(obj.ramSafetyOverheadPct) * availBytes;

                tf = availBytes >= requiredBytes;
            end
        end

        function createdFiles = registerOutputs(obj, nodeLocal, outCell, folder)
            %REGISTEROUTPUTS Register outputs in obj.dataStore and return created filenames.
            %
            %   CREATEDFILES = REGISTEROUTPUTS(OBJ, NODELOCAL, OUTCELL, FOLDER)
            %   registers pipeline-relevant outputs produced by NODELOCAL.
            %
            %   Compatibility policy for metaData:
            %       - Outputs named "metaData" are ignored.
            %       - A warning is raised once per call when such outputs are present.
            %       - Ignored metaData outputs are not stored in dataStore, not treated
            %         as created files, and do not participate in manager-side saving.
            %
            %   Legacy outFile behavior:
            %       - If the node is legacy and has an "outFile" output, the concrete
            %         filename list is read from the corresponding output position in
            %         OUTCELL (not from outCell{:}).
            %       - Each created file is registered in dataStore using a filename-based
            %         key for backward compatibility.
            %
            %   Modern output contract:
            %       - outputMode = 'data' -> function returns data in RAM or one
            %                                existing backing filename
            %       - outputMode = 'file' -> function returns filename(s) that already
            %                                exist on disk
            %
            %   For outputMode = 'file':
            %       - The returned value must be text-like (char/string/cellstr)
            %       - Relative filenames are resolved against FOLDER
            %       - Returned files must exist after function execution
            %       - The primary output key remains <nodeID>:<outputName>
            %       - Compatibility keys <nodeID>:<filename.ext> are also registered so
            %         selectedFile-based flows can resolve concrete file identities

            createdFiles = strings(0,1);

            if ~isfield(nodeLocal.info,'outputs') || isempty(nodeLocal.info.outputs)
                return
            end

            nodeIDLocal  = nodeLocal.id;
            outputsLocal = nodeLocal.info.outputs;

            % ---------------------------------------------------------
            % Compatibility: ignore metaData outputs with warning
            % ---------------------------------------------------------
            metaMask = strcmpi({outputsLocal.name}, 'metaData');
            if any(metaMask)
                warning('PipelineManager:registerOutputs:IgnoredMetaDataOutput', ...
                    ['Output "metaData" from node "%s" is ignored by PipelineManager ' ...
                    'for backward compatibility.'], ...
                    char(string(nodeLocal.name)));
            end

            % ---------------------------------------------------------
            % Case A: Legacy outFile list (ONLY if present)
            % ---------------------------------------------------------
            if isfield(nodeLocal.info,'legacyOpts') && nodeLocal.info.legacyOpts

                outFileIdx = find(strcmpi({outputsLocal.name}, 'outFile'), 1, 'first');

                if ~isempty(outFileIdx)

                    if outFileIdx > numel(outCell)
                        warning('PipelineManager:registerOutputs:MissingLegacyOutFileValue', ...
                            ['Legacy node "%s" declares output "outFile" at position %d, ' ...
                            'but OUTCELL contains only %d value(s).'], ...
                            char(string(nodeLocal.name)), outFileIdx, numel(outCell));
                        return
                    end

                    fileList = outCell{outFileIdx};

                    if ischar(fileList) || isstring(fileList)
                        fileList = string(fileList);
                    elseif iscell(fileList)
                        fileList = string(fileList(:));
                    else
                        warning('PipelineManager:registerOutputs:InvalidLegacyOutFileValue', ...
                            ['Legacy node "%s" returned a non-text value for output "outFile". ' ...
                            'No files were registered.'], ...
                            char(string(nodeLocal.name)));
                        return
                    end

                    fileList = fileList(:);

                    for iF = 1:numel(fileList)
                        fName = strtrim(fileList(iF));
                        if strlength(fName) == 0
                            continue
                        end

                        [fullFn, folderBoundName] = localResolveReturnedFile(folder, fName);

                        rec = struct( ...
                            'ramValue', [], ...
                            'fileName', string(fullFn), ...
                            'isTemp', false, ...
                            'remainingConsumers', 0);

                        % Legacy compatibility: key by filename
                        keyCompat = obj.makeKey(nodeIDLocal, char(folderBoundName));
                        obj.dataStore(keyCompat) = rec;

                        createdFiles(end+1,1) = folderBoundName; %#ok<AGROW>
                    end

                    if ~isempty(createdFiles)
                        createdFiles = unique(createdFiles,'stable');
                    end

                    return
                end
                % IMPORTANT: if legacyOpts==true but no outFile output, DO NOT return.
                % Fall through to standard outputs below.
            end

            % ---------------------------------------------------------
            % Case B: Standard outputs
            % ---------------------------------------------------------
            n = min(numel(outputsLocal), numel(outCell));

            for iOut = 1:n

                outDef = outputsLocal(iOut);

                % Ignore legacy compatibility metadata outputs
                if strcmpi(char(string(outDef.name)), 'metaData')
                    continue
                end

                outputModeLocal = 'data';
                if isfield(outDef,'outputMode') && ~isempty(outDef.outputMode)
                    outputModeLocal = lower(strtrim(char(string(outDef.outputMode))));
                end

                isDataOutputLocal = isfield(outDef,'isData') && ~isempty(outDef.isData) && logical(outDef.isData);

                % Non-DATA file outputs are folder-level artifacts. Register them
                % so setup steps such as getEvents are logged and can contribute
                % dataHistory entries, but continue to ignore non-DATA non-file
                % outputs.
                if ~isDataOutputLocal && ~strcmpi(outputModeLocal, 'file')
                    continue
                end

                outName = char(string(outDef.name));
                key     = obj.makeKey(nodeIDLocal, outName);
                val     = outCell{iOut};

                rec = struct( ...
                    'ramValue', [], ...
                    'fileName', "", ...
                    'isTemp',   false, ...
                    'remainingConsumers', obj.getConsumerCount(key) );

                % =====================================================
                % Modern file-producing outputs
                % =====================================================
                if strcmpi(outputModeLocal, 'file')

                    fileList = localNormalizeReturnedFileList(val, nodeLocal, outName);
                    if isempty(fileList)
                        error('PipelineManager:registerOutputs:MissingFileOutput', ...
                            ['Node "%s" output "%s" has outputMode="file" but returned no filename.\n' ...
                            'File outputs must return filename(s).'], ...
                            char(string(nodeLocal.name)), outName);
                    end

                    primarySet = false;

                    for iF = 1:numel(fileList)

                        [fullFn, folderBoundName] = localResolveReturnedFile(folder, fileList(iF));

                        % Primary key for the output port: keep first concrete file
                        if ~primarySet
                            rec.fileName = string(fullFn);
                            rec.isTemp   = false;
                            obj.dataStore(key) = rec;
                            primarySet = true;
                        end

                        % Compatibility key by concrete filename
                        keyCompat = obj.makeKey(nodeIDLocal, char(folderBoundName));
                        recCompat = struct( ...
                            'ramValue', [], ...
                            'fileName', string(fullFn), ...
                            'isTemp',   false, ...
                            'remainingConsumers', 0);

                        obj.dataStore(keyCompat) = recCompat;
                        createdFiles(end+1,1) = folderBoundName; %#ok<AGROW>
                    end

                    continue
                end

                % =====================================================
                % File-backed representation of a logical data output
                % =====================================================
                if ischar(val) || isstring(val) || iscell(val)
                    fileList = localNormalizeReturnedFileList( ...
                        val, nodeLocal, outName);
                    if numel(fileList) ~= 1
                        error('PipelineManager:registerOutputs:InvalidDataFileManifest', ...
                            ['Node "%s" output "%s" returned %d backing files.\n' ...
                            'A logical data output must resolve to exactly one file.'], ...
                            char(string(nodeLocal.name)), outName, numel(fileList));
                    end

                    [fullFn, folderBoundName] = localResolveReturnedFile( ...
                        folder, fileList(1));
                    rec.fileName = string(fullFn);
                    obj.dataStore(key) = rec;

                    keyCompat = obj.makeKey(nodeIDLocal, char(folderBoundName));
                    recCompat = rec;
                    recCompat.remainingConsumers = 0;
                    obj.dataStore(keyCompat) = recCompat;
                    createdFiles(end+1,1) = folderBoundName; %#ok<AGROW>
                    continue
                end

                % =====================================================
                % Modern manager-owned data outputs
                % =====================================================
                if strcmpi(obj.ramMode,'ramsafe')

                    if isnumeric(val) || islogical(val)
                        tmpFile = obj.writeTempData(val, folder, nodeIDLocal, outName);
                        rec.ramValue = [];
                        rec.fileName = string(tmpFile);
                        rec.isTemp   = true;

                        [~,fn,ext] = fileparts(char(string(tmpFile)));
                        createdFiles(end+1,1) = string(fn) + string(ext); %#ok<AGROW>

                    else
                        rec.ramValue = val;
                    end

                    obj.dataStore(key) = rec;
                    continue
                end

                % Auto mode
                if isnumeric(val) || islogical(val)

                    rec.ramValue = val;

                    if obj.getConsumerCount(key) >= 2
                        tmpFile = obj.writeTempData(val, folder, nodeIDLocal, outName);
                        rec.fileName = string(tmpFile);
                        rec.isTemp   = true;

                        [~,fn,ext] = fileparts(char(string(tmpFile)));
                        createdFiles(end+1,1) = string(fn) + string(ext); %#ok<AGROW>
                    end

                else
                    rec.ramValue = val;
                end

                obj.dataStore(key) = rec;
            end

            if ~isempty(createdFiles)
                createdFiles = unique(createdFiles,'stable');
            end

            % =========================================================
            % Local helpers
            % =========================================================
            function fileListOut = localNormalizeReturnedFileList(valIn, nodeIn, outNameIn)
                %LOCALNORMALIZERETURNEDFILELIST Normalize returned filename(s) to string column.

                if ischar(valIn) || (isstring(valIn) && isscalar(valIn))
                    fileListOut = string(valIn);

                elseif isstring(valIn)
                    fileListOut = valIn(:);

                elseif iscell(valIn)
                    try
                        fileListOut = string(valIn(:));
                    catch
                        error('PipelineManager:registerOutputs:InvalidFileOutput', ...
                            ['Node "%s" output "%s" returned an invalid file list.\n' ...
                            'File-backed outputs must return filename(s).'], ...
                            char(string(nodeIn.name)), outNameIn);
                    end

                else
                    error('PipelineManager:registerOutputs:InvalidFileOutput', ...
                        ['Node "%s" output "%s" returned a non-text file value.\n' ...
                        'File-backed outputs must return filename(s).'], ...
                        char(string(nodeIn.name)), outNameIn);
                end

                fileListOut = strip(fileListOut(:));
                fileListOut = fileListOut(strlength(fileListOut) > 0);
            end

            function [fullPathOut, folderBoundNameOut] = localResolveReturnedFile(folderIn, fileTokenIn)
                %LOCALRESOLVERETURNEDFILE Resolve returned filename to concrete full path.
                %
                % Relative filenames are resolved against the current execution folder.
                % Returned files must already exist on disk.

                fileTokenChar = char(string(fileTokenIn));

                if isfile(fileTokenChar)
                    fullPathOut = fileTokenChar;
                else
                    fullPathOut = fullfile(folderIn, fileTokenChar);
                end

                if ~isfile(fullPathOut)
                    error('PipelineManager:registerOutputs:MissingReturnedFile', ...
                        ['A file-producing output returned "%s", but the file was not found.\n' ...
                        'Expected path: %s'], ...
                        fileTokenChar, fullPathOut);
                end

                [~, fBase, fExt] = fileparts(fullPathOut);
                folderBoundNameOut = string(fBase) + string(fExt);
            end
        end

        function tickCooldown(obj, nodeID)
            %TICKCOOLDOWN Decrement cooldownRemaining for a node (if present).
            %
            % Also clears runtime.filePreferred when cooldown reaches 0.

            nodeIdx = obj.getNodeIndexByID(nodeID);

            if ~isfield(obj.nodes(nodeIdx),'runtime') || isempty(obj.nodes(nodeIdx).runtime)
                return
            end

            if ~isfield(obj.nodes(nodeIdx).runtime,'cooldownRemaining') || isempty(obj.nodes(nodeIdx).runtime.cooldownRemaining)
                return
            end

            if obj.nodes(nodeIdx).runtime.cooldownRemaining > 0
                obj.nodes(nodeIdx).runtime.cooldownRemaining = obj.nodes(nodeIdx).runtime.cooldownRemaining - 1;
            end

            if obj.nodes(nodeIdx).runtime.cooldownRemaining <= 0
                if isfield(obj.nodes(nodeIdx).runtime,'filePreferred') && obj.nodes(nodeIdx).runtime.filePreferred
                    obj.nodes(nodeIdx).runtime.filePreferred = false;
                end
            end
        end

        function tmpFile = writeTempData(obj, dataVal, folder, nodeIDLocal, outName)
            %WRITETEMPDATA Write temporary DATA output and return its full saved path.
            %
            %   tmpFile = writeTempData(obj, dataVal, folder, nodeIDLocal, outName)
            %
            %   Behavior:
            %       - Validates that the requested output exists on the step
            %       - Creates an extensionless temporary base name
            %       - Saves the payload through saveData
            %       - Normalizes the returned value from saveData to a full path
            %       - Registers the full path in obj.tempFiles

            % Resolve node
            nodeIdx = obj.getNodeIndexByID(nodeIDLocal);
            node = obj.nodes(nodeIdx);

            bFoundOutput = false;

            % Look up the matching output definition only to validate the output name exists
            if isfield(node,'info') && isfield(node.info,'outputs') && ~isempty(node.info.outputs)
                for iOut = 1:numel(node.info.outputs)

                    thisName = '';
                    if isfield(node.info.outputs(iOut),'name') && ~isempty(node.info.outputs(iOut).name)
                        thisName = char(string(node.info.outputs(iOut).name));
                    end

                    if strcmpi(thisName, char(string(outName)))
                        bFoundOutput = true;
                        break
                    end
                end
            end

            if ~bFoundOutput
                error('PipelineManager:writeTempData:OutputNotFound', ...
                    'Could not find output definition "%s" for step %d.', ...
                    char(string(outName)), nodeIDLocal);
            end

            % Create extensionless PMTMP_* base name and let saveData infer extension.
            % Use the current execution session tag so all temporary files from
            % one run are grouped by the same reserved filename prefix.
            if isempty(obj.currentTempSessionTag)
                obj.currentTempSessionTag = obj.makeTempSessionTag();
            end

            stamp = obj.currentTempSessionTag;
            nodeTag = matlab.lang.makeValidName(char(string(node.name)));
            outTag = matlab.lang.makeValidName(char(string(outName)));
            tmpBasePath = fullfile(folder, sprintf('%s%s_%s_%s', ...
                obj.tempOutputPrefix, stamp, nodeTag, outTag));

            savedPath = saveData(tmpBasePath, dataVal);
            savedPath = char(string(savedPath));

            % Normalize to full path if saveData returned only a filename
            if ~isfile(savedPath)
                savedPath = fullfile(folder, savedPath);
            end

            if ~isfile(savedPath)
                error('PipelineManager:writeTempData:SaveFailed', ...
                    'Temporary file was not found after saveData. Expected path: %s', ...
                    savedPath);
            end

            tmpFile = string(savedPath);
            obj.tempFiles(end+1,1) = tmpFile; %#ok<AGROW>
        end

        function decrementConsumers(obj, key)
            %DECREMENTCONSUMERS Decrement remainingConsumers; release RAM/delete temp if zero.
            %
            %   decrementConsumers(obj, key)
            %
            %   Decrements the remaining consumer count for the given dataStore key.
            %   When the count reaches zero, RAM is released and any temporary file
            %   is deleted.

            if isempty(obj.dataStore) || ~obj.dataStore.isKey(key)
                return
            end

            rec = obj.dataStore(key);

            if ~isfield(rec,'remainingConsumers') || isempty(rec.remainingConsumers)
                rec.remainingConsumers = 0;
            else
                rec.remainingConsumers = max(rec.remainingConsumers - 1, 0);
            end

            obj.dataStore(key) = rec;

            if rec.remainingConsumers <= 0
                rec.ramValue = [];
                obj.dataStore(key) = rec;

                if isfield(rec,'isTemp') && rec.isTemp && ...
                        isfield(rec,'fileName') && strlength(string(rec.fileName)) > 0 && ...
                        isfile(char(string(rec.fileName)))
                    delete(char(string(rec.fileName)));
                end
            end
        end

        function cleanupTemps(obj)
            %CLEANUPTEMPS Defensive cleanup for temp files not referenced by any dataStore record.

            if isempty(obj.tempFiles)
                return
            end

            referenced = strings(0,1);
            keys = obj.dataStore.keys;

            for iK = 1:numel(keys)
                rec = obj.dataStore(keys{iK});
                if isfield(rec,'isTemp') && rec.isTemp && strlength(rec.fileName) > 0
                    referenced(end+1) = string(rec.fileName); %#ok<AGROW>
                end
            end

            for iF = 1:numel(obj.tempFiles)
                item = obj.tempFiles(iF);
                if isfile(item) && ~any(referenced == item)
                    delete(item);
                end
            end
        end

        function key = makeKey(obj, nid, port) %#ok<INUSL>
            %MAKEKEY Create canonical dataStore/consumerCount key: "<nodeID>:<port>"
            key = sprintf('%d:%s', nid, char(string(port)));
        end

        function n = getConsumerCount(obj, key)
            %GETCONSUMERCOUNT Return number of consumers for key.
            if obj.consumerCount.isKey(key)
                n = obj.consumerCount(key);
            else
                n = 0;
            end
        end

        function funcName = getCallableFuncName(obj, nodeLocal)
            %GETCALLABLEFUNCNAME Determine callable function name for node.
            % Uses:
            %   - node.name if it matches a function in obj.funcList
            %   - else parses from node.tag "<funcName>_<id>"
            %   - else falls back to node.name

            funcName = char(string(nodeLocal.name));

            if isprop(obj,'funcList') && ~isempty(obj.funcList)
                if any(strcmp(funcName, {obj.funcList.name}))
                    return
                end
            end

            tagStr = string(nodeLocal.tag);
            suffix = "_" + string(nodeLocal.id);
            if contains(tagStr, suffix)
                funcName = char(extractBefore(tagStr, suffix));
            else
                funcName = char(string(nodeLocal.name));
            end
        end

        function savedFiles = saveNodeDataOutputs(obj, node, saveFolder, varargin)
            %SAVENODEDATAOUTPUTS Save requested DATA outputs for a step to disk.
            %
            %   savedFiles = saveNodeDataOutputs(obj, node, saveFolder)
            %   savedFiles = saveNodeDataOutputs(..., 'overrideFileNames', S)
            %   savedFiles = saveNodeDataOutputs(..., 'skipIfAlreadySaved', TF)
            %   savedFiles = saveNodeDataOutputs(..., 'updateDataHistoryOnMove', TF)
            %
            %   Inputs:
            %       node       - Step definition from obj.nodes.
            %       saveFolder - Destination folder for saved outputs.
            %
            %   Optional name-value pairs:
            %       'overrideFileNames'       - Optional output-specific filename
            %                                   overrides. Fields must use
            %                                   matlab.lang.makeValidName(outputName).
            %                                   When provided, an override filename
            %                                   takes precedence over outDef.saveFileName.
            %
            %       'skipIfAlreadySaved'      - If true, do not create a new file when
            %                                   the output is already backed by an
            %                                   existing non-temporary file.
            %
            %       'updateDataHistoryOnMove' - If true, and a temporary file is
            %                                   promoted/moved to a new filename,
            %                                   update matching entries in
            %                                   obj.dataHistory and save dataHistory.mat.
            %
            %   Behavior:
            %       - Temporary file-backed outputs are promoted first.
            %       - RAM-backed outputs are saved with saveData.
            %       - Permanent file-backed outputs are copied if needed.
            %       - If a temporary file is promoted, obj.dataStore and obj.tempFiles
            %         are updated so downstream steps resolve the new filename.
            %
            %   Output:
            %       savedFiles - Folder-bound filenames saved by the manager during
            %                    this call.

            savedFiles = strings(0,1);

            % -------------------------------------------------------------
            % Parse optional inputs
            % -------------------------------------------------------------
            overrideFileNames       = struct();
            skipIfAlreadySaved      = false;
            updateDataHistoryOnMove = false;

            for iArg = 1:2:numel(varargin)
                key = lower(char(string(varargin{iArg})));
                val = varargin{iArg+1};

                switch key
                    case 'overridefilenames'
                        overrideFileNames = val;

                    case 'skipifalreadysaved'
                        skipIfAlreadySaved = logical(val);

                    case 'updatedatahistoryonmove'
                        updateDataHistoryOnMove = logical(val);

                    otherwise
                        error('PipelineManager:saveNodeDataOutputs:UnknownOption', ...
                            'Unknown option "%s".', char(string(varargin{iArg})));
                end
            end

            if ~isfield(node,'info') || ~isfield(node.info,'outputs') || isempty(node.info.outputs)
                return
            end

            b_historyChanged = false;

            for iOut = 1:numel(node.info.outputs)

                outDef = node.info.outputs(iOut);

                if ~isfield(outDef,'isData') || ~outDef.isData
                    continue
                end

                outName = char(string(outDef.name));
                outFld  = matlab.lang.makeValidName(outName);

                % ---------------------------------------------------------
                % Resolve destination filename:
                %   1) overrideFileNames.(outFld)
                %   2) outDef.saveFileName
                % ---------------------------------------------------------
                fName = '';

                if isstruct(overrideFileNames) && isfield(overrideFileNames, outFld) && ...
                        ~isempty(overrideFileNames.(outFld))
                    fName = char(string(overrideFileNames.(outFld)));

                else
                    saveNameRows = obj.normalizeOutputSaveFileNameList(outDef);
                    if ~isempty(saveNameRows)
                        fName = char(saveNameRows(1));
                    end
                end

                if isempty(strtrim(fName))
                    continue
                end

                % Always use obj.makeKey (consistent with registerOutputs)
                key = obj.makeKey(node.id, outName);

                if isempty(obj.dataStore) || ~isa(obj.dataStore,'containers.Map') || ~obj.dataStore.isKey(key)
                    error('PipelineManager:saveNodeDataOutputs:MissingDataStoreKey', ...
                        'Cannot save output "%s": dataStore key not found: %s', ...
                        outName, char(string(key)));
                end

                rec = obj.dataStore(key);
                dstPath = fullfile(saveFolder, fName);

                hasRamValue  = isfield(rec,'ramValue')  && ~isempty(rec.ramValue);
                hasFileValue = isfield(rec,'fileName')  && ~isempty(rec.fileName);
                isTempSrc    = isfield(rec,'isTemp')    && logical(rec.isTemp);

                % ---------------------------------------------------------
                % Fast skip: already backed by a non-temp file and user requested skip
                % ---------------------------------------------------------
                if skipIfAlreadySaved && hasFileValue && ~isTempSrc
                    srcPath = char(string(rec.fileName));
                    if isfile(srcPath)
                        [~,srcBase,srcExt] = fileparts(srcPath);
                        savedFiles(end+1,1) = string(srcBase) + string(srcExt); %#ok<AGROW>
                        continue
                    end
                end

                % ---------------------------------------------------------
                % Case A: Temporary file-backed -> move/promote
                % ---------------------------------------------------------
                if hasFileValue && isTempSrc

                    srcPath = char(string(rec.fileName));
                    [~,srcBase,srcExt] = fileparts(srcPath);
                    oldFileName = string(srcBase) + string(srcExt);

                    [finalDstPath, finalFileName] = localResolveFinalPath(dstPath, srcPath);

                    if strcmpi(string(srcPath), string(finalDstPath))

                        rec.fileName = string(finalDstPath);
                        rec.isTemp   = false;
                        obj.dataStore(key) = rec;

                        if ~isempty(obj.tempFiles)
                            tempMask = strcmp(string(obj.tempFiles), string(srcPath));
                            obj.tempFiles(tempMask) = [];
                        end

                        savedFiles(end+1,1) = finalFileName; %#ok<AGROW>
                        continue
                    end

                    ok = movefile(srcPath, finalDstPath);
                    if ~ok
                        error('PipelineManager:saveNodeDataOutputs:MoveFailed', ...
                            'Failed to move temp file "%s" -> "%s".', srcPath, finalDstPath);
                    end

                    rec.fileName = string(finalDstPath);
                    rec.isTemp   = false;
                    obj.dataStore(key) = rec;

                    % Remove old temporary path from tempFiles after promotion
                    if ~isempty(obj.tempFiles)
                        tempMask = strcmp(string(obj.tempFiles), string(srcPath));
                        obj.tempFiles(tempMask) = [];
                    end

                    % Update dataHistory only when a temporary file is promoted
                    if updateDataHistoryOnMove && ~isempty(obj.dataHistory)
                        for iHist = 1:numel(obj.dataHistory)
                            if isfield(obj.dataHistory(iHist),'file') && ...
                                    strcmpi(char(string(obj.dataHistory(iHist).file)), char(oldFileName))
                                obj.dataHistory(iHist).file = char(finalFileName);
                                b_historyChanged = true;
                            end
                        end
                    end

                    savedFiles(end+1,1) = finalFileName; %#ok<AGROW>
                    continue
                end

                % ---------------------------------------------------------
                % Case B: RAM-backed -> saveData
                % ---------------------------------------------------------
                if hasRamValue

                    savedPath = saveData(dstPath, rec.ramValue);
                    savedPath = char(string(savedPath));

                    if ~isfile(savedPath)
                        savedPath = fullfile(saveFolder, savedPath);
                    end

                    [~,savedBase,savedExt] = fileparts(savedPath);
                    savedFileName = string(savedBase) + string(savedExt);

                    rec.fileName = string(savedPath);
                    rec.isTemp   = false;
                    obj.dataStore(key) = rec;

                    savedFiles(end+1,1) = savedFileName; %#ok<AGROW>
                    continue
                end

                % ---------------------------------------------------------
                % Case C: Permanent file-backed -> copy if needed
                % ---------------------------------------------------------
                if hasFileValue

                    srcPath = char(string(rec.fileName));
                    [finalDstPath, finalFileName] = localResolveFinalPath(dstPath, srcPath);

                    if strcmpi(string(srcPath), string(finalDstPath))

                        rec.fileName = string(finalDstPath);
                        rec.isTemp   = false;
                        obj.dataStore(key) = rec;

                        savedFiles(end+1,1) = finalFileName; %#ok<AGROW>
                        continue
                    end

                    ok = copyfile(srcPath, finalDstPath);
                    if ~ok
                        error('PipelineManager:saveNodeDataOutputs:CopyFailed', ...
                            'Failed to copy file "%s" -> "%s".', srcPath, finalDstPath);
                    end

                    rec.fileName = string(finalDstPath);
                    rec.isTemp   = false;
                    obj.dataStore(key) = rec;

                    savedFiles(end+1,1) = finalFileName; %#ok<AGROW>
                    continue
                end

                error('PipelineManager:saveNodeDataOutputs:NoValue', ...
                    'Cannot save output "%s" for step %d because it is neither in RAM nor file-backed.', ...
                    outName, node.id);
            end

            if b_historyChanged
                obj.saveDataHistory(saveFolder);
            end

            if ~isempty(savedFiles)
                savedFiles = unique(savedFiles,'stable');
            end

            % =============================================================
            % Local helper
            % =============================================================
            function [finalPath, finalFileName] = localResolveFinalPath(dstPathIn, srcPathIn)
                %LOCALRESOLVEFINALPATH Resolve final destination path/file name.
                %
                % If dstPathIn already has an extension, keep it.
                % Otherwise, inherit the extension from srcPathIn when available.

                finalPath = char(string(dstPathIn));

                [dstFolder, dstBase, dstExt] = fileparts(finalPath);

                if isempty(dstExt)
                    [~,~,srcExtLocal] = fileparts(char(string(srcPathIn)));
                    if ~isempty(srcExtLocal)
                        finalPath = fullfile(dstFolder, [dstBase srcExtLocal]);
                    end
                end

                [~,finalBase,finalExt] = fileparts(finalPath);
                finalFileName = string(finalBase) + string(finalExt);
            end

        end

        function md = getMetaData(obj, node, saveFolder)
            %GETMETADATA Return metadata for legacy functions without loading the data array.
            %
            %   MD = GETMETADATA(OBJ, NODE, SAVEFOLDER) retrieves the metadata
            %   associated with the primary DATA input of NODE.
            %
            %   Resolution policy:
            %       1) If the primary DATA input can be traced to a concrete .dat file,
            %          call loadData(filePath,'InfoOnly',true). This preserves the
            %          retrocompatibility behavior for old .dat + .mat sidecar formats.
            %       2) Otherwise, fall back to <saveFolder>/AcqInfos.mat, which is the
            %          metadata source for the new standard format.
            %
            %   Notes:
            %       - This is intended only for legacy/custom functions that still use
            %         'metaData' as an input.
            %       - The data array itself is never loaded.
            %       - If no metadata source can be found, [] is returned.

            md = [];

            if nargin < 3 || isempty(saveFolder)
                return
            end

            % -------------------------------------------------------------
            % 1) Try to trace the first DATA input back to a concrete file
            % -------------------------------------------------------------
            dataFilePath = '';

            if nargin >= 2 && ~isempty(node) && isfield(node, 'info') && ...
                    isfield(node.info, 'inputs') && ~isempty(node.info.inputs)

                dataInputs = node.info.inputs(arrayfun(@(x) isfield(x,'isData') && x.isData, node.info.inputs));

                if ~isempty(dataInputs)
                    inName = char(string(dataInputs(1).name));

                    try
                        [~, resolvedFile, ~] = obj.resolveDataInputSource(node, inName);

                        if ~isempty(resolvedFile)
                            cand = fullfile(saveFolder, char(string(resolvedFile)));
                            if isfile(cand)
                                dataFilePath = cand;
                            end
                        end
                    catch
                        % Fall through to AcqInfos fallback
                    end
                end
            end

            % -------------------------------------------------------------
            % 2) If a concrete .dat file is available, use loadData(...,InfoOnly)
            %    so retrocompatibility sidecar logic is reused.
            % -------------------------------------------------------------
            if ~isempty(dataFilePath)
                [~, ~, ext] = fileparts(dataFilePath);

                if strcmpi(ext, '.dat')
                    try
                        [~, md] = loadData(dataFilePath, 'InfoOnly', true);
                        obj.metaData = md;
                        return
                    catch
                        % Fall through to AcqInfos fallback
                    end
                elseif strcmpi(ext, '.pdat')
                    md = [];
                    obj.metaData = md;
                    return
                end
            end

            % -------------------------------------------------------------
            % 3) Fallback to new-format shared metadata file
            % -------------------------------------------------------------
            acqInfoPath = fullfile(saveFolder, 'AcqInfos.mat');

            if isfile(acqInfoPath)
                tmp = load(acqInfoPath);

                if isfield(tmp, 'AcqInfoStream')
                    md = tmp.AcqInfoStream;
                elseif isfield(tmp, 'AcqInfos')
                    md = tmp.AcqInfos;
                else
                    % Best-effort fallback: return the first variable in the MAT file
                    fn = fieldnames(tmp);
                    if ~isempty(fn)
                        md = tmp.(fn{1});
                    else
                        md = [];
                    end
                end
            end

            obj.metaData = md;
        end

        function restoreExecutionRunState(obj, previousRunPolicy, previousSessionTag)
            %RESTOREEXECUTIONRUNSTATE Restore transient per-run execution state.

            obj.currentLeafOutputPolicy = previousRunPolicy;
            obj.currentTempSessionTag = previousSessionTag;
        end

        %%%%%%--Data History-related --------------------------------------
        function matchHistoryAndSetPreload(obj, folder)
            %MATCHHISTORYANDSETPRELOAD Match dataHistory entries against candidate DAG paths.
            %
            %   MATCHHISTORYANDSETPRELOAD(OBJ, FOLDER) finds the best matching
            %   dataHistory entry for each leaf candidate path and sets either:
            %
            %       1) Per-output-port preloads:
            %          obj.nodes(nodeIdx).runtime.preloadedData.(<outputPort>) =
            %              struct('file',...,'info',...)
            %
            %       2) Full-branch (leaf) cache markers when one history file covers
            %          the entire candidate node path:
            %          obj.nodes(leafIdx).runtime.leafCachedFile    = <filename>
            %          obj.nodes(leafIdx).runtime.leafCachedNodeIDs = <candidateNodeIDs>
            %
            %   Selection rules:
            %       1) Choose matches with maximum matched NODE count, not raw
            %          expanded provenance length.
            %       2) If multiple matches have the same maximum node count, require
            %          historyEntry.file to match the concrete required file when the
            %          producing output is an ambiguous file-producing output.
            %       3) If still ambiguous, or if the required output port cannot be
            %          determined, do NOT preload.
            %
            %   Important:
            %       - candidateSteps may contain prepended provenance coming from
            %         file-backed inputs.
            %       - candidateNodeIDs only contains actual DAG node IDs.
            %       - nStepsMatched returned by isHistoryMatch counts only actual
            %         matched DAG nodes, so zero-step matches must never be used for
            %         preload indexing.
            %
            %   Notes:
            %       - Uses matlab.lang.makeValidName for output port field names.
            %       - Clears any previous preloads/cache flags at the start.
            %       - Ambiguity is determined from output metadata, not from the
            %         hard-coded legacy port name 'outFile'.

            if isempty(obj.dataHistory)
                return
            end

            % -------------------------------------------------------------
            % Clear any previous preloads / leaf cache flags
            % -------------------------------------------------------------
            for iNode = 1:numel(obj.nodes)
                if ~isfield(obj.nodes(iNode), 'runtime') || isempty(obj.nodes(iNode).runtime)
                    obj.nodes(iNode).runtime = struct();
                end

                obj.nodes(iNode).runtime.preloadedData = struct();
                obj.nodes(iNode).runtime.leafCachedFile = string.empty(0,1);
                obj.nodes(iNode).runtime.leafCachedNodeIDs = [];
            end

            % -------------------------------------------------------------
            % Determine leaf nodes
            % -------------------------------------------------------------

            leafIDs = obj.getLeafNodeIDs();

            if isempty(leafIDs)
                return
            end

            % Resolve rawFolder for this SaveFolder (exact)
            rawFolder = '';
            idxSF = find(strcmp(folder, obj.SaveFolderList), 1, 'first');
            if ~isempty(idxSF) && idxSF <= numel(obj.RawFolderList)
                rawFolder = obj.RawFolderList{idxSF};
            end

            % -------------------------------------------------------------
            % Per-leaf matching
            % -------------------------------------------------------------
            for iLeaf = 1:numel(leafIDs)

                leafID = leafIDs(iLeaf);

                [candidateSteps, candidateNodeIDs, candidateStepIsNode] = ...
                    obj.getCandidatePath(leafID, folder, rawFolder);

                if isempty(candidateSteps) || isempty(candidateNodeIDs)
                    continue
                end

                % ---------------------------------------------------------
                % Scan history entries: keep only best-length matches
                % bestLen is measured in matched DAG nodes only.
                % ---------------------------------------------------------
                bestLen = 0;
                matches = struct('hIdx', {}, 'nSteps', {}, 'preloadNodeID', {});

                for iHist = 1:numel(obj.dataHistory)

                    histEntry = obj.dataHistory(iHist);

                    % History file must still exist in this folder to be reusable
                    if ~isfield(histEntry, 'file') || isempty(histEntry.file)
                        continue
                    end

                    if ~isfile(fullfile(folder, histEntry.file))
                        continue
                    end

                    if ~isfield(histEntry, 'pipelineVersion') || ...
                            ~isequal(histEntry.pipelineVersion, obj.pipelineVersion)
                        continue
                    end

                    [tf, nStepsMatched] = obj.isHistoryMatch( ...
                        candidateSteps, candidateStepIsNode, histEntry, folder, rawFolder);

                    if ~tf
                        continue
                    end

                    % Ignore matches that only cover prepended file provenance and
                    % do not actually match any DAG node in the candidate path.
                    if nStepsMatched <= 0
                        continue
                    end

                    if nStepsMatched > numel(candidateNodeIDs)
                        error('PipelineManager:matchHistoryAndSetPreload:InvalidMatchLength', ...
                            ['isHistoryMatch returned %d matched node step(s), but the ' ...
                            'candidate path only has %d node(s).'], ...
                            nStepsMatched, numel(candidateNodeIDs));
                    end

                    if nStepsMatched > bestLen
                        bestLen = nStepsMatched;
                        matches = struct( ...
                            'hIdx', iHist, ...
                            'nSteps', nStepsMatched, ...
                            'preloadNodeID', candidateNodeIDs(nStepsMatched));

                    elseif nStepsMatched == bestLen && bestLen > 0
                        matches(end+1) = struct( ...
                            'hIdx', iHist, ...
                            'nSteps', nStepsMatched, ...
                            'preloadNodeID', candidateNodeIDs(nStepsMatched)); %#ok<AGROW>
                    end
                end

                if bestLen == 0 || isempty(matches)
                    continue
                end

                % ---------------------------------------------------------
                % FULL COVERAGE: candidate fully satisfied by one file -> tag leaf
                % and skip the whole branch.
                %
                % Full coverage must be evaluated against the number of DAG nodes,
                % not the expanded provenance length.
                % ---------------------------------------------------------
                if bestLen == numel(candidateNodeIDs)

                    % Accept full-skip only if all best matches refer to the SAME file
                    fileList = strings(0,1);
                    for iM = 1:numel(matches)
                        fileList(end+1,1) = string(obj.dataHistory(matches(iM).hIdx).file); %#ok<AGROW>
                    end
                    fileList = unique(fileList, 'stable');

                    if numel(fileList) ~= 1
                        % Ambiguous full coverage => do not full-skip
                        continue
                    end

                    leafIdx = obj.getNodeIndexByID(candidateNodeIDs(end));

                    if ~isfield(obj.nodes(leafIdx), 'runtime') || isempty(obj.nodes(leafIdx).runtime)
                        obj.nodes(leafIdx).runtime = struct();
                    end

                    obj.nodes(leafIdx).runtime.leafCachedFile    = fileList(1);
                    obj.nodes(leafIdx).runtime.leafCachedNodeIDs = candidateNodeIDs(:).';

                    continue
                end

                % ---------------------------------------------------------
                % PARTIAL COVERAGE:
                % preloadNodeID is the last matched DAG node.
                % nextUnmatchedNodeID is the first unmatched DAG node after it.
                % ---------------------------------------------------------
                if bestLen < 1 || bestLen >= numel(candidateNodeIDs)
                    continue
                end

                preloadNodeID = matches(1).preloadNodeID;
                nextUnmatchedNodeID = candidateNodeIDs(bestLen + 1);

                connIdx = find( ...
                    [obj.connections.sourceNodeID] == preloadNodeID & ...
                    [obj.connections.targetNodeID] == nextUnmatchedNodeID, ...
                    1, 'first');

                if isempty(connIdx)
                    continue
                end

                conn = obj.connections(connIdx);

                requiredPort = char(string(conn.sourceOutputName));
                requiredFld  = matlab.lang.makeValidName(requiredPort);

                % ---------------------------------------------------------
                % Determine whether the producing output is an ambiguous file output
                % ---------------------------------------------------------
                [isAmbiguousFileOutput, requiredFile] = resolveRequiredFileIdentity(preloadNodeID, conn);

                % ---------------------------------------------------------
                % Resolve match choice under unified rules
                % ---------------------------------------------------------
                hBest = [];

                if numel(matches) == 1
                    hCand = matches(1).hIdx;

                    if isAmbiguousFileOutput
                        if isempty(requiredFile)
                            continue
                        end
                        if ~strcmpi(char(string(obj.dataHistory(hCand).file)), requiredFile)
                            continue
                        end
                    end

                    hBest = hCand;

                else
                    % Tie at bestLen
                    if isAmbiguousFileOutput
                        if isempty(requiredFile)
                            continue
                        end

                        keep = false(1, numel(matches));
                        for iM = 1:numel(matches)
                            hIdx = matches(iM).hIdx;
                            keep(iM) = strcmpi(char(string(obj.dataHistory(hIdx).file)), requiredFile);
                        end

                        matches2 = matches(keep);
                        if numel(matches2) ~= 1
                            continue
                        end

                        hBest = matches2(1).hIdx;

                    else
                        % Non-ambiguous ties remain ambiguous -> do not preload
                        continue
                    end
                end

                if isempty(hBest)
                    continue
                end

                % ---------------------------------------------------------
                % Apply preload per output port (store file + provenance info)
                % ---------------------------------------------------------
                nodeIdx = obj.getNodeIndexByID(preloadNodeID);

                if ~isfield(obj.nodes(nodeIdx), 'runtime') || isempty(obj.nodes(nodeIdx).runtime)
                    obj.nodes(nodeIdx).runtime = struct();
                end
                if ~isfield(obj.nodes(nodeIdx).runtime, 'preloadedData') || isempty(obj.nodes(nodeIdx).runtime.preloadedData)
                    obj.nodes(nodeIdx).runtime.preloadedData = struct();
                end

                obj.nodes(nodeIdx).runtime.preloadedData.(requiredFld) = struct( ...
                    'file', obj.dataHistory(hBest).file, ...
                    'info', obj.dataHistory(hBest).info);
            end

            % =============================================================
            % Local helper
            % =============================================================
            function [tf, reqFile] = resolveRequiredFileIdentity(producerNodeID, connLocal)
                %RESOLVEREQUIREDFILEIDENTITY Determine whether the producer output is
                %an ambiguous file-producing output and resolve the required filename.
                %
                %   [TF, REQFILE] = RESOLVEREQUIREDFILEIDENTITY(PRODUCERNODEID, CONNLOCAL)
                %   returns:
                %       TF      true when the producer output is a file output with
                %               multiple declared filenames
                %       REQFILE concrete required filename when it can be resolved, else ''

                tf = false;
                reqFile = '';

                prodIdx = obj.getNodeIndexByID(producerNodeID);
                prodNode = obj.nodes(prodIdx);

                if ~isfield(prodNode, 'info') || ~isfield(prodNode.info, 'outputs') || isempty(prodNode.info.outputs)
                    return
                end

                outNameLocal = char(string(connLocal.sourceOutputName));
                outNamesLocal = {prodNode.info.outputs.name};
                iOutLocal = find(strcmpi(outNamesLocal, outNameLocal), 1, 'first');

                if isempty(iOutLocal)
                    return
                end

                outDefLocal = prodNode.info.outputs(iOutLocal);

                outputModeLocal = 'data';
                if isfield(outDefLocal, 'outputMode') && ~isempty(outDefLocal.outputMode)
                    outputModeLocal = lower(strtrim(char(string(outDefLocal.outputMode))));
                end

                if ~strcmpi(outputModeLocal, 'file')
                    return
                end

                defOutListLocal = {};
                if isfield(outDefLocal, 'defOutfilename')
                    if ischar(outDefLocal.defOutfilename) || isstring(outDefLocal.defOutfilename)
                        tmpLocal = strtrim(char(string(outDefLocal.defOutfilename)));
                        if ~isempty(tmpLocal)
                            defOutListLocal = {tmpLocal};
                        end
                    elseif iscell(outDefLocal.defOutfilename)
                        defOutListLocal = cellfun(@(x) strtrim(char(string(x))), ...
                            outDefLocal.defOutfilename, 'UniformOutput', false);
                        defOutListLocal = defOutListLocal(~cellfun(@isempty, defOutListLocal));
                    end
                end

                tf = numel(defOutListLocal) > 1;

                % Priority 1: explicit selectedFile
                if isfield(connLocal, 'selectedFile') && ~isempty(connLocal.selectedFile)
                    reqFile = char(string(connLocal.selectedFile));
                    return
                end

                % Priority 2: single declared file output can be resolved directly
                if numel(defOutListLocal) == 1
                    reqFile = defOutListLocal{1};
                    return
                end

                % Priority 3: concrete file from current dataStore record
                keyLocal = obj.makeKey(producerNodeID, outNameLocal);
                if ~isempty(obj.dataStore) && isa(obj.dataStore, 'containers.Map') && obj.dataStore.isKey(keyLocal)
                    recLocal = obj.dataStore(keyLocal);
                    if isstruct(recLocal) && isfield(recLocal, 'fileName') && ~isempty(recLocal.fileName)
                        filePathLocal = char(string(recLocal.fileName));
                        [~, fBaseLocal, fExtLocal] = fileparts(filePathLocal);
                        reqFile = [fBaseLocal fExtLocal];
                    end
                end
            end
        end

        function [candidateSteps, candidateNodeIDs, candidateStepIsNode] = getCandidatePath(obj, leafNodeID, saveFolder, rawFolder)
            %GETCANDIDATEPATH Build the ordered candidate step list for a leaf.
            %
            % Option-2 merge policy:
            %   - History matching must NOT cross merge nodes.
            %   - A merge node is any node with 2+ incoming connections.
            %   - Candidate path is truncated so that nodes upstream of the first merge
            %     encountered (walking upstream from the leaf) are excluded.
            %
            % Returns:
            %   candidateSteps       struct array with fields:
            %       .name
            %       .version
            %       .parameters
            %       .inputs
            %   candidateNodeIDs     vector of node IDs for actual DAG nodes only
            %   candidateStepIsNode  logical vector aligned with candidateSteps:
            %       true  -> step corresponds to a node in candidateNodeIDs
            %       false -> step was prepended from file dataHistory
            %
            % Provenance behavior:
            %   - Stream nodes only.
            %   - Data input sources use selectedFile (preferred) else file-backed
            %     dataStore fileName else SrcNodeName:sourceOutputName.
            %   - If a DATA input comes from a file-source proxy node and resolves to a
            %     concrete file with an existing dataHistory entry, that file provenance
            %     is prepended before the current processing step.
            %   - File-source proxy nodes are replaced by the history of the concrete
            %     file they represent when that history exists.
            %   - Files produced by upstream stream nodes do NOT prepend their own
            %     dataHistory here, because their provenance is already represented
            %     explicitly by upstream nodes in the candidate path.

            candidateSteps      = struct.empty(0,1);
            candidateNodeIDs    = [];
            candidateStepIsNode = false(0,1);

            % -------------------------------------------------------------
            % Build a candidate node ID list (best-effort)
            % -------------------------------------------------------------
            nodeIDs = obj.branchPathFromLeaf(leafNodeID);

            if isempty(nodeIDs)
                return
            end

            % -------------------------------------------------------------
            % Merge-boundary truncation (Option 2)
            % -------------------------------------------------------------
            mergeStartID = [];
            curID = leafNodeID;

            while true

                % Guard against single-node / no-edge pipelines and fieldless empty structs
                if isempty(obj.connections) || ...
                        ~isstruct(obj.connections) || ...
                        ~isfield(obj.connections, 'targetNodeID') || ...
                        ~isfield(obj.connections, 'sourceNodeID')
                    break
                end

                inConns = obj.connections([obj.connections.targetNodeID] == curID);

                if numel(inConns) >= 2
                    mergeStartID = curID;
                    break
                end

                if isempty(inConns)
                    break
                end

                curID = inConns(1).sourceNodeID;
            end

            if ~isempty(mergeStartID)
                idxStart = find(nodeIDs == mergeStartID, 1, 'first');
                if ~isempty(idxStart)
                    nodeIDs = nodeIDs(idxStart:end);
                end
            end

            % -------------------------------------------------------------
            % Convert to nodes; keep stream nodes only
            % -------------------------------------------------------------
            nodesPath = obj.nodes(ismember([obj.nodes.id], nodeIDs));

            [~, ord] = ismember(nodeIDs(:), [nodesPath.id]);
            ord = ord(ord > 0);
            nodesPath = nodesPath(ord);

            maskStream = strcmpi({nodesPath.kind}, 'stream');
            nodesPath  = nodesPath(maskStream);

            if isempty(nodesPath)
                return
            end

            % Track file histories already prepended during this candidate build
            prependedFiles = containers.Map('KeyType', 'char', 'ValueType', 'logical');

            for iStep = 1:numel(nodesPath)

                node = nodesPath(iStep);

                % ---------------------------------------------------------
                % Special handling for file-source proxy nodes
                % ---------------------------------------------------------
                if obj.isHistoryProxyNode(node)

                    proxyFile = obj.resolveProxyNodeFile(node);

                    if ~isempty(proxyFile)
                        histInfo = obj.getHistoryInfoForFile(proxyFile);

                        if ~isempty(histInfo)
                            fKey = lower(strtrim(proxyFile));

                            if ~isKey(prependedFiles, fKey)
                                [candidateSteps, candidateStepIsNode] = ...
                                    appendCandidateInfo(candidateSteps, candidateStepIsNode, histInfo, false);
                                prependedFiles(fKey) = true;
                            end

                            % Do not append the proxy step itself when the
                            % represented file already has its own dataHistory.
                            continue
                        end
                    end
                end

                % ---------------------------------------------------------
                % Build current node step info
                % ---------------------------------------------------------
                stepInfo = struct();
                stepInfo.name    = node.info.name;
                stepInfo.version = node.info.version;

                if isfield(node.info, 'parameters') && ~isempty(node.info.parameters)
                    stepInfo.parameters = node.info.parameters;
                else
                    stepInfo.parameters = struct.empty(0,1);
                end

                inputs = struct('name', {}, 'source', {});

                if isfield(node.info, 'inputs') && ~isempty(node.info.inputs)

                    for iIn = 1:numel(node.info.inputs)

                        inDef  = node.info.inputs(iIn);
                        inName = char(string(inDef.name));

                        thisIn = struct();
                        thisIn.name   = inName;
                        thisIn.source = [];

                        if isfield(inDef, 'isData') && inDef.isData

                            [srcToken, resolvedInputFile, isProxyBackedInput] = ...
                                obj.resolveDataInputSource(node, inName);

                            thisIn.source = srcToken;

                            % Only prepend file history when the input is backed by
                            % a file-source proxy node. Do NOT prepend when the
                            % file is simply the persisted output of an upstream
                            % generated function already represented in the path.
                            if isProxyBackedInput && ~isempty(resolvedInputFile)
                                histInfo = obj.getHistoryInfoForFile(resolvedInputFile);

                                if ~isempty(histInfo)
                                    fKey = lower(strtrim(resolvedInputFile));

                                    if ~isKey(prependedFiles, fKey)
                                        [candidateSteps, candidateStepIsNode] = ...
                                            appendCandidateInfo(candidateSteps, candidateStepIsNode, histInfo, false);
                                        prependedFiles(fKey) = true;
                                    end
                                end
                            end

                        else
                            switch lower(inName)
                                case 'savefolder'
                                    thisIn.source = char(string(saveFolder));
                                case 'rawfolder'
                                    thisIn.source = char(string(rawFolder));
                                case 'metadata'
                                    thisIn.source = [];
                                otherwise
                                    thisIn.source = [];
                            end
                        end

                        inputs(end+1) = thisIn; %#ok<AGROW>
                    end
                end

                stepInfo.inputs = inputs;

                [candidateSteps, candidateStepIsNode] = ...
                    appendCandidateInfo(candidateSteps, candidateStepIsNode, stepInfo, true);

                candidateNodeIDs(end+1) = node.id; %#ok<AGROW>
            end

            % =============================================================
            % Local helper
            % =============================================================
            function [stepsOut, isNodeOut] = appendCandidateInfo(stepsIn, isNodeIn, infoToAppend, isNodeFlag)
                %APPENDCANDIDATEINFO Append provenance steps while preserving node mask.
                %
                %   [STEPSOUT, ISNODEOUT] = APPENDCANDIDATEINFO(STEPSIN, ISNODEIN,
                %   INFOTOAPPEND, ISNODEFLAG) appends one or more steps to the
                %   candidate list with boundary deduplication and extends the aligned
                %   node-origin mask accordingly.
                %
                %   ISNODEFLAG may be:
                %       - scalar logical: replicated for all appended steps
                %       - logical vector of same length as INFOTOAPPEND

                stepsOut  = stepsIn;
                isNodeOut = isNodeIn;

                if isempty(infoToAppend)
                    return
                end

                if isscalar(isNodeFlag)
                    maskToAppend = repmat(logical(isNodeFlag), numel(infoToAppend), 1);
                else
                    maskToAppend = logical(isNodeFlag(:));
                end

                if isempty(stepsOut)
                    stepsOut  = infoToAppend;
                    isNodeOut = maskToAppend;
                    return
                end

                firstAppend = infoToAppend(1);
                lastAcc     = stepsOut(end);

                if obj.isSameStep(lastAcc, firstAppend)
                    infoToAppend = infoToAppend(2:end);
                    maskToAppend = maskToAppend(2:end);
                end

                if ~isempty(infoToAppend)
                    stepsOut  = [stepsOut; infoToAppend];
                    isNodeOut = [isNodeOut; maskToAppend];
                end
            end
        end

        function [tf, nStepsMatched] = isHistoryMatch(~, candidateSteps, candidateStepIsNode, historyEntry, saveFolder, rawFolder)
            %ISHISTORYMATCH Strict prefix match between candidateSteps and historyEntry.info.
            %
            %   [TF, NSTEPSMATCHED] = ISHISTORYMATCH(~, CANDIDATESTEPS,
            %   CANDIDATESTEPISNODE, HISTORYENTRY, SAVEFOLDER, RAWFOLDER) compares the
            %   saved history against the expanded candidate provenance.
            %
            % Returns:
            %   tf            true if history matches the first N steps of candidateSteps
            %   nStepsMatched number of matched steps that correspond to actual DAG
            %                 nodes only (prepended file-history steps are excluded)
            %
            % Matching rules:
            %   - function name and version must match
            %   - parameters must match strictly (isequal)
            %   - inputs must match by (name, source), order-free by input name
            %       * SaveFolder/RawFolder: must equal exact runtime values
            %       * metaData: ignored
            %       * data inputs: exact source-string match after candidate-side
            %         provenance expansion has already been applied upstream
            %
            % Notes:
            %   - history length must be <= candidate length
            %   - this function does NOT require candidate and history to be the same length
            %   - candidateStepIsNode must be aligned with candidateSteps

            tf = false;
            nStepsMatched = 0;

            if ~isfield(historyEntry,'info') || isempty(historyEntry.info)
                return
            end

            if numel(candidateStepIsNode) ~= numel(candidateSteps)
                error('PipelineManager:isHistoryMatch:InvalidCandidateMask', ...
                    'candidateStepIsNode must have the same length as candidateSteps.');
            end

            histSteps = historyEntry.info;
            nHist = numel(histSteps);

            if nHist > numel(candidateSteps)
                return
            end

            for k = 1:nHist

                hs = histSteps(k);
                cs = candidateSteps(k);

                % ---------------------------------------------------------
                % Function identity
                % ---------------------------------------------------------
                if ~isfield(hs,'name'); return; end
                if ~isfield(cs,'name'); return; end
                if ~isequal(char(string(cs.name)), char(string(hs.name)))
                    return
                end

                if ~isfield(hs,'version'); hs.version = ''; end
                if ~isfield(cs,'version'); cs.version = ''; end
                if ~isequal(char(string(cs.version)), char(string(hs.version)))
                    return
                end

                % ---------------------------------------------------------
                % Parameters (strict)
                % ---------------------------------------------------------
                if ~isfield(hs,'parameters'); hs.parameters = struct.empty(0,1); end
                if ~isfield(cs,'parameters'); cs.parameters = struct.empty(0,1); end

                if ~isequal(cs.parameters, hs.parameters)
                    return
                end

                % ---------------------------------------------------------
                % Inputs (strict on name+source; ignore metaData)
                % ---------------------------------------------------------
                if ~isfield(hs,'inputs'); hs.inputs = struct('name',{},'source',{}); end
                if ~isfield(cs,'inputs'); cs.inputs = struct('name',{},'source',{}); end

                histNames = string({hs.inputs.name});
                candNames = string({cs.inputs.name});

                if ~isequal(sort(histNames), sort(candNames))
                    return
                end

                for iN = 1:numel(histNames)

                    nm = histNames(iN);

                    hIdx = find(histNames == nm, 1, 'first');
                    cIdx = find(candNames == nm, 1, 'first');

                    hSrc = hs.inputs(hIdx).source;
                    cSrc = cs.inputs(cIdx).source;

                    if strcmpi(nm,'SaveFolder')
                        if ~isequal(char(string(hSrc)), char(string(saveFolder)))
                            return
                        end
                        if ~isequal(char(string(cSrc)), char(string(saveFolder)))
                            return
                        end
                        continue
                    end

                    if strcmpi(nm,'RawFolder')
                        if ~isequal(char(string(hSrc)), char(string(rawFolder)))
                            return
                        end
                        if ~isequal(char(string(cSrc)), char(string(rawFolder)))
                            return
                        end
                        continue
                    end

                    if strcmpi(nm,'metaData')
                        continue
                    end

                    % Data input source strict match
                    % Parse source:
                    hToken = extractAfter(hSrc,':');
                    cToken = extractAfter(cSrc,':');
                    if ~isequal(char(string(hToken)), char(string(cToken)))
                        return
                    end

                end
            end

            tf = true;

            % Count only matched steps that correspond to actual DAG nodes.
            % Prepended file-history steps are excluded.
            nStepsMatched = sum(candidateStepIsNode(1:nHist));
        end

        %%%%%%- DAG helpers------------------------------------------------
        function idx= getNodeIndexByID(obj,nodeID)
            %GETNODEINDEXBYID Return the index of a node inside obj.nodes.
            %
            %   nodeIdx = getNodeIndexByID(obj, nodeID) resolves the position of
            %   NODEID in the current node array.

            idx = find([obj.nodes.id] == nodeID,1,'first');
        end

        function upstreamNodes = getUpstreamNodes(obj, nodeID)
            %GETUPSTREAMNODES Return all upstream nodes that can reach nodeID.
            %
            %   upstreamNodes = GETUPSTREAMNODES(OBJ, nodeID) returns a struct array of
            %   nodes (OBJ.nodes) that have a directed path to the given nodeID using
            %   OBJ.connections.
            %
            %   Notes:
            %     - Uses indexed traversal (no containers.Map).
            %     - Returns node structs (not IDs).

            arguments
                obj
                nodeID (1,1) double
            end

            if isempty(obj.nodes) || isempty(obj.connections)
                upstreamNodes = obj.nodes([]); % empty struct array of same type
                return
            end

            nodeIDs = [obj.nodes.id];
            if ~any(nodeIDs == nodeID)
                error('PipelineManager:getUpstreamNodes:UnknownNode', ...
                    'NodeID %d not found in pipeline.', nodeID);
            end

            visitedIdx = false(1, numel(nodeIDs));
            queue = nodeID;

            while ~isempty(queue)

                currentID = queue(1);
                queue(1) = [];

                parentIDs = [obj.connections([obj.connections.targetNodeID] == currentID).sourceNodeID];

                if isempty(parentIDs)
                    continue
                end

                for p = 1:numel(parentIDs)

                    pid = parentIDs(p);
                    idx = find(nodeIDs == pid, 1, 'first');

                    if isempty(idx)
                        continue
                    end

                    if ~visitedIdx(idx)
                        visitedIdx(idx) = true;
                        queue(end+1) = pid; %#ok<AGROW>
                    end
                end
            end

            upstreamNodes = obj.nodes(visitedIdx);
        end

        function path = branchPathFromLeaf(obj, leafID)
            %BRANCHPATHFROMLEAF Return ordered path from root to leaf.

            path = [];
            % To account for a single node.
            if isempty(obj.connections)
                path = leafID;
                return
            end

            current = leafID;

            while true
                path = [current path];
                parentConn = obj.connections( ...
                    [obj.connections.targetNodeID]==current);

                if isempty(parentConn)
                    break
                end

                current = parentConn(1).sourceNodeID;
            end
        end

        %%%%%%-------------------------------------------------------------
        function tf = pipelineRequiresRawFolder(obj)
            %PIPELINEREQUIRESRAWFOLDER True if any stream step declares RawFolder input.
            %
            %   TF = PIPELINEREQUIRESRAWFOLDER(OBJ) returns true when at least one
            %   stream node in the current DAG declares a non-data input whose
            %   name is 'rawfolder' or whose semantic type includes 'RawFolder'.

            tf = false;

            if isempty(obj.nodes)
                return
            end

            for iNode = 1:numel(obj.nodes)

                nodeLocal = obj.nodes(iNode);

                if ~isfield(nodeLocal,'kind') || ~strcmpi(nodeLocal.kind,'stream')
                    continue
                end

                if ~isfield(nodeLocal,'info') || ~isfield(nodeLocal.info,'inputs') || isempty(nodeLocal.info.inputs)
                    continue
                end

                for iIn = 1:numel(nodeLocal.info.inputs)

                    inDef = nodeLocal.info.inputs(iIn);

                    inputNameLocal = "";
                    if isfield(inDef,'name') && ~isempty(inDef.name)
                        inputNameLocal = lower(strtrim(string(inDef.name)));
                    end

                    inputTypesLocal = strings(0,1);
                    if isfield(inDef,'type') && ~isempty(inDef.type)
                        if ischar(inDef.type) || (isstring(inDef.type) && isscalar(inDef.type))
                            inputTypesLocal = string(inDef.type);
                        else
                            inputTypesLocal = string(inDef.type(:));
                        end
                    end

                    if strcmp(inputNameLocal,'rawfolder') || any(strcmpi(inputTypesLocal,'RawFolder'))
                        tf = true;
                        return
                    end
                end
            end
        end

        function createFcnList(obj)
            %CREATEFCNLIST Create the list of analysis functions with pipelineInfo metadata.
            %
            %   CREATEFCNLIST(OBJ) scans the Analysis folder and builds OBJ.FUNCLIST.
            %
            %   Behavior:
            %       - Each function is first queried for modern pipelineInfo metadata.
            %       - If the function clearly declares a pipelineInfo query but that
            %         query fails, the error is treated as a broken modern metadata
            %         definition and is rethrown with context.
            %       - If modern metadata is not declared, legacy parsing is used as a
            %         fallback for callable functions.
            %       - If the function itself is not callable from the MATLAB path, it
            %         is skipped and not added to the list.
            %
            %   Notes:
            %       - This avoids silently falling back to legacy parsing when a
            %         modern local pipelineInfo block contains an error. Silent fallback
            %         can create incomplete metadata, for example steps with missing
            %         parameters even though the function declares them.
            %       - Inputs and outputs are annotated with the boolean field isData
            %         after legacy parsing only. Modern pipelineInfo functions are
            %         expected to provide these fields through addInput/addOutput.

            disp('Creating Fcn list...');
            obj.funcList = [];  % Reset

            % List all .m files in the Analysis folder.
            list = dir(fullfile(obj.fcnDir, '*', '*.m'));

            for i = 1:length(list)

                fcnFullPath = fullfile(list(i).folder, list(i).name);
                [~, fcnName] = fileparts(fcnFullPath);

                % -------------------------------------------------------------
                % Skip functions that are not callable from the MATLAB path.
                % -------------------------------------------------------------
                if isempty(which(fcnName))
                    warning('PipelineManager:createFcnList:FunctionNotOnPath', ...
                        'Skipping function "%s" because it is not on the MATLAB path.', ...
                        fcnName);
                    continue
                end

                % -------------------------------------------------------------
                % Detect whether the file explicitly declares a modern
                % pipelineInfo query. This is used only to decide whether a failed
                % query should fall back to legacy parsing or be reported as a
                % broken modern metadata block.
                % -------------------------------------------------------------
                b_declaresPipelineInfo = false;
                try
                    fileText = fileread(fcnFullPath);
                    fileLines = regexp(fileText, '\r\n|\n|\r', 'split');
                    keepLine = true(size(fileLines));

                    for iLine = 1:numel(fileLines)
                        keepLine(iLine) = ~startsWith(strtrim(fileLines{iLine}), '%');
                    end

                    nonCommentText = strjoin(fileLines(keepLine), newline);
                    b_declaresPipelineInfo = ~isempty(regexpi(nonCommentText, ...
                        '[''\"]pipelineInfo[''\"]', 'once'));
                catch
                    % If the file cannot be inspected here, keep the old behavior:
                    % try the query, and use legacy fallback if needed.
                    b_declaresPipelineInfo = false;
                end

                % -------------------------------------------------------------
                % Try to get pipelineInfo via function query.
                % -------------------------------------------------------------
                try
                    fcnHandle = str2func(fcnName);
                    infoStruct = fcnHandle('pipelineInfo');  % Modern functions

                    if ~isstruct(infoStruct)
                        error('PipelineManager:createFcnList:InvalidPipelineInfoReturn', ...
                            'Function "%s" returned a non-struct pipelineInfo payload.', ...
                            fcnName);
                    end

                    % Modern pipelineInfo should at least contain the canonical
                    % fields created by createPipelineInfo. This catches accidental
                    % returns of unrelated structs.
                    requiredFields = {'inputs','outputs','parameters','arguments'};
                    missingFields = requiredFields(~isfield(infoStruct, requiredFields));
                    if ~isempty(missingFields)
                        error('PipelineManager:createFcnList:InvalidPipelineInfoReturn', ...
                            'Function "%s" returned pipelineInfo missing field(s): %s.', ...
                            fcnName, strjoin(missingFields, ', '));
                    end

                catch ME

                    % If the function itself is undefined/unreachable, do not fall
                    % back to legacy parsing. Skip it.
                    if strcmp(ME.identifier, 'MATLAB:UndefinedFunction')
                        warning('PipelineManager:createFcnList:FunctionUnavailable', ...
                            'Skipping function "%s" because it could not be called: %s', ...
                            fcnName, ME.message);
                        continue
                    end

                    % If the file appears to declare modern pipelineInfo support,
                    % do not silently legacy-parse it. A failed modern metadata query
                    % means the function metadata needs to be fixed.
                    if b_declaresPipelineInfo
                        error('PipelineManager:createFcnList:BrokenPipelineInfo', ...
                            ['Function "%s" appears to declare a modern pipelineInfo query, ' ...
                            'but calling %s(''pipelineInfo'') failed.\n\n%s'], ...
                            fcnName, fcnName, getReport(ME, 'basic', 'hyperlinks', 'off'));
                    end

                    % Fallback to legacy parser for callable functions that do not
                    % support modern pipelineInfo querying.
                    infoStruct = obj.parseFuncFile(list(i));

                    % -------------------------------------------------------------
                    % Add boolean to indicate if each input is semantic data.
                    % -------------------------------------------------------------
                    for jj = 1:length(infoStruct.inputs)

                        if any(ismember(infoStruct.inputs(jj).type, obj.dataSemanticTypes))
                            infoStruct.inputs(jj).isData = true;
                        else
                            infoStruct.inputs(jj).isData = false;
                        end
                    end

                    % -------------------------------------------------------------
                    % Add boolean to indicate if each output is semantic data.
                    % -------------------------------------------------------------
                    for jj = 1:length(infoStruct.outputs)

                        if any(ismember(infoStruct.outputs(jj).type, obj.dataSemanticTypes))
                            infoStruct.outputs(jj).isData = true;
                        else
                            infoStruct.outputs(jj).isData = false;
                        end
                    end
                end

                % -------------------------------------------------------------
                % Create and append function list entry.
                % -------------------------------------------------------------
                funcEntry = list(i);
                funcEntry.name = fcnName;
                funcEntry.info = infoStruct;

                obj.funcList = [obj.funcList; funcEntry];
            end

            disp('Function list created!');
        end

        function info = parseFuncFile(~, fcnStruct)
            %PARSEFUNCFILE Parse a legacy analysis function into pipelineInfo metadata.
            %
            %   INFO = PARSEFUNCFILE(~, FCNSTRUCT) reads a legacy function file and
            %   converts its signature and legacy defaults into a pipelineInfo-
            %   compatible struct.
            %
            %   UPDATED POLICY
            %       - NAME in outputs refers to the MATLAB output variable / output port.
            %       - File-producing outputs must declare default filenames through
            %         default_Output.
            %       - For legacy multi-file functions, output variable name remains
            %         'outFile', while defOutfilename stores the allowed filename list.
            %
            %   OUTPUT ASSUMPTIONS FOR LEGACY FUNCTIONS
            %       - outData  : DATA output carried as array by default
            %       - outFile  : file-producing DATA output; requires default_Output
            %       - metaData : non-data output
            %
            %   NOTES
            %       - Legacy functions are assumed not to support file INPUTS unless
            %         they are explicitly modernized.
            %       - Optional parameters are still represented through the legacy
            %         'opts' positional argument in info.arguments.
            %       - default_Output is mandatory for legacy outFile outputs.

            % -------------------------------------------------------------
            % Step 1: Legacy parsing
            % -------------------------------------------------------------
            legacyInfo = struct('argsIn', {}, 'argsOut', {}, 'outFileName', '', 'opts', [], 'opts_vals', []);

            fid = fopen(fullfile(fcnStruct.folder, fcnStruct.name), 'r');
            txt = '';

            while true
                tline = fgetl(fid);
                if tline == -1
                    break
                end
                if ~startsWith(strip(tline), '%')
                    txt = [txt, sprintf('%s\n', tline)]; %#ok<AGROW>
                end
            end

            fclose(fid);

            % -------------------------------------------------------------
            % Parse function header
            % -------------------------------------------------------------
            funcStr = erase(regexp(txt, '(?<=function\s*).*?(?=\r*\n)', 'match', 'once'), ' ');

            outStr = regexpi(funcStr, '.*(?=\=)', 'match', 'once');
            out_args = regexpi(outStr, '\[*(\w*)\,*(\w*)\]*', 'tokens', 'once');
            legacyInfo(1).argsOut = out_args(~cellfun(@isempty, out_args));

            [~, funcName, ~] = fileparts(fcnStruct.name);

            expInput = ['(?<=' funcName '\s*\().*?(?=\))'];
            str = regexpi(funcStr, expInput, 'match', 'once');
            str = strip(split(str, ','));
            legacyInfo.argsIn = str(~strcmp(str, 'varargin'));

            % -------------------------------------------------------------
            % Default output filename(s)
            % -------------------------------------------------------------
            expOutput = 'default_Output\s*=.*?(?=\n)';
            str = regexpi(txt, expOutput, 'match', 'once');

            if ~isempty(str)
                eval(str) %#ok<EVLDIR>
            else
                default_Output = '';
            end

            legacyInfo.outFileName = default_Output;

            % -------------------------------------------------------------
            % Optional parameters
            % -------------------------------------------------------------
            expOpts = 'default_opts\s*=.*?(?=\n)';
            str = regexpi(txt, expOpts, 'match', 'once');

            optsStruct = struct();
            optsValues = struct();

            if ~isempty(str)
                eval(str) %#ok<EVLDIR>
                optsStruct = default_opts;

                optsValsExp = 'opts_values\s*=.*?(?=\n)';
                str_opts = regexpi(txt, optsValsExp, 'match', 'once');

                if ~isempty(str_opts)
                    eval(str_opts) %#ok<EVLDIR>
                    optsValues = opts_values;
                end
            end

            % -------------------------------------------------------------
            % Step 2: Build pipelineInfo
            % -------------------------------------------------------------
            info = PipelineManager.createPipelineInfo();

            info.name = funcName;
            info.version = '';
            info.description = '';

            % -------------------------------------------------------------
            % Inputs
            % -------------------------------------------------------------
            for kIn = 1:length(legacyInfo.argsIn)

                arg = legacyInfo.argsIn{kIn};

                if strcmpi(arg, 'data')
                    type = 'UnknownDataType';
                    isData = true;

                elseif strcmpi(arg, 'savefolder')
                    type = 'SaveFolder';
                    isData = false;

                elseif strcmpi(arg, 'rawfolder')
                    type = 'RawFolder';
                    isData = false;

                elseif strcmpi(arg, 'metadata')
                    type = 'metaData';
                    isData = false;

                elseif strcmpi(arg, 'object')
                    continue

                elseif strcmpi(arg, 'opts')
                    % handled later as parameter container
                    continue

                else
                    type = 'Unknown';
                    isData = false;
                end

                if isData
                    % Legacy functions: assume NO file-input support unless explicitly modernized
                    info = PipelineManager.addInput( ...
                        info, ...
                        arg, ...
                        type, ...
                        '', ...
                        'kind', 'input', ...
                        'position', kIn, ...
                        'callType', 'positional', ...
                        'isData', true, ...
                        'supportsFile', false, ...
                        'dataMode', 'either');
                else
                    info = PipelineManager.addInput( ...
                        info, ...
                        arg, ...
                        type, ...
                        '', ...
                        'kind', 'input', ...
                        'position', kIn, ...
                        'callType', 'positional', ...
                        'isData', false);
                end
            end

            % -------------------------------------------------------------
            % Parameters (from opts struct)
            % -------------------------------------------------------------
            flds = fieldnames(optsStruct);

            for kP = 1:numel(flds)

                val = optsStruct.(flds{kP});

                if isfield(optsValues, flds{kP})
                    allowed = optsValues.(flds{kP});
                else
                    allowed = {};
                end

                info = PipelineManager.addInput( ...
                    info, ...
                    flds{kP}, ...
                    'parameter', ...
                    '', ...
                    'kind', 'parameter', ...
                    'default', val, ...
                    'allowed', allowed, ...
                    'callType', 'namevalue');
            end

            % ---------------------------------------------------------
            % Fix "arguments" field to display just "opts" (LEGACY)
            % ---------------------------------------------------------
            info.arguments(strcmp({info.arguments.kind}, 'parameter')) = [];

            if isempty(info.arguments)
                pos = 1;
            else
                pos = max([info.arguments.position]) + 1;
            end

            info.arguments(end+1) = struct( ...
                'name', 'opts', ...
                'kind', 'parameter', ...
                'position', pos, ...
                'callType', 'positional', ...
                'isData', false);

            % -------------------------------------------------------------
            % Outputs
            % -------------------------------------------------------------
            for kOut = 1:length(legacyInfo.argsOut)

                arg = legacyInfo.argsOut{kOut};

                if strcmpi(arg, 'outData')
                    type = 'UnknownDataType';
                    outputMode = 'data';

                    % outData is a DATA output, but it is not itself a file output.
                    % Do not pass legacyInfo.outFileName here; that belongs only to
                    % legacy outFile outputs.
                    info = PipelineManager.addOutput( ...
                        info, ...
                        arg, ...
                        type, ...
                        outputMode, ...
                        '', ...
                        '', ...
                        kOut, ...
                        'isData', true, ...
                        'saveFileName', '');

                elseif strcmpi(arg, 'outFile')
                    type = 'UnknownDataType';
                    outputMode = 'file';

                    % Enforce new policy:
                    % legacy file outputs must declare default_Output.
                    if isempty(legacyInfo.outFileName) || ...
                            (iscell(legacyInfo.outFileName) && isempty(legacyInfo.outFileName)) || ...
                            ((ischar(legacyInfo.outFileName) || isstring(legacyInfo.outFileName)) && ...
                            strlength(string(legacyInfo.outFileName)) == 0)
                        error('PipelineManager:parseFuncFile:MissingDefaultOutput', ...
                            ['Legacy function "%s" declares output "outFile" but does not define ' ...
                            'default_Output.\n' ...
                            'File-producing functions must declare their default output filename(s).'], ...
                            funcName);
                    end

                    info = PipelineManager.addOutput( ...
                        info, ...
                        arg, ...
                        type, ...
                        outputMode, ...
                        '', ...
                        legacyInfo.outFileName, ...
                        kOut, ...
                        'isData', true, ...
                        'saveFileName', '');

                elseif strcmpi(arg, 'metaData')
                    type = 'metaData';
                    outputMode = 'data';

                    info = PipelineManager.addOutput( ...
                        info, ...
                        arg, ...
                        type, ...
                        outputMode, ...
                        '', ...
                        '', ...
                        kOut, ...
                        'isData', false);

                else
                    type = 'Unknown';
                    outputMode = 'data';

                    % Unknown legacy outputs are treated as non-data by default
                    info = PipelineManager.addOutput( ...
                        info, ...
                        arg, ...
                        type, ...
                        outputMode, ...
                        '', ...
                        '', ...
                        kOut, ...
                        'isData', false);
                end
            end

            % Add Legacy Flag
            info.legacyOpts = true;
        end

        function list_truncated = truncateFolderList(~,list)
            % TRUNCATEFOLDERLIST reduces the size of the path by replacing
            % the common segments with "...".

            % Split the paths
            list_split = cellfun(@(x) strsplit(x, filesep), list, 'UniformOutput', false);

            % Find the maximum number of segments in any path
            maxSegments = max(cellfun(@length, list_split));

            % Convert the cell array to a matrix of strings
            stringMat = strings(length(list_split), maxSegments);
            for ii = 1:length(list_split)
                stringMat(ii, 1:length(list_split{ii})) = string(list_split{ii});
            end
            if length(list) > 1
                % Identify common segments and missing segments
                b_isCommon = all(stringMat == stringMat(1, :), 1);
                b_isMissing = any(stringMat == "", 1);

                % Adjust common segments indicator based on missing segments
                b_isCommon(find(b_isMissing, 1, 'last')-1 : end) = false;

                % Create new truncated list
                string_truncated = [repmat("...", size(stringMat, 1), 1), stringMat(:, ~b_isCommon)];
            else
                string_truncated = ["..." stringMat(end)];
            end
            % Rebuild paths
            list_truncated = cell(size(list));
            for ii = 1:size(string_truncated, 1)
                str = string_truncated(ii,:);
                list_truncated{ii} = char(strjoin(str(str~=""), filesep));
            end

        end
        function errors = validateParameterStructArray(obj, params, nodeName)
            %VALIDATEPARAMETERSTRUCTARRAY Validate one node's parameter values.
            %
            %   errors = obj.validateParameterStructArray(params, nodeName)
            %   returns a row cell array of user-facing error messages. It does
            %   not throw, so callers can aggregate all invalid parameters before
            %   aborting execution.

            errors = {};

            if isempty(params)
                return
            end

            for iParam = 1:numel(params)

                p = params(iParam);

                if ~isfield(p, 'name') || isempty(p.name)
                    errors{end+1} = sprintf( ... %#ok<AGROW>
                        'Invalid parameter metadata in step "%s": missing parameter name at index %d.', ...
                        char(string(nodeName)), iParam);
                    continue
                end

                pName = char(string(p.name));

                if ~isfield(p, 'type') || isempty(p.type)
                    errors{end+1} = sprintf( ... %#ok<AGROW>
                        'Invalid parameter "%s" in step "%s": missing parameter type.', ...
                        pName, char(string(nodeName)));
                    continue
                end

                if isfield(p, 'value')
                    value = p.value;
                elseif isfield(p, 'default')
                    value = p.default;
                else
                    errors{end+1} = sprintf( ... %#ok<AGROW>
                        'Invalid parameter "%s" in step "%s": missing value and default fields.', ...
                        pName, char(string(nodeName)));
                    continue
                end

                if isfield(p, 'allowed')
                    allowed = p.allowed;
                else
                    allowed = [];
                end

                [isValid, msg] = validateOneParameterValue(pName, p.type, value, allowed);

                if ~isValid
                    errors{end+1} = sprintf( ... %#ok<AGROW>
                        'Invalid parameter "%s" in step "%s": %s', ...
                        pName, char(string(nodeName)), msg);
                end
            end

            % =============================================================
            % Local validation helpers
            % =============================================================
            function [tf, msg] = validateOneParameterValue(paramName, paramType, value, allowed)
                tf = true;
                msg = '';

                typeStr = lower(strtrim(char(string(paramType))));

                % Mixed allowed specs are used by some analysis functions to
                % represent text-or-numeric values, for example {'auto', Inf}.
                % Handle those before applying strict single-type validation.
                if isMixedTextNumericAllowedSpec(allowed)
                    [tf, msg] = validateMixedAllowedValue(value, allowed);
                    return
                end

                switch typeStr
                    case 'logical'
                        if ~(islogical(value) && isscalar(value)) && ...
                                ~(isnumeric(value) && isscalar(value) && isfinite(value) && any(value == [0 1]))
                            tf = false;
                            msg = sprintf('expected a scalar logical value, got %s.', formatParameterValueForMessage(value));
                            return
                        end

                    case {'numeric', 'double', 'single'}
                        if ~isnumeric(value) || isempty(value) || any(~isfinite(value(:)))
                            tf = false;
                            msg = sprintf('expected a finite numeric value, got %s.', formatParameterValueForMessage(value));
                            return
                        end

                    case {'char', 'string'}
                        if ~(ischar(value) || (isstring(value) && isscalar(value)) || isTextCellOrVector(value))
                            tf = false;
                            msg = sprintf('expected text, got %s.', formatParameterValueForMessage(value));
                            return
                        end

                    otherwise
                        % Be permissive for custom classes while still checking
                        % allowed values below when they are explicitly declared.
                        if isempty(typeStr)
                            tf = false;
                            msg = 'parameter type is empty.';
                            return
                        end
                end

                if obj.isUnrestrictedAllowedSpec(allowed)
                    return
                end

                [tf, msg] = validateAllowedValue(value, allowed, typeStr, paramName);
            end

            function tf = isMixedTextNumericAllowedSpec(allowed)
                tf = false;

                if ~iscell(allowed) || obj.isUnrestrictedAllowedSpec(allowed)
                    return
                end

                hasText = false;
                hasNumeric = false;

                for iAllowed = 1:numel(allowed)
                    item = allowed{iAllowed};
                    hasText = hasText || ischar(item) || (isstring(item) && isscalar(item));
                    hasNumeric = hasNumeric || (isnumeric(item) && ~isempty(item));
                end

                tf = hasText && hasNumeric;
            end

            function [tf, msg] = validateMixedAllowedValue(value, allowed)
                tf = true;
                msg = '';

                textAllowed = strings(0,1);
                numericAllowed = [];

                for iAllowed = 1:numel(allowed)
                    item = allowed{iAllowed};
                    if ischar(item) || (isstring(item) && isscalar(item))
                        textAllowed(end+1,1) = string(item); %#ok<AGROW>
                    elseif isnumeric(item)
                        numericAllowed = [numericAllowed, item(:).']; %#ok<AGROW>
                    end
                end

                if ischar(value) || (isstring(value) && isscalar(value))
                    if any(strcmpi(string(value), textAllowed))
                        return
                    end

                    % Accept numeric text only when the numeric portion of the
                    % allowed spec permits numeric values.
                    numericCandidate = str2double(char(string(value)));
                    if ~isnan(numericCandidate) && validateNumericAgainstAllowed(numericCandidate, numericAllowed)
                        return
                    end

                    tf = false;
                    msg = sprintf('value %s is not allowed. Allowed text values: %s.', ...
                        formatParameterValueForMessage(value), char(strjoin(textAllowed, ', ')));
                    return
                end

                if isnumeric(value)
                    if validateNumericAgainstAllowed(value, numericAllowed)
                        return
                    end

                    tf = false;
                    msg = sprintf('numeric value %s is outside the allowed numeric specification %s.', ...
                        formatParameterValueForMessage(value), mat2str(numericAllowed));
                    return
                end

                tf = false;
                msg = sprintf('value %s does not match the mixed text/numeric allowed specification.', ...
                    formatParameterValueForMessage(value));
            end

            function [tf, msg] = validateAllowedValue(value, allowed, typeStr, paramName)
                tf = true;
                msg = '';

                % -------------------------------------------------------------
                % Logical parameters
                % -------------------------------------------------------------
                % Logical parameters are already type-checked above. Here,
                % allowed can optionally restrict accepted values. Support both
                % logical specs, e.g. [true false], and numeric 0/1 specs.
                if strcmpi(typeStr, 'logical')

                    valueLogical = logical(value);

                    if islogical(allowed)
                        allowedLogical = allowed(:);

                        if any(valueLogical == allowedLogical)
                            return
                        end

                        tf = false;
                        msg = sprintf('value %s is not one of the allowed logical values: %s.', ...
                            formatParameterValueForMessage(valueLogical), mat2str(allowedLogical.'));
                        return
                    end

                    if isnumeric(allowed)
                        if isempty(allowed) || any(~isfinite(allowed(:))) || ...
                                any(~ismember(allowed(:), [0 1]))
                            tf = false;
                            msg = sprintf(['allowed values for "%s" must be logical values ' ...
                                'or numeric 0/1 values, got %s.'], ...
                                paramName, formatParameterValueForMessage(allowed));
                            return
                        end

                        allowedLogical = logical(allowed(:));

                        if any(valueLogical == allowedLogical)
                            return
                        end

                        tf = false;
                        msg = sprintf('value %s is not one of the allowed logical values: %s.', ...
                            formatParameterValueForMessage(valueLogical), mat2str(allowedLogical.'));
                        return
                    end

                    if iscell(allowed) || isstring(allowed) || ischar(allowed)
                        allowedText = normalizeAllowedText(allowed);

                        if isempty(allowedText)
                            return
                        end

                        valueText = string(mat2str(valueLogical));
                        allowedLower = lower(allowedText);
                        valueIsAllowed = ...
                            any(strcmp(valueText, allowedText)) || ...
                            (valueLogical && any(ismember(allowedLower, ["true", "1"]))) || ...
                            (~valueLogical && any(ismember(allowedLower, ["false", "0"])));

                        if valueIsAllowed
                            return
                        end

                        tf = false;
                        msg = sprintf('value %s is not one of the allowed logical values: %s.', ...
                            formatParameterValueForMessage(valueLogical), char(strjoin(allowedText, ', ')));
                        return
                    end

                    tf = false;
                    msg = sprintf('unsupported allowed specification of class "%s" for type "%s".', ...
                        class(allowed), typeStr);
                    return
                end

                if isnumeric(allowed)
                    if ~isnumeric(value)
                        tf = false;
                        msg = sprintf('allowed values for "%s" are numeric, but value is %s.', ...
                            paramName, formatParameterValueForMessage(value));
                        return
                    end

                    if validateNumericAgainstAllowed(value, allowed)
                        return
                    end

                    tf = false;
                    if numel(allowed) == 2
                        msg = sprintf('value %s is outside the allowed range [%g, %g].', ...
                            formatParameterValueForMessage(value), allowed(1), allowed(2));
                    else
                        msg = sprintf('value %s is not one of the allowed numeric values: %s.', ...
                            formatParameterValueForMessage(value), mat2str(allowed));
                    end
                    return
                end

                if iscell(allowed) || isstring(allowed) || ischar(allowed)
                    allowedText = normalizeAllowedText(allowed);

                    if isempty(allowedText)
                        return
                    end

                    if isTextCellOrVector(value)
                        valueText = string(value(:));
                    elseif ischar(value) || (isstring(value) && isscalar(value))
                        valueText = string(value);
                    else
                        tf = false;
                        msg = sprintf('allowed values for "%s" are text values, but value is %s.', ...
                            paramName, formatParameterValueForMessage(value));
                        return
                    end

                    if all(ismember(lower(valueText), lower(allowedText)))
                        return
                    end

                    tf = false;
                    msg = sprintf('value %s is not one of the allowed values: %s.', ...
                        formatParameterValueForMessage(value), char(strjoin(allowedText, ', ')));
                    return
                end

                % Unknown allowed metadata should be treated as invalid metadata,
                % not silently ignored.
                tf = false;
                msg = sprintf('unsupported allowed specification of class "%s" for type "%s".', ...
                    class(allowed), typeStr);
            end

            function tf = validateNumericAgainstAllowed(value, allowed)
                tf = false;

                if ~isnumeric(value) || isempty(value) || any(~isfinite(value(:)))
                    return
                end

                if isempty(allowed)
                    tf = true;
                    return
                end

                allowed = allowed(:).';

                if numel(allowed) == 1 && isinf(allowed(1))
                    tf = true;
                    return
                end

                if numel(allowed) == 2 && any(isinf(allowed))
                    lo = min(allowed);
                    hi = max(allowed);
                    tf = all(value(:) >= lo & value(:) <= hi);
                    return
                end

                if numel(allowed) == 2
                    lo = min(allowed);
                    hi = max(allowed);
                    tf = all(value(:) >= lo & value(:) <= hi);
                    return
                end

                tf = all(ismember(value(:), allowed(:)));
            end

            function tf = isTextCellOrVector(x)
                tf = (iscell(x) && isvector(x) && all(cellfun(@(c) ischar(c) || (isstring(c) && isscalar(c)), x))) || ...
                    (isstring(x) && isvector(x));
            end

            function allowedText = normalizeAllowedText(allowed)
                allowedText = strings(0,1);

                if ischar(allowed) || (isstring(allowed) && isscalar(allowed))
                    allowedText = string(allowed);
                    allowedText = allowedText(strlength(strtrim(allowedText)) > 0);
                    return
                end

                if isstring(allowed)
                    allowedText = allowed(:);
                    allowedText = allowedText(strlength(strtrim(allowedText)) > 0);
                    return
                end

                if ~iscell(allowed)
                    return
                end

                for iAllowed = 1:numel(allowed)
                    item = allowed{iAllowed};
                    if ischar(item) || (isstring(item) && isscalar(item))
                        txt = strtrim(string(item));
                        if strlength(txt) > 0
                            allowedText(end+1,1) = txt; %#ok<AGROW>
                        end
                    end
                end
            end

            function txt = formatParameterValueForMessage(value)
                try
                    if ischar(value) || (isstring(value) && isscalar(value))
                        txt = sprintf('"%s"', char(string(value)));
                    elseif isnumeric(value) || islogical(value)
                        txt = mat2str(value);
                    elseif iscell(value)
                        txt = sprintf('[%s cell]', localSizeToString(size(value)));
                    elseif isstring(value)
                        txt = sprintf('[%s string]', localSizeToString(size(value)));
                    else
                        txt = sprintf('[%s %s]', localSizeToString(size(value)), class(value));
                    end
                catch
                    txt = sprintf('[%s]', class(value));
                end
            end

            function s = localSizeToString(sz)
                s = sprintf('%dx', sz);
                if ~isempty(s)
                    s(end) = [];
                end
            end
        end

        function tf = isUnrestrictedAllowedSpec(~, allowed)
            %ISUNRESTRICTEDALLOWEDSPEC True for empty/no-restriction placeholders.
            %
            %   Some existing pipelineInfo definitions use allowed={{}} or
            %   allowed={[]} to mean unrestricted. Treat those placeholders the
            %   same as [] so the dialog and validation do not force an empty
            %   dropdown/list.

            tf = false;

            if nargin < 2 || isempty(allowed)
                tf = true;
                return
            end

            if iscell(allowed)
                if isempty(allowed)
                    tf = true;
                    return
                end

                if numel(allowed) == 1
                    item = allowed{1};
                    if isempty(item) || (iscell(item) && isempty(item))
                        tf = true;
                        return
                    end
                end
            end
        end

        %%%%%%--- Helper of "setParameters" -------------------------------
        function [values,state] = buildParameterDialog(obj, node)
            %BUILDPARAMETERDIALOG Build and show the parameter editing dialog.
            %
            %   [values, state] = buildParameterDialog(obj, node) creates the UI
            %   used by setParameters and returns the edited values.


            params = node.info.parameters;
            n = numel(params);

            state  = false;
            values = cell(n,1);

            rowH = 28;
            btnH = 36;
            choiceRowH = 26;
            panelChromeH = 28;
            maxVisibleChoices = 6;
            rowSpacing = 6;
            dialogPadding = [15 15 15 10];
            rowHeights = repmat({rowH}, 1, n);

            % Multi-select parameters need enough vertical space for their
            % checkbox grid. Keep long lists bounded; their panel remains
            % scrollable for choices beyond the visible estimate.
            for i = 1:n
                p = params(i);
                isTextChoice = ~obj.isUnrestrictedAllowedSpec(p.allowed) && ...
                    iscell(p.allowed) && ...
                    all(cellfun(@(x) ischar(x) || ...
                    (isstring(x) && isscalar(x)), p.allowed));
                isMultiSelect = strcmpi(p.type, 'char') && ...
                    isTextChoice && ~isrow(p.allowed);
                if isMultiSelect
                    visibleChoices = min(numel(p.allowed), maxVisibleChoices);
                    rowHeights{i} = max(rowH, ...
                        visibleChoices * choiceRowH + panelChromeH);
                end
            end

            % Include every vertical contribution made by the grid layout.
            % Omitting the n inter-row gaps places the nested action row below
            % the visible figure for dialogs with several parameters.
            figH = dialogPadding(2) + dialogPadding(4) + ...
                sum(cell2mat(rowHeights)) + btnH + rowSpacing * n;

            dlg = uifigure( ...
                'Name',['Parameters: ' node.name], ...
                'Position',[100 100 350 figH], ...
                'Resize','on');
            movegui(dlg,'center')
            gl = uigridlayout(dlg,[n+1 2]);
            gl.RowHeight   = [rowHeights, {btnH}];
            gl.ColumnWidth = {'1x','1.2x'};
            gl.RowSpacing  = rowSpacing;
            gl.Padding     = dialogPadding;

            controls = gobjects(n,1);

            % ---------------------------------------------------------
            % Create controls
            % ---------------------------------------------------------
            for i = 1:n

                p = params(i);

                lbl = uilabel(gl, ...
                    'Text',[p.name ':'], ...
                    'HorizontalAlignment','right');
                lbl.Layout.Row = i;
                lbl.Layout.Column = 1;

                switch lower(p.type)

                    % ---------------- LOGICAL ----------------
                    case 'logical'

                        c = uicheckbox(gl, 'Text', '');
                        c.Value = logical(p.value);

                        % ---------------- NUMERIC ----------------
                    case 'numeric'

                        if obj.isUnrestrictedAllowedSpec(p.allowed)

                            c = uieditfield(gl,'numeric');
                            c.Value = p.value;

                        elseif isnumeric(p.allowed) && numel(p.allowed)==2

                            c = uieditfield(gl,'numeric');
                            c.Limits = p.allowed;
                            c.Value  = p.value;

                        elseif isnumeric(p.allowed)

                            c = uidropdown(gl);
                            c.Items = arrayfun(@num2str,p.allowed,'UniformOutput',false);
                            c.Value = num2str(p.value);

                        else
                            error('Invalid allowed field for numeric parameter.');
                        end

                        % ---------------- CHAR ----------------
                    case 'char'

                        if obj.isUnrestrictedAllowedSpec(p.allowed)

                            c = uieditfield(gl,'text');
                            c.Value = p.value;

                        elseif iscell(p.allowed)

                            % Mixed text/numeric allowed specs, for example
                            % {'auto', Inf}, cannot be represented safely as
                            % a dropdown. Use a text field and let the shared
                            % parameter validator perform the final check.
                            allowedIsText = all(cellfun(@(x) ischar(x) || ...
                                (isstring(x) && isscalar(x)), p.allowed));

                            if ~allowedIsText

                                c = uieditfield(gl,'text');
                                c.Value = char(string(p.value));

                            elseif isrow(p.allowed)

                                c = uidropdown(gl);
                                c.Items = p.allowed;
                                c.Value = p.value;

                            else
                                % Multi-select
                                c = uipanel(gl,'Scrollable','on');
                                gl2 = uigridlayout(c,[numel(p.allowed) 1]);
                                gl2.RowHeight = repmat({choiceRowH},1,numel(p.allowed));
                                gl2.Padding = [5 5 5 5];

                                for k = 1:numel(p.allowed)
                                    uicheckbox(gl2, ...
                                        'Text', p.allowed{k}, ...
                                        'Value', ismember(p.allowed{k}, p.value));
                                end
                            end

                        else
                            error('Invalid allowed field for char parameter.');
                        end

                    otherwise
                        error('Unsupported parameter type "%s".', p.type);
                end

                c.Layout.Row = i;
                c.Layout.Column = 2;
                c.Tooltip = p.description;

                controls(i) = c;
            end

            % ---------------------------------------------------------
            % Nested button layout
            % ---------------------------------------------------------
            btnPanel = uigridlayout(gl,[1 2]);
            btnPanel.Layout.Row = n+1;
            btnPanel.Layout.Column = [1 2];
            btnPanel.ColumnWidth = {'1x','1x'};
            btnPanel.Padding = [0 5 0 0];
            btnPanel.ColumnSpacing = 10;

            btnOK = uibutton(btnPanel, ...
                'Text','OK', ...
                'ButtonPushedFcn',@onSave);

            btnReset = uibutton(btnPanel, ...
                'Text','Reset', ...
                'ButtonPushedFcn',@onReset,...
                'Tooltip','Reset Parameters to default values');

            uiwait(dlg);

            % =========================================================
            % Save Callback
            % =========================================================
            function onSave(~,~)

                for ii = 1:n
                    p = params(ii);
                    ctrl = controls(ii);

                    switch lower(p.type)

                        case 'logical'
                            values{ii} = logical(ctrl.Value);

                        case 'numeric'
                            if isa(ctrl,'matlab.ui.control.DropDown')
                                values{ii} = str2double(ctrl.Value);
                            else
                                values{ii} = ctrl.Value;
                            end

                        case 'char'

                            if isa(ctrl,'matlab.ui.control.DropDown')
                                values{ii} = ctrl.Value;

                            elseif isa(ctrl,'matlab.ui.container.Panel')
                                checks = ctrl.Children.Children;
                                sel = arrayfun(@(x) x.Value, checks);
                                labels = arrayfun(@(x) x.Text, checks, 'UniformOutput',false);
                                values{ii} = labels(sel);

                            else
                                values{ii} = char(ctrl.Value);
                            end
                    end
                end

                state = true;
                delete(dlg);
            end

            % =========================================================
            % Reset Callback
            % =========================================================
            function onReset(~,~)

                for ii = 1:n

                    p = params(ii);
                    ctrl = controls(ii);

                    switch lower(p.type)

                        case 'logical'
                            ctrl.Value = logical(p.default);

                        case 'numeric'
                            if isa(ctrl,'matlab.ui.control.DropDown')
                                ctrl.Value = num2str(p.default);
                            else
                                ctrl.Value = p.default;
                            end

                        case 'char'

                            if isa(ctrl,'matlab.ui.control.DropDown')
                                ctrl.Value = p.default;

                            elseif isa(ctrl,'matlab.ui.container.Panel')
                                checks = ctrl.Children.Children;
                                for kk = 1:numel(checks)
                                    checks(kk).Value = ismember(checks(kk).Text, p.default);
                                end

                            else
                                ctrl.Value = p.default;
                            end
                    end
                end
            end
        end

    end

    methods (Static)

        function info = createPipelineInfo(name, description)
            %CREATEPIPELINEINFO Create a new pipelineInfo struct.
            %
            %   info = PipelineManager.createPipelineInfo()
            %   info = PipelineManager.createPipelineInfo(name)
            %   info = PipelineManager.createPipelineInfo(name, description)
            %
            %   Creates a standardized metadata structure used by PipelineManager to
            %   build, validate, schedule, and execute analysis-function nodes.
            %
            %   Inputs:
            %       name        - Function name. Default: ''.
            %       description - Short function description. Default: ''.
            %
            %   Output:
            %       info        - Pipeline metadata struct with fields:
            %
            %           name
            %           version
            %           description
            %           legacyOpts
            %           arguments
            %           inputs
            %           parameters
            %           outputs
            %           notes
            %
            %   Metadata groups:
            %       info.arguments
            %           Function-call contract used during execution.
            %
            %           Fields:
            %               name
            %               kind        - 'input' or 'parameter'
            %               position
            %               callType    - 'positional' or 'namevalue'
            %               isData
            %
            %       info.inputs
            %           Pipeline input-port metadata used for DATA-flow wiring and
            %           RAM/file routing.
            %
            %           Fields:
            %               name
            %               type
            %               description
            %               isData
            %               supportsFile - DATA inputs only. True if the input can
            %                              receive a filename/file-backed source.
            %               dataMode     - DATA inputs only. One of:
            %                              'either', 'ram', or 'file'.
            %
            %       info.parameters
            %           User-editable parameter metadata.
            %
            %           Fields:
            %               name
            %               type
            %               default
            %               allowed
            %               description
            %
            %       info.outputs
            %           Output metadata used for downstream wiring, saving, and
            %           produced-file tracking.
            %
            %           Fields:
            %               name
            %               type
            %               outputMode     - 'data' if the function returns data;
            %                                'file' if the function returns filename(s)
            %                                for files it created.
            %               description
            %               defOutfilename - Default output filename metadata.
            %               position
            %               isData         - True if the output participates in the
            %                                DATA-flow graph.
            %               saveFileName   - PipelineManager-managed save target for
            %                                DATA outputs.
            %
            %   Notes:
            %       - supportsFile and dataMode are input-only concepts.
            %       - Output RAM/file behavior is defined by outputMode and isData.
            %       - Function type classification is inferred by PipelineManager from
            %         the declared inputs and outputs. It is intentionally not stored
            %         here to keep custom pipelineInfo definitions minimal.
            %
            %   See also:
            %       PipelineManager.addInput
            %       PipelineManager.addOutput

            arguments
                name = ''
                description = ''
            end

            info = struct();

            info.name        = char(string(name));
            info.version     = '1.0.0';
            info.description = char(string(description));
            info.supportsPreflight = false;

            % Legacy analysis functions may use a single positional opts struct instead
            % of regular name-value parameters.
            info.legacyOpts = false;

            % Execution contract used to build the MATLAB function call.
            info.arguments = struct( ...
                'name', {}, ...
                'kind', {}, ...
                'position', {}, ...
                'callType', {}, ...
                'isData', {} );

            % Pipeline input semantics.
            % supportsFile and dataMode are input-only fields used by RAM/file routing.
            info.inputs = struct( ...
                'name', {}, ...
                'type', {}, ...
                'description', {}, ...
                'isData', {}, ...
                'supportsFile', {}, ...
                'dataMode', {} );

            % User-editable parameters.
            info.parameters = struct( ...
                'name', {}, ...
                'type', {}, ...
                'default', {}, ...
                'allowed', {}, ...
                'description', {} );

            % Pipeline output semantics.
            % Do not include supportsFile/dataMode here; they are not output concepts.
            info.outputs = struct( ...
                'name', {}, ...
                'type', {}, ...
                'outputMode', {}, ...
                'description', {}, ...
                'defOutfilename', {}, ...
                'position', {}, ...
                'isData', {}, ...
                'saveFileName', {} );

            info.notes = {};

        end

        function info = addInput(info, name, type, description, varargin)
            %ADDINPUT Add an INPUT or PARAMETER definition to pipelineInfo.
            %
            %   INPUT PORT (default):
            %     info = PipelineManager.addInput(info, name, type, description, ...)
            %
            %   PARAMETER (set 'kind','parameter'):
            %     info = PipelineManager.addInput(info, paramName, 'parameter', '', ...
            %               'kind','parameter','default',val,'allowed',allowedVals, ...)
            %
            % REQUIRED INPUTS
            %   info        pipelineInfo struct (from createPipelineInfo)
            %   name        (text) port/parameter name
            %   type        (char|string|cellstr) semantic type(s) for inputs
            %               or 'parameter' when kind='parameter'
            %   description (char|string) optional
            %
            % NAME-VALUE OPTIONS
            %   'kind'        : 'input' | 'parameter' (default: 'input')
            %   'position'    : scalar numeric. If empty, appended to end of arguments.
            %   'callType'    : If 'positional' (case-insensitive), argument is positional.
            %                   Otherwise, argument is treated as name-value and stored as
            %                   callType='namevalue'.
            %   'default'     : default value (parameters only)
            %   'allowed'     : allowed set (parameters only)
            %   'dataType'    : explicit parameter type (parameters only). If empty, inferred.
            %   'isData'      : logical. For input ports only. Default true.
            %   'supportsFile': logical. DATA ports only. Default false.
            %   'dataMode'    : 'either'|'ram'|'file'. DATA ports only. Default 'either'.
            %
            % STRICT VALIDATION
            %   - kind must be 'input' or 'parameter'
            %   - callType is normalized: only 'positional' stays positional; all other
            %     values become 'namevalue'
            %   - dataMode must be one of 'either','ram','file' (DATA ports only)
            %
            % SIDE EFFECTS
            %   - Adds entry to info.inputs or info.parameters
            %   - Adds corresponding entry to info.arguments

            arguments
                info struct
                name {mustBeTextScalar}
                type
                description = ''
            end
            arguments (Repeating)
                varargin
            end

            % Defaults
            kind        = 'input';
            position    = [];
            callType    = 'positional';
            default     = [];
            allowed     = {};
            isData      = true;
            paramType   = '';

            % DATA-only RAM metadata
            supportsFile = false;
            dataMode     = 'either';

            % Parse optional arguments (manual to keep backwards compatibility)
            for k = 1:2:numel(varargin)
                key = lower(char(string(varargin{k})));
                val = varargin{k+1};

                switch key
                    case 'kind'
                        kind = lower(char(string(val)));
                    case 'position'
                        position = val;
                    case 'calltype'
                        callType = lower(char(string(val)));
                    case 'default'
                        default = val;
                    case 'allowed'
                        allowed = val;
                    case 'datatype'
                        paramType = char(string(val));
                    case 'isdata'
                        isData = logical(val);

                    case 'supportsfile'
                        supportsFile = logical(val);
                    case 'datamode'
                        dataMode = lower(char(string(val)));
                end
            end

            % -------------------------------------------------------------
            % Validate / normalize kind
            % -------------------------------------------------------------
            validKinds = {'input','parameter'};
            if ~ismember(kind, validKinds)
                error('addInput:InvalidKind', 'kind must be one of: %s', strjoin(validKinds, ', '));
            end

            % -------------------------------------------------------------
            % Normalize callType (confirm rule)
            %   Only 'positional' stays positional.
            %   Everything else => 'namevalue'.
            % -------------------------------------------------------------
            if strcmpi(callType,'positional')
                callType = 'positional';
            else
                callType = 'namevalue';
            end

            % -------------------------------------------------------------
            % Validate dataMode
            % -------------------------------------------------------------
            validModes = {'either','ram','file'};
            if ~ismember(dataMode, validModes)
                error('addInput:InvalidDataMode', 'dataMode must be one of: %s', strjoin(validModes, ', '));
            end

            % Normalize NAME
            name = strtrim(char(string(name)));
            if isempty(name)
                error('addInput:InvalidName','Name cannot be empty.');
            end

            % Normalize TYPE -> 1xN cell array of char
            if ischar(type) || isstring(type)
                typeCell = {strtrim(char(string(type)))};
            elseif iscell(type)
                typeCell = cellfun(@(x) strtrim(char(string(x))), type, 'UniformOutput', false);
            else
                error('addInput:InvalidType','TYPE must be char/string or cell array of char/string.');
            end
            typeCell = unique(typeCell,'stable');

            % ---------------------------------------------------------
            % Add to INPUTS or PARAMETERS
            % ---------------------------------------------------------
            if strcmp(kind,'input')

                % DATA-only fields are only meaningful when isData==true
                if ~isData
                    supportsFile = false;
                    dataMode = 'either';
                end

                newInput = struct( ...
                    'name', name, ...
                    'type', {typeCell}, ...
                    'description', char(string(description)), ...
                    'isData', logical(isData), ...
                    'supportsFile', logical(supportsFile), ...
                    'dataMode', dataMode);

                if isempty(info.inputs)
                    info.inputs = newInput;
                else
                    info.inputs(end+1) = newInput;
                end

            else
                % PARAMETER
                if isempty(paramType)
                    if isnumeric(default)
                        paramType = 'numeric';
                    else
                        paramType = class(default);
                    end
                end

                % Wrap default and allowed in scalar cells so parameter
                % metadata remains a scalar struct even when a parameter
                % default is itself a cell array, e.g. {'AI1','AI2'}.
                newParam = struct( ...
                    'name', name, ...
                    'type', paramType, ...
                    'default', {default}, ...
                    'allowed', {allowed}, ...
                    'description', char(string(description)));

                if isempty(info.parameters)
                    info.parameters = newParam;
                else
                    info.parameters(end+1) = newParam;
                end

                isData = false; % parameters are never data-flow
            end

            % ---------------------------------------------------------
            % Add ARGUMENT entry
            % ---------------------------------------------------------
            if isempty(position)
                position = numel(info.arguments) + 1;
            end

            newArg = struct( ...
                'name', name, ...
                'kind', kind, ...
                'position', position, ...
                'callType', callType, ...
                'isData', strcmp(kind,'input') && logical(isData));

            if isempty(info.arguments)
                info.arguments = newArg;
            else
                info.arguments(end+1) = newArg;
            end
        end

        function info = addOutput(info, name, type, outputMode, description, defOutfilename, position, varargin)
            %ADDOUTPUT Add an output definition to pipelineInfo.outputs.
            %
            %   info = PipelineManager.addOutput(info, name, type, outputMode, ...
            %       description, defOutfilename, position)
            %
            %   info = PipelineManager.addOutput(..., 'isData', tf, ...
            %       'saveFileName', fileName)
            %
            %   Inputs:
            %       info           - pipelineInfo struct created by createPipelineInfo.
            %       name           - Logical output port name. Must be unique within
            %                        info.outputs.
            %       type           - Semantic type as char/string or cell array of
            %                        char/string.
            %       outputMode     - 'data' or 'file'.
            %       description    - User-facing description.
            %       defOutfilename - Default output filename metadata. For file-manifest
            %                        outputs, this can be a cell array of candidate files.
            %       position       - Positional order of the output.
            %
            %   Name-Value options:
            %       isData         - Logical scalar. Default: true.
            %       saveFileName   - Default PipelineManager-managed save target.
            %                        Default: ''.
            %
            %   Notes:
            %       - For file-manifest outputs, this method stores ONE logical
            %         output port whose defOutfilename field may contain multiple
            %         candidate files.
            %       - Output names must be unique within one pipelineInfo.
            %       - Path components in defOutfilename are stripped automatically.
            %       - For DATA outputs with empty defOutfilename, a default name is
            %         auto-generated from the function prefix.

            p = inputParser;
            addParameter(p, 'isData', true, @(x) islogical(x) && isscalar(x));
            addParameter(p, 'saveFileName', '', @(x) ischar(x) || (isstring(x) && isscalar(x)));
            parse(p, varargin{:});

            isData = p.Results.isData;
            saveFileName = char(string(p.Results.saveFileName));

            % -------------------------------------------------------------
            % Normalize NAME
            % -------------------------------------------------------------
            name = strtrim(char(string(name)));
            if isempty(name)
                error('addOutput:InvalidName', 'Name cannot be empty.');
            end

            % Enforce unique logical output port names
            if isfield(info, 'outputs') && ~isempty(info.outputs)
                existingNames = {info.outputs.name};
                if any(strcmpi(existingNames, name))
                    error('addOutput:DuplicateOutputName', ...
                        ['Duplicate output name "%s". Output names must be unique ' ...
                        'within one pipelineInfo.'], ...
                        name);
                end
            end

            % -------------------------------------------------------------
            % Normalize TYPE -> 1xN cell array of char
            % -------------------------------------------------------------
            if ischar(type) || isstring(type)
                typeCell = {strtrim(char(string(type)))};
            elseif iscell(type)
                typeCell = cellfun(@(x) strtrim(char(string(x))), type, 'UniformOutput', false);
            else
                error('addOutput:InvalidType', ...
                    'TYPE must be char/string or a cell array of char/string.');
            end

            typeCell = typeCell(~cellfun(@isempty, typeCell));
            typeCell = unique(typeCell, 'stable');

            if isempty(typeCell)
                error('addOutput:EmptyType', 'TYPE cannot be empty.');
            end

            % -------------------------------------------------------------
            % Validate outputMode
            % -------------------------------------------------------------
            outputMode = lower(strtrim(char(string(outputMode))));
            validOutModes = {'data', 'file'};
            if ~ismember(outputMode, validOutModes)
                error('addOutput:InvalidOutputMode', ...
                    'outputMode must be one of: %s', strjoin(validOutModes, ', '));
            end

            % -------------------------------------------------------------
            % Normalize description and position
            % -------------------------------------------------------------
            description = char(string(description));

            if isempty(position)
                position = [];
            elseif ~(isnumeric(position) && isscalar(position) && isfinite(position))
                error('addOutput:InvalidPosition', ...
                    'position must be a numeric finite scalar or empty.');
            end

            % -------------------------------------------------------------
            % Normalize defOutfilename to a clean cell row
            % -------------------------------------------------------------
            if isempty(defOutfilename)
                defOutList = {};
            elseif ischar(defOutfilename) || isstring(defOutfilename)
                defOutList = {strtrim(char(string(defOutfilename)))};
            elseif iscell(defOutfilename)
                defOutList = cellfun(@(x) strtrim(char(string(x))), defOutfilename, 'UniformOutput', false);
            else
                error('addOutput:InvalidDefaultOutputName', ...
                    'defOutfilename must be empty, text, or a cell array of text.');
            end

            defOutList = defOutList(~cellfun(@isempty, defOutList));

            % Strip any path components if provided
            for iDef = 1:numel(defOutList)
                [~, b, e] = fileparts(defOutList{iDef});
                defOutList{iDef} = [b e];
            end

            % Keep unique filenames only
            defOutList = unique(defOutList, 'stable');

            % -------------------------------------------------------------
            % Auto-generate default output name for DATA outputs when missing
            % -------------------------------------------------------------
            if isData && isempty(defOutList)

                funcPrefix = localResolveFunctionPrefix(info);

                nExistingDataOutputs = 0;
                if isfield(info, 'outputs') && ~isempty(info.outputs)
                    for iOut = 1:numel(info.outputs)
                        if isfield(info.outputs(iOut), 'isData') && info.outputs(iOut).isData
                            nExistingDataOutputs = nExistingDataOutputs + 1;
                        end
                    end
                end

                autoIdx = nExistingDataOutputs + 1;

                if autoIdx == 1
                    autoName = sprintf('%s_data', funcPrefix);
                else
                    autoName = sprintf('%s_data_%d', funcPrefix, autoIdx);
                end

                defOutList = {autoName};

                warning('PipelineManager:addOutput:AutoDefaultOutputName', ...
                    ['Output "%s" did not declare defOutfilename. Using auto-generated default "%s". ' ...
                    'If you want a custom name, update the pipelineInfo creation in the function itself.'], ...
                    name, autoName);
            end

            % -------------------------------------------------------------
            % Rebuild defOutfilename output shape
            % Important: keep file manifests as ONE field value, not a struct array
            % -------------------------------------------------------------
            if isempty(defOutList)
                defOutValue = '';
            elseif numel(defOutList) == 1
                defOutValue = defOutList{1};
            else
                defOutValue = defOutList(:).';
            end

            % -------------------------------------------------------------
            % Normalize saveFileName
            % -------------------------------------------------------------
            saveFileName = strtrim(saveFileName);
            if ~isempty(saveFileName)
                [~, bSave, eSave] = fileparts(saveFileName);
                saveFileName = [bSave eSave];
            end

            % -------------------------------------------------------------
            % Build output struct
            % Important: wrap defOutValue in braces so a cell manifest stays as a
            % single field value instead of expanding into a struct array.
            % -------------------------------------------------------------
            newOutput = struct( ...
                'name', name, ...
                'type', {typeCell}, ...
                'outputMode', outputMode, ...
                'description', description, ...
                'defOutfilename', {defOutValue}, ...
                'position', position, ...
                'isData', logical(isData), ...
                'saveFileName', saveFileName);

            if ~isfield(info, 'outputs') || isempty(info.outputs)
                info.outputs = newOutput;
            else
                info.outputs(end+1) = newOutput;
            end

            % =============================================================
            % Local helper
            % =============================================================
            function funcPrefix = localResolveFunctionPrefix(infoLocal)
                funcPrefix = 'output';

                if isfield(infoLocal, 'name') && ~isempty(infoLocal.name)
                    funcPrefix = char(string(infoLocal.name));
                elseif isfield(infoLocal, 'functionName') && ~isempty(infoLocal.functionName)
                    funcPrefix = char(string(infoLocal.functionName));
                end

                funcPrefix = matlab.lang.makeValidName(funcPrefix);

                if isempty(funcPrefix)
                    funcPrefix = 'output';
                end
            end
        end

    end
end
